0Q662 328 671 316Q680 304 701 286Q722 268 725 262Q729 256 728 250Q727 244 721 232Q714 220 685 182Q656 143 647 130Q637 116 627 95Q616 75 612 69Q607 64 602 60Q597 56 587 51Q576 47 564 45Q552 43 542 45Q532 46 526 51Q520 55 518 58Q516 62 515 67Q514 72 514 78Q515 84 517 90Q519 96 524 104Q529 112 544 130Q560 149 566 162Q573 176 575 194Q577 212 575 228Q573 244 567 254Q562 264 553 272Q544 279 536 284Q527 288 494 302Q460 315 450 322Q440 328 433 334Q427 340 419 349Q412 358 406 369Q399 380 395 392Q390 404 387 419Z'/%3E%3Cpath d='M454 394Q452 400 451 410Q451 420 453 426Q455 432 457 436Q460 440 464 444Q468 448 474 452Q480 455 492 459Q504 462 518 462Q532 462 544 458Q556 454 565 447Q573 440 579 430Q584 419 585 408Q586 396 585 390Q584 384 581 378Q579 372 571 365Q564 358 554 354Q544 351 536 351Q528 351 520 352Q512 352 498 357Q484 362 474 370Q464 378 460 383Q457 388 454 394Z'/%3E%3C/g%3E%3C/svg%3E");
        --fx-texture-size: 900px 900px;
        --fx-texture-opacity: 0;
    }

    /* The field is static and anchored to the page: it scrolls with the content, repeats
       on both axes over the whole page height, and never moves on its own (Kenny,
       2026-10-07: no drift, no fixed layer). So it is the body's background, and the
       shared fixed overlay (body::after) is switched off for this theme. */
    [data-theme='forest'] body {
        background-image: var(--fx-texture);
        background-size: var(--fx-texture-size);
        background-repeat: repeat;
        background-attachment: scroll;
    }

    [data-theme='forest'] body::after {
        display: none;
    }

    /* The typefaces the theme declares [TH12].
 *
 * Every theme has declared --theme-font-body and --theme-font-display
 * since the extraction, and until now exactly one rule read either of
 * them: formal's headings. A consumer who vendors this stylesheet and
 * writes plain HTML therefore got the browser's default serif — found on
 * 2026-09-04 by the first field test, where a page served the way kyu and
 * almanac serve theirs came back in Times New Roman.
 *
 * The fallbacks matter as much as the tokens: a vendoring consumer may
 * not load the webfonts, and a theme should degrade to a sane stack
 * rather than to whatever the browser picked in 1996. */
    body {
        font-family: var(--theme-font-body, ui-sans-serif, system-ui, sans-serif);
        /* One line height for running text, the package's in every theme
     * [scope-80, option E of research/uniform-size/]. `normal` let each
     * face's own ascent and descent decide how tall a line is: the same
     * two-line alert was 60px in dark and 78px in nostromo. A number, so it
     * scales with the font size of whatever inherits it. One-line boxes —
     * controls and table rows, css/components.css — read the tighter
     * --kp-control-line-height instead. */
        line-height: var(--kp-line-height, 1.5);
    }

    h1,
    h2,
    h3 {
        font-family: var(--theme-font-display, var(--theme-font-body, ui-sans-serif, system-ui, sans-serif));
    }

    /* A heading's size is the package's in every theme [scope-87, option B
     * of research/uniform-size/]: the browser's own steps, in em as the
     * browser writes them, at titanium's heading line height — the median
     * theme's [scope-82]. A register keeps the face, weight, case, letter
     * spacing and ornaments; gates/box-metrics.test.mjs refuses a register
     * that sets a heading's font size, line height, block padding or
     * height. */
    h1 {
        font-size: var(--kp-h1-size, 2em);
    }

    h2 {
        font-size: var(--kp-h2-size, 1.5em);
    }

    h3 {
        font-size: var(--kp-h3-size, 1.17em);
    }

    h4 {
        font-size: var(--kp-h4-size, 1em);
    }

    h5 {
        font-size: var(--kp-h5-size, 0.83em);
    }

    h6 {
        font-size: var(--kp-h6-size, 0.67em);
    }

    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
        line-height: var(--kp-heading-line-height, 1.1);
    }

    /* A surface's headline: the display size every theme already declared,
     * at titanium's display line height. */
    [data-kp-surface] h1 {
        font-size: var(--kp-text-display, clamp(2rem, 4vw, 3rem));
        line-height: var(--kp-display-line-height, 1.08);
    }

    /* ── Theme flourishes ─────────────────────────────────────────────── */

    [data-theme='formal'] h1,
    [data-theme='formal'] h2 {
        letter-spacing: -0.01em;
    }

    [data-theme='cyberpunk'] ::selection {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    [data-theme='cyberpunk'] .glow-primary {
        text-shadow:
            0 0 6px hsl(from var(--primary) h s l / 0.9),
            0 0 24px hsl(from var(--primary) h s l / 0.5),
            0 0 64px hsl(from var(--primary) h s l / 0.3);
    }

    [data-theme='cyberpunk'] .glow-accent {
        text-shadow:
            0 0 6px hsl(from var(--accent) h s l / 0.9),
            0 0 24px hsl(from var(--accent) h s l / 0.5);
    }

    [data-theme='cyberpunk'] .glow-card {
        box-shadow:
            0 0 0 1px hsl(from var(--primary) h s l / 0.35),
            0 0 24px hsl(from var(--primary) h s l / 0.15),
            inset 0 0 32px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    .gradient-text {
        background: linear-gradient(120deg, var(--primary), var(--ring) 60%, var(--primary));
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
    }

    [data-theme='cyberpunk'] .gradient-text {
        background: linear-gradient(120deg, var(--primary), var(--accent), var(--primary));
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
    }

    /* Plain-CSS equivalent of kp-soft's `@apply bg-background text-foreground`
   on body (the Tailwind @apply lines themselves are not part of this
   package). */
    body {
        background-color: var(--background);
        color: var(--foreground);
    }

    /* The cross-fade when a visitor switches theme. Guarded, because DI7 asks
   for it and because a 400ms colour sweep across the whole page is exactly
   the kind of motion someone turns that setting on to avoid. */
    @media (prefers-reduced-motion: no-preference) {
        body {
            /* Twice the theme's own duration: a full-page sweep should be
         * slower than a button, but it is still the incoming theme that
         * decides how it arrives. Terminal snaps, pastel eases slowly. */
            transition:
                background-color calc(var(--fx-duration, 200ms) * 2) var(--fx-ease, ease),
                color calc(var(--fx-duration, 200ms) * 2) var(--fx-ease, ease);
        }
    }

    /* The two-channel focus ring [DI2].
 *
 * Two rings, adjacent: the box-shadow is the inner ring (--focus-ring,
 * the theme's foreground), the outline the outer one
 * (--focus-ring-contrast, its background), and the outline's offset is
 * exactly the width of the inner ring so the two touch. Whatever the element sits on, one of the two
 * colours contrasts with it, and they contrast with each other — which is
 * what a single ring cannot promise. Before this, the focus indicator was
 * whatever the browser drew, and on a primary button in three themes that
 * was a ring of the same luminance as the button.
 *
 * :focus-visible rather than :focus, so a mouse click does not leave a
 * ring behind while the keyboard still gets one.
 */
    :focus-visible {
        /* The same token the components read; the global ring ignored it [KT6]. */
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        /* The offset is the width of the inner ring, so the two touch — one
     * knob rather than two literals that can drift, and the same knob
     * .kp-button's composed ring reads [AR30, KT6]. Default 2px, which is
     * what both lines said before. */
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    /* DI6, actually reaching the browser.
 *
 * Every theme declares --color-scheme, the token gate has checked that
 * since L3, and the compliance table has read pass ever since. But a
 * custom property named color-scheme is not the color-scheme property:
 * nothing applied it, so the browser went on drawing light scrollbars,
 * light form internals and a light autofill highlight over the three dark
 * themes. Found on 2026-09-04 by the first test to open a fixture in a
 * real browser — which is the whole argument for AR14's bare pages.
 */
    :root {
        color-scheme: var(--color-scheme);
    }

    /* ------------------------------------------------------------------
   Element-level rules [L6].

   Everything below styles plain HTML, not classes. A theme that leaves
   these to the browser is not complete: the browser's own link blue
   scores 1.99 against the dark theme's background, 2.09 against
   cyberpunk's and 2.06 against terminal's, where 4.5 is the floor. A
   consumer who takes this stylesheet and writes ordinary markup should
   get a themed page, not a themed page with browser-default holes.
   ------------------------------------------------------------------ */

    /* Links [TH31]. Underlined, always: colour is never the only carrier
   (DI4), and a link that is only a colour disappears for anyone who
   cannot see that colour. */
    a {
        color: var(--link);
        text-decoration: underline;
        text-underline-offset: 0.15em;
    }

    a:visited {
        color: var(--link-visited);
    }

    a:hover {
        text-decoration-thickness: 2px;
    }

    /* Text selection [TH31]. The primary pair, which the contrast gate
   already holds at AA — the browser's default highlight ignores the
   theme entirely and can land unreadably on a dark ground. */
    ::selection {
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* Ordinary text elements [TH32]. */
    code,
    kbd,
    samp,
    pre {
        font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
    }

    code,
    kbd,
    samp {
        background: var(--muted);
        color: var(--foreground);
        padding: 0.1em 0.35em;
        border-radius: calc(var(--radius, 0.5rem) / 2);
        font-size: 0.9em;
    }

    kbd {
        border: 1px solid var(--border-strong);
        /* A key looks pressable; a code span does not. */
        box-shadow: 0 1px 0 var(--border-strong);
    }

    pre {
        background: var(--muted);
        color: var(--foreground);
        padding: 0.75rem 1rem;
        border-radius: var(--radius, 0.5rem);
        /* Long lines scroll inside the block instead of widening the page:
       SC 1.4.10 asks for no two-dimensional scrolling of the document. */
        overflow-x: auto;
    }

    pre code {
        background: none;
        padding: 0;
    }

    mark {
        background: var(--warning);
        color: var(--warning-foreground);
        padding: 0 0.15em;
    }

    /* A surface paints its own ground [TH116, AR38]. The generated hero block
       in themes.css remaps what a component reads inside
       [data-kp-surface='hero']; this is the rule that paints it — without it
       the remap changes every colour but the ground, which is what the
       critic's blocking objection to AR38 was about. The app surface paints
       the theme's own background, so a page with both is two grounds. */
    /* The hidden attribute wins over every display rule in the package
       [KT13]: a layout class (`.kp-stack`, `display: flex`) beat it on the
       compare page and a button frame beat it in the synthwave demo. The
       rule every reset carries, and this package did not. */
    [hidden] {
        display: none !important;
    }

    [data-kp-surface] {
        background-color: var(--background);
        color: var(--foreground);
    }

    /* `data-kp-surface-align="center"` sets a surface's content on its
       middle — a landing hero, an empty state — and is off unless a page
       asks for it [Kenny, 2026-09-15]. The text centres; a narrower child (a
       prose measure) takes auto margins, which centre it in a block surface
       and in a flex column alike; a row keeps its full width and centres its
       controls instead — auto margins would shrink a wrapping row to its
       widest control in firefox and stack the buttons. A row modifier that
       says otherwise (`.kp-row--between`) sits in a later layer and wins. */
    [data-kp-surface][data-kp-surface-align='center'] {
        text-align: center;
    }

    [data-kp-surface][data-kp-surface-align='center'] > :not(.kp-row) {
        margin-inline: auto;
    }

    [data-kp-surface][data-kp-surface-align='center'] .kp-row {
        justify-content: center;
    }

    /* A divider between surfaces [S45, TH121]: the quiet answer is room —
       one step of the spacing scale — so a section and what follows never
       touch (the rhythm gate measured 0px under formal); a register may
       paint a tear across it. */
    [data-kp-divider] {
        display: block;
        block-size: var(--kp-space-xl);
    }

    blockquote {
        margin-inline-start: 0;
        padding-inline-start: 1rem;
        border-inline-start: 3px solid var(--border-strong);
        color: var(--muted-foreground);
    }

    /* A rule between blocks. The browser draws <hr> in its own grey — colour
 * AND border, 128,128,128 in Chromium and Firefox alike — which the
 * foreign-colour test found on every fixture: the one element on the page
 * that wore no theme at all [KT8]. Both are the theme's now. */
    hr {
        color: inherit;
        border: 0;
        border-block-start: 1px solid var(--border);
        margin-block: 1rem;
    }

    ::marker {
        color: var(--muted-foreground);
    }

    /* The browser's own hooks [TH34]. These are the surfaces a stylesheet
   cannot repaint — it can only tell the browser which colours to use. */
    :root {
        accent-color: var(--primary);
        caret-color: var(--foreground);
    }

    ::placeholder {
        color: var(--muted-foreground);
        opacity: 1; /* Firefox dims placeholders by default, on top of the colour. */
    }

    :disabled {
        cursor: not-allowed;
    }

    /* `:user-invalid`, not `:invalid` [fix-74]: an empty required field is
       invalid the moment the page loads, and kyu's login opened with its
       token field already red. The user-invalid state waits until someone
       has touched the field or tried to submit. */
    input:user-invalid,
    select:user-invalid,
    textarea:user-invalid {
        border-color: var(--destructive);
    }

    /* ------------------------------------------------------------------
   One signature per theme [HA2].

   Kenny's brief: motion should give a theme extra flavour, and a formal
   theme should be more careful with it than cyberpunk. "Less is more,
   but not always."

   So each theme gets exactly one gesture of its own, and three of them
   answer "none" on purpose — that is a character too. Everything here
   sits inside a reduced-motion guard, and none of it opposes its own
   direction fast enough to approach the flash threshold; check-motion.mjs
   measures both and reads this file.

   Cyberpunk is absent: it already has a whole register of its own, which
   is its signature.
   ------------------------------------------------------------------ */

    @media (prefers-reduced-motion: no-preference) {
        /* formal — lifted to a register [S48, LIFT_PLAN row 16]: the rule
       under a heading is now the register's own `rule` hook, drawn when
       the heading scrolls into view instead of firing on every load.
       The block that stood here animated the very same `h2::after` the
       register uses, and an animation outranks the register's armed
       `scaleX(0)`, so the rule painted itself drawn before it was ever
       seen. Removed, as academia's was for the same reason. */

        /* light and dark — the restrained pair. Their signature is that a
       raised surface lifts under the cursor, which --fx-lift already
       carries; nothing is added here. */

        /* pastel — the only theme that overshoots. A badge arrives with a
       small bounce, which its easing does for free. */
        [data-theme='pastel'] .kp-badge {
            animation: kp-settle var(--fx-duration) var(--fx-ease) both;
        }

        /* forest — the contour field does not move: it is a static page background
       (see the forest texture rule above). */

        /* blueprint — lifted to a register [S48, LIFT_PLAN row 6]: the
       ruled line under a heading is now the register's own `rule` hook,
       drawn when the heading enters the viewport. The block that stood
       here animated the same `h2::after` the hook uses, which is how it
       outranked formal's armed start state; removed with the lift. */

        /* deco — lifted to a register [S48, LIFT_PLAN row 8]: the double
       gold rule under a heading is now the register's own `rule` hook,
       drawn when the heading enters the viewport. The block that stood
       here animated the same `h2::after` the hook uses, the conflict
       formal's lift measured; removed with the lift. */

        /* academia — lifted to a register [S48, LIFT_PLAN row 10]: the
       gesture is now the register's own headline and rule draw, gated on
       the heading entering the viewport rather than firing on every load.
       Two of them ran at once until this went. */

        /* woodblock — lifted to a register [S48]: the hanko after a heading
       is the register's own, and this block animated the same `h1::after`
       the `rule` hook uses, the conflict formal's lift measured.
       Removed with the lift. */

        /* solstice — an ember: the primary colour warms and cools once when a
       card appears. Slow, small, and never repeated. */
        [data-theme='solstice'] [data-slot='card'] {
            animation: kp-ember calc(var(--fx-duration) * 6) var(--fx-ease) both;
        }
    }

    @keyframes kp-slide-in {
        from {
            translate: -6px 0;
        }

        to {
            translate: 0 0;
        }
    }

    @keyframes kp-rule-in {
        from {
            transform: scaleX(0);
            transform-origin: left;
        }

        to {
            transform: scaleX(1);
            transform-origin: left;
        }
    }

    @keyframes kp-settle {
        from {
            transform: scale(0.92);
        }

        to {
            transform: scale(1);
        }
    }

    @keyframes kp-blink {
        0%,
        49% {
            opacity: 1;
        }

        50%,
        100% {
            opacity: 0;
        }
    }

    @keyframes kp-drift {
        from {
            background-position: 0 0;
        }

        to {
            background-position: 360px 360px;
        }
    }

    @keyframes kp-ember {
        0% {
            box-shadow: 0 0 0 0 transparent;
        }

        40% {
            box-shadow: 0 0 12px 0 var(--primary);
        }

        100% {
            box-shadow: 0 0 0 0 transparent;
        }
    }
}

/* @kp-soft/themes — css/_density.css
   Concatenated into css/themes.css after the authored rules.

   The compact density mode [TH105]. Set `data-density="compact"` on any
   element and everything inside it tightens: the spacing scale drops one
   step's worth and the control height comes down.

   Unlayered and after the token blocks, for the same reason css/_print.css
   is: AR17 left the theme token blocks unlayered, and unlayered CSS beats
   layered CSS whatever the specificity, so a layered override of
   --kp-space-md would lose to every theme's own declaration.

   Every value is a knob with the compact value as its default, so a
   consumer retunes the density without restating the whole block (KT6).

   The mode reaches only what reads the scale. A register that restates a
   spacing or a pinned control height as a fixed length (`gap: 1rem`)
   switches the mode off for its theme, which is how eighteen themes had a
   compact form as roomy as the default one. A register writes its own
   value as a multiple of a step (`calc(var(--kp-space-lg) * 1.1)`): the
   same length at the default density, and tighter under this block. A
   control's or a table row's height is not a register's to pin at all
   since scope-80: css/components.css derives both from
   --kp-control-height, and gates/box-metrics.test.mjs refuses the pin.
   tests/density-compact.spec.mjs holds it in every theme.

   The floor is not negotiable: --kp-control-height stays at 1.75rem
   (28px at a 16px root), above the 24px WCAG 2.5.8 asks of a pointer
   target, and that is why it is not a knob. */

[data-density='compact'] {
    --kp-space-xs: var(--kp-compact-xs, 0.125rem);
    --kp-space-sm: var(--kp-compact-sm, 0.25rem);
    --kp-space-md: var(--kp-compact-md, 0.5rem);
    --kp-space-lg: var(--kp-compact-lg, 0.75rem);
    --kp-space-xl: var(--kp-compact-xl, 1rem);
    --kp-space-2xl: var(--kp-compact-2xl, 1.5rem);
    --kp-control-height: 1.75rem;
}

/* @kp-soft/themes — css/_print.css
   Concatenated into css/themes.css after the authored rules.

   This block sits OUTSIDE @layer kp.base on purpose, and the purpose is
   measured. AR17 put the authored rules in a cascade layer but left the
   theme token blocks unlayered, and unlayered CSS beats layered CSS
   whatever the specificity. So a layered `--background: white` lost to
   every theme's own `--background`, and printing a dark theme came out
   dark: measured on 2026-09-06 as hsl(258, 40%, 6%) where white was
   expected, in both browsers, on every one of the 24 themes. It was
   introduced by the layer wrap in R0 and found twice independently while
   building R3 and R4.

   Unlayered, it wins by source order, which is what TH36 always meant.
   Nothing else in this file may be layered either, for the same reason. */

/* The words that exist only for paper are off the screen (before the print block, so its rules win by order). */
.kp-print-stamp,
.kp-print-state,
.kp-print-title {
    display: none;
}

/* Print [TH36]. Paper has no theme: ink is black, the ground is white,
   and the decorative layers cost toner without carrying meaning. */
@media print {
    :root {
        color-scheme: light;
        --background: hsl(0, 0%, 100%);
        --foreground: hsl(0, 0%, 0%);
    }

    /* The texture layer is body::after. The first version of this rule
 * hid body::before, which carries nothing, so the texture printed
 * for two versions while the guide promised otherwise [KT6]. */
    body::after {
        display: none;
    }

    a {
        color: inherit;
    }

    /* A printed page cannot be clicked, so the address has to be on it. */
    a[href^='http']::after {
        content: ' (' attr(href) ')';
        font-size: 0.85em;
        word-break: break-all;
    }

    /* --- Lists that print well [kpadopt6-media; print-checklist] --------------
       Paper has no controls and no colour: the sheet is black on white, a tone is
       a word or a border and never a fill, and a checkbox is a box a pen can tick.
       Everything here is only @media print, so the screen never changes. The same
       rules, with this at-rule turned into `@media all`, are what the demo's print
       preview shows. Kenny, 2026-10-17: a ticked item prints with a filled box and
       its text kept. Knobs: --kp-print-box (1.1em, never under 4 mm). */
    :root {
        print-color-adjust: economy;
        -webkit-print-color-adjust: economy;
    }

    /* Hidden on paper: navigation, toolbars, toasts, tooltips, menus, the selection bar, floating buttons, buttons, the
       shortcut sheet; and whatever the page marks. `data-kp-print="include"` keeps one of them. */
    :is(
        .kp-sidenav,
        .kp-nav-bar,
        .kp-nav,
        .kp-toasts,
        .kp-tooltip,
        .kp-popover,
        .kp-menu,
        .kp-selection-bar,
        .kp-shortcuts,
        .kp-skip-link,
        .kp-list-toolbar,
        .kp-button,
        .kp-icon-button,
        [data-kp-print='exclude']
    ):not([data-kp-print='include']) {
        display: none !important;
    }

    .kp-checklist,
    .kp-checklist * {
        animation: none !important;
        transition: none !important;
        box-shadow: none !important;
        text-shadow: none !important;
        filter: none !important;
        color: #000 !important;
        background-image: none !important;
    }

    .kp-checklist {
        border: 0;
        background: #fff;
    }

    /* The bar (Check all, Clear checked, the count), the live region and the busy card carry nothing a sheet needs. */
    .kp-checklist__bar,
    .kp-checklist__live,
    .kp-checklist .kp-datatable__busy-card {
        display: none !important;
    }

    .kp-checklist__body {
        min-block-size: 0 !important;
        padding: 0;
        border: 0;
        background: none;
    }

    .kp-checklist[data-kp-print-groups='columns'] .kp-checklist__body {
        column-count: 2;
        column-gap: 10mm;
    }

    .kp-checklist__group {
        break-inside: auto;
        margin: 0 0 4mm;
        padding: 0;
        border: 0;
        background: none;
    }

    /* A group's heading stays with its first two items and carries a rule. */
    .kp-checklist__head {
        break-after: avoid;
        margin: 0 0 1.5mm;
        padding: 0 0 1mm;
        border: 0;
        border-bottom: 1pt solid #000;
        background: none;
        font-weight: 700;
    }

    .kp-checklist__item {
        break-inside: avoid;
        border: 0;
        background: none;
    }

    .kp-checklist__item:nth-child(-n + 2) {
        break-before: avoid;
    }

    .kp-checklist__row {
        min-block-size: 0;
        padding-block: 1.2mm;
        background: none !important;
    }

    .kp-checklist[data-kp-print-notes-lines] .kp-checklist__row {
        padding-block: 2.2mm;
        border-bottom: 0.5pt dotted #000;
    }

    /* A ticked item keeps its text; it is not struck through unless the list asks. */
    .kp-checklist__item[data-kp-checklist-checked] .kp-checklist__label {
        text-decoration: none;
        opacity: 1;
    }

    .kp-checklist[data-kp-print-done='strike'] .kp-checklist__item[data-kp-checklist-checked] .kp-checklist__label {
        text-decoration: line-through;
    }

    .kp-checklist[data-kp-print-done='hide'] .kp-checklist__item[data-kp-checklist-checked],
    .kp-checklist[data-kp-print-done='hide'] .kp-checklist__group[data-kp-checklist-done] {
        display: none !important;
    }

    .kp-checklist[data-kp-print-notes='hide'] .kp-checklist__detail {
        display: none !important;
    }

    .kp-checklist__detail {
        opacity: 1;
    }

    /* The real checkbox is replaced by a drawn box: browsers do not print a page's custom check art reliably. */
    .kp-checklist .kp-checklist__check.kp-field__check {
        appearance: none;
        -webkit-appearance: none;
        display: inline-grid;
        flex: none;
        place-content: center;
        box-sizing: border-box;
        inline-size: max(var(--kp-print-box, 1.1em), 4mm);
        block-size: max(var(--kp-print-box, 1.1em), 4mm);
        margin: 0;
        padding: 0;
        border: 1.5pt solid #000 !important;
        border-radius: 0;
        outline: none;
        background: #fff !important;
        transform: none;
    }

    .kp-checklist[data-kp-print-box='round'] .kp-checklist__check.kp-field__check {
        border-radius: 50%;
    }

    .kp-checklist .kp-checklist__check.kp-field__check::before,
    .kp-checklist .kp-checklist__check.kp-field__check::after {
        content: none;
    }

    .kp-checklist .kp-checklist__check.kp-field__check:checked::before {
        content: '\2713';
        position: static;
        inset: auto;
        inline-size: auto;
        block-size: auto;
        margin: 0;
        border: 0;
        border-radius: 0;
        background: none !important;
        clip-path: none;
        mask: none;
        transform: none;
        font-size: 1em;
        font-weight: 700;
        line-height: 1;
        text-align: center;
    }

    /* In a list, a link shows its words and no address; elsewhere the address still follows the link. */
    .kp-checklist:not([data-kp-print-links='url']) a[href]::after {
        content: none;
    }

    /* The words a sheet needs when the list has no rows: why, and the title and the date. */
    .kp-print-state,
    .kp-print-title {
        display: block;
        margin: 0 0 3mm;
        font-weight: 700;
    }

    .kp-print-state {
        padding: 6mm 0;
        font-size: 1.25em;
    }

    .kp-print-title {
        font-size: 1.5em;
    }

    .kp-checklist__empty {
        display: block;
        padding: 6mm 0;
        border: 0;
        background: none;
        font-size: 1.25em;
        font-weight: 700;
    }

    .kp-checklist__empty[hidden] {
        display: none !important;
    }

    .kp-print-stamp {
        display: block;
        position: fixed;
        inset-block-end: 0;
        inset-inline: 0;
        margin: 0;
        padding-block-start: 1.5mm;
        border-top: 0.5pt solid #000;
        font-size: 0.8em;
    }
}

/* The sheet itself: A4, a 15 mm margin. The printer dialog still overrides it. */
@page {
    size: A4;
    margin: 15mm;

    /* A printed invitation keeps the QR code and its link and drops the buttons [kpadopt6]. */
    .kp-qr__actions,
    .kp-qr__warn {
        display: none;
    }
}

/* ---- css/components.css ---- */
@layer kp.components {
    /* Component styles [T1, L4].
 *
 * Separate from themes.css on purpose: a consumer who only wants the
 * palette takes themes.css and is done. This file is for the consumers
 * who also take the components, and every rule in it reads tokens rather
 * than colours, so it inherits whatever theme is active.
 *
 * Import order: themes.css first, this after.
 */

    /* --- The theme picker ---------------------------------------------- */

    /* The swatch previews a theme without activating it, by wearing that
 * theme's own token block. `data-theme` works on any element, not only on
 * <html>, so the two custom properties below resolve to the previewed
 * theme's colours — the live ones, not a copy [AR11]. */
    .kp-swatch {
        display: inline-block;
        inline-size: 1rem;
        block-size: 1rem;
        flex: none;
        border-radius: 50%;
        border: 1px solid var(--border-strong);
        background: linear-gradient(135deg, var(--background) 50%, var(--primary) 50%);
    }

    [data-kp-theme-picker] {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-picker-gap, 0.25rem);
    }

    /* A picker written as a list is a list of options, not a bulleted list
       [gap-12]: the options lose the browser's 40px indent and its markers.
       `:where` keeps this at one attribute's weight, so .kp-menu — which is
       a list too, later in this file — still sets its own padding. */
    :where(ul, ol)[data-kp-theme-picker] {
        padding-inline-start: 0;
        list-style: none;
    }

    /* Grouped light and dark [TH63]. A group is a list item that presents a
 * small label and its own list, so a flat picker becomes two short rows
 * with a title each, and a menu becomes two sections with a rule between
 * them. The label is aria-hidden because the inner list carries it as
 * its accessible name; a screen reader hears "Light, list, 6 items". */
    [data-kp-theme-picker] .kp-theme-group {
        display: flex;
        flex-direction: column;
        gap: var(--kp-picker-gap, 0.25rem);
        flex-basis: 100%;
        list-style: none;
        margin: 0;
        padding: 0;
    }

    .kp-theme-group__list {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-picker-gap, 0.25rem);
        list-style: none;
        margin: 0;
        padding: 0;
    }

    .kp-theme-group__label {
        display: block;
        font-size: var(--kp-picker-group-size, 0.6875rem);
        font-weight: 600;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* The second group starts with a rule: a separator, not a gap. */
    .kp-theme-group + .kp-theme-group {
        margin-block-start: var(--kp-picker-gap, 0.25rem);
        padding-block-start: var(--kp-picker-gap, 0.25rem);
        border-block-start: 1px solid var(--border);
    }

    [data-kp-theme-picker] [data-kp-theme] {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.375rem 0.625rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        font: inherit;
        cursor: pointer;
    }

    /* Every transition in this file takes its timing from the theme, not from
 * a number typed here [HA2]. --fx-duration and --fx-ease were declared by
 * all eleven themes and used by nothing; the values differed and the
 * behaviour did not. Terminal steps rather than eases, pastel overshoots,
 * formal is brisk — that is the theme's handwriting, and
 * it costs no extra CSS. */
    @media (prefers-reduced-motion: no-preference) {
        [data-kp-theme-picker] [data-kp-theme] {
            transition:
                background-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                border-color var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    /* Hover and the keyboard highlight are a WASH OF THE INK over whatever
 * surface they sit on — --kp-highlight, default the foreground at 8% —
 * not --accent. Seven rules read --accent for this until 3.1.0, and in
 * every theme whose accent is a colour rather than a tint (brutalism's
 * lavender, deco's emerald, woodblock's beni) a highlighted row turned that
 * colour. Kenny saw it on the showcase [KT8]. A wash has no hue of its
 * own, so it is quiet in all twenty-four by construction; a theme that
 * wants more sets the knob. */
    [data-kp-theme-picker] [data-kp-theme]:hover {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    /* The selected option is marked twice over: the border carries it for
 * everyone, and the check mark carries it for anyone who cannot see the
 * border's colour [DI4]. Colour alone would be the only channel. */
    /* --selected is a boundary colour, gated at 3:1 against the surfaces it
 * is drawn on [DI1]. It is not a gated text background, so it stays a
 * border here: filling the button with it would put --card-foreground on
 * a pair nothing measures. */
    [data-kp-theme-picker] [data-kp-theme][data-selected='true'],
    [data-kp-theme-picker] [data-kp-theme].is-selected {
        border-color: var(--selected);
        box-shadow: inset 0 0 0 1px var(--selected);
    }

    [data-kp-theme-picker] [data-kp-theme][data-selected='true']::after,
    [data-kp-theme-picker] [data-kp-theme].is-selected::after {
        content: var(--kp-glyph-check, '✓');
        font-size: 0.875em;
    }

    [data-kp-theme-status] {
        margin: 0.5rem 0 0;
        color: var(--destructive);
        font-size: var(--kp-theme-status-size, 0.875rem);
    }

    /* --- Showing data [TH33] --------------------------------------------
 *
 * Six patterns that are not components — nobody imports a "URL" — but
 * that every data-heavy page rewrites badly. kyu hand-wrote three of
 * them. The failures they prevent are specific: a URL that widens the
 * page instead of wrapping, and numbers that jitter between rows because
 * the digits are not the same width.
 */

    /* A long URL or identifier wraps anywhere rather than pushing the page
 * sideways — SC 1.4.10 again, and the reason kyu's dashboard scrolled. */
    .kp-url,
    .kp-id {
        overflow-wrap: anywhere;
        word-break: break-word;
    }

    .kp-id {
        font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
        font-size: 0.9em;
    }

    /* Tabular numerals: same-width digits, so a column of numbers lines up
 * and does not shimmer as values change. */
    .kp-numeric,
    .kp-timestamp {
        font-variant-numeric: tabular-nums;
        font-feature-settings: 'tnum';
    }

    .kp-timestamp {
        color: var(--muted-foreground);
    }

    /* A masked value keeps its shape without claiming to be the real one. */
    .kp-masked {
        font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
        letter-spacing: 0.15em;
        color: var(--muted-foreground);
    }

    /* One line, ellipsis, and the full text still reachable — a truncation
 * without a title attribute hides data rather than shortening it. */
    .kp-truncate {
        display: block;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        max-width: 100%;
    }

    /* An empty state says the list is empty; a blank area says the page is
 * broken. */
    .kp-empty {
        padding: 1.5rem;
        border: 1px dashed var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        color: var(--muted-foreground);
        text-align: center;
    }

    /* --- A state word that keeps its width [scope-143] -------------------- */

    /* A word that changes with its state ("Running", "Stopped", "in 3 min")
 * is as wide as the widest word it can show, so nothing beside it moves
 * when it changes. The words are listed in `data-kp-words`, one per line
 * (`&#10;` between them in markup); an invisible line of no height holds
 * the width. */
    .kp-state-word {
        display: inline-flex;
        flex-direction: column;
        font-variant-numeric: tabular-nums;
        vertical-align: baseline;
    }

    .kp-state-word::after {
        content: attr(data-kp-words);
        block-size: 0;
        overflow: hidden;
        visibility: hidden;
        white-space: pre;
    }

    .kp-state-word--center {
        align-items: center;
        text-align: center;
    }

    /* --- The page's shell [TH36] ---------------------------------------- */

    /* The skip link is visible only when focused, and then it must be
 * unmissable: it is the first thing a keyboard user meets on the page. */
    .kp-skip-link {
        position: absolute;
        inset-inline-start: 0.5rem;
        inset-block-start: -100%;
        z-index: var(--kp-z-skip, 100);
        padding: 0.5rem 0.875rem;
        border-radius: var(--radius, 0.5rem);
        background: var(--primary);
        color: var(--primary-foreground);
        text-decoration: underline;
    }

    .kp-skip-link:focus {
        inset-block-start: 0.5rem;
    }

    /* --- Page header [scope-143] ------------------------------------------ */

    /* A page's title and its one-sentence description on the left; what acts
 * on the whole page on the right: secondary buttons, ONE primary, and an
 * overflow menu last (a `.kp-button` that says "More ▾", opening a
 * `.kp-popover` with a `.kp-menu`). On a narrow page it reads top to
 * bottom. */
    .kp-page-header {
        container: kp-page-header / inline-size;
    }

    .kp-page-header__inner {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: start;
        gap: var(--kp-space-sm, 0.5rem) var(--kp-space-lg, 1.5rem);
    }

    .kp-page-header__title {
        margin: 0;
    }

    .kp-page-header__description {
        max-inline-size: 70ch;
        margin: var(--kp-space-xs, 0.25rem) 0 0;
        color: var(--muted-foreground);
    }

    .kp-page-header__actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-page-header__actions > .kp-button {
        white-space: nowrap;
    }

    /* The overflow menu hangs under its button towards the start, so it
 * stays on the page from a header's far end. */
    .kp-page-header__actions > .kp-popover {
        position-area: block-end span-inline-start;
    }

    @container kp-page-header (max-width: 40rem) {
        .kp-page-header__inner {
            grid-template-columns: minmax(0, 1fr);
        }

        /* The buttons from the left, wrapping; the primary on a line of
 * its own, full width and first, the rest beside each other under it. */
        .kp-page-header__actions {
            justify-content: flex-start;
        }

        .kp-page-header__actions > .kp-button--primary {
            flex: 1 1 100%;
            order: -1;
        }
    }

    /* ====================================================================
 * The concept demo's own pieces [S46, round six]: laurels, a side note,
 * a platforms line and a spec sheet. Quiet by default — a list, a note,
 * a row, a card — so a theme without an answer shows them plainly and a
 * register may dramatise them.
 * ==================================================================== */
    .kp-laurels {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem 2rem;
        margin: 0;
        padding: 0;
        list-style: none;
        font-size: var(--kp-text-sm);
        color: var(--muted-foreground);
    }
    .kp-laurels b {
        display: block;
        color: var(--foreground);
    }
    .kp-side-note {
        margin: 0;
        font-size: var(--kp-text-xs);
        color: var(--muted-foreground);
    }
    .kp-platforms {
        display: flex;
        flex-wrap: wrap;
        gap: 0.25rem 1.5rem;
        font-size: var(--kp-text-xs);
        color: var(--muted-foreground);
    }
    .kp-spec {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        padding: 1rem 1.25rem;
        font-size: var(--kp-text-sm);
        line-height: 1.7;
    }
    .kp-spec dl {
        margin: 0;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        gap: 0.15rem 1.2rem;
    }
    .kp-spec dt {
        color: var(--muted-foreground);
    }
    .kp-spec dd {
        margin: 0;
        overflow-wrap: anywhere;
    }
    .kp-spec__swatch {
        display: inline-block;
        inline-size: 0.9em;
        block-size: 0.9em;
        vertical-align: -0.1em;
        margin-inline-end: 0.4em;
        border: 1px solid var(--border-strong);
    }
    .kp-spec__swatch[data-token='surface-hero-bg'] {
        background: var(--surface-hero-bg);
    }
    .kp-spec__swatch[data-token='background'] {
        background: var(--background);
    }
    .kp-spec__swatch[data-token='destructive'] {
        background: var(--destructive);
    }
    .kp-spec__swatch[data-token='accent'] {
        background: var(--accent);
    }
    .kp-spec__swatch[data-token='chart-4'] {
        background: var(--chart-4);
    }
    .kp-spec__swatch[data-token='foreground'] {
        background: var(--foreground);
    }
    .kp-spec__swatch[data-token='card'] {
        background: var(--card);
    }
    .kp-spec__swatch[data-token='card-foreground'] {
        background: var(--card-foreground);
    }
    .kp-spec__swatch[data-token='primary'] {
        background: var(--primary);
    }
    .kp-spec__swatch[data-token='primary-foreground'] {
        background: var(--primary-foreground);
    }
    .kp-spec__swatch[data-token='secondary'] {
        background: var(--secondary);
    }
    .kp-spec__swatch[data-token='muted'] {
        background: var(--muted);
    }
    .kp-spec__swatch[data-token='muted-foreground'] {
        background: var(--muted-foreground);
    }
    .kp-spec__swatch[data-token='border'] {
        background: var(--border);
    }
    .kp-spec__swatch[data-token='border-strong'] {
        background: var(--border-strong);
    }
    .kp-spec__swatch[data-token='input'] {
        background: var(--input);
    }
    .kp-spec__swatch[data-token='selected'] {
        background: var(--selected);
    }
    .kp-spec__swatch[data-token='surface-hero-fg'] {
        background: var(--surface-hero-fg);
    }
    .kp-spec__swatch[data-token='surface-hero-fg-2'] {
        background: var(--surface-hero-fg-2);
    }
    .kp-spec__swatch[data-token='surface-hero-muted'] {
        background: var(--surface-hero-muted);
    }
    .kp-spec__swatch[data-token='surface-hero-border'] {
        background: var(--surface-hero-border);
    }
    .kp-spec__swatch[data-token='surface-hero-primary'] {
        background: var(--surface-hero-primary);
    }
    .kp-spec__swatch[data-token='surface-hero-primary-foreground'] {
        background: var(--surface-hero-primary-foreground);
    }
    .kp-spec__swatch[data-token='surface-hero-danger'] {
        background: var(--surface-hero-danger);
    }
    .kp-spec__swatch[data-token='surface-hero-card'] {
        background: var(--surface-hero-card);
    }
    .kp-spec__swatch[data-token='success'] {
        background: var(--success);
    }
    .kp-spec__swatch[data-token='warning'] {
        background: var(--warning);
    }
    .kp-spec__swatch[data-token='info'] {
        background: var(--info);
    }
    .kp-spec__swatch[data-token='link'] {
        background: var(--link);
    }
    .kp-spec__font[data-font='display'] {
        font-family: var(--theme-font-display);
    }
    .kp-spec__font[data-font='body'] {
        font-family: var(--theme-font-body);
    }
    .kp-spec__font[data-font='mono'] {
        font-family: var(--kp-mono, monospace);
    }
    .kp-footer {
        padding: 1.5rem clamp(1rem, 4vw, 3rem);
        border-top: 1px solid var(--border);
        color: var(--muted-foreground);
        font-size: var(--kp-footer-size, 0.875rem);
    }

    /* A footer column's heading: its size is the package's [scope-87],
     * titanium's 0.95rem taken to 15px. */
    .kp-footer h4 {
        font-size: var(--kp-footer-heading-size, 0.9375rem);
        line-height: var(--kp-heading-line-height, 1.1);
    }

    /* An error page is a message, not a wall: the destructive colour names
 * the failure, the body text explains it on the ordinary surface. */
    .kp-error {
        max-width: var(--kp-error-max-width, 60ch);
        margin: 3rem auto;
        padding: 0 1rem;
    }

    .kp-error h1 {
        color: var(--destructive);
        margin-bottom: 0.5rem;
    }

    /* ====================================================================
 * The seven base components [L7, TH1-TH7].
 *
 * One set of classes, used by both channels: the React components render
 * exactly these class names, so a page can mix the two and nothing
 * betrays which is which. That is what makes the side-by-side comparison
 * mean anything.
 *
 * Every colour is a token, and every token pair used here is in the
 * contrast gate. No component invents a colour.
 * ==================================================================== */

    /* The overflow floor, written once [TH113, AR32].
 *
 * Five inline-flex components that held a single unbroken value at its
 * full width and pushed the document sideways with it. Measured at 360px
 * before this rule: .kp-button 607, .kp-badge 485, .kp-tag 483,
 * .kp-health 581. A key, a hash or an id has no space to wrap at, so the
 * value has to be allowed to break rather than the layout.
 *
 * One rule the five share rather than five copies of it: AR32, and the
 * reason is that .kp-copyable already grew its own copy in 3.2.0 and the
 * other four did not inherit it. overflow-wrap is inherited, so the
 * anonymous flex item that carries the text gets it from here -- and
 * `anywhere` rather than `break-word` because only `anywhere` takes the
 * min-content contribution down, which is what a flex item's automatic
 * minimum size is measured against.
 *
 * .kp-icon-button is deliberately not in this list: it has a fixed size.
 */
    .kp-button,
    .kp-badge,
    .kp-tag,
    .kp-health,
    .kp-copyable {
        max-inline-size: 100%;
        overflow-wrap: anywhere;
    }

    /* --- Button [TH1] ---------------------------------------------------- */

    .kp-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        /* The height is the package's, in every theme [scope-80, option E of
     * research/uniform-size/]: a border-box floor on --kp-control-height,
     * one line height, the label centred in what is left. A register
     * keeps its inline padding, type, border and paint;
     * gates/box-metrics.test.mjs refuses a register that restates any of
     * the box's block metrics. min-height, not height: forced text spacing
     * must make this taller rather than clip the label [DI11]. The floor
     * follows the density mode down with --kp-control-height [TH105].
     *
     * The block padding is only what a label that wraps needs to keep off
     * the border, and never enough to lift a one-line button past the
     * floor: a quarter rem, or less where the floor has no room for it —
     * half of what the floor leaves around one line (`1lh`), less a
     * border of up to 3px. Option E's own mock had none, and a
     * two-line label touched its frame in brutalism, titanium and phantom. */
        box-sizing: border-box;
        min-height: var(--kp-control-height, 2.25rem);
        padding: var(--kp-control-padding-block, max(0px, min(var(--kp-space-xs, 0.25rem), (var(--kp-control-height, 2.25rem) - 1lh) / 2 - 3px)))
            0.875rem;
        border: 1px solid transparent;
        border-radius: var(--radius, 0.5rem);
        font: inherit;
        line-height: var(--kp-control-line-height, 1.25);
        cursor: pointer;
        background: var(--secondary);
        color: var(--secondary-foreground);
        border-color: var(--border-strong);
        /* --fx-shadow-offset is a hard, unblurred shadow the control casts
     * down and right — brutalism's signature [TH85]. 0px everywhere else,
     * which paints nothing: the knob is the only theme-shaped thing here. */
        box-shadow: var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
    }

    /* The theme's typeface on every other control the package draws
       [fix-28, scope-83]. A browser's own stylesheet gives a button, a
       checkbox, a range and a file input the SYSTEM font, not the page's:
       Kenny's FireDragon read his desktop's Fira Sans on these, Playwright's
       Firefox the generic sans-serif, and 39 of his 158 verdict hashes of
       2026-09-14 differed from the tools' for that reason alone. The family
       only, not the `font` shorthand: the size stays what each control
       measured before, so no glyph and no box moves in any theme.
       tests/control-font.spec.mjs forces a distinctive default and finds
       every control on the review pages that still shows it. */
    .kp-icon-button,
    .kp-nav__toggle,
    .kp-sidenav__toggle,
    .kp-field__check,
    .kp-switch__input,
    .kp-colorpicker input,
    input[type='file']:has(+ .kp-upload__zone) {
        font-family: inherit;
    }

    /* Two surfaces a theme may paint on, and nothing else [scope-16,
       scope-17, Kenny 2026-09-12]. Both approved concept demos of round
       seven put an oxide film along the control's edge AND a small reading
       above it, which is one surface more than a button's two
       pseudo-elements can carry — the spectral instrument already spends
       both on its brackets.

       Out of flow, so neither can move the control; `inset: 0` so the edge
       has the whole box to work with; and invisible until a register gives
       them something. Twenty-four themes never notice they are there,
       which is the same bargain `.kp-button__label` already makes. */
    /* The control is the containing block for both, which is what makes
       "out of flow" mean "inside this button" rather than "somewhere on
       the page". Without it the edge measured 1280px wide — the viewport —
       on the first run of tests/button-surfaces.spec.mjs. */
    .kp-button {
        position: relative;
    }

    .kp-button__edge,
    .kp-button__readout {
        position: absolute;
        pointer-events: none;
    }

    .kp-button__edge {
        inset: 0;
    }

    .kp-button__readout {
        inset-block-end: 100%;
        inset-inline-start: 0;
        white-space: nowrap;
        opacity: 0;
    }

    /* The button's own label, in its own element [S49, A7]: a theme that
       skews the button (phantom's demo does) sets the label upright
       again on this, and every other theme never notices it is there. */
    .kp-button__label {
        display: inline-flex;
        align-items: center;
        gap: inherit;
    }

    /* A marked accelerator letter stays in its label's text run [scope-57].
       In a flex row every child is an item and the row's gap goes between
       items, so `<span data-kp-key>S</span>ave` read "S ave" — half a rem
       inside a word, in every theme — and the space in "Save as" collapsed
       at the item's edge. A label that marks a letter is laid out as text
       instead: one line box, the letter an inline box inside it (retro still
       underlines it), centred both ways as the flex row was. An icon beside
       such a label floats to its own side with the row's gap as its margin;
       the float also swallows the markup's whitespace at the line's start,
       so the gap is exactly the one an unmarked button has. */
    .kp-button:has(> [data-kp-key]),
    .kp-button__label:has(> [data-kp-key]) {
        display: inline-block;
        align-content: center;
        text-align: center;
    }

    :is(.kp-button, .kp-button__label):has(> [data-kp-key])
        > :not([data-kp-key], .kp-button__edge, .kp-button__readout, .kp-button__label):has(~ [data-kp-key]) {
        float: inline-start;
        margin-inline-end: 0.5rem;
    }

    :is(.kp-button, .kp-button__label):has(> [data-kp-key])
        > [data-kp-key]
        ~ :not([data-kp-key], .kp-button__edge, .kp-button__readout, .kp-button__label) {
        float: inline-end;
        margin-inline-start: 0.5rem;
    }

    /* The focus ring composed with the offset shadow, not instead of it
 * [AR30, DI2].
 *
 * The focus indicator is two parts: an outline in --focus-ring-contrast
 * and an inner ring in --focus-ring (css/_rules.css, `:focus-visible`, in
 * @layer kp.base). The rule above sets box-shadow in @layer kp.components
 * for the brutalist offset, and a later layer wins whatever the
 * specificity — so on every button in every theme the inner half read
 * `0px 0px 0px 0px`, which paints nothing. Half a ring is exactly what
 * DI2's two-part design exists to prevent.
 *
 * Restated here with both layers, the ring first so it is not buried
 * under the offset. --kp-focus-ring-inner-width is the same knob the
 * global rule reads, so the two halves cannot drift apart [KT6].
 */
    .kp-button:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-button {
            transition:
                background-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                border-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                translate var(--fx-duration, 150ms) var(--fx-ease, ease);
        }

        /* --fx-lift is how far a control rises under the cursor. Many themes
     * answer 0px, which is not an oversight: formal, for one, does not
     * move things, it only changes its colour. */
        .kp-button:hover:not(:disabled) {
            translate: 0 calc(-1 * var(--fx-lift, 0px));
        }
    }

    .kp-button:hover:not(:disabled) {
        background: var(--secondary-hover);
    }

    .kp-button:active:not(:disabled) {
        background: var(--secondary-active);
    }

    .kp-button:disabled {
        background: var(--secondary-disabled);
        cursor: not-allowed;
        /* DI8 is Kenny's recorded decision that a disabled control may fall
     * below the contrast floor, with GOV.UK's counter-case beside it.
     * The cursor and the aria state carry the meaning as well. */
    }

    .kp-button--primary {
        background: var(--primary);
        color: var(--primary-foreground);
        border-color: var(--primary);
    }

    .kp-button--primary:hover:not(:disabled) {
        background: var(--primary-hover);
        border-color: var(--primary-hover);
    }

    .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    .kp-button--primary:disabled {
        background: var(--primary-disabled);
        border-color: var(--primary-disabled);
    }

    .kp-button--destructive {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    .kp-button--destructive:hover:not(:disabled) {
        background: var(--destructive-hover);
        border-color: var(--destructive-hover);
    }

    .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
        border-color: var(--destructive-active);
    }

    .kp-button--destructive:disabled {
        background: var(--destructive-disabled);
        border-color: var(--destructive-disabled);
    }

    .kp-button--ghost {
        background: transparent;
        color: var(--foreground);
        border-color: transparent;
    }

    /* A ghost or icon button in the bar wears the bar's ink, not the page's [fix-77].
 * The bar has its own plate in several registers (cyberpunk's yellow,
 * nostromo's sidebar), and the page's ink on it read 1.2:1 and 1:1 in the
 * homelab dashboard's bar; the bar's own colour is the ink every register
 * already gates against that plate. */
    .kp-nav :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    /* And its hover is a veil of that ink, not the page's highlight: a
       page-coloured plate under the bar's ink read 1.12:1 in nostromo
       [fix-82]. --kp-nav-ink names the ink when a register wants another
       than the bar's own colour. */
    .kp-nav :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: hsl(from var(--kp-nav-ink, currentColor) h s l / 0.12);
        color: inherit;
    }

    .kp-button--ghost:hover:not(:disabled) {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    /* The size scale [TH111, T15].
 *
 * Modifier classes rather than a data- attribute, frozen as T15: the
 * button already carries four modifiers and a fifth axis through a
 * second mechanism would make it the one component mixing both styles.
 *
 * Three steps, each a knob over the scale rather than a literal
 * [KT6]: the height derives from --kp-control-height, the padding from
 * the spacing scale, and the type from the text scale. Retuning a scale
 * moves all three; retuning one knob moves one step.
 *
 * The unmodified button is the middle step and keeps `font: inherit`,
 * so a consumer who sets a type size on a region still gets a button
 * that matches the text around it.
 *
 * The 1.75rem inside max() is a literal for the same reason
 * css/_density.css writes one: 28px at a 16px root is above the 24px
 * WCAG 2.5.8 asks of a pointer target, and the small button may not
 * fall through that floor however the scale is tuned. Under compact
 * density it sits ON the floor, which is the floor doing its job.
 */
    .kp-button--sm {
        min-height: var(--kp-button-height-sm, max(1.75rem, calc(var(--kp-control-height, 2.25rem) - var(--kp-space-sm, 0.5rem))));
        padding: var(--kp-button-padding-block-sm, max(0px, min(var(--kp-space-xs, 0.25rem), (1.75rem - 1lh) / 2 - 3px)))
            var(--kp-button-padding-inline-sm, var(--kp-space-sm, 0.5rem));
        font-size: var(--kp-button-text-sm, var(--kp-text-sm, 0.8125rem));
    }

    .kp-button--lg {
        min-height: var(--kp-button-height-lg, calc(var(--kp-control-height, 2.25rem) + var(--kp-space-sm, 0.5rem)));
        padding: var(
                --kp-button-padding-block-lg,
                var(--kp-control-padding-block, max(0px, min(var(--kp-space-xs, 0.25rem), (var(--kp-control-height, 2.25rem) - 1lh) / 2 - 3px)))
            )
            var(--kp-button-padding-inline-lg, var(--kp-space-xl, 1.5rem));
        font-size: var(--kp-button-text-lg, calc(var(--kp-text-md, 1rem) * 1.125));
    }

    /* --- Badge [TH2] ----------------------------------------------------- */

    .kp-badge {
        display: inline-flex;
        align-items: center;
        gap: 0.3em;
        /* The badge's block metrics and type size are the package's in every
     * theme [scope-87, option B of research/uniform-size/]: the values are
     * titanium's, the median theme's [scope-82]. A register keeps its
     * inline padding, colour, border, face, case and letter spacing;
     * gates/box-metrics.test.mjs refuses the rest. */
        padding: var(--kp-badge-padding-block, 0.125rem) 0.5rem;
        border-radius: var(--kp-radius-pill, 999px);
        font-size: var(--kp-badge-size, var(--kp-text-sm, 0.8125rem));
        line-height: var(--kp-badge-line-height, 1.4);
        background: var(--muted);
        color: var(--muted-foreground);
        /* The overflow floor above puts five components on `anywhere`, and
     * for four of them that is the whole story. The badge is the one
     * whose content is usually a label — and a label cut in half reads
     * worse than a column that grew. chassis-rs measured "acti / ve" in
     * a status column at a 1000px viewport [ask-1], where the badge was
     * narrow because the column was, not because the value was long.
     *
     * Both cases are real, so neither becomes the rule: the default is
     * unchanged, and a consumer whose badges only ever hold labels sets
     * `--kp-badge-wrap: normal` on the badge or on anything above it.
     * A custom property rather than a modifier class, because the place
     * that knows is usually the column, not the badge. */
        overflow-wrap: var(--kp-badge-wrap, anywhere);
    }

    /* --- Card [TH6] ------------------------------------------------------ */

    .kp-card {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        padding: 1rem;
        box-shadow: var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
    }

    .kp-card__title {
        margin: 0 0 0.25rem;
        /* A title's size is the package's [scope-87]: titanium's 1.5rem at
     * the heading line height. */
        font-size: var(--kp-card-title-size, 1.5rem);
        line-height: var(--kp-heading-line-height, 1.1);
    }

    .kp-card__body {
        margin: 0;
        color: var(--muted-foreground);
    }

    /* The card's header row, actions and footer [KT6]: slots that were a
 * fixed <h3> and a body div. */
    .kp-card__header {
        display: flex;
        /* In a narrow card the actions go under the title rather than
           breaking their own words apart. */
        flex-wrap: wrap;
        align-items: baseline;
        justify-content: space-between;
        gap: var(--kp-space-sm);
    }

    .kp-card__actions {
        display: flex;
        gap: var(--kp-space-xs);
    }

    .kp-card__footer {
        margin-block-start: var(--kp-space-md);
        padding-block-start: var(--kp-space-md);
        border-block-start: 1px solid var(--border);
    }

    /* A card in four data states [kpadopt4-rows] (js/card-state.js):
 * `data-kp-state` loading, empty, error or ready on a `.kp-card`, its data
 * in `.kp-card__stage > .kp-card__data`. The data and the state's note
 * share one grid cell, so a state never moves the header, the footer or a
 * neighbouring card; in empty and error the data keeps its room, hidden, and
 * the note stands centred in it (UI principles: loading, empty, error and
 * filled take the same footprint); a first load has `--kp-card-stage-min` (7.5rem) for the loading card,
 * which is the data table's own (js/busy-card.js). Knobs [KT6]:
 * `--kp-card-stage-min`, `--kp-card-stage-gap` (the room above the stage). */
    .kp-card__stage {
        position: relative;
        display: grid;
        min-block-size: var(--kp-card-stage-min, 7.5rem);
        margin-block-start: var(--kp-card-stage-gap, var(--kp-space-md, 1rem));
    }

    .kp-card__stage > :is(.kp-card__data, .kp-card__state) {
        grid-area: 1 / 1;
        min-inline-size: 0;
    }

    .kp-card__stage:focus {
        outline: none;
    }

    .kp-card__state {
        display: grid;
        align-content: center;
    }

    .kp-card__state[hidden] {
        display: none;
    }

    .kp-card:is([data-kp-state='empty'], [data-kp-state='error']) > .kp-card__stage > .kp-card__data {
        visibility: hidden;
    }

    /* Empty: the package's empty state, filling the stage, its title in the
     * page's ink over the muted sentence. */
    .kp-card__state > .kp-card__empty {
        display: grid;
        align-content: center;
        justify-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        block-size: 100%;
        box-sizing: border-box;
    }

    .kp-card__state-title {
        color: var(--foreground);
        overflow-wrap: anywhere;
    }

    .kp-card__state-text {
        overflow-wrap: anywhere;
    }

    .kp-card__state-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: var(--kp-space-sm, 0.5rem);
        margin-block-start: var(--kp-space-sm, 0.5rem);
    }

    /* Error: the destructive alert, what failed in bold over why, Try again
     * at its end (under the words in a narrow card). */
    .kp-card__failure {
        flex-wrap: wrap;
        align-items: center;
    }

    .kp-card__failure > .kp-alert__body {
        display: grid;
        gap: calc(var(--kp-space-xs, 0.25rem) / 2);
        flex: 1 1 14rem;
        min-inline-size: 0;
    }

    .kp-card__failure > .kp-card__retry {
        flex: none;
    }

    .kp-card[data-kp-state='loading'] > .kp-card__stage > .kp-card__data {
        cursor: progress;
    }

    /* One rule per status, so a plate comes from a class rather than from
 * a style attribute [R5-BADGE, TH109]. Before this, the only way to
 * colour a badge was `style="background: var(--status-offer)"` — which
 * the React component wrote for you and a server-rendered page had to
 * write by hand, against the zero-inline-style bar.
 *
 * The seven names are `STATUS_NAMES` in gates/check-contrast.mjs, the
 * same list the contrast gate already holds the 24 themes to; a unit
 * test lays these rules beside it in both directions, so a new status
 * cannot arrive without its rule and a rule cannot outlive its status.
 *
 * Specificity (0,2,0) beats .kp-badge's (0,1,0), so the plate wins over
 * the muted default; it stays inside @layer kp.components, so a utility
 * still wins over it. A consumer pointing the React component at their
 * own token family keeps the inline style — these rules only know these
 * seven names. */
    .kp-badge[data-status='draft'] {
        background: var(--status-draft);
        color: var(--status-draft-foreground);
    }

    .kp-badge[data-status='sent'] {
        background: var(--status-sent);
        color: var(--status-sent-foreground);
    }

    .kp-badge[data-status='screening'] {
        background: var(--status-screening);
        color: var(--status-screening-foreground);
    }

    .kp-badge[data-status='interview'] {
        background: var(--status-interview);
        color: var(--status-interview-foreground);
    }

    .kp-badge[data-status='offer'] {
        background: var(--status-offer);
        color: var(--status-offer-foreground);
    }

    .kp-badge[data-status='rejected'] {
        background: var(--status-rejected);
        color: var(--status-rejected-foreground);
    }

    .kp-badge[data-status='withdrawn'] {
        background: var(--status-withdrawn);
        color: var(--status-withdrawn-foreground);
    }

    /* Severity, beside the application statuses rather than instead of them
 * [gap-11]. The seven names above are JobTracker's and say where an
 * application stands; a service that is healthy, degraded or down had no
 * badge. Modifiers on the alert's four token pairs, written the way the
 * alert writes them, so a badge and an alert of one severity are one
 * colour and the contrast gate already holds every pair. Not `data-status`
 * values: that attribute names the application statuses, one token family
 * each, and the unit test that ties them together stays true. The word on
 * the badge still carries the meaning [DI4]. */
    .kp-badge--success {
        background: var(--success);
        color: var(--success-foreground);
    }

    .kp-badge--info {
        background: var(--info);
        color: var(--info-foreground);
    }

    .kp-badge--warning {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-badge--destructive {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    /* A destructive button with an undo offers it inline, beside itself. */
    .kp-button__undo {
        display: inline-flex;
        margin-inline-start: var(--kp-space-xs);
    }

    /* --- Tiles of one height [scope-143] ---------------------------------- */

    /* Cards in a grid are one height, and each card's footer keeps to its
 * bottom edge, so the footers of a row form one line. The cards are the
 * package's own `.kp-card`; this only lays them out. */
    .kp-tiles {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kp-tile-min, 15rem)), 1fr));
        /* Every row as tall as the tallest tile of the grid. */
        grid-auto-rows: 1fr;
        gap: var(--kp-tiles-gap, var(--kp-space-md, 1rem));
        /* A tile is a small card: its title a step under a page card's. */
        --kp-card-title-size: var(--kp-tile-title-size, 1.125rem);
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-tiles > .kp-card {
        display: flex;
        flex-direction: column;
        gap: var(--kp-space-xs, 0.25rem);
        min-inline-size: 0;
    }

    .kp-tiles > .kp-card > .kp-card__footer {
        margin-block-start: auto;
    }

    /* The body never touches the footer's rule when the card is the tallest. */
    .kp-tiles > .kp-card > :nth-last-child(2):not(.kp-card__footer) {
        margin-block-end: var(--kp-space-sm, 0.5rem);
    }

    /* Tiles of one height across a board [port spec H]: the grids of one
 * `data-kp-tiles-set` share the set's tallest tile as the floor of their
 * rows, `--kp-tile-row-min`, which attachTileSets() (js/tiles.js) measures
 * and writes. Unset, the floor is `auto`, so a grid outside a set is laid
 * out exactly as before. While the script measures, a grid's rows size to
 * their content and its tiles to their own height. */
    :where([data-kp-tiles-set]) .kp-tiles,
    .kp-tiles[data-kp-tiles-set] {
        grid-auto-rows: minmax(var(--kp-tile-row-min, auto), 1fr);
    }

    .kp-tiles[data-kp-tiles-measuring] {
        grid-auto-rows: auto;
        align-items: start;
    }

    /* While the tiles of a set move to a new height (js/tiles.js eases each
 * one at the theme's size motion), the rows follow the tiles rather than
 * the floor, and a tile clips what it has not yet grown to show. */
    .kp-tiles[data-kp-tiles-easing] {
        grid-auto-rows: auto;
        align-items: start;
    }

    .kp-tiles[data-kp-tiles-easing] > * {
        overflow: clip;
        box-sizing: border-box;
    }

    /* --- Key figures: the KPI strip and tile [scope-143] ------------------- */

    /* A row of key figures. Every tile is as tall as the tallest, on every row
 * the strip wraps to; inside a tile the label, the number and the trend sit
 * on the same lines as the neighbours', and the sparkline or meter keeps to
 * the bottom. */
    .kp-kpis {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--kp-kpi-min, 9rem)), 1fr));
        grid-auto-rows: 1fr;
        gap: var(--kp-kpis-gap, var(--kp-space-md, 1rem));
    }

    .kp-kpi {
        container: kp-kpi / inline-size;
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        grid-template-rows: auto auto 1fr auto;
        gap: 0.125rem var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        padding: var(--kp-space-md, 1rem);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        font: inherit;
        text-align: start;
        text-decoration: none;
    }

    .kp-kpi > * {
        grid-column: 1 / -1;
    }

    /* A plain tile's label is never cut [kpi-label-cut-M1]: it wraps between
 * words as wide as the tile is, and a word longer than the tile breaks.
 * The tiles of a row stretch to the tallest, so a row stays one height;
 * a trend tile and a strip with columns keep their one-line rule below. */
    .kp-kpi__label {
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 500;
        letter-spacing: 0.06em;
        overflow-wrap: break-word;
        text-transform: uppercase;
        white-space: normal;
    }

    /* The number, its unit, and a note beside it ("avg 15 min"). */
    .kp-kpi__value {
        display: flex;
        flex-wrap: wrap;
        align-items: baseline;
        column-gap: var(--kp-space-sm, 0.5rem);
        font-size: var(--kp-kpi-value-size, 1.75rem);
        font-weight: 600;
        font-variant-numeric: tabular-nums;
        line-height: 1.15;
    }

    .kp-kpi__value small {
        margin-inline-start: -0.25rem;
        color: var(--muted-foreground);
        font-size: 0.55em;
        font-weight: 500;
    }

    .kp-kpi__note {
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 400;
        letter-spacing: 0;
        white-space: nowrap;
    }

    .kp-kpi__trend {
        min-block-size: 1.4em;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: break-word;
    }

    .kp-kpi__delta {
        font-variant-numeric: tabular-nums;
        font-weight: 600;
        white-space: nowrap;
    }

    /* A change with a tone carries its status pair, the plate and its own
 * ink, never one half on the card [fix-70, fix-99]: as an ink alone
 * `--success-foreground` read 1.00:1 in high-contrast, Shade (light) and
 * grotesk, `--destructive` 4.11:1 in solstice. Inline padding only, so the
 * line keeps its height. */
    .kp-kpi__delta[data-kp-tone] {
        padding-inline: 0.3em;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
    }

    .kp-kpi__delta[data-kp-tone='good'] {
        background: var(--success);
        color: var(--success-foreground);
    }

    .kp-kpi__delta[data-kp-tone='bad'] {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    .kp-kpi__delta[data-kp-direction='up']::before {
        content: '▲\00a0';
    }

    .kp-kpi__delta[data-kp-direction='down']::before {
        content: '▼\00a0';
    }

    .kp-kpi__spark {
        display: block;
        inline-size: 100%;
        block-size: var(--kp-kpi-spark-height, 1.75rem);
        margin-block-start: var(--kp-space-xs, 0.25rem);
        overflow: visible;
        color: var(--chart-1);
    }

    .kp-kpi__spark-line {
        fill: none;
        stroke: currentColor;
        stroke-width: 1.6;
        stroke-linejoin: round;
        vector-effect: non-scaling-stroke;
    }

    /* The line over a soft area. */
    .kp-kpi__spark-area {
        fill: currentColor;
        opacity: 0.12;
    }

    .kp-kpi[data-kp-tone='warning'] {
        box-shadow: inset 3px 0 0 var(--warning-foreground);
    }

    /* The figure in a tone sits on that tone's status pair, the plate and
 * its own ink, one rule for every tone [fix-70, fix-99]: as an ink alone on
 * the card `--warning-foreground` read 1.00:1 in high-contrast and 1.04:1
 * in Shade (light), `--destructive` 4.11:1 in solstice to 4.47:1 in
 * synthwave. The plate hugs the figure (its unit and note take the plate's
 * ink too); inline padding only, so the line keeps its height. */
    .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        justify-self: start;
        padding-inline: 0.25em;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
    }

    .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value :is(small, .kp-kpi__note) {
        color: inherit;
    }

    .kp-kpi[data-kp-tone='warning'] .kp-kpi__value {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-kpi[data-kp-tone='destructive'] .kp-kpi__value {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    .kp-kpi[data-kp-tone='warning'] {
        --kp-kpi-meter-fill: var(--warning-foreground);
    }

    .kp-kpi[data-kp-tone='destructive'] {
        --kp-kpi-meter-fill: var(--destructive);
        /* Mixed with the frame that holds 3:1, not the hairline [fix-101]:
         * with `--border` it read 2.07:1 (Lapis) to 2.94:1 on the page in
         * eleven themes. */
        border-color: color-mix(in oklab, var(--destructive) 55%, var(--border-strong));
        box-shadow: inset 3px 0 0 var(--destructive);
    }

    /* A tile that is a link to its detail, or a filter toggle on this page. */
    a.kp-kpi:hover,
    .kp-kpi--toggle:hover {
        border-color: var(--ring);
    }

    .kp-kpi--toggle {
        cursor: pointer;
    }

    .kp-kpi--toggle:focus-visible,
    a.kp-kpi:focus-visible {
        outline: 2px solid var(--focus-ring);
        outline-offset: 2px;
    }

    /* Pressed (a filter on): the primary edge over a primary wash, so the
 * filters that are on read from across the room. */
    .kp-kpi--toggle[aria-pressed='true'] {
        border-color: var(--primary);
        background: color-mix(in oklab, var(--primary) 9%, var(--card));
        box-shadow: none;
    }

    /* What a click does, beside the label: the consumer's words, one per
 * state. The label gives way to it, never the other way round. */
    .kp-kpi--toggle > .kp-kpi__label {
        grid-column: 1;
    }

    .kp-kpi > .kp-kpi__hint {
        grid-row: 1;
        grid-column: 2;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        line-height: inherit;
    }

    .kp-kpi__hint > [data-kp-when='on'],
    .kp-kpi--toggle[aria-pressed='true'] .kp-kpi__hint > [data-kp-when='off'] {
        display: none;
    }

    .kp-kpi--toggle[aria-pressed='true'] .kp-kpi__hint > [data-kp-when='on'] {
        display: inline;
        color: var(--primary);
    }

    /* --- Meter with a mark [scope-143] ------------------------------------ */

    /* A used-of-total bar anywhere: in a tile, at the start of a line of
 * words, in a table cell. `--kp-value` is the share (0 to 1; above 1 the
 * bar is full and `data-kp-over` puts a small ▸ at its end), `--kp-mark` an
 * optional tick (a promise, a limit, a target) across the bar, sticking out
 * above and below it without taking any room, so a meter is as tall with a
 * mark as without one. `.kp-kpi__meter` is the same meter at the bottom of
 * a key figure, whose tone (`data-kp-tone` on the tile) colours its fill.
 * setMeter() (js/kpi.js) writes it all, with its ARIA, in one call.
 * Knobs: `--kp-meter-height` (0.375rem), `--kp-meter-fill` (the primary
 * colour), `--kp-meter-mark-colour` (the text colour),
 * `--kp-meter-mark-overhang` (3px), `--kp-meter-halo` (the card colour: a
 * 1px ring that keeps the mark apart from a dark fill),
 * `--kp-meter-inline-size` (3rem). */
    .kp-meter,
    .kp-kpi__meter {
        --kp-meter-fill-colour: var(--kp-meter-fill, var(--kp-kpi-meter-fill, var(--primary)));
        position: relative;
        display: block;
        block-size: var(--kp-meter-height, 0.375rem);
        overflow: visible;
        border-radius: 999px;
        background: var(--muted);
    }

    .kp-kpi__meter {
        margin-block-start: var(--kp-space-sm, 0.5rem);
    }

    .kp-meter::before,
    .kp-kpi__meter::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: calc(clamp(0, var(--kp-value, 0), 1) * 100%);
        border-radius: inherit;
        background: var(--kp-meter-fill-colour);
    }

    /* The share itself past the end: a ▸ at the bar's end, unless a sign
 * below is asked for. */
    :is(.kp-meter, .kp-kpi__meter)[data-kp-over]:not(.kp-meter--over-hatch, .kp-meter--over-spill, .kp-meter--over-break)::after {
        content: '▸';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-end: -0.0625rem;
        translate: 0 -50%;
        color: var(--kp-meter-mark-colour, var(--foreground));
        font-size: 0.75rem;
        line-height: 1;
        text-shadow:
            0 0 1px var(--kp-meter-halo, var(--card)),
            0 0 2px var(--kp-meter-halo, var(--card));
    }

    /* Other signs for a share past the end, one modifier each [fault 2026-10-05]:
 * `--over-hatch` cuts stripes of the surface colour into the fill's last
 * rem; `--over-spill` puts a short piece in the destructive colour past the
 * end, a 2px gap after the full bar; `--over-break` lets the fill itself
 * run past the end, with a cut of the surface colour where the track ends.
 * The two that reach past the end take `--kp-meter-over-overhang`
 * (0.5rem) beyond the box, inside a cell's or a tile's padding; an inline
 * meter keeps that room after it in every state, so the words never move. */
    :is(.kp-meter, .kp-kpi__meter):is(.kp-meter--over-hatch, .kp-meter--over-spill, .kp-meter--over-break)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset-block: 0;
        pointer-events: none;
    }

    :is(.kp-meter, .kp-kpi__meter).kp-meter--over-hatch[data-kp-over]::after {
        inset-inline-end: 0;
        inline-size: min(1rem, 35%);
        border-start-end-radius: 999px;
        border-end-end-radius: 999px;
        background: repeating-linear-gradient(-45deg, var(--kp-meter-halo, var(--card)) 0 1.5px, transparent 1.5px 4px);
    }

    /* The piece past the end is 2px taller above and below than the bar, as
 * the mark is, so it reads as overflow, not as more bar; it takes no room. */
    :is(.kp-meter, .kp-kpi__meter).kp-meter--over-spill[data-kp-over]::after {
        inset-block: -2px;
        inset-inline-start: calc(100% + 2px);
        inline-size: var(--kp-meter-over-overhang, 0.5rem);
        border-radius: 999px;
        background: var(--destructive);
    }

    /* The fill's own colour runs on past the end, after a 2px cut of the
 * surface colour where the track stops. */
    :is(.kp-meter, .kp-kpi__meter).kp-meter--over-break[data-kp-over]::after {
        inset-block: -2px;
        inset-inline-start: calc(100% - 2px);
        inline-size: calc(var(--kp-meter-over-overhang, 0.5rem) + 2px);
        box-sizing: border-box;
        border-inline-start: 2px solid var(--kp-meter-halo, var(--card));
        border-start-end-radius: 999px;
        border-end-end-radius: 999px;
        background: var(--kp-meter-fill-colour);
    }

    .kp-meter--inline:is(.kp-meter--over-spill, .kp-meter--over-break) {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-meter-over-overhang, 0.5rem) + 2px);
    }

    @media (prefers-reduced-motion: no-preference) {
        :is(.kp-meter, .kp-kpi__meter):is(.kp-meter--over-hatch, .kp-meter--over-spill, .kp-meter--over-break)[data-kp-over]::after {
            transition: opacity var(--fx-duration, 150ms) var(--fx-ease, ease);
        }

        @starting-style {
            :is(.kp-meter, .kp-kpi__meter):is(.kp-meter--over-hatch, .kp-meter--over-spill, .kp-meter--over-break)[data-kp-over]::after {
                opacity: 0;
            }
        }
    }

    :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning'] {
        --kp-meter-fill-colour: var(--warning-foreground);
    }

    :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive'] {
        --kp-meter-fill-colour: var(--destructive);
    }

    /* The mark: a tick across the bar, sticking out above and below, with a
 * halo of the surface colour so it reads on the fill and on the track. */
    .kp-meter__mark {
        position: absolute;
        inset-block: calc(var(--kp-meter-mark-overhang, 3px) * -1);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - 1px);
        inline-size: 2px;
        border-radius: 1px;
        background: var(--kp-meter-mark-colour, var(--foreground));
        box-shadow: 0 0 0 1px var(--kp-meter-halo, var(--card));
        pointer-events: none;
    }

    .kp-meter__mark[hidden] {
        display: none;
    }

    /* A mark past the end: the tick stops short of the end and a small ▸
 * fills the last bit, inside the bar's box. */
    .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    .kp-meter__mark[data-kp-over]::after {
        content: '▸';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-start: 0.1875rem;
        translate: 0 -50%;
        color: var(--kp-meter-mark-colour, var(--foreground));
        font-size: 0.75rem;
        line-height: 1;
        text-shadow:
            0 0 1px var(--kp-meter-halo, var(--card)),
            0 0 2px var(--kp-meter-halo, var(--card));
    }

    /* Loading (`data-kp-loading`): the track pulses at full width and its
 * height, with no fill and no mark; still under reduced motion. */
    :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] .kp-meter__mark,
    :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        display: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
            animation: kp-pulse 1600ms ease-in-out infinite;
        }

        .kp-meter::before {
            transition:
                inline-size 300ms ease,
                background-color 300ms ease;
        }
    }

    /* A small meter at the start of a line of words: three rem wide, its
 * middle on the first line's middle. */
    .kp-meter--inline {
        display: inline-block;
        inline-size: var(--kp-meter-inline-size, 3rem);
        margin-inline-end: var(--kp-space-xs, 0.25rem);
        vertical-align: middle;
    }

    /* --- Key-figure strip on allowed column counts [scope-143] ------------ */

    /* `data-kp-kpis-columns="all 3 2 1"`: the strip takes the first count in
 * the list at which every tile is at least `--kp-kpi-min` wide, by its own
 * width, and steps down a count when that would leave one tile alone on
 * the last row; when no allowed count avoids it, the lone tile spans its
 * row. attachKpiStrips() (js/kpi.js) writes the count
 * (`--kp-kpis-columns`) and `data-kp-kpis-span-last`; before the script
 * runs the strip keeps the package's auto-fit. */
    .kp-kpis[data-kp-kpis-columns][style*='--kp-kpis-columns'] {
        grid-template-columns: repeat(var(--kp-kpis-columns), minmax(0, 1fr));
    }

    .kp-kpis[data-kp-kpis-span-last] > :last-child {
        grid-column: 1 / -1;
    }

    /* A tile of a strip with columns is framed in `--border-strong`, the
 * boundary DI1 holds at 3:1 against the page, the card and the popover:
 * its frame is what parts it from the next tile and from the page, and
 * `--border` read 1.21:1 (synthwave, Shade (dark)) to 2.72:1 (retro) in 20
 * of 22 themes [fix-101]. Knob `--kp-kpi-border`: dark and titanium, whose
 * `--border-strong` stays under 3:1 (an open DI1 finding), set a share of
 * `--foreground` in it. `:where()` keeps the
 * strip out of the weight, so a tone, a hover and a pressed toggle still
 * draw their own edge. Its label, figure and words keep one line box each
 * whatever the state (the rules with the trend tile's, below). */
    :where(.kp-kpis[data-kp-kpis-columns]) > .kp-kpi {
        border-color: var(--kp-kpi-border, var(--border-strong));
    }

    /* --- A key figure with its 24-hour trend [scope-143] ------------------ */

    /* `.kp-kpi--trend`: the whole tile is a link (its `.kp-kpi__link`
 * stretched over it), and the trend inside it is a second stop for the
 * keyboard: no control sits inside the link. The trend is the time
 * chart's spark variant without its head line, `figure.kp-kpi__chart
 * [data-kp-chart="spark"][data-kp-spark-head="none"]
 * [data-kp-spark-axis="relative"]` (js/chart.js): under the line the axis,
 * where the trend starts (a clock and a day word) and `now`. A pointer, a
 * finger or the arrow keys read one point: a crosshair and a chip with its
 * moment and value over the line. A note such as "avg 15 min" goes in the
 * label, in its capitals: `.kp-kpi__label-note`. Knob:
 * `--kp-kpi-spark-height` (2.75rem in a trend), `--kp-kpi-trend-lines`. */
    .kp-kpi--trend {
        position: relative;
        grid-template-rows: auto auto 1fr auto;
        /* The tile is the box its link stretches over (the link's ::after is
 * fixed, and layout containment makes the tile its containing block). */
        contain: layout;
    }

    /* At rest a trend tile in a strip with columns is framed in
 * `--border-strong` already [fix-101], so a hover draws `--ring`, as a
 * link tile and a toggle do. */
    .kp-kpi--trend:hover {
        border-color: var(--ring);
    }

    .kp-kpi--trend:has(.kp-kpi__link:focus-visible) {
        outline: 2px solid var(--ring);
        outline-offset: 2px;
    }

    /* The label is one line, never wrapped and never cut [fix-99], in a
 * trend tile and in every tile of a strip with columns [fix-101], where
 * it was cut (223 px in a 220 px box in dark and deco) or wrapped by the
 * narrow tile's rule: the name and its note stay on the tile's first
 * line, clear of the trend's link in the corner, and step down with the tile's width (container query units,
 * from `--kp-text-xs` to seven eighths of it, as the calendar's title does
 * [fix-98]). Where it still does not fit, the tile grows: attachKpiStrips()
 * (js/kpi.js) takes the strip to its next allowed column count until every
 * label fits, in the phone pane too. The tile is a size container, so its content cannot
 * widen it from CSS: `min-inline-size: fit-content` and a `max-content`
 * track both left it at 228.5 px with the label over its edge. */
    .kp-kpi--trend > .kp-kpi__label,
    :where(.kp-kpis[data-kp-kpis-columns]) > .kp-kpi > .kp-kpi__label {
        min-inline-size: 0;
        overflow: visible;
        font-size: clamp(calc(var(--kp-text-xs, 0.75rem) * 0.875), 5cqi, var(--kp-text-xs, 0.75rem));
        /* The line box of the label at its full size, so a label that steps
         * down does not lower its tile (2.3 px, the strip's height moving
         * with its column count [fix-101]). */
        line-height: calc(var(--kp-text-xs, 0.75rem) * var(--kp-line-height, 1.5));
        text-overflow: clip;
        white-space: nowrap;
    }

    /* The link in the corner takes the label's end: the label's box stops
 * before it and a label that is still too long wraps between words, so it
 * never runs under the link and is never cut (a 148 px tile, a phone pane;
 * Kenny, 2026-10-14). Two lines are kept for it, as for the words under the
 * figure, so a row of trends is one height whether a label wraps or not. */
    .kp-kpi--trend > .kp-kpi__label {
        margin-inline-end: 4.5rem;
        min-block-size: calc(2 * var(--kp-text-xs, 0.75rem) * var(--kp-line-height, 1.5));
        overflow: visible;
        overflow-wrap: break-word;
        text-overflow: clip;
        white-space: normal;
    }

    /* Every state as tall as filled: the value line keeps its height under
 * a skeleton or a dash, and the words under it keep two lines (three in a
 * narrow trend tile; knob `--kp-kpi-trend-lines`), so a row of trends, or
 * of the tiles of a strip with columns, does not shrink while it loads or
 * grow when a figure's words take a second line (79.4 to 121.2 px in one
 * strip before [fix-101]). */
    .kp-kpi--trend > .kp-kpi__value,
    :where(.kp-kpis[data-kp-kpis-columns]) > .kp-kpi > .kp-kpi__value {
        min-block-size: 1lh;
    }

    .kp-kpi--trend > .kp-kpi__trend,
    :where(.kp-kpis[data-kp-kpis-columns]) > .kp-kpi > .kp-kpi__trend {
        min-block-size: calc(var(--kp-kpi-trend-lines, 2) * 1lh);
    }

    .kp-kpi__label-note {
        font-weight: 400;
        white-space: nowrap;
    }

    .kp-kpi__label-note::before {
        content: '· ';
    }

    .kp-kpi__link {
        position: absolute;
        inset-block-start: var(--kp-space-sm, 0.5rem);
        inset-inline-end: var(--kp-space-sm, 0.5rem);
        padding: 0.125rem 0.375rem;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        color: var(--link, var(--primary));
        font-size: var(--kp-text-xs, 0.75rem);
        text-decoration: none;
    }

    .kp-kpi__link::after {
        content: '';
        position: fixed;
        inset: 0;
    }

    .kp-kpi__link:focus-visible {
        outline: none;
    }

    .kp-kpi__link:hover {
        text-decoration: underline;
    }

    /* A narrow tile: the corner says ↗ alone; the word stays for a screen
 * reader. */
    @container kp-kpi (max-width: 12rem) {
        .kp-kpi__link-word {
            position: absolute;
            inline-size: 1px;
            block-size: 1px;
            overflow: hidden;
            clip-path: inset(50%);
            white-space: nowrap;
        }

        .kp-kpi--trend > .kp-kpi__label {
            margin-inline-end: 2.25rem;
        }

        .kp-kpi--trend > .kp-kpi__trend {
            min-block-size: calc(var(--kp-kpi-trend-lines, 3) * 1lh);
        }
    }

    .kp-kpi__chart {
        position: relative;
        z-index: 1;
        display: grid;
        grid-template-rows: var(--kp-kpi-spark-height, 2.75rem) auto;
        margin: var(--kp-space-xs, 0.25rem) 0 0;
        color: var(--kp-chart-series, var(--chart-1));
    }

    .kp-kpi__chart-plot {
        position: relative;
        display: block;
        cursor: crosshair;
        touch-action: pan-y;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
    }

    .kp-kpi__chart-plot:not([tabindex]) {
        cursor: default;
    }

    .kp-kpi__chart-plot:focus-visible {
        outline: 2px solid var(--ring);
        outline-offset: 2px;
    }

    /* The line takes the trend's series colour (`--kp-chart-series` on the
 * figure, as on a plot), not the plain sparkline's `--chart-1`. */
    .kp-kpi__chart .kp-kpi__spark {
        block-size: 100%;
        margin: 0;
        color: inherit;
    }

    .kp-kpi__chart-cross {
        position: absolute;
        inset-block: 0;
        inline-size: 1px;
        background: hsl(from var(--foreground) h s l / 0.55);
        pointer-events: none;
    }

    .kp-kpi__chart-chip {
        position: absolute;
        inset-block-end: calc(100% + 0.125rem);
        display: flex;
        column-gap: 0.25em;
        padding: 0.0625rem var(--kp-space-xs, 0.25rem);
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--popover);
        color: var(--popover-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
        pointer-events: none;
    }

    .kp-kpi__chart-chip > .kp-kpi__chart-value::before {
        content: '· ';
    }

    /* Too wide for the trend on one line: the value under the moment. */
    .kp-kpi__chart-chip[data-kp-stacked] {
        flex-direction: column;
    }

    .kp-kpi__chart-chip[data-kp-stacked] > .kp-kpi__chart-value::before {
        content: none;
    }

    .kp-kpi__chart-cross[hidden],
    .kp-kpi__chart-chip[hidden],
    .kp-kpi__chart-axis > [hidden] {
        display: none;
    }

    .kp-kpi__chart-axis {
        display: flex;
        justify-content: space-between;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
        line-height: 1.5;
        white-space: nowrap;
    }

    /* The reading in the axis row, when even a stacked chip would not fit. */
    .kp-kpi__chart-read {
        overflow: hidden;
        color: var(--foreground);
        text-overflow: ellipsis;
    }

    .kp-kpi__chart-read > .kp-kpi__chart-value::before {
        content: ' · ';
    }
    /* --- Time chart [scope-143] ------------------------------------------- */

    /* One time chart for every page, so its controls mean the same
 * everywhere: a legend that singles a source out and keeps sources on or
 * off, a crosshair every chart of a group shares, a tooltip with the change
 * over the hour before and the events within reach, drag to zoom, and
 * event markers. attachCharts() draws it; the colours are the theme's
 * `--chart-1..5`, and from the sixth source on they come round again with
 * a dashed line. */
    .kp-chart-group {
        display: grid;
        gap: var(--kp-space-lg, 1.5rem);
        min-inline-size: 0;
    }

    /* The range buttons and the zoom chip, once for the group. */
    .kp-chart-group__bar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 1rem);
    }

    .kp-chart-ranges {
        display: inline-flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem);
    }

    .kp-chart-ranges > [aria-pressed='true'] {
        border-color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
        color: var(--foreground);
    }

    .kp-chart-zoom {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    .kp-chart-zoom[hidden] {
        display: none;
    }

    .kp-chart-zoom__reset {
        padding: 0;
        border: 0;
        background: none;
        color: var(--foreground);
        font: inherit;
        font-weight: 600;
        text-decoration: underline;
        text-underline-offset: 3px;
        cursor: pointer;
    }

    .kp-chart-zoom__reset:focus-visible {
        outline: 2px solid var(--focus-ring);
        outline-offset: 2px;
    }

    .kp-chart {
        container: kp-chart / inline-size;
        position: relative;
        display: grid;
        gap: var(--kp-space-xs, 0.25rem);
        min-inline-size: 0;
        margin: 0;
        /* The source's colour: its `--chart-n`, or its own. */
        --kp-chart-series: var(--chart-1);
    }

    .kp-chart__title {
        margin: 0;
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 600;
    }

    .kp-chart [data-kp-series='2'] {
        --kp-chart-series: var(--chart-2);
    }

    .kp-chart [data-kp-series='3'] {
        --kp-chart-series: var(--chart-3);
    }

    .kp-chart [data-kp-series='4'] {
        --kp-chart-series: var(--chart-4);
    }

    .kp-chart [data-kp-series='5'] {
        --kp-chart-series: var(--chart-5);
    }

    .kp-chart__plot {
        position: relative;
        border-radius: calc(var(--radius, 0.5rem) * 0.5);
        cursor: crosshair;
        touch-action: pan-y;
        user-select: none;
    }

    .kp-chart__plot:focus-visible {
        outline: 2px solid var(--focus-ring);
        outline-offset: 4px;
    }

    .kp-chart__plot > svg {
        display: block;
        inline-size: 100%;
        overflow: visible;
    }

    .kp-chart__grid {
        stroke: var(--border);
        stroke-width: 1;
    }

    .kp-chart__tick {
        fill: var(--muted-foreground);
        font-size: var(--kp-chart-tick-size, 11px);
        font-variant-numeric: tabular-nums;
    }

    .kp-chart__line {
        fill: none;
        stroke: var(--kp-chart-series);
        stroke-width: 2;
        stroke-linejoin: round;
        stroke-linecap: round;
    }

    .kp-chart__series[data-kp-dash='1'] .kp-chart__line {
        stroke-dasharray: 5 3;
    }

    .kp-chart__series[data-kp-dash='2'] .kp-chart__line {
        stroke-dasharray: 1.5 2.5;
    }

    .kp-chart__series[data-kp-dash='3'] .kp-chart__line {
        stroke-dasharray: 8 3 1.5 3;
    }

    /* A soft area under the line while one or two sources are on; with
 * three or more, the lines alone. Stacked sources are areas always. */
    .kp-chart__area {
        fill: var(--kp-chart-series);
        fill-opacity: 0.06;
        stroke: none;
    }

    .kp-chart__area--alone {
        fill-opacity: 0.12;
    }

    .kp-chart__area--stacked {
        fill-opacity: 0.22;
    }

    .kp-chart__point {
        fill: var(--kp-chart-series);
    }

    /* A source singled out: it thickens, the others fade. */
    .kp-chart__series[data-kp-state='hot'] .kp-chart__line {
        stroke-width: 2.75;
    }

    .kp-chart__series[data-kp-state='dim'] .kp-chart__line {
        opacity: 0.18;
    }

    .kp-chart__series[data-kp-state='dim'] .kp-chart__area {
        fill-opacity: 0.02;
    }

    .kp-chart__threshold {
        stroke: var(--destructive);
        stroke-dasharray: 4 4;
        opacity: 0.8;
    }

    .kp-chart__event-line {
        stroke: var(--muted-foreground);
        stroke-dasharray: 2 3;
        opacity: 0.7;
    }

    .kp-chart__mark {
        cursor: pointer;
        --kp-chart-tone: var(--info-foreground);
    }

    .kp-chart [data-kp-tone='warning'] {
        --kp-chart-tone: var(--warning-foreground);
    }

    .kp-chart [data-kp-tone='critical'] {
        --kp-chart-tone: var(--destructive);
    }

    .kp-chart__mark-hit {
        fill: transparent;
    }

    .kp-chart__mark-dot {
        fill: var(--kp-chart-tone);
        stroke: var(--card);
        stroke-width: 1.5;
    }

    .kp-chart__mark:hover .kp-chart__mark-dot {
        stroke: var(--foreground);
    }

    /* --- Annotations [kpadopt5-people] ----------------------------------- */

    /* A band: an event with an end (a maintenance window), tinted in its tone across the plot with a solid edge
     * where it begins and ends, so it is told from a dashed event line. */
    .kp-chart__band {
        --kp-chart-tone: var(--info-foreground);
    }

    .kp-chart__band-fill {
        fill: var(--kp-chart-tone);
        fill-opacity: var(--kp-chart-band-opacity, 0.14);
        stroke: none;
    }

    /* `hatch`: diagonal lines in the tone instead of a wash, readable without the colour. */
    .kp-chart__band-fill[fill^='url'] {
        fill-opacity: 1;
    }

    .kp-chart__hatch {
        stroke: var(--kp-chart-tone, var(--info-foreground));
        stroke-width: 1.5;
        opacity: 0.55;
    }

    pattern[data-kp-tone='warning'] {
        --kp-chart-tone: var(--warning-foreground);
    }

    pattern[data-kp-tone='critical'] {
        --kp-chart-tone: var(--destructive);
    }

    pattern[data-kp-tone='info'] {
        --kp-chart-tone: var(--info-foreground);
    }

    /* `bracket`: a bar along the top between two short ticks. */
    .kp-chart__band-bar {
        stroke: var(--kp-chart-tone);
        stroke-width: 3;
        stroke-linecap: round;
    }

    .kp-chart__band-edge {
        stroke: var(--kp-chart-tone);
        stroke-width: 1.5;
        opacity: 0.85;
    }

    /* The median of a source: its own colour, long dashes, and its value written on the plot. */
    .kp-chart__median {
        fill: none;
        stroke: var(--kp-chart-series);
        stroke-width: 1.5;
        stroke-dasharray: 10 4;
    }

    .kp-chart__median-label {
        fill: var(--foreground);
        font-size: var(--kp-chart-tick-size, 11px);
        font-variant-numeric: tabular-nums;
        font-weight: 600;
        paint-order: stroke;
        stroke: var(--card);
        stroke-width: 3px;
        stroke-linejoin: round;
    }

    /* A point of a run of six or more on one side of the median: ringed. */
    .kp-chart__run {
        fill: var(--card);
        stroke: var(--kp-chart-series);
        stroke-width: 2;
    }

    /* Events past the window's edge: an arrow and their count. */
    .kp-chart__edge-text {
        fill: var(--muted-foreground);
        font-size: var(--kp-chart-tick-size, 11px);
        font-variant-numeric: tabular-nums;
        font-weight: 600;
    }

    /* Too early for a trend: the readings so far stay, faint, under one sentence in the middle of the plot. */
    .kp-chart__plot > svg[data-kp-faint] {
        opacity: 0.5;
    }

    .kp-chart__few {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        padding: var(--kp-space-md, 0.75rem);
        border-radius: calc(var(--radius, 0.5rem) * 0.5);
        background: color-mix(in oklab, var(--card) 50%, transparent);
        pointer-events: none;
    }

    /* The plate is opaque: it stands on a ground of the card's colour, under whatever ground the theme gives the plate
       itself, so nothing of the plot shows through its words (Kenny, 2026-10-18 17:45). */
    .kp-chart__few-ground {
        display: grid;
        max-inline-size: 100%;
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
    }

    .kp-chart__few-plate {
        box-sizing: border-box;
        max-inline-size: min(36ch, 100%);
        margin: 0;
        padding: var(--kp-space-md, 0.75rem) var(--kp-space-lg, 1rem);
        color: var(--foreground);
        font-size: calc(var(--kp-text-md, 1rem) * 1.25);
        font-weight: 600;
        line-height: 1.35;
        overflow-wrap: anywhere;
    }

    /* The key above the plot: one switch per kind of event, and a note for the median and the runs. */
    .kp-chart__annkey {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-chart__annkey[hidden] {
        display: none;
    }

    .kp-chart__annkey[data-kp-wait] {
        visibility: hidden;
    }

    .kp-chart__annkey-item {
        display: inline-flex;
        align-items: center;
        gap: 0.375rem;
        padding: 0.125rem 0.5rem;
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-pill, 999px);
        background: none;
        color: var(--foreground);
        font: inherit;
        cursor: pointer;
    }

    .kp-chart__annkey-item:focus-visible {
        outline: 2px solid var(--focus-ring);
        outline-offset: 2px;
    }

    .kp-chart__annkey-item[data-kp-off] {
        color: var(--muted-foreground);
        border-style: dashed;
    }

    .kp-chart__annkey-item[data-kp-off] .kp-chart__dot {
        opacity: 0.35;
    }

    .kp-chart__annkey-count {
        font-variant-numeric: tabular-nums;
        font-weight: 600;
    }

    .kp-chart__annkey-note {
        display: inline-flex;
        align-items: center;
        gap: 0.375rem;
    }

    .kp-chart__annkey-line {
        inline-size: 1.25rem;
        border-block-start: 2px dashed var(--chart-1);
    }

    .kp-chart__annkey-ring {
        inline-size: 0.625rem;
        block-size: 0.625rem;
        box-sizing: border-box;
        border: 2px solid var(--chart-1);
        border-radius: 50%;
        background: var(--card);
    }

    .kp-chart__tip-median {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
    }

    /* On a phone the median's words leave the plot (the tooltip carries them). */
    @container kp-chart (max-width: 26rem) {
        .kp-chart__median-label {
            display: none;
        }
    }

    .kp-chart__crosshair {
        stroke: var(--foreground);
        opacity: 0.35;
    }

    .kp-chart__crosshair--pinned {
        stroke-width: 1.5;
        opacity: 0.8;
    }

    .kp-chart__snap {
        fill: var(--kp-chart-series);
        stroke: var(--card);
        stroke-width: 2;
    }

    .kp-chart__brush {
        fill: hsl(from var(--chart-1) h s l / 0.16);
        stroke: var(--chart-1);
        stroke-dasharray: 3 3;
    }

    /* The tooltip: beside the crosshair, on the side with room. */
    .kp-chart__tip {
        position: absolute;
        z-index: 5;
        inset-block-start: 4px;
        inset-inline-start: var(--kp-chart-tip-x, 0);
        display: grid;
        gap: 3px;
        inline-size: max-content;
        min-inline-size: min(var(--kp-chart-tip-min, 14rem), 100%);
        max-inline-size: min(var(--kp-chart-tip-max, 17.5rem), 100%);
        padding: var(--kp-space-sm, 0.5rem) 0.625rem;
        border: 1px solid var(--border);
        border-radius: calc(var(--radius, 0.5rem) * 0.75);
        background: var(--popover);
        color: var(--popover-foreground);
        box-shadow: 0 8px 24px hsl(from var(--foreground) h s l / 0.14);
        font-size: var(--kp-text-xs, 0.75rem);
        pointer-events: none;
    }

    .kp-chart__tip[hidden] {
        display: none;
    }

    /* Pinned: it takes the pointer (its ✕, an event's link) and says so. */
    .kp-chart__tip[data-kp-pinned] {
        box-shadow:
            0 0 0 1px var(--ring),
            0 8px 24px hsl(from var(--foreground) h s l / 0.14);
        pointer-events: auto;
    }

    .kp-chart__tip p {
        margin: 0;
    }

    .kp-chart__tip-head {
        display: flex;
        justify-content: space-between;
        gap: 0.625rem;
        margin-block-end: var(--kp-space-xs, 0.25rem);
        font-variant-numeric: tabular-nums;
    }

    /* The tooltip's words are all in the popover's own ink: the muted ink
 * reads 4.44:1 on titanium's popover and 4.48:1 on Lapis's [scope-143]. */
    .kp-chart__pin {
        white-space: nowrap;
    }

    .kp-chart__release {
        margin-inline-start: var(--kp-space-sm, 0.5rem);
        padding: 0 var(--kp-space-xs, 0.25rem);
        border: 0;
        border-radius: calc(var(--radius, 0.5rem) * 0.5);
        background: none;
        color: var(--foreground);
        font: inherit;
        cursor: pointer;
    }

    .kp-chart__release:focus-visible {
        outline: 2px solid var(--focus-ring);
    }

    /* The change column: `--kp-chart-delta-width` (default 5.5rem) is its
 * floor, so the rows' changes line up, and a wider change takes its own
 * width rather than a second line. A fixed 4.5rem wrapped `▼ 74.5 KiB/s`
 * in 16 of 22 themes, the widest 5.36rem in terminal's mono [fix-97]. */
    .kp-chart__tip-row {
        display: grid;
        grid-template-columns: 10px minmax(0, 1fr) auto minmax(var(--kp-chart-delta-width, 5.5rem), max-content);
        align-items: center;
        gap: 6px;
    }

    .kp-chart__tip-row > span:nth-child(2) {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-chart__tip-row[data-kp-state='hot'] {
        font-weight: 700;
    }

    .kp-chart__num {
        font-variant-numeric: tabular-nums;
        text-align: end;
    }

    /* The change over the hour before: up and down are not good or bad, so
 * neither is green or red. A status ink is text only on its own plate:
 * `--warning-foreground` on the popover read 1.00:1 in high-contrast and
 * `--info-foreground` 1.00:1 in grotesk [scope-143]. */
    .kp-chart__delta {
        white-space: nowrap;
    }

    .kp-chart__delta[data-kp-direction] {
        justify-self: end;
        padding-inline: 0.3em;
        border-radius: calc(var(--radius, 0.5rem) * 0.5);
    }

    .kp-chart__delta[data-kp-direction='up'] {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-chart__delta[data-kp-direction='down'] {
        background: var(--info);
        color: var(--info-foreground);
    }

    .kp-chart__tip-foot {
        text-align: end;
    }

    .kp-chart__tip-event {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 6px;
        margin-block-start: var(--kp-space-xs, 0.25rem);
        padding-block-start: var(--kp-space-xs, 0.25rem);
        border-block-start: 1px solid var(--border);
    }

    /* In the popover's ink and underlined: `--primary` read 4.26:1 on
 * Lapis's popover [scope-143]. */
    .kp-chart__tip-event > a {
        color: inherit;
        font-weight: 600;
        text-decoration: underline;
        text-underline-offset: 2px;
    }

    .kp-chart__dot {
        flex: none;
        inline-size: 8px;
        block-size: 8px;
        border-radius: 50%;
        background: var(--kp-chart-tone, var(--info-foreground));
    }

    /* In the tooltip, a ring in the popover's ink: a tone is a text ink, and
 * on the popover the warning one read 1.07:1 in Shade (light), 1.00:1 in
 * high-contrast and 1.04:1 in nostromo [fix-97]. */
    .kp-chart__tip .kp-chart__dot {
        box-shadow: 0 0 0 1.5px var(--popover-foreground);
    }

    .kp-chart__swatch {
        display: inline-block;
        inline-size: 10px;
        block-size: 3px;
        border-radius: 2px;
        background: var(--kp-chart-series);
    }

    [data-kp-dash] > .kp-chart__swatch,
    .kp-chart__swatch[data-kp-dash] {
        background: repeating-linear-gradient(90deg, var(--kp-chart-series) 0 3px, transparent 3px 5px);
    }

    /* The legend: one button per source, its value at the crosshair (or
 * the latest), and Show all while some are kept on. */
    .kp-chart__legend {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem);
        margin-block-start: 0.625rem;
    }

    .kp-chart__legend[hidden],
    .kp-chart__hint[hidden] {
        display: none;
    }

    .kp-chart__source,
    .kp-chart__show-all {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 3px var(--kp-space-sm, 0.5rem);
        border: 1px solid transparent;
        border-radius: 999px;
        background: none;
        color: var(--muted-foreground);
        font: inherit;
        font-size: var(--kp-text-xs, 0.75rem);
        cursor: pointer;
    }

    .kp-chart__source > b {
        color: var(--foreground);
        font-variant-numeric: tabular-nums;
        font-weight: 600;
    }

    .kp-chart__source:hover,
    .kp-chart__source:focus-visible {
        border-color: var(--border);
        color: var(--foreground);
    }

    .kp-chart__source:focus-visible,
    .kp-chart__show-all:focus-visible {
        outline: 2px solid var(--focus-ring);
    }

    .kp-chart__source[aria-pressed='true'] {
        border-color: var(--border);
        background: var(--card);
        color: var(--foreground);
        box-shadow: 0 0 0 1px var(--ring);
    }

    /* A source not shown is struck through, its label at full contrast:
 * at opacity 0.45 it read 1.89:1 to 3.02:1 [scope-143]. */
    .kp-chart__source[data-kp-off] {
        text-decoration: line-through;
    }

    .kp-chart__source[data-kp-off] > .kp-chart__swatch {
        background: var(--muted-foreground);
    }

    .kp-chart__show-all {
        border: 1px dashed var(--border-strong, var(--border));
        color: var(--foreground);
    }

    .kp-chart__show-all[hidden] {
        display: none;
    }

    .kp-chart__hint {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    /* Words for a pointer, or for a finger: never both. */
    .kp-chart__hint > [data-kp-when='touch'] {
        display: none;
    }

    @media (hover: none) {
        .kp-chart__hint > [data-kp-when='pointer'] {
            display: none;
        }

        .kp-chart__hint > [data-kp-when='touch'] {
            display: inline;
        }
    }

    /* The spark variant: a tile's 24-hour line on the group's crosshair,
 * drawn by drawSparkline(), its value at the crosshair (or now) beside
 * its name: a line over a soft area, as the KPI tile's. */
    .kp-chart--spark {
        gap: 2px;
    }

    .kp-chart__spark-head {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 0 var(--kp-space-sm, 0.5rem);
        margin: 0;
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-chart__spark-label {
        overflow: hidden;
        color: var(--muted-foreground);
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-chart__spark {
        display: block;
        inline-size: 100%;
        block-size: var(--kp-kpi-spark-height, 1.75rem);
        overflow: visible;
        color: var(--kp-chart-series);
    }

    .kp-chart__spark-line {
        fill: none;
        stroke: currentColor;
        stroke-width: 1.6;
        stroke-linejoin: round;
        vector-effect: non-scaling-stroke;
    }

    .kp-chart__spark-area {
        fill: currentColor;
        opacity: 0.12;
    }

    .kp-chart__spark .kp-chart__crosshair {
        stroke-width: 1;
    }

    /* The chart's states [scope-143]: loading, no readings and an error keep
 * the plot's final height (js/chart.js writes it, border-box, from
 * `data.height`, else `--kp-chart-height`, else 168px), the sentence in the
 * middle. Loading is also a `.kp-skeleton`, so it pulses only without
 * reduced motion. */
    .kp-chart__state {
        display: grid;
        place-items: center;
        padding: var(--kp-space-md, 0.75rem);
        border-radius: calc(var(--radius, 0.5rem) * 0.5);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        text-align: center;
    }

    .kp-chart__state-text {
        display: inline-flex;
        align-items: baseline;
        gap: var(--kp-space-sm, 0.5rem);
        max-inline-size: 48ch;
        margin: 0;
    }

    /* A failed chart is the package's own failed plate (`.kp-stateplate`, js/state-plate.js: the destructive alert every other
 * failed area uses) filling the plot's height, so each register dresses it [t56-chart-failed-1018]. The state box adds no tint,
 * border or padding of its own. */
    .kp-chart__state[data-kp-state='error'] {
        display: grid;
        padding: 0;
        border-radius: 0;
        color: var(--foreground);
        text-align: start;
    }

    .kp-chart__state[data-kp-state='error'] > .kp-stateplate {
        block-size: 100%;
    }

    .kp-chart__state-text > .kp-chart__dot {
        flex: none;
    }

    /* While loading, the legend row keeps its place for the sources to come:
 * a stub the size of a source button. */
    .kp-chart__source-stub {
        padding: 3px var(--kp-space-sm, 0.5rem);
        border: 1px solid transparent;
        border-radius: 999px;
        font-size: var(--kp-text-xs, 0.75rem);
        line-height: inherit;
    }

    /* Under a chart whose every source has one reading (`onePointNote`). */
    .kp-chart__note {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    /* A long source name stops at 24 characters; the button's title says all of it. */
    .kp-chart__source-label {
        overflow: hidden;
        min-inline-size: 0;
        max-inline-size: 24ch;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    /* The tooltip's rows: after twelve they scroll (a pinned tooltip takes
 * the pointer and the wheel). */
    .kp-chart__tip-rows {
        display: grid;
        gap: 3px;
        max-block-size: calc(12 * 1.5em + 11 * 3px);
        overflow-y: auto;
        overscroll-behavior: contain;
    }

    .kp-chart__tip-rows[hidden],
    .kp-chart__tip-foot[hidden] {
        display: none;
    }

    /* --- Alert [TH4] ----------------------------------------------------- */

    .kp-alert {
        display: flex;
        gap: 0.625rem;
        padding: 0.75rem 1rem;
        border-radius: var(--radius, 0.5rem);
        border: 1px solid var(--border-strong);
        background: var(--muted);
        color: var(--foreground);
    }

    /* An alert is a message, not a control: it has no hover or active state,
 * which is why the generator derives none for these surfaces. */
    .kp-alert--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    .kp-alert--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    .kp-alert--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    .kp-alert--destructive {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    /* A destructive action on a destructive plate (Stop on an urgent or a refused question, a failed plate's action) is an outlined key: its
     * own destructive fill with the plate's ink as its edge and a hairline of the plate's colour outside that, so it is never red on red,
     * and on a light or dark card the same edge still reads as the button's own [t56-shared3-1018]. */
    .kp-alert--destructive .kp-button--destructive,
    .kp-alert--destructive .kp-button--destructive:hover:not(:disabled),
    .kp-alert--destructive .kp-button--destructive:active:not(:disabled),
    .kp-alert--destructive .kp-button--destructive:disabled {
        border-color: var(--destructive-foreground);
        box-shadow: 0 0 0 1px var(--destructive);
    }

    /* The flavour is named in text as well as coloured [DI4]: four coloured
 * plates are four colours to someone who sees them all as one. */
    .kp-alert__label {
        font-weight: 600;
    }

    .kp-alert__icon {
        flex: none;
    }

    .kp-alert__body {
        flex: 1;
    }

    .kp-alert__close {
        margin-inline-start: auto;
        flex: none;
    }

    /* --- Network graph [scope-143] ---------------------------------------- */

    /* One node in the middle, the rest on a ring around it, the links between
 * them drawn by kind (a colour and a dash each, listed above the picture
 * with Show all). A pointer or the focus on a node shows only its links; a
 * click keeps it. Labels point away from the hub and are shortened where
 * they would touch, so nothing overlaps or leaves the box at any width.
 * attachGraphs() (js/graph.js) builds it. Each node takes its own hue at the
 * lightness and strength of the theme's first chart colour; a link kind's
 * colour is the page's (`--kp-graph-edge-colour`, a token such as
 * `var(--chart-2)`). Knobs: `--kp-graph-h` (480px; the script sets it to
 * the height it draws), `--kp-graph-label-size` (12px), `--kp-graph-dim`
 * (0.08, a link that is not lit while a node is), `--kp-graph-hue` (210, a
 * node's hue, set per node by the script). */
    .kp-graph {
        display: grid;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        margin: 0;
    }

    /* The kinds of link and Show all, over the picture. */
    .kp-graph__bar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: var(--kp-space-sm, 0.5rem);
        min-block-size: var(--kp-control-height, 2.25rem);
    }

    .kp-graph__show-all {
        margin-inline-start: auto;
    }

    /* Show all keeps its place when there is nothing to show again. */
    .kp-graph__show-all[data-kp-idle] {
        visibility: hidden;
    }

    .kp-graph__kinds {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem);
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-graph__kinds[hidden] {
        display: none;
    }

    .kp-graph__kind {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        padding: 0.125rem var(--kp-space-sm, 0.5rem);
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--card);
        color: var(--foreground);
        font: inherit;
        font-size: var(--kp-text-sm, 0.8125rem);
        cursor: pointer;
    }

    .kp-graph__kind[aria-pressed='false'] {
        color: var(--muted-foreground);
        text-decoration: line-through;
    }

    .kp-graph__kind[aria-pressed='false'] .kp-graph__sample {
        opacity: 0.35;
    }

    .kp-graph__kind:focus-visible {
        outline: 2px solid var(--ring);
        outline-offset: 2px;
    }

    .kp-graph__sample {
        inline-size: 1.5rem;
        block-size: 0.5rem;
        overflow: visible;
    }

    /* The picture, at the height it is drawn at in every state, so the page
 * does not move when the data arrives. */
    .kp-graph__box {
        position: relative;
        min-block-size: var(--kp-graph-h, 480px);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--background);
    }

    .kp-graph__svg {
        display: block;
        inline-size: 100%;
        overflow: visible;
    }

    /* Loading, nothing to draw, or an error: the page's sentence in the
 * picture. */
    .kp-graph__note {
        position: absolute;
        inset: auto var(--kp-space-md, 1rem) 45%;
        margin: 0;
        color: var(--muted-foreground);
        text-align: center;
    }

    .kp-graph__note[hidden] {
        display: none;
    }

    .kp-graph[data-kp-state='error'] .kp-graph__note::before {
        content: '';
        display: inline-block;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        margin-inline-end: var(--kp-space-xs, 0.25rem);
        border-radius: 50%;
        background: var(--destructive);
    }

    /* The ghost of the coming network while loading. A register paints its decided loading picture through
 * these knobs: --kp-graph-ghost (the ghost's opacity), --kp-graph-ghost-anim (the whole ghost's motion, the generic
 * pulse unless a register sets none), and --kp-graph-edge-anim / --kp-graph-node-anim with a stagger per --i and a
 * delay for the links and the nodes. Each link carries pathLength 100, so a travelling dash is a percentage. */
    .kp-graph__ghost {
        opacity: var(--kp-graph-ghost, 0.45);
        pointer-events: none;
    }

    .kp-graph__ghost .kp-graph__node {
        transform-box: fill-box;
        transform-origin: center;
    }

    /* The sentence stands at the foot of the box, under the picture and not over it: the picture gives up the height of
 * one line (--kp-graph-note-h), so the box keeps the height of the drawn network and nothing jumps when it arrives. */
    .kp-graph[data-kp-state='loading'] .kp-graph__svg {
        block-size: calc(var(--kp-graph-h, 480px) - var(--kp-graph-note-h, 2.5rem));
    }

    .kp-graph[data-kp-state='loading'] .kp-graph__note {
        position: static;
        display: flex;
        align-items: center;
        justify-content: center;
        box-sizing: border-box;
        min-block-size: var(--kp-graph-note-h, 2.5rem);
        padding-inline: var(--kp-space-md, 1rem);
    }

    .kp-graph[data-kp-state='loading'] .kp-graph__note[hidden] {
        display: none;
    }

    @keyframes kp-graph-spark {
        to {
            stroke-dashoffset: -100;
        }
    }

    @keyframes kp-graph-signal {
        from {
            stroke-dashoffset: 100;
        }
        to {
            stroke-dashoffset: -16;
        }
    }

    @keyframes kp-graph-glow {
        0%,
        100% {
            filter: brightness(1);
        }
        50% {
            filter: brightness(1.6);
        }
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-graph__ghost {
            animation: var(--kp-graph-ghost-anim, kp-pulse 1600ms ease-in-out infinite);
        }

        .kp-graph[data-kp-state='loading'] .kp-graph__ghost .kp-graph__edge {
            animation: var(--kp-graph-edge-anim, none);
            animation-delay: calc(var(--i, 0) * var(--kp-graph-edge-stagger, 0ms) + var(--kp-graph-edge-delay, 0ms));
        }

        .kp-graph[data-kp-state='loading'] .kp-graph__ghost .kp-graph__node {
            animation: var(--kp-graph-node-anim, none);
            animation-delay: calc(var(--i, 0) * var(--kp-graph-node-stagger, 0ms) + var(--kp-graph-node-delay, 0ms));
        }

        .kp-graph__edge,
        .kp-graph__node {
            transition:
                opacity 150ms ease,
                stroke-width 150ms ease;
        }
    }

    /* What a pointer, a click and the keys do, under the picture in the
 * page's flow (never over it). */
    .kp-graph__hint {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-graph__edge,
    .kp-graph__sample line {
        fill: none;
        stroke: var(--kp-graph-edge-colour, var(--chart-3));
        stroke-width: 1.6;
    }

    .kp-graph__sample line {
        stroke-width: 2;
    }

    /* A kind's dash, on its links and on its sample in the list. */
    .kp-graph [data-kp-style='dash'] {
        stroke-dasharray: 6 3;
    }

    .kp-graph [data-kp-style='dot'] {
        stroke-dasharray: 2 4;
        stroke-linecap: round;
    }

    .kp-graph [data-kp-style='long-dash'] {
        stroke-dasharray: 12 4;
    }

    .kp-graph__edge.is-on {
        stroke-width: 2.6;
    }

    .kp-graph__edge.is-dim {
        opacity: var(--kp-graph-dim, 0.08);
    }

    .kp-graph__edge.is-hidden {
        display: none;
    }

    /* Each node its own hue, at the lightness and strength of the theme's
 * first chart colour, so it reads on the theme's ground. */
    .kp-graph__node {
        --kp-graph-node-colour: oklch(from var(--chart-1) l max(c, 0.12) var(--kp-graph-hue, 210));
        cursor: pointer;
        outline: none;
    }

    .kp-graph__ring {
        fill: var(--card);
        stroke: var(--kp-graph-node-colour);
        stroke-width: 2.5;
    }

    .kp-graph__core {
        fill: var(--kp-graph-node-colour);
    }

    /* A node outside the network: a dashed grey ring, no core. */
    .kp-graph__node--external .kp-graph__ring {
        stroke: var(--muted-foreground);
        stroke-dasharray: 3 3;
    }

    /* A node whose settings differ from the plan: a dotted ring around it. */
    .kp-graph__flag {
        fill: none;
        stroke: var(--warning-foreground);
        stroke-width: 1.5;
        stroke-dasharray: 2 3;
    }

    .kp-graph__label {
        fill: var(--foreground);
        font-size: var(--kp-graph-label-size, 12px);
        font-weight: 500;
        paint-order: stroke;
        stroke: var(--background);
        stroke-width: 4px;
        stroke-linejoin: round;
    }

    .kp-graph__node:focus-visible .kp-graph__ring {
        stroke: var(--ring);
        stroke-width: 4;
    }

    .kp-graph__node.is-picked .kp-graph__ring {
        stroke-width: 5;
    }

    .kp-graph__node.is-dim {
        opacity: 0.3;
    }
    /* --- Freshness line [scope-143] ---------------------------------------- */

    /* "updated 12 s ago", ticking (js/freshness.js). Tabular digits, kept
 * whole on one line (it wraps as a unit, never inside a number), and as
 * wide as the widest text of its unit: the script reserves that width, so
 * a neighbour never moves when "59 s" becomes "1 min". Turning stale
 * (`data-kp-stale`, past `data-kp-stale-after` seconds) draws a warning
 * plate whose edge is a shadow, so it changes no size either. */
    :where(.kp-ago, [data-kp-ago]) {
        display: inline-block;
        white-space: nowrap;
        font-variant-numeric: tabular-nums;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
    }

    :where(.kp-ago, [data-kp-ago])[data-kp-stale] {
        background: var(--kp-ago-stale-bg, var(--warning));
        color: var(--kp-ago-stale-fg, var(--warning-foreground));
        box-shadow: 0 0 0 var(--kp-ago-stale-edge, 0.25em) var(--kp-ago-stale-bg, var(--warning));
    }

    /* --- Freshness line: a calm stale tone [audhd-opts-1019; audhd-recepten 2] ---
 * `data-kp-stale-tone="calm"` on the line: once stale it is a quiet plate (the muted ground, the ordinary ink) and not the
 * amber warning, for data that is old on purpose. The same edge shadow as the warning plate, so turning
 * stale still moves nothing. Knobs [KT6]: --kp-ago-calm-bg (the muted), --kp-ago-calm-fg (the foreground),
 * --kp-ago-stale-edge (0.25em, shared). */
    :where(.kp-ago, [data-kp-ago])[data-kp-stale][data-kp-stale-tone='calm'] {
        background: var(--kp-ago-calm-bg, var(--muted));
        color: var(--kp-ago-calm-fg, var(--foreground));
        box-shadow: 0 0 0 var(--kp-ago-stale-edge, 0.25em) var(--kp-ago-calm-bg, var(--muted));
    }

    /* --- Attention band [scope-143] --------------------------------------- */

    /* One alert per problem, worst first, each with its own fix. With no
 * problem the band takes no room at all: never an "all is well" filler.
 * attachAttention() keeps the items in severity order in the DOM, so a
 * screen reader meets them in the order the eye does. */
    .kp-attention {
        container: kp-attention / inline-size;
        display: grid;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-attention:not(:has(> .kp-attention__item)) {
        display: none;
    }

    .kp-attention__item {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 1rem);
        margin: 0;
    }

    .kp-attention__icon {
        display: grid;
        place-items: center;
        inline-size: 1.75rem;
        block-size: 1.75rem;
        border-radius: 50%;
        background: color-mix(in oklab, currentColor 14%, transparent);
        font-weight: 700;
    }

    .kp-attention__text > strong {
        display: block;
    }

    .kp-attention__text > span {
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-attention__actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* data-kp-subgrid [align-grid-1019; HTTPSwitchboard gap 25]: an inline-size container is layout-contained, and a
     * layout-contained grid cannot be a subgrid, so a band and its neighbours could not share rows. With the attribute
     * the band (and .kp-problems) is no container: its rows may be subgrids of the page's grid, and the narrow fold
     * follows the form grid around it (36rem) instead of its own width. */
    .kp-attention[data-kp-subgrid],
    .kp-problems[data-kp-subgrid] {
        container-type: normal;
    }

    @container kp-formgrid (max-width: 36rem) {
        .kp-attention[data-kp-subgrid] .kp-attention__item {
            grid-template-columns: auto minmax(0, 1fr);
        }

        .kp-attention[data-kp-subgrid] .kp-attention__actions {
            grid-column: 1 / -1;
            justify-content: flex-start;
        }

        .kp-problems[data-kp-subgrid] .kp-alert__item {
            grid-template-columns: minmax(0, 1fr);
        }

        .kp-problems[data-kp-subgrid] .kp-alert__item > .kp-alert__actions {
            grid-column: 1;
            grid-row: auto;
        }
    }

    @container kp-attention (max-width: 34rem) {
        .kp-attention__item {
            grid-template-columns: auto minmax(0, 1fr);
        }

        .kp-attention__actions {
            grid-column: 1 / -1;
            justify-content: flex-start;
        }
    }

    /* A soft tint of the severity with an edge of it, in the page's own
 * text colour, and a solid round icon: calm, still unmistakable.
 * `--kp-attention-tint` is how much of the tone the plate takes, 8 % by
 * default; a register lowers it for a severity whose tint pulls the page's
 * text under 4.6:1 (Shade (dark)'s info, 4.49 at 8 %) [alert-contrast-M1]. */
    .kp-attention > .kp-attention__item {
        border-color: color-mix(in oklab, var(--kp-attention-tone) 45%, var(--border));
        border-inline-start-width: 3px;
        background: color-mix(in oklab, var(--kp-attention-tone) var(--kp-attention-tint, 8%), var(--card));
        color: var(--foreground);
    }

    .kp-attention > .kp-attention__item > .kp-attention__icon {
        background: var(--kp-attention-tone);
        color: var(--kp-attention-on-tone);
    }

    .kp-attention__item[data-kp-severity='critical'] {
        --kp-attention-tone: var(--destructive);
        --kp-attention-on-tone: var(--destructive-foreground);
    }

    .kp-attention__item[data-kp-severity='warning'] {
        --kp-attention-tone: var(--warning-foreground);
        --kp-attention-on-tone: var(--warning);
    }

    .kp-attention__item[data-kp-severity='info'] {
        --kp-attention-tone: var(--info-foreground);
        --kp-attention-on-tone: var(--info);
    }

    /* --- Form field [TH5] ------------------------------------------------ */

    .kp-field {
        display: flex;
        flex-direction: column;
        /* --kp-space-xs is 0.25rem, which is what this was [TH94, TH105]. */
        gap: var(--kp-field-gap, var(--kp-space-xs));
        max-width: var(--kp-field-max-width, 28rem);
        min-inline-size: 0;
    }

    .kp-field__label {
        /* The label's and the help text's size are the package's [scope-87]:
     * titanium's, on the running line height. */
        font-size: var(--kp-field-label-size, 0.9rem);
        line-height: var(--kp-line-height, 1.5);
        font-weight: 600;
    }

    .kp-field__input {
        /* The button's box [scope-80]: the floor, no block padding and one
     * line height are the package's; a register keeps the rest. */
        min-height: var(--kp-control-height, 2.25rem);
        padding: 0 0.625rem;
        line-height: var(--kp-control-line-height, 1.25);
        border: 1px solid var(--input);
        border-radius: var(--radius, 0.5rem);
        background: var(--background);
        color: var(--foreground);
        font: inherit;
        box-shadow: var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
        /* An input's intrinsic width comes from its `size` in the current
     * face, and a wide face (woodblock's Zen Kaku Gothic New) pushed it past
     * a 320px viewport — found by the DI11 reflow test in Firefox. The
     * field, not the face, bounds it. */
        inline-size: 100%;
        min-inline-size: 0;
        box-sizing: border-box;
    }

    /* The field's ring, composed with its offset shadow [fix-38, DI2]: the
     * rule above sets box-shadow in kp.components, which beats the ring in
     * kp.base, so a focused input kept only the outer half — the page's own
     * ground, on a field grounded in the same colour. Tabbing to a field
     * changed 0 pixels in formal, light, pastel, blueprint, solstice and
     * Shade (light). Restated as .kp-button:focus-visible does. */
    .kp-field__input:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
    }

    /* The native <select>'s open list is drawn by the browser in the
 * platform's own highlight colour — purple on Kenny's desktop, in every
 * theme, which is how the one control the package did not paint became
 * the one that looked wrong [KT8]. Where the browser lets a page take the
 * list over (Chromium 135+, `appearance: base-select`), it wears the
 * theme: the popover surface, the ink wash on the hovered option, weight
 * and a check on the chosen one. Elsewhere the native list stays. */
    @supports (appearance: base-select) {
        select.kp-field__input,
        select.kp-field__input::picker(select) {
            appearance: base-select;
        }

        select.kp-field__input::picker(select) {
            margin-block-start: 0.25rem;
            padding: 0.25rem;
            border: 1px solid var(--border-strong);
            border-radius: var(--radius, 0.5rem);
            background: var(--popover);
            color: var(--popover-foreground);
            max-block-size: var(--kp-popover-max-height, min(80vh, 40rem));
            /* Without an inline limit the list is as wide as its longest
               option, and a long one ran past the window's edge [fix-78]. */
            max-inline-size: var(--kp-picker-max-width, min(40rem, calc(100vw - 2rem)));
            overflow: auto;
        }

        select.kp-field__input option {
            padding: var(--kp-menu-item-pad, 0.375rem 0.625rem);
            border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
            white-space: normal;
            overflow-wrap: anywhere;
        }

        select.kp-field__input option:hover,
        select.kp-field__input option:focus-visible {
            background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        }

        select.kp-field__input option:checked {
            font-weight: 600;
        }

        /* The check mark is the option's first flex item, so an auto margin
           alone pushed the label to the end with it [fix-78]; ordered last,
           the label keeps the start edge and the mark sits at the end. */
        select.kp-field__input option::checkmark {
            content: var(--kp-glyph-check, '✓');
            order: 1;
            margin-inline-start: auto;
        }
    }

    .kp-field__help {
        font-size: var(--kp-field-help-size, 0.8rem);
        line-height: var(--kp-line-height, 1.5);
        color: var(--muted-foreground);
    }

    /* The error is text, and it names what is wrong. A red border alone is
 * colour as the only carrier [DI4], and says nothing to a screen reader. */
    .kp-field__error {
        /* Its size is the package's [scope-88]: titanium's 13px, on the
     * running line height; a register keeps its face and its ornaments. */
        padding-block: 0;
        font-size: var(--kp-field-error-size, 0.8125rem);
        line-height: var(--kp-line-height, 1.5);
        color: var(--destructive);
    }

    .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    /* A field is not always a text box. Before this the component rendered an
 * input whatever it was told, so every real form grew a hand-written half
 * beside it — without the label, the error and the describedby wiring
 * that are the point of the component. */

    /* Disabled and read-only are two promises and look like two [gap-11].
 * Disabled cannot be used: it fades and refuses the pointer. Read-only can
 * be focused, selected and copied but not changed: it keeps full ink, so
 * the value stays a value, and loses the editable look — a dashed
 * boundary on the muted ground, a record rather than a box to type in.
 * All three painted the same, and a reviewer typed into the read-only
 * field and thought the page had frozen. `[readonly]` rather than
 * `:read-only`, which also matches every <select>. */
    .kp-field__input:disabled {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        cursor: not-allowed;
    }

    .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    .kp-field__input--multiline {
        min-height: 5.5rem;
        /* Several lines, so a text box and not a one-line control: it keeps
     * block padding and the running text's line height [scope-80]. */
        padding-block: calc(var(--kp-space-sm, 0.5rem) * 0.75);
        line-height: var(--kp-line-height, 1.5);
        /* Vertical only: a textarea dragged wider than its column breaks the
     * layout it sits in, and nobody needs it. */
        resize: vertical;
    }

    /* The box comes before its label, because that is the order it is read in
 * and the order it is clicked in. The label's words sit on the box's centre,
 * not on its baseline [scope-92]: a checkbox's baseline is its bottom edge,
 * so baseline alignment put the words at the height of the box's bottom in
 * every theme; and a register that draws its own box (appearance: none, a
 * grid whose only child is the ::before tick) has no baseline until the
 * tick exists, so the words rose by 2 to 6px when the box was ticked
 * (cyberpunk, dark, brutalism, retro, titanium). Centring reads no
 * baseline, so the state cannot move the words. */
    .kp-field--check {
        flex-direction: row;
        align-items: center;
        flex-wrap: wrap;
        gap: 0.5rem;
    }

    .kp-field--check .kp-field__label {
        font-weight: 400;
        /* Beside the box, and wrapping there: at its max-content width a long
     * label went down to a line of its own, under the box, in every theme
     * whose face is wide (cyberpunk, brutalism, deco, nostromo) [scope-92]. */
        flex: 1 1 0;
        min-inline-size: 0;
    }

    .kp-field--check .kp-field__help,
    .kp-field--check .kp-field__error {
        /* Under both, not beside the label: an error squeezed into the gap
     * next to a checkbox wraps to one word per line at 320 px [DI11]. */
        flex-basis: 100%;
    }

    /* A radio group is a group: fieldset and legend, so the question is read
 * before the answers rather than once per answer. */
    .kp-fieldset {
        border: 0;
        margin: 0;
        padding: 0;
        min-inline-size: 0;
    }

    .kp-fieldset > legend {
        padding: 0;
    }

    /* The same centre as a checkbox field's, for the same two reasons
 * [scope-92]. */
    .kp-field__option {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        font-size: var(--kp-field-option-size, 0.875rem);
    }

    .kp-field__check {
        /* 1.15rem rather than the browser default 13 px: the box is the
     * target, and a target under 24 px fails WCAG 2.5.8 for anyone whose
     * hands are not steady. The label is clickable too, which is what
     * actually makes the target big enough. */
        inline-size: 1.15rem;
        block-size: 1.15rem;
        /* A knob: the browser paints the check and the radio dot in this
     * colour, and a theme whose primary is its ink (brutalism, mono) gets
     * a check that looks like an unchecked box. Those themes set it in
     * css/_rules.css [KT8]. */
        accent-color: var(--kp-control-accent, var(--primary));
        flex: none;
    }

    /* The browser's margin on a radio is 3px above and none below, so a
 * centred radio's box sat 1.5px above its words [scope-92]. Beside its
 * words the control carries no margin across the line; the gap holds the
 * two apart. A register that sets its own margin still wins. */
    .kp-field--check > .kp-field__check,
    .kp-field__option > .kp-field__check {
        margin-block: 0;
    }

    /* The error text carries the message [DI4]; this only makes the control
 * itself findable when the summary sends someone to it. A checkbox has no
 * border to colour, so it is an outline. The child combinator keeps it on
 * the checkbox that IS the field: the radios inside an invalid group were
 * framed one by one, a square frame around every round control, which
 * read as several wrong answers rather than one [gap-11]. */
    .kp-field--invalid > .kp-field__check {
        outline: var(--focus-ring-width, 2px) solid var(--destructive);
        outline-offset: 2px;
    }

    /* An invalid radio group is one wrong answer, so it carries one mark:
 * an outline around the whole group, legend and options together
 * [gap-11]. An outline rather than a border, because a register that
 * frames its fieldsets sets the border in a later layer and would
 * silently take the mark away. Either spelling counts: the attribute on
 * the group, or the group inside an invalid field. */
    .kp-fieldset[aria-invalid='true'],
    .kp-field--invalid > .kp-fieldset {
        outline: var(--focus-ring-width, 2px) solid var(--destructive);
        outline-offset: var(--kp-fieldset-invalid-offset, 0.375rem);
    }

    /* --- Switch [gap-11] ------------------------------------------------- */

    /* A checkbox that says on and off instead of ticked: the real control is
 * an <input type="checkbox" role="switch">, so it submits with a form,
 * reads its state from `checked`, flips with Space and needs no script.
 * The geometry and the states are the concept Kenny approved on
 * 2026-09-13 ("Switch: Akkoord", catalogue/switch.html), moved onto knobs
 * whose defaults are the concept's own values [KT6]. The label is the
 * whole target: the row is a <label>. */
    .kp-switch {
        display: inline-flex;
        /* The track stays on the first line of a label that wraps: the text
     * lines are as tall as the track. */
        align-items: flex-start;
        line-height: var(--kp-switch-height, 1.5rem);
        gap: var(--kp-switch-gap, 0.625rem);
        max-inline-size: var(--kp-switch-max-width, 28rem);
        cursor: pointer;
    }

    .kp-switch__input {
        appearance: none;
        position: relative;
        flex: none;
        inline-size: var(--kp-switch-width, 2.5rem);
        block-size: var(--kp-switch-height, 1.5rem);
        margin: 0;
        border: var(--kp-switch-border, 1px) solid var(--border-strong);
        /* A knob, so a register squares the track from the row without
     * restating the track's own rule; the thumb has its own. */
        border-radius: var(--kp-switch-radius, var(--kp-radius-pill, 999px));
        background: var(--muted);
        cursor: inherit;
    }

    /* The thumb: a disc that travels. Its position carries the state as well
 * as the colour does [DI4]. Sized from the track, its inset and the
 * border on both sides, so a register that thickens the border keeps the
 * thumb inside. */
    .kp-switch__input::before {
        content: '';
        position: absolute;
        inset-block: var(--kp-switch-inset, 0.125rem);
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        inline-size: calc(var(--kp-switch-height, 1.5rem) - 2 * var(--kp-switch-inset, 0.125rem) - 2 * var(--kp-switch-border, 1px));
        border-radius: var(--kp-switch-thumb-radius, 50%);
        background: var(--muted-foreground);
    }

    .kp-switch__input:checked {
        border-color: var(--primary);
        background: var(--primary);
    }

    /* The thumb travels by its inset. Moving it by transform instead (fix-88,
 * 2026-10-03) put the same thumb in the same place but rasterised its edge
 * differently, which sent 62 approved switch pairs back to Kenny for no
 * visible change; for a 24px thumb over 150ms the layout cost is not worth
 * that, so the inset stays. */
    .kp-switch__input:checked::before {
        inset-inline-start: calc(100% - var(--kp-switch-height, 1.5rem) + var(--kp-switch-inset, 0.125rem) + 2 * var(--kp-switch-border, 1px));
        background: var(--primary-foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-switch__input,
        .kp-switch__input::before {
            transition:
                background-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                inset-inline-start var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    /* On and off in words beside the track, so the state never rests on
 * colour or position alone. The words are two spans from js/strings.js —
 * never a `content` literal, which no consumer could replace [KT5] — and
 * the one that does not apply is not rendered. aria-hidden on the
 * wrapper, because the role already announces the state. */
    .kp-switch__state {
        display: inline-grid;
        min-inline-size: var(--kp-switch-state-min, 2rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* Both words share one cell and the one that does not apply is only
       hidden, so the box is as wide as the wider word in any face or
       language and a flip moves nothing after it [fix-79]. It used to be
       display: none, which held only while a word fitted the 2rem floor. */
    .kp-switch__on,
    .kp-switch__off {
        grid-area: 1 / 1;
    }

    .kp-switch__on,
    .kp-switch:has(:checked) .kp-switch__off {
        visibility: hidden;
    }

    .kp-switch:has(:checked) .kp-switch__on {
        visibility: visible;
    }

    .kp-switch:has(:disabled) {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        cursor: not-allowed;
    }

    /* The same mark an invalid checkbox takes, in the alarm colour; the
 * message under it says what is wrong in words [DI4]. */
    .kp-switch__input[aria-invalid='true'] {
        outline: var(--focus-ring-width, 2px) solid var(--destructive);
        outline-offset: 2px;
    }

    /* --- Table [TH3] ----------------------------------------------------- */

    .kp-table-wrap {
        /* The table scrolls inside its own box; the page does not scroll
     * sideways because of it [DI11]. Reaching that scrollbar without a
     * mouse is TH95's repair, and it is not written here: the attributes
     * that make this box a named region come from components/table.jsx
     * and js/tables.js, because a `tabindex` is markup, not style. */
        overflow-x: auto;

        /* The size everything below this reads [TH96, AR24]. A table that
     * falls into cards because the WINDOW is narrow is wrong in every
     * layout that is not the whole window — a 400 px column on a 1280 px
     * page kept the table shape and scrolled. The query asks the box the
     * table actually lives in instead.
     *
     * `container-type: inline-size` applies inline-axis containment, so
     * the element no longer sizes to its contents. Measured before and
     * after, in Chromium 141 and Firefox 145, at the build of R3:
     * normal block flow 500 px -> 500 px, and inside `.kp-datatable`
     * (a column flex container, the shipped shape) 500 px -> 500 px.
     * A wrapper the consumer has put in a SHRINK-TO-FIT box does move:
     * as a flex-row item 279/328 px -> 0, as an inline-block 207/244 px
     * -> 0, in an auto grid track 389/414 px -> 250 px. The user guide
     * says so, and `tests/tables.spec.mjs` holds the two shapes the
     * package draws itself. */
        container: kp-table / inline-size;
        /* A floor for the consumer whose layout collapses the wrapper
     * [R3-CQ, KT6]. Containment means this box no longer sizes to its
     * contents, so in a shrink-to-fit parent — a flex row, an
     * inline-block — it goes to zero. Measured while deciding this: no
     * value restores the natural width, because the contents are
     * precisely what stopped counting. `100%` gives the whole parent,
     * `min-content` gives zero. So this is a floor and not a repair, and
     * `auto` — the initial value in every context — makes the default a
     * true no-op. */
        min-inline-size: var(--kp-table-wrap-min, auto);
    }

    /* Two ways a cell can hold a value that does not fit [TH96].
 *
 * `.kp-cell-break` is for identifiers: a 70-character key with no space
 * in it is one unbreakable word, and one such word in one row widens the
 * whole table past its container. `.kp-cell-truncate` is for prose: one
 * line, an ellipsis, and the value still whole in the cell — a screen
 * reader reads it, find-in-page finds it, a copy takes it, and both
 * channels put it in the `title` for the pointer.
 *
 * `--kp-cell-truncate-max` is a suggestion rather than a limit, and it
 * is there for a measured reason: under the automatic table layout a
 * `max-inline-size` on a `<td>` does not cap the cell — asked for 12rem
 * it came out 416 px wide in a 500 px container — but it does stop a
 * `white-space: nowrap` cell from making its column as wide as the whole
 * sentence and pushing the table out of its wrapper. Without it the
 * table simply grows and nothing is ever clipped, which is the first cut
 * of this class, measured red. A hard cap needs `table-layout: fixed` or
 * a width on the column. */
    .kp-cell-break {
        overflow-wrap: anywhere;
        word-break: break-word;
    }

    .kp-cell-truncate {
        max-inline-size: var(--kp-cell-truncate-max, 12rem);
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-table {
        width: 100%;
        border-collapse: collapse;
        font-variant-numeric: tabular-nums;
    }

    .kp-table th,
    .kp-table td {
        /* The row height is the package's, in every theme [scope-80]: a cell's
     * block size is a floor in a table (a taller value still grows the
     * row), with one line height, so a face's own
     * ascent and descent no longer decide how tall a row is.
     * --kp-row-height is a step above --kp-control-height, so a field
     * edited in its cell fits and the density mode brings rows down with
     * the controls. The inline padding has no step equal to 0.625rem, so it
     * keeps its literal and a knob of its own [TH94, TH105]. */
        box-sizing: border-box;
        block-size: var(--kp-row-height, calc(var(--kp-control-height, 2.25rem) + 0.25rem));
        /* A quarter rem keeps a wrapped value off the row's rules and leaves
     * a one-line row at its height (1.25 lines of text in 2.5rem). */
        padding: var(--kp-table-cell-block, var(--kp-space-xs, 0.25rem)) var(--kp-table-cell-inline, 0.625rem);
        line-height: var(--kp-control-line-height, 1.25);
        text-align: start;
        border-bottom: 1px solid var(--border);
    }

    .kp-table thead th {
        border-bottom: 1px solid var(--border-strong);
        font-size: var(--kp-text-sm, 0.8125rem);
        color: var(--muted-foreground);
    }

    .kp-table tbody tr:hover {
        background: var(--muted);
    }

    /* --- Action columns [scope-143] --------------------------------------- */

    /* A list's row buttons sit in columns the whole list shares, so a button
 * of one role starts at one edge and has one width on every row, whatever
 * its label, and a row that lacks a role leaves that column empty.
 *
 * A list (`ul`, `ol`) is a grid; each row is a subgrid of it, and the row's
 * button box a subgrid of the row. The browser sizes every column to its
 * widest button: no measuring, nothing to redo when a font arrives or the
 * theme changes. By position from the end it needs no script at all (up to
 * four buttons); with named roles (`data-kp-action` on a button)
 * attachActionColumns() writes each button's column and the list's count.
 *
 * A table cannot be a subgrid, so there the script measures each role's
 * widest button and writes the widths on the table. */
    .kp-action-list {
        --kp-action-count: 1;
        container: kp-action-list / inline-size;
        display: grid;
        grid-template-columns: minmax(0, 1fr) repeat(var(--kp-action-count), auto);
        column-gap: var(--kp-action-gap, var(--kp-space-sm, 0.5rem));
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-action-list:has(> li > .kp-row-actions > :nth-child(2)) {
        --kp-action-count: 2;
    }

    .kp-action-list:has(> li > .kp-row-actions > :nth-child(3)) {
        --kp-action-count: 3;
    }

    .kp-action-list:has(> li > .kp-row-actions > :nth-child(4)) {
        --kp-action-count: 4;
    }

    .kp-action-list > li {
        display: grid;
        grid-column: 1 / -1;
        grid-template-columns: subgrid;
        align-items: center;
        row-gap: var(--kp-space-xs, 0.25rem);
        padding-block: var(--kp-space-sm, 0.5rem);
        border-block-end: 1px solid var(--border);
    }

    .kp-action-list > li > :first-child {
        grid-column: 1;
        min-inline-size: 0;
    }

    .kp-row-actions {
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: max-content;
        grid-template-columns: var(--kp-action-widths, none);
        justify-content: end;
        align-items: center;
        gap: var(--kp-action-gap, var(--kp-space-sm, 0.5rem));
    }

    .kp-action-list .kp-row-actions {
        grid-column: 2 / -1;
        grid-template-columns: subgrid;
    }

    /* By position from the end, the primary last: CSS alone. */
    .kp-action-list .kp-row-actions > :nth-last-child(1) {
        --kp-action-col: -2 / -1;
    }

    .kp-action-list .kp-row-actions > :nth-last-child(2) {
        --kp-action-col: -3 / -2;
    }

    .kp-action-list .kp-row-actions > :nth-last-child(3) {
        --kp-action-col: -4 / -3;
    }

    .kp-action-list .kp-row-actions > :nth-last-child(4) {
        --kp-action-col: -5 / -4;
    }

    /* A button fills its column, its label centred: one role, one width. */
    .kp-row-actions > * {
        grid-column: var(--kp-action-col, auto);
        justify-content: center;
        white-space: nowrap;
    }

    .kp-row-actions:empty {
        display: none;
    }

    /* While the script measures a table, every button at its own size. */
    [data-kp-action-measuring] .kp-row-actions > * {
        grid-column: auto;
        justify-self: start;
    }

    /* On a narrow list (under 30rem) the row's text takes the whole line
     * and its buttons stack under it, one per line, each centred under the
     * row (Kenny, 2026-10-05: "the phone view can center the buttons, left
     * alignment doesn't look nice"), each label on a single line: a label is
     * never wrapped or cut (Kenny's UI rule; the equal columns of the wider
     * list cut "Review and update all 4…" by 20 px on the dashboard's Inbox,
     * action-columns-narrow-M1). The wider list keeps the equal columns
     * Kenny approved (2026-10-04). */
    @container kp-action-list (max-width: 30rem) {
        .kp-action-list > li {
            grid-template-columns: minmax(0, 1fr);
        }

        .kp-action-list > li > :first-child,
        .kp-action-list .kp-row-actions {
            grid-column: 1;
        }

        .kp-action-list .kp-row-actions {
            grid-template-columns: minmax(0, 1fr);
            grid-auto-flow: row;
            justify-content: stretch;
            row-gap: var(--kp-space-xs, 0.25rem);
        }

        .kp-action-list .kp-row-actions > * {
            grid-column: 1;
            justify-self: center;
            inline-size: auto;
            white-space: nowrap;
        }
    }

    /* On a narrow table the row's buttons stack in one column, as wide as
     * the widest (`--kp-action-stack`, measured by attachActionColumns()).
     * Any table holding `.kp-row-actions`, not only `.kp-table`
     * [action-columns-narrow-M1]: inside the package's table wrapper
     * (`.kp-table-wrap`, the `kp-table` container) at its 30rem, and in a
     * table outside it once the window is a phone's or a small tablet's
     * (under 48rem, the width the homelab dashboard measured its own
     * repository table squeezing its cells at). */
    @container kp-table (max-width: 30rem) {
        table .kp-row-actions {
            grid-auto-flow: row;
            grid-template-columns: var(--kp-action-stack, max-content);
        }

        table .kp-row-actions > * {
            grid-column: 1;
        }
    }

    @media (max-width: 48rem) {
        table:not(.kp-table-wrap table, .kp-datatable table) .kp-row-actions {
            grid-auto-flow: row;
            grid-template-columns: var(--kp-action-stack, max-content);
        }

        table:not(.kp-table-wrap table, .kp-datatable table) .kp-row-actions > * {
            grid-column: 1;
        }
    }

    /* Rows with a lead [kpadopt4-rows; homelab's Inbox `nx-inbox`, JobTracker's
 * queue, files and appointments, kyu's backlog]. `.kp-action-list--lead`
 * gives every row a lead column before its words: a state badge or dot, a
 * file's format, an appointment's day and hour. The column is as wide as
 * the widest lead of the list and no wider (fix-64), so every title starts
 * at one edge; the buttons keep their shared columns. The words are
 * `.kp-action-list__main`: a title, a meta line whose parts are set apart
 * by a dot, and an optional fold for a payload (the accordion's bare item,
 * so it opens with the theme's fold motion). A row says its state on
 * `data-kp-state` by a bar along its start edge that every row reserves,
 * so a state moves nothing: `new` (unread), `active` (claimed, in flight),
 * `warn`, `failed`, `next` (the next one up: the bar, a primary wash and
 * the lead in the primary), `done` and `past` (quieter ink, not opacity).
 * `.kp-action-list__group` is a heading row across the list (Upcoming,
 * Past). Knobs [KT6]: `--kp-action-list-lead-gap`, `--kp-action-list-bar`
 * (3px), `--kp-action-list-pad` (the row's inline padding),
 * `--kp-action-list-next-wash` (6 %), `--kp-action-list-payload-max`. */
    .kp-action-list--lead {
        grid-template-columns: auto minmax(0, 1fr) repeat(var(--kp-action-count), auto);
    }

    .kp-action-list--lead > li {
        padding-inline: var(--kp-action-list-pad, var(--kp-space-sm, 0.5rem));
        border-inline-start: var(--kp-action-list-bar, 3px) solid transparent;
    }

    /* The lead sits on the title's first line: its box is one line of the
     * title high, its content centred in it. */
    .kp-action-list--lead > li > .kp-action-list__lead {
        grid-column: 1;
        display: grid;
        justify-items: center;
        align-items: center;
        align-self: start;
        min-block-size: 1lh;
        min-inline-size: 0;
        margin-inline-end: var(--kp-action-list-lead-gap, var(--kp-space-xs, 0.25rem));
    }

    .kp-action-list--lead > li > .kp-action-list__main {
        grid-column: 2;
        min-inline-size: 0;
    }

    .kp-action-list--lead > li > .kp-row-actions {
        grid-column: 3 / -1;
    }

    /* align-pkg-1019:action-lead:start
     * The row's first line is one band as high as a control: the lead (a badge), the title's first line and the row's
     * buttons all stand on that band's centre. The buttons were centred on the whole row, so beside a two-line row they sat
     * 21 px below the badge (measure-align: audhd-recepten zero-prep, homelab inbox-list). A one-line row keeps its height:
     * the band is the control height, which the buttons filled anyway. */
    .kp-action-list--lead > li {
        --kp-action-list-band: max(1lh, var(--kp-control-height, 2.25rem));
        align-items: start;
    }

    .kp-action-list--lead > li > .kp-action-list__lead {
        align-items: center;
        min-block-size: var(--kp-action-list-band);
    }

    .kp-action-list--lead > li > .kp-action-list__main > .kp-action-list__title {
        padding-block-start: calc((var(--kp-action-list-band) - 1lh) / 2);
    }

    .kp-action-list--lead > li > .kp-row-actions {
        align-self: start;
        min-block-size: var(--kp-action-list-band);
    }
    /* align-pkg-1019:action-lead:end */

    .kp-action-list__main {
        display: grid;
        gap: calc(var(--kp-space-xs, 0.25rem) / 2);
    }

    .kp-action-list__title {
        font-weight: 600;
        overflow-wrap: anywhere;
    }

    .kp-action-list__text {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: anywhere;
    }

    .kp-action-list__meta {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    .kp-action-list__meta > * {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    /* A dot after each part of the meta line that a plain part follows, kept
     * with the part before it, so a line that wraps never starts with a dot;
     * silent to a reader. Badges stand apart by their own plate. */
    .kp-action-list__meta > :not(.kp-badge):has(+ :not(.kp-badge))::after {
        content: '·' / '';
        margin-inline-start: var(--kp-space-sm, 0.5rem);
    }

    /* The lead parts: an appointment's moment, the day over the hour. */
    .kp-action-list__when {
        display: grid;
        justify-items: center;
        line-height: 1.25;
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
    }

    .kp-action-list__when > :first-child {
        font-weight: 600;
    }

    .kp-action-list__when > :last-child:not(:first-child) {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* A payload under the row, folded: the bare accordion item. */
    .kp-action-list__more > summary {
        inline-size: fit-content;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        cursor: pointer;
    }

    .kp-action-list__more > summary:hover {
        color: var(--foreground);
    }

    .kp-action-list__payload {
        box-sizing: border-box;
        max-block-size: var(--kp-action-list-payload-max, 16rem);
        margin: var(--kp-space-xs, 0.25rem) 0 0;
        padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 1rem);
        overflow: auto;
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--muted);
        color: var(--foreground);
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-xs, 0.75rem);
        white-space: pre-wrap;
        overflow-wrap: anywhere;
    }

    /* A heading row across the list. */
    .kp-action-list > li.kp-action-list__group {
        display: block;
        padding-block: var(--kp-space-md, 1rem) var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 600;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    .kp-action-list__group > :is(h2, h3, h4, h5, h6) {
        margin: 0;
        font: inherit;
        letter-spacing: inherit;
        text-transform: inherit;
    }

    /* The row's state: a bar along the start edge (reserved by every row),
     * a quieter ink for what is over. */
    .kp-action-list--lead > li[data-kp-state='new'] {
        border-inline-start-color: var(--primary);
    }

    .kp-action-list--lead > li[data-kp-state='active'] {
        border-inline-start-color: var(--info-foreground);
    }

    .kp-action-list--lead > li[data-kp-state='warn'] {
        border-inline-start-color: var(--warning-foreground);
    }

    .kp-action-list--lead > li[data-kp-state='failed'] {
        border-inline-start-color: var(--destructive);
    }

    .kp-action-list--lead > li[data-kp-state='next'] {
        border-inline-start-color: var(--primary);
        background: color-mix(in oklab, var(--primary) var(--kp-action-list-next-wash, 6%), transparent);
    }

    .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--primary);
    }

    .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead .kp-action-list__when > :last-child {
        color: inherit;
    }

    .kp-action-list--lead > li:is([data-kp-state='done'], [data-kp-state='past']) :is(.kp-action-list__lead, .kp-action-list__title) {
        color: var(--muted-foreground);
    }

    .kp-action-list--lead > li:is([data-kp-state='done'], [data-kp-state='past']) .kp-action-list__title {
        font-weight: 500;
    }

    /* A row at work (setRowBusy, js/actions.js): its buttons say no to a
     * press, and the pressed one shows the theme's spinner in place of its
     * words, which keep their room, so no column moves. */
    .kp-row-actions > [data-kp-busy] {
        position: relative;
    }

    .kp-row-actions > [data-kp-busy] > :not(.kp-button__busy) {
        flex: none;
        visibility: hidden;
    }

    /* The spinner's own box, laid over the words; the spinner in it is the
     * theme's, as the register draws it. */
    .kp-button__busy {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        pointer-events: none;
    }

    .kp-button__busy > .kp-spinner {
        --kp-spinner-size: 1em;
    }

    .kp-action-list > li[aria-busy='true'] .kp-row-actions > [aria-disabled='true'] {
        cursor: progress;
    }

    /* Rows the keyboard moves through (attachRowKeys): the focused row
     * wears the ring. */
    [data-kp-row-keys] > li:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: calc(-1 * var(--focus-ring-width, 2px));
    }

    /* On a narrow list the rows stay subgrids of the list, so the lead column
     * is still one width for every row; the words take the rest of the row
     * and the buttons go under both. */
    @container kp-action-list (max-width: 30rem) {
        .kp-action-list--lead > li {
            grid-template-columns: subgrid;
        }

        .kp-action-list--lead > li > .kp-action-list__lead {
            grid-row: 1;
        }

        .kp-action-list--lead > li > .kp-action-list__main {
            grid-column: 2 / -1;
        }

        .kp-action-list.kp-action-list--lead > li > .kp-row-actions {
            grid-column: 1 / -1;
        }
    }

    /* --- Navigation bar [TH7] -------------------------------------------- */

    /* The box the nav bar measures itself against [TH104, AR24].
 *
 * A container query styles a container's CONTENTS, never the container
 * itself, and the rule that has to change is the nav's own padding — so
 * the query needs an element one level up. components/nav-bar.jsx
 * renders this itself (`wrap`, default true); markup written by hand
 * adds it, which is what MIGRATION.md's 4.0.0 section is for. */
    .kp-nav-wrap {
        container: kp-nav / inline-size;
        /* The same floor as .kp-table-wrap, for the same reason: inline-size
     * containment stops this box sizing to its contents, so in a
     * shrink-to-fit parent — a flex row, an inline-block — it goes to
     * zero. `auto` is the initial value in every context, so the default
     * is a true no-op [R3-CQ, KT6]. */
        min-inline-size: var(--kp-nav-wrap-min, auto);
        /* The bar's layer, in the base so every theme gives the same answer
     * [scope-48, research/navbar finding 3]. Two registers lifted the
     * wrapper and nine the nav inside it; in six themes nothing did, and
     * the next element on the popover layer painted over an open dropdown
     * (tests/app-shell.spec.mjs). One layer for the whole bar: its dropdown rides on it, and
     * a page stacks against one number. Knob: --kp-z-nav (30), between the
     * popover layer (20) and back-to-top (50). */
        position: relative;
        z-index: var(--kp-z-nav, 30);
    }

    .kp-nav {
        display: flex;
        align-items: center;
        gap: 1rem;
        flex-wrap: wrap;
        /* Up to 3.2.0 the inline padding was `clamp(0.75rem, 3vw, 1.5rem)`:
     * it read the WINDOW, so a nav in a 300px column on a 1280px page
     * was given the padding of a 1280px page. The two ends of that ramp
     * are now the wide default here and the narrow value in the
     * @container block below [TH104]. Both are knobs [KT6]. */
        padding: calc(var(--kp-nav-pad-block, 0.625rem) * var(--kp-nav-pad-scale, 1)) var(--kp-nav-pad-inline, 1.5rem);
        background: var(--card);
        color: var(--card-foreground);
        border-bottom: 1px solid var(--border-strong);
    }

    /* Narrow: the bar takes the smaller inset, the way it used to below a
 * 400px window — except that the width which decides is now the width of
 * the box the nav actually lives in [TH104, DI11]. */
    @container kp-nav (max-width: 40rem) {
        /* 40rem is a contract value [TH26]: a container query can no more
     * read a custom property than a media query can, so this number is
     * repeated in docs/USER_GUIDE.md rather than exposed as a knob. It is
     * the same number the table's card query uses, so the package steps
     * at one width rather than at two. */
        .kp-nav {
            padding-inline: var(--kp-nav-pad-inline-narrow, 0.75rem);
        }
    }

    /* The shrinking header [scope-48 wave 2, research/navbar].
 *
 * Opt-in by the modifier on the wrapper: the bar sticks to the top of the
 * box that scrolls it, on the bar's one layer (--kp-z-nav, above). Once the
 * page has scrolled past a threshold, attachStickyNavs (js/components.js)
 * or NavBar's `sticky` sets `data-kp-nav-compact`, and the compact state
 * scales the bar's own block padding: every register reads
 * --kp-nav-pad-block since research finding 2 was closed, and multiplies it,
 * per side, by --kp-nav-pad-scale (1 at rest). The compact bar keeps half of
 * whatever its theme or its page gave it [scope-85] — cyberpunk's 1.2rem top
 * and 0.4rem bottom become 0.6rem and 0.2rem, retro's 3px becomes 1.5px — so
 * it gets shorter in all 22 themes and is never taller than at rest. Knobs:
 * --kp-nav-sticky-shrink (0.5), the factor the compact bar's block padding
 * is multiplied by; --kp-nav-sticky-duration (the theme's --fx-duration),
 * how long it glides. The factor is set on the nav itself, so a consumer's
 * at-rest --kp-nav-pad-block on the nav is halved rather than replaced. The same module measures the bar and writes its height to
 * --kp-nav-sticky-height on the scrolling box, which scroll-padding reads
 * when --kp-scroll-offset is not set: an anchor or a focused element lands
 * below the bar instead of under it. */
    .kp-nav-wrap--sticky {
        position: sticky;
        inset-block-start: 0;
    }

    .kp-nav-wrap--sticky[data-kp-nav-compact] > .kp-nav {
        --kp-nav-pad-scale: var(--kp-nav-sticky-shrink, 0.5);
    }

    [data-kp-nav-sticky-root]:has(.kp-nav-wrap--sticky) {
        scroll-padding-block-start: var(--kp-scroll-offset, var(--kp-nav-sticky-height, 0px));
    }

    /* The shrink moves; a reader who asked for less motion gets the end state
 * at once [DI7]. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-nav-wrap--sticky > .kp-nav {
            transition: padding-block var(--kp-nav-sticky-duration, var(--fx-duration, 220ms)) var(--fx-ease, ease);
        }
    }

    .kp-nav__brand {
        font-weight: 700;
    }

    /* The file code beside the wordmark [S49, A3]: phantom's PH//15,
       terminal's TTY//06. Quiet by default; a register gives it a voice. */
    .kp-nav__brand-tag {
        font-family: var(--kp-mono, var(--theme-font-mono));
        font-size: 0.68em;
        font-weight: 400;
        letter-spacing: 0.16em;
        color: var(--muted-foreground);
    }

    .kp-nav__links {
        display: flex;
        gap: 0.75rem;
        flex-wrap: wrap;
        margin: 0;
        padding: 0;
        list-style: none;
    }

    /* The toggle a narrow bar collapses into [scope-10, stage 1.3].

 * Measured before this existed: the package had no collapse of any kind,
 * so a bar simply wrapped. On the round-seven demo at 462px that put the
 * chrome at 229px tall before any of the page was visible.
 *
 * It is opt-in by the presence of the button, not by a width: a nav
 * without a toggle behaves exactly as it did, which is what keeps this
 * additive for every page already built. The width that decides is the
 * 40rem container query the nav already steps at — the package steps at
 * one width rather than at two [TH104].
 *
 * The three bars are drawn rather than fetched, because this package
 * ships type and not icons; a consumer who puts their own glyph in the
 * button gets theirs instead. The accessible name comes from the
 * dictionary [KT5] and says which way the press goes. */
    .kp-nav__toggle {
        display: none;
        align-items: center;
        justify-content: center;
        inline-size: var(--kp-nav-toggle-size, 2.25rem);
        block-size: var(--kp-nav-toggle-size, 2.25rem);
        margin-inline-start: auto;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: transparent;
        color: inherit;
        cursor: pointer;
    }

    .kp-nav__toggle::before {
        content: '';
        inline-size: 1.05rem;
        block-size: 2px;
        background: currentColor;
        box-shadow:
            0 -0.36rem 0 currentColor,
            0 0.36rem 0 currentColor;
    }

    /* A consumer's own glyph wins over the drawn one. */
    .kp-nav__toggle:has(*)::before {
        content: none;
    }

    /* DI3: open is a state, and a state is visible as one. The plate is the
 * theme's own accent rather than a shape change, because three bars
 * folding into a cross is geometry that twenty-one registers would each
 * have to keep working. */
    .kp-nav[data-kp-nav-open] > .kp-nav__toggle {
        background: var(--accent);
        color: var(--accent-foreground);
        border-color: var(--accent);
    }

    @container kp-nav (max-width: 40rem) {
        .kp-nav:has(> .kp-nav__toggle) > .kp-nav__toggle {
            display: inline-flex;
        }

        .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
            display: none;
            flex-basis: 100%;
        }

        .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            gap: 0.25rem;
        }

        /* A 12rem panel floating over a 320px screen is the fault TH99
     * already caught once. Collapsed, a dropdown is a nested list
     * instead: in the flow, open, and indented. */
        .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            position: static;
            display: block;
            opacity: 1;
            width: auto;
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            /* No frame, no ground, and no shadow either: a shadow under a
             * list with no ground is a panel's ghost [gap-12]. Every register
             * dresses the floating panel in kp.register, which beats this
             * layer, so each register restates this reset for itself. */
            box-shadow: none;
        }

        /* A mega menu's panel [scope-48] is that nested list too — one
         * column, in the flow — and still opens only when its button is
         * pressed. */
        .kp-nav[data-kp-nav-open] li:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide {
            display: none;
        }

        .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links > li > .kp-nav__menu--wide {
            grid-template-columns: 1fr;
        }
    }

    /* A bar that folds what does not fit behind a More menu [kpadopt-nav].
 *
 * Opt-in by `data-kp-nav-fold` on the nav (js/nav-fold.js). The list takes
 * the room the brand and the end slots leave and never wraps: it is
 * `flex: 1 1 0`, so what it holds cannot change how wide it is, nor the bar
 * how tall. Before the script has fitted the bar the overflow is clipped, not
 * wrapped, so the bar is one row before and after (no layout shift); after,
 * the items that do not fit are `data-kp-nav-folded`: out of the flow, invisible,
 * out of the focus order, but still laid out at their own width, so the next
 * fit can measure them. The More item is a kp menu button whose button is a bar
 * link, so every register that dresses a link dresses it; it is out of the
 * flow in the same way while nothing is folded. The selectors lead with
 * `:where()` so the bar's own phone toggle (its container query, above) wins
 * where it is shown, and the script stands down there.
 * Knob: --kp-nav-more-dot (0.5rem), the dot that tells a counter is behind
 * the button. */
    /* One row: a bar that folds never wraps its brand, list, job and search onto a second line; the list is what gives. */
    .kp-nav:where([data-kp-nav-fold]:not(:has(> .kp-nav__toggle))) {
        flex-wrap: nowrap;
    }

    /* The list is the one that gives, but never below the More button while something is folded (the script writes
     * --kp-nav-fold-more): the brand gives way first, to an ellipsis, so the folded links stay reachable. The job and the
     * search keep their size. */
    .kp-nav:where([data-kp-nav-fold]) > .kp-nav__links {
        position: relative;
        flex: 1 1 0;
        min-inline-size: var(--kp-nav-fold-more, 0px);
        flex-wrap: nowrap;
    }

    .kp-nav:where([data-kp-nav-fold]:not(:has(> .kp-nav__toggle))) > .kp-nav__brand {
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-nav:where([data-kp-nav-fold]:not(:has(> .kp-nav__toggle))) > .kp-nav__search {
        flex: none;
    }

    .kp-nav:where([data-kp-nav-fold]:not(:has(> .kp-nav__toggle))) > .kp-nav__search .kp-button {
        white-space: nowrap;
    }

    .kp-nav:where([data-kp-nav-fold]):not([data-kp-nav-fold-ready]) > .kp-nav__links {
        overflow-x: clip;
    }

    .kp-nav:where([data-kp-nav-fold]) > .kp-nav__links > li {
        flex: none;
        white-space: nowrap;
    }

    .kp-nav:where([data-kp-nav-fold]) > .kp-nav__links > li[data-kp-nav-folded],
    .kp-nav:where([data-kp-nav-fold]) > .kp-nav__links > [data-kp-nav-more][data-kp-nav-idle] {
        /* !important: a register that dresses the list items (cyberpunk's `position: relative` on every one) sits in a
         * later layer and would put a folded item, and the idle More, back in the flow; it would push the More button
         * out of the bar. An important declaration of this layer beats every normal one of a later layer. */
        position: absolute !important;
        inset-block-start: 0;
        inset-inline-start: 0;
        inline-size: max-content;
        visibility: hidden !important;
        pointer-events: none;
    }

    /* The More item is a list item like the others: its menu button hangs from
     * the button, in the bar's own column. */
    .kp-nav__more > .kp-menu-button {
        display: flex;
        flex-direction: column;
        align-items: flex-start;
    }

    /* The menu hangs from the button's start edge, as a menu under a link of a bar does; the script moves it back in
     * only where that would leave the window (menuPlacement). Not the menu button's default, its end edge. */
    .kp-nav__more > .kp-menu-button > .kp-menu {
        inset-inline-start: 0;
        inset-inline-end: auto;
    }

    .kp-nav__more-button {
        position: relative;
        margin: 0;
        border: 0;
        background: none;
        color: inherit;
        font: inherit;
        font-size: var(--kp-nav-link-size, 0.9375rem);
        cursor: pointer;
    }

    .kp-nav__more-button[aria-current='true'] {
        font-weight: 600;
        text-decoration: underline;
        text-decoration-thickness: 2px;
    }

    .kp-nav__more-dot {
        /* Inline-block, not a flex item: a register that makes its links blocks makes this button one. */
        display: inline-block;
        vertical-align: middle;
        margin-inline-start: 0.4em;
        inline-size: var(--kp-nav-more-dot, 0.5rem);
        block-size: var(--kp-nav-more-dot, 0.5rem);
        border-radius: var(--kp-radius-pill, 999px);
        background: var(--destructive);
        flex: none;
    }

    .kp-nav__more-dot[hidden] {
        display: none;
    }

    /* A separator between two groups of links [kpadopt3]: `<li class="kp-nav__sep" aria-hidden="true">`, a hairline as
     * tall as a link, in the list's own gap. Never a target and never focused. In a folding bar (js/nav-fold.js) it stands
     * only between two shown links and becomes the More menu's own `.kp-menu__separator`; in the phone's open list it is
     * a rule across the list. Knobs: --kp-nav-sep-colour (--border-strong), --kp-nav-sep-inset (the room above and below
     * it, 0.25rem). */
    .kp-nav__sep {
        flex: none;
        align-self: stretch;
        box-sizing: border-box;
        inline-size: 0;
        min-block-size: 1em;
        margin-block: var(--kp-nav-sep-inset, 0.25rem);
        padding: 0;
        border-inline-start: 1px solid var(--kp-nav-sep-colour, var(--border-strong));
        list-style: none;
        pointer-events: none;
    }

    @container kp-nav (max-width: 40rem) {
        .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: auto;
            min-block-size: 0;
            block-size: 0;
            margin-block: var(--kp-nav-sep-inset, 0.25rem);
            border-inline-start: 0;
            border-block-start: 1px solid var(--kp-nav-sep-colour, var(--border-strong));
        }
    }

    /* The bar's own toggle shown: the bar collapses as it always did. */
    @container kp-nav (max-width: 40rem) {
        .kp-nav:where([data-kp-nav-fold]):has(> .kp-nav__toggle) > .kp-nav__links {
            overflow: visible;
            flex-wrap: wrap;
        }

        .kp-nav:where([data-kp-nav-fold]):has(> .kp-nav__toggle) > .kp-nav__links > li {
            white-space: normal;
        }

        .kp-nav:where([data-kp-nav-fold]):has(> .kp-nav__toggle) > .kp-nav__links > [data-kp-nav-more] {
            display: none;
        }
    }

    /* The command palette's trigger in the bar [scope-48]. A hotkey alone is
 * a secret, so the bar keeps a visible door to the palette at its end:
 * a slot that pushes itself to the far edge, holding a button that reads
 * as a quiet search box — a word in the muted ink and the key beside it —
 * rather than as one more loud action. The button is an ordinary
 * `data-kp-palette-open` opener; js/palette.js fills its empty
 * `<kbd data-kp-palette-keys>` with ⌘K or Ctrl K. Every register answers
 * the slot (gates/check-register-coverage.mjs, REQUIRED_PARTS). */
    .kp-nav__search {
        display: flex;
        align-items: center;
        margin-inline-start: auto;
    }

    .kp-nav__search-trigger {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        /* Never wider than the bar it sits in: a narrow bar gives the
     * row to the brand and the toggle rather than to an empty box. */
        min-inline-size: min(var(--kp-nav-search-min, 10rem), 100%);
        /* As tall as a bar link and in its type size [scope-87], whatever
     * border the register draws: a border-box floor of one line and the
     * link's two block paddings, the label centred in it. */
        box-sizing: border-box;
        min-block-size: calc(1lh + 2 * var(--kp-nav-link-padding-block, var(--kp-space-sm, 0.5rem)));
        padding: 0 0.5rem 0 0.75rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--background);
        color: var(--muted-foreground);
        font: inherit;
        font-size: var(--kp-nav-link-size, 0.9375rem);
        line-height: var(--kp-line-height, 1.5);
        /* One line: squeezed on grotesk's bar, the key hint broke into
     * "Ctrl" over "K" inside its own chip [scope-80]. */
        white-space: nowrap;
        cursor: pointer;
    }

    .kp-nav__search-trigger:hover {
        color: var(--foreground);
        border-color: var(--border-strong);
    }

    /* The key sits at the button's far end, the way it sits at a palette
 * row's end. Empty until the module fills it, and then out of the way. */
    .kp-nav__search-trigger .kp-palette__keys:empty {
        display: none;
    }

    /* The current page is marked by more than colour: aria-current is what a
 * screen reader announces, and the underline is what everyone else
 * sees [DI4]. */
    /* A bar link's size is the package's in every theme [scope-87, option B
 * of research/uniform-size/]: its type size, line height and block
 * padding are titanium's, the median theme's [scope-82]. A register keeps
 * its inline padding, colour, border, face, case, letter spacing and
 * ornaments; gates/box-metrics.test.mjs refuses the rest. The size is
 * titanium's 0.94rem taken to 15px: at 15.04px the line box fell between
 * two layout units, and the bar's measured height and the scroll offset
 * written from it no longer read the same (tests/nav-sticky.spec.mjs). The call to
 * action, `.kp-nav__link--cta`, is a bar link and takes the same [scope-88]. The links sit in
 * a column item (below), so the padding holds its room even where a
 * register leaves the link inline. */
    .kp-nav__link {
        padding-block: var(--kp-nav-link-padding-block, var(--kp-space-sm, 0.5rem));
        font-size: var(--kp-nav-link-size, 0.9375rem);
        line-height: var(--kp-line-height, 1.5);
    }

    .kp-nav__link[aria-current='page'] {
        font-weight: 600;
        text-decoration-thickness: 2px;
    }

    /* A dropdown under a link [TH117]: a nested list the link announces
     * with aria-haspopup. It opens on hover and on focus within, so the
     * keyboard reaches every item by Tab; the register decides its look. */
    .kp-nav__links > li {
        position: relative;
        /* The item is a column, so the link in it is a flex item, and a flex
     * item is a block box whatever `display` a register gives the link
     * [scope-80]. An inline link takes no room for its block padding: a
     * register's plate under the current page, on a bar that wraps, painted
     * 13px over the row above in dark (catalogue/navigation.html#bar-long,
     * Kenny's note of 2026-09-14), and a label that wraps inside itself
     * laid its second line's plate over its first. As a block, the plate
     * holds its own room, the row gap sits between plates, and a text
     * underline still follows each line. The column keeps a collapsed
     * bar's nested menu under its link (tests/nav-wrap.spec.mjs). */
        display: flex;
        flex-direction: column;
        align-items: flex-start;
    }

    /* A marquee [S45, M1 of 2026-09-08]: a row that runs, and the first
       shared element whose content a consumer supplies. The quiet answer
       is a row that does not move at all — every theme gets the items,
       laid out — and a theme that wants them to run says how fast with
       `--kp-marquee`. The module doubles the row so the pass is seamless
       and marks the copy `aria-hidden`; without the module the row is
       simply a row, which is the no-script answer [T17, AR34].

       The knobs a stylesheet reads are declared here: how long one full
       pass takes, and the gap between the items. The third — whether the
       row rests while it is off screen — is read by js/effects.js alone
       and so is not declared in this file (AR21); unset means it rests,
       and a theme that wants it running on says so in its own register,
       which is where the module looks. */
    .kp-marquee,
    [data-kp-marquee] {
        --kp-marquee: 42000ms;
        --kp-marquee-gap: var(--kp-space-lg);
        display: block;
        overflow: hidden;
    }

    [data-kp-marquee-track] {
        display: flex;
        inline-size: max-content;
    }

    [data-kp-marquee-run] {
        display: flex;
        flex: none;
        align-items: center;
        gap: var(--kp-marquee-gap);
        padding-inline: calc(var(--kp-marquee-gap) / 2);
        padding-block: var(--kp-space-xs);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-kp-marquee-ready][data-kp-marquee-runs] [data-kp-marquee-track] {
            animation: kp-marquee-pass var(--kp-marquee) linear infinite;
        }

        /* The module writes this attribute while the band sits outside the
           viewport; the animation keeps its position and resumes from it. */
        [data-kp-marquee-ready][data-kp-paused] [data-kp-marquee-track] {
            animation-play-state: paused;
        }
    }

    @keyframes kp-marquee-pass {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(-50%);
        }
    }

    /* The menu's own caption [M3 of 2026-09-08]: a line above the items
       saying what this menu is — blueprint's title block reads "Detail ·
       scale 4:1" there. The consumer supplies it (a `menuLabel` on the
       NavBar's link, or the attribute by hand); a menu without one has no
       line at all, so nothing appears where nothing was asked for. Every
       register may draw it its own way. */
    .kp-nav__menu[data-kp-menu-label]::before {
        content: attr(data-kp-menu-label);
        display: block;
        padding: var(--kp-space-xs) 0.75rem;
        margin-block-end: 0.25rem;
        font-size: var(--kp-text-xs);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-block-end: 1px solid var(--border);
    }

    .kp-nav__menu {
        position: absolute;
        top: 100%;
        inset-inline-start: 0;
        z-index: var(--kp-z-popover, 20);
        /* How far the panel slides along the inline axis to stay inside the
         * box that shows it [fix-39]. Changing edges is not always enough —
         * a panel can be cut while both of its item's edges lie inside the
         * window — so the module writes the pixels here after it has
         * measured. Physical pixels, signed: negative moves it left, in a
         * right-to-left page too, which is what "inside the window" means
         * on either axis direction. Nothing but js/components.js writes it;
         * unset, the panel sits exactly where the stylesheet put it. */
        translate: var(--kp-nav-menu-shift, 0) 0;
        /* As wide as its longest row, never narrower than the floor
         * [nav-dropdown-M1]. Absolutely placed in a small item, the panel's
         * width is otherwise shrink-to-fit against that item, so a link of
         * 38 characters broke onto two lines while the panel stayed 192px
         * (formal, deco, retro; Kenny: a label never wraps or is
         * cut). A wider panel is still kept inside the window by the shift
         * above, which measures the panel as it is laid out. The mega menu
         * and the phone drawer set `width: auto` again. */
        width: max-content;
        min-width: 12rem;
        margin: 0;
        padding: 0.25rem 0;
        list-style: none;
        background: var(--popover);
        color: var(--popover-foreground);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        /* Closed is `display: none`, not hidden-but-laid-out: a laid-out
         * panel 12rem wide inside a 56px item is scrollable overflow, and
         * the overflow gate read it as such at 320px (TH99). The keyboard
         * still gets in — focus on the trigger opens the panel through
         * :focus-within, and the next Tab lands on its first link. */
        display: none;
        opacity: 0;
    }

    /* `data-kp-nav-menu-open` on the item declares the panel open [gap-12]:
     * for a page that shows it open (a catalogue, a screenshot, a guided
     * tour) or a script that opens it on a press. Hover and focus still
     * open it too; taking the attribute away is the way back [KT6]. */
    .kp-nav__links > li:hover > .kp-nav__menu,
    .kp-nav__links > li:focus-within > .kp-nav__menu,
    .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu {
        display: block;
        opacity: 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-nav__menu {
            transition:
                opacity var(--fx-duration, 150ms) var(--fx-ease, ease),
                display var(--fx-duration, 150ms) allow-discrete;
        }

        @starting-style {
            .kp-nav__links > li:hover > .kp-nav__menu,
            .kp-nav__links > li:focus-within > .kp-nav__menu,
            .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu {
                opacity: 0;
            }
        }
    }

    /* A dropdown's and a mega menu's links: their size is the package's
     * [scope-87], titanium's padding and its 0.92rem taken to 14px. */
    .kp-nav__menu a {
        display: block;
        padding: var(--kp-nav-menu-link-padding-block, calc(var(--kp-space-sm, 0.5rem) * 0.9)) 0.875rem;
        font-size: var(--kp-nav-menu-link-size, 0.875rem);
        line-height: var(--kp-line-height, 1.5);
    }

    /* A dropdown with no room on its item's end side hangs from the other
     * edge instead [fix-27]. Grotesk's catalogue bar showed the panel under
     * the last item running past the window's right edge; measured on a bar
     * whose links sit at the window's end, it lay 36 to 106px past it at
     * 1400px in all 22 themes (tests/nav-menu.spec.mjs). A stylesheet cannot
     * know where the window ends relative to an item, so the module that
     * wires the bar (js/components.js, placeNavMenu) measures the panel as
     * it opens and writes this attribute; the React NavBar calls the same
     * function. Without script the panel keeps its start edge.
     *
     * The edge is chosen first and `--kp-nav-menu-shift` finishes the job
     * [fix-39]: the box that shows a bar is not always the window. */
    .kp-nav__menu[data-kp-nav-menu-end] {
        inset-inline-start: auto;
        inset-inline-end: 0;
    }

    /* The mega menu [scope-48, research/navbar "Mega menu"]: one bar item
     * opens a wide panel of grouped links. It is a disclosure, not a hover
     * dropdown — a panel this size cannot follow a pointer, and a touch or
     * keyboard reader must be able to open it on purpose — so its item holds
     * a `data-kp-nav-disclosure` button, and the panel is shown only while
     * that button says `aria-expanded="true"` (or the item carries
     * `data-kp-nav-menu-open`, the declared open state). The panel is a
     * `.kp-nav__menu` too, so every register's dropdown voice dresses it, and
     * each register answers `--wide` besides (KT14). Plain lists with
     * headings inside, never `role="menu"`: this is site navigation.
     *
     * The button reads as one of the bar's links (give it `kp-nav__link`
     * too) with a caret after its word that turns while open. */
    .kp-nav__disclosure {
        margin: 0;
        /* The bar link's block padding and type size [scope-87], restated
         * after `font: inherit`, which would reset them. */
        padding: var(--kp-nav-link-padding-block, var(--kp-space-sm, 0.5rem)) 0;
        border: 0;
        background: transparent;
        color: inherit;
        font: inherit;
        font-size: var(--kp-nav-link-size, 0.9375rem);
        line-height: var(--kp-line-height, 1.5);
        cursor: pointer;
    }

    .kp-nav__disclosure::after {
        content: '';
        /* Inline-block, not a flex item: a register that makes its links
         * blocks makes this button one, and an inline box has no size. */
        display: inline-block;
        vertical-align: middle;
        margin-inline-start: 0.35em;
        inline-size: 0.4em;
        block-size: 0.4em;
        border-inline-end: 1.5px solid currentColor;
        border-block-end: 1.5px solid currentColor;
        rotate: 45deg;
        translate: 0 -0.15em;
    }

    .kp-nav__disclosure[aria-expanded='true']::after {
        rotate: -135deg;
        translate: 0 0.1em;
    }

    /* The panel spans the bar, so its item is no containing block. Whatever
     * box is — the `.kp-nav-wrap` positioned in the base, a register's
     * positioned bar, or cyberpunk's positioned strip of links — the module
     * (js/components.js, placeNavPanel) measures the bar against it as the
     * panel opens and writes the two offsets that line the panel up with
     * the bar's edges; both default to 0, which is right for a bar whose
     * own box is the containing block. */
    .kp-nav__links > li:has(> .kp-nav__menu--wide) {
        position: static;
    }

    .kp-nav__menu--wide {
        inset-inline-start: var(--kp-nav-mega-start, 0);
        inset-inline-end: var(--kp-nav-mega-end, 0);
        width: auto;
        min-width: 0;
        /* Three to four columns (NN/g: beyond that, choice overload): never
         * narrower than the knob, never more than four across. */
        grid-template-columns: repeat(
            auto-fit,
            minmax(max(min(var(--kp-nav-mega-min, 11rem), 100%), calc((100% - 3 * var(--kp-nav-mega-gap, 1.5rem)) / 4)), 1fr)
        );
        gap: var(--kp-nav-mega-gap, 1.5rem);
        padding: var(--kp-space-md, 1rem) var(--kp-nav-pad-inline, 1.5rem);
    }

    /* Hover and focus open a dropdown; they do not open this one. One that is
     * closing stays until its close has played (js/components.js). */
    .kp-nav__links
        > li:not([data-kp-nav-menu-open], [data-kp-nav-closing], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
        > .kp-nav__menu--wide {
        display: none;
        opacity: 0;
    }

    .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu--wide,
    .kp-nav__links > li[data-kp-nav-closing] > .kp-nav__menu--wide,
    .kp-nav__links > li:has(> [data-kp-nav-disclosure][aria-expanded='true']) > .kp-nav__menu--wide {
        display: grid;
        opacity: 1;
    }

    .kp-nav__group {
        min-inline-size: 0;
    }

    .kp-nav__group > ul {
        margin: 0;
        padding: 0;
        list-style: none;
    }

    /* A group's heading takes the voice of the dropdown's own caption
     * (`data-kp-menu-label`), which every register already draws. */
    .kp-nav__menu-heading {
        margin: 0 0 0.25rem;
        padding: var(--kp-space-xs, 0.25rem) 0.75rem;
        font-size: var(--kp-text-xs);
        font-weight: 600;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--muted-foreground);
        border-block-end: 1px solid var(--border);
    }

    /* ====================================================================
 * The eleven overlays and their neighbours [L8, TH35].
 *
 * The hard part of these is keyboard behaviour, and the browser now does
 * most of it: <dialog> traps focus, closes on Escape and returns focus
 * where it came from; popover="auto" light-dismisses and closes on
 * Escape; <details> is a keyboard-operable disclosure. AR15's baseline is
 * modern Chrome and Firefox only, which is what makes that affordable.
 * We write the looks, and only the behaviour the platform does not give.
 * ==================================================================== */

    /* The brand as a link home keeps the brand's look; the underline is the
 * page's ordinary link rule, which is what says it is one. */
    a.kp-nav__brand {
        color: inherit;
    }

    /* --- Media [feat-media-1] --------------------------------------------
       Of the component roots this package declares, not one was for a
       picture, so every page that wanted one at the top invented its own —
       and nearly all of them forgot the same thing.

       The space is there before the picture is. `aspect-ratio` on the frame
       and `object-fit` on the image mean the page has its final shape at
       the first paint, so the text below it does not jump when the bytes
       arrive. That is a layout bug a consumer cannot fix from the outside,
       because it lives between the frame and the image.

       No width of its own: a picture is as wide as what holds it, and
       whoever placed it knows that better than this file does. */

    .kp-media {
        display: block;
        position: relative;
        overflow: hidden;
        aspect-ratio: var(--kp-media-ratio, 16 / 9);
        background: var(--muted);
        border-radius: var(--radius, 0);
    }

    .kp-media > img,
    .kp-media > video,
    .kp-media > picture,
    .kp-media > picture > img {
        inline-size: 100%;
        block-size: 100%;
        object-fit: var(--kp-media-fit, cover);
        object-position: var(--kp-media-position, 50% 50%);
        display: block;
    }

    /* Its own ratios, because a hero and a portrait are not the same
       picture and a consumer should not have to remember the numbers. */
    .kp-media--wide {
        --kp-media-ratio: 21 / 9;
    }

    .kp-media--square {
        --kp-media-ratio: 1;
    }

    .kp-media--portrait {
        --kp-media-ratio: 3 / 4;
    }

    /* A caption belongs to the picture, so it sits with it rather than
       floating below in whatever the page happens to give it. */
    .kp-media-figure {
        margin: 0;
    }

    .kp-media-figure > figcaption {
        margin-block-start: 0.5rem;
        font-size: var(--kp-font-size-sm, 0.875rem);
        color: var(--muted-foreground);
    }

    /* Text over the picture, with a ground under it. A caption laid
       straight on a photograph is legible until the day somebody uploads a
       bright one [DI1]. */
    .kp-media__overlay {
        position: absolute;
        inset-block-end: 0;
        inset-inline: 0;
        padding: var(--kp-media-overlay-pad, 1rem);
        color: var(--kp-media-overlay-ink, #fff);
        background: var(--kp-media-overlay-ground, linear-gradient(to top, rgb(0 0 0 / 0.72), rgb(0 0 0 / 0)));
    }

    /* --- Back to top [feat-page-1] ---------------------------------------
       The control that appears once the reader is a way down and takes them
       back. It leans on the scroll offset built for the sticky bar: landing
       at the top of a page whose bar covers the first line is not arriving.

       Visibility is `visibility` rather than the hidden attribute, so the
       button can fade rather than blink — and `visibility: hidden` keeps it
       out of the tab order just as surely, which is the part that matters
       for a control that is not there yet. */

    .kp-to-top {
        position: fixed;
        inset-block-end: calc(var(--kp-to-top-offset, 1.5rem) + var(--kp-tabbar-height, 0px));
        inset-inline-end: var(--kp-to-top-offset, 1.5rem);
        z-index: var(--kp-to-top-layer, 50);
        opacity: 0;
        visibility: hidden;
    }

    .kp-to-top[data-kp-to-top-shown] {
        opacity: 1;
        visibility: visible;
    }

    /* The glyph an empty control gets [gap-12]. Written the documented way —
       a button with only a name — the control painted as an empty box in
       every theme. js/components.js puts this element in a button that has
       nothing of its own, and takes it out again on detach; the arrow is
       drawn here rather than typed there, like the tree's twisty, so a theme
       or a consumer changes it with one knob. Its own element rather than
       the button's pseudo-elements, because those are the two surfaces a
       register paints a button on [scope-16]. */
    .kp-to-top__glyph::before {
        content: var(--kp-glyph-to-top, '↑');
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-to-top {
            transition:
                opacity var(--fx-duration, 150ms) var(--fx-ease, ease),
                visibility var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    /* --- Side navigation [feat-nav-3] ------------------------------------
       A navigation that stands beside the content instead of above it,
       built to the feature list Kenny pointed at (MDBootstrap's sidenav,
       read 2026-09-11). Three modes, a slim rail, collapsible categories,
       a backdrop, either edge, and a way out of every one of them [KT6].

       What is deliberately NOT taken from that reference is its `color`
       option. What the active link looks like is the theme's to say, and
       that is the whole of this package: a register answers `.kp-sidenav`,
       and a consumer picks a theme rather than a colour.

       One thing CSS cannot do alone: `push` and `side` offset a content
       element this component does not own, so the module sets that inset
       and says so in an event. Everything else here is CSS, so a page
       without JavaScript still gets a navigation rather than a pile of
       links. */

    .kp-sidenav {
        --kp-sidenav-w: var(--kp-sidenav-width, 15rem);
        /* The knob names the whole panel, border included. Without this it
           named the content box, the panel painted a pixel wider than the
           number, and the offset a push mode puts on the content — which
           reads that same knob — left the text under the border. The
           package does not set box-sizing globally, so a component that
           has a width says so itself. */
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
        /* It has a width, so it does not give it up. In `side` mode the
           panel is a flex item of the consumer's own layout, and the
           default there is to shrink — which made a panel asked for 11rem
           paint at 135px beside its content. */
        flex-shrink: 0;
        inline-size: var(--kp-sidenav-w);
        max-inline-size: 100%;
        background: var(--kp-sidenav-surface, var(--card));
        color: var(--foreground);
        border-inline-end: var(--kp-sidenav-edge, 1px solid var(--border));
    }

    /* A narrower panel on a narrow screen [Kenny, 2026-10-14, from the
       libraries survey: shadcn's --sidebar-width-mobile, Mantine's
       responsive width]. `data-kp-sidenav-narrow` is what js/sidenav.js writes
       while `data-kp-sidenav-over-below` holds the panel as an `over` panel
       (40rem or its own step). The knob is opt-in: without
       `--kp-sidenav-width-narrow` the fallback is the width the panel has
       anywhere else, so nothing moves. It stands before the rail's rule
       below, which names a width of its own and wins over it. */
    .kp-sidenav[data-kp-sidenav-narrow] {
        --kp-sidenav-w: var(--kp-sidenav-width-narrow, var(--kp-sidenav-width, 15rem));
    }

    /* The panel that is part of the page. This is the default because a
       navigation that is there is a better starting point than one that
       has to be summoned; `over` and `push` are the ones you ask for. */
    .kp-sidenav[data-kp-sidenav-mode='over'],
    .kp-sidenav[data-kp-sidenav-mode='push'] {
        --kp-sidenav-away: var(--kp-sidenav-away-to-start, -100%);
        position: fixed;
        /* One value or two, so a page with a bar it wants to keep can say
           `--kp-sidenav-inset-block: 3rem 0` and have the panel start under
           it instead of sliding beneath it. */
        inset-block: var(--kp-sidenav-inset-block, 0);
        inset-inline-start: 0;
        z-index: var(--kp-sidenav-layer, 60);
        translate: var(--kp-sidenav-away) 0;
    }

    .kp-sidenav[data-kp-sidenav-position='absolute'] {
        position: absolute;
    }

    /* Either edge, and the edge is logical: in a right-to-left page the
       start is the right, and the panel still slides out of the side it
       came from. */
    .kp-sidenav[data-kp-sidenav-side='end'] {
        --kp-sidenav-away: var(--kp-sidenav-away-to-end, 100%);
        inset-inline-start: auto;
        inset-inline-end: 0;
        border-inline-end: none;
        border-inline-start: var(--kp-sidenav-edge, 1px solid var(--border));
    }

    .kp-sidenav:dir(rtl) {
        --kp-sidenav-away: var(--kp-sidenav-away-to-end, 100%);
    }

    .kp-sidenav[data-kp-sidenav-side='end']:dir(rtl) {
        --kp-sidenav-away: var(--kp-sidenav-away-to-start, -100%);
    }

    .kp-sidenav[data-kp-sidenav-open='true'] {
        translate: 0 0;
    }

    .kp-sidenav[data-kp-sidenav-mode='side'][data-kp-sidenav-open='false'],
    .kp-sidenav[data-kp-sidenav-mode='side'][data-kp-sidenav-open='false'] + .kp-sidenav__backdrop {
        display: none;
    }

    /* Its timing is the theme's, like everything else here: a slide on the
       package's own `ease` keyword read as abrupt, and terminal steps where
       pastel overshoots is the handwriting this file is for. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-sidenav {
            transition: translate var(--kp-sidenav-duration, var(--fx-duration, 220ms)) var(--kp-sidenav-ease, var(--fx-ease, ease));
        }

        /* The far edge travels again [gap-9]. It was excepted here for
           nine days — `transition: none`, because the slide read as rough
           through two attempts and Kenny, 2026-09-11: "die is nog altijd
           fucked up. Maar voorlopig laten we het er gewoon uit". The eye
           was wrong: measured 2026-09-20, frame by frame, the panel moves
           in 10 to 15 frames at one every 17 to 18 ms, for as long as each
           register declares — formal 166 ms of 180, dark 216 of 220,
           pastel 232 of 220 because its ease overshoots. Nothing is
           dropped, and terminal's two steps are its own `steps(2, end)`
           [research/gap-9-far-edge/README.md]. */

        /* Width is a layout property and animating it costs a reflow per
           frame. Only a panel that actually has a rail pays for it. */
        .kp-sidenav[data-kp-sidenav-slim] {
            transition:
                translate var(--kp-sidenav-duration, var(--fx-duration, 220ms)) var(--kp-sidenav-ease, var(--fx-ease, ease)),
                inline-size var(--kp-sidenav-duration, var(--fx-duration, 220ms)) var(--kp-sidenav-ease, var(--fx-ease, ease));
        }

        /* Closing and collapsing are the opening played backwards: a
           transition takes the curve of the state it goes to, so the panel
           going away and the rail going slim take the theme's curve turned
           around, which js/sidenav.js writes as --kp-sidenav-ease-back
           (Kenny, 2026-10-05: no discrepancy between opening and closing). */
        .kp-sidenav:is(
            [data-kp-sidenav-open='false'],
            [data-kp-sidenav-slim-collapsed]:not(
                [data-kp-sidenav-peek='open'],
                [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover
            )
        ) {
            transition-timing-function: var(--kp-sidenav-ease-back, var(--kp-sidenav-ease, var(--fx-ease, ease)));
        }
    }

    /* The slim rail: icons stay, labels go. `--slim-hide` and `--slim-show`
       are the two halves of the same switch, so a consumer can swap a
       wordmark for a monogram rather than only losing text. */
    .kp-sidenav[data-kp-sidenav-slim-collapsed] {
        --kp-sidenav-w: var(--kp-sidenav-slim-width, 4.5rem);
    }

    /* Collapsed and not peeking: a rail told to expand on hover is expanded
       while js/sidenav.js writes `data-kp-sidenav-peek="open"` (after the
       pointer has rested, or while the focus is inside), and on plain
       `:hover` on a page without the module. Narrowing again it is
       `"leaving"` until the rail has its icon width: the words stay while
       the width closes, as they came at once when it opened, so the close
       is the opening backwards. */
    .kp-sidenav[data-kp-sidenav-slim-collapsed]:not([data-kp-sidenav-peek], [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover)
        [data-kp-sidenav-slim-hide],
    .kp-sidenav:not([data-kp-sidenav-slim-collapsed]) [data-kp-sidenav-slim-show] {
        display: none;
    }

    /* A label leaves the eye, never the accessibility tree [scope-45]. With
       display:none a rail entry whose only visible content is an icon had no
       name at all, so a screen reader said "button". The consumer's own
       slim-hide hooks keep display:none: those are ornaments the consumer
       chose to drop, where a label is the entry's name. */
    .kp-sidenav[data-kp-sidenav-slim-collapsed]:not([data-kp-sidenav-peek], [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover)
        .kp-sidenav__label:not(.kp-sidenav__flyout *) {
        position: absolute;
        inline-size: 1px;
        block-size: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        white-space: nowrap;
        border: 0;
        clip-path: inset(50%);
    }

    /* Hovering a rail that was told to expand gives the labels back without
       changing the state anything else reads. */
    .kp-sidenav[data-kp-sidenav-slim-collapsed]:is(
            [data-kp-sidenav-peek='open'],
            [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover
        ) {
        --kp-sidenav-w: var(--kp-sidenav-width, 15rem);
    }

    /* In the collapsed rail a group's submenu floats beside the rail, in the
       top layer (js/sidenav.js makes it a manual `.kp-popover` there, so it
       opens with the theme's popover effect and js/motion.js plays its close
       as that opening backwards), and an item's label shows as the
       package's tooltip. Both are placed by the module beside the rail and
       kept inside the window. */
    :is(.kp-sidenav__flyout, .kp-sidenav__tip):popover-open,
    :is(.kp-sidenav__flyout, .kp-sidenav__tip)[data-kp-ghost] {
        position: fixed;
        inset: auto;
        left: var(--kp-sidenav-float-x, 0);
        top: var(--kp-sidenav-float-y, 0);
        margin: 0;
        position-area: none;
    }

    /* In the floating mode a group's chevron shows the group's folded or
       unfolded state, not whether it floats out: the float is drawn by the
       popover, and a chevron that turned with it would turn on a different
       clock from the popover's open and close. */
    .kp-sidenav__category:has(> .kp-sidenav__flyout) > .kp-sidenav__category-toggle::after {
        rotate: -45deg;
    }

    .kp-sidenav__category[data-kp-sidenav-expanded]:has(> .kp-sidenav__flyout) > .kp-sidenav__category-toggle::after {
        rotate: 45deg;
    }

    /* The submenu's own `display` would beat the browser's rule that hides a
       popover that is not open. */
    .kp-sidenav__flyout:not(:popover-open, [data-kp-ghost]) {
        display: none;
    }

    .kp-sidenav__flyout:popover-open {
        display: grid;
        grid-template-rows: 1fr;
        min-inline-size: var(--kp-sidenav-flyout-min, 11rem);
        transition: none;
    }

    .kp-sidenav__flyout .kp-sidenav__link {
        padding-inline-start: var(--kp-sidenav-flyout-indent, 0.6rem);
    }

    .kp-sidenav__tip {
        white-space: nowrap;
    }

    .kp-sidenav__header {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        padding: var(--kp-sidenav-pad, 0.75rem);
        border-block-end: var(--kp-sidenav-edge, 1px solid var(--border));
    }

    .kp-sidenav__title {
        margin: 0;
        /* Its size is the package's [scope-88]: titanium's 14px, on the
           running line height; a register keeps its face, case and spacing. */
        padding-block: 0;
        font-size: var(--kp-sidenav-title-size, 0.875rem);
        line-height: var(--kp-line-height, 1.5);
        font-weight: 600;
    }

    /* The list scrolls, the header and footer do not. A long navigation in
       a short window is the normal case, not the edge one. */
    .kp-sidenav__scroll {
        flex: 1 1 auto;
        overflow-y: auto;
        /* Never sideways [Kenny, 2026-09-11]. A narrow panel measured 140px
           of content in a 127px box and the count after a long label sat two
           pixels past the edge, reachable only by scrolling. A navigation you
           have to scroll sideways is a navigation you cannot read. */
        overflow-x: hidden;
        overscroll-behavior: contain;
    }

    .kp-sidenav__list {
        list-style: none;
        margin: 0;
        padding: var(--kp-sidenav-list-pad, 0.4rem);
        display: flex;
        flex-direction: column;
        gap: var(--kp-sidenav-gap, 0.1rem);
    }

    .kp-sidenav__link,
    .kp-sidenav__category-toggle {
        display: flex;
        align-items: center;
        gap: 0.6rem;
        /* Its width INCLUDING its padding. The package sets no global
           box-sizing, so `inline-size: 100%` on a padded row made every row
           19px wider than the list that held it — which is where the
           sideways scroll came from. */
        box-sizing: border-box;
        inline-size: 100%;
        min-inline-size: 0;
        /* The row's block padding, type size and line height are the
           package's in every theme [scope-87], titanium's values; a
           register keeps its inline padding (gates/box-metrics.test.mjs). */
        padding: var(--kp-sidenav-item-pad, var(--kp-sidenav-link-padding-block, var(--kp-space-sm, 0.5rem)) 0.6rem);
        font: inherit;
        font-size: var(--kp-sidenav-link-size, var(--kp-font-size-sm, 0.875rem));
        line-height: var(--kp-line-height, 1.5);
        text-align: start;
        text-decoration: none;
        color: inherit;
        background: none;
        border: none;
        border-radius: var(--radius, 0);
        cursor: pointer;
    }

    .kp-sidenav__link:hover,
    .kp-sidenav__category-toggle:hover {
        background: var(--muted);
        color: var(--muted-foreground);
    }

    /* The current page is marked by more than colour [DI4], the same way
       the top bar marks it: aria-current is what a screen reader reads and
       what every theme hangs its own mark on. */
    .kp-sidenav__link[aria-current='page'] {
        background: var(--muted);
        font-weight: 600;
    }

    .kp-sidenav__icon {
        flex: 0 0 auto;
        display: inline-flex;
        inline-size: var(--kp-sidenav-icon-size, 1.25rem);
        justify-content: center;
    }

    .kp-sidenav__label {
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-sidenav__badge {
        margin-inline-start: auto;
        /* The label gives way, the count does not: a number cut in half is
           worse than a name cut in half, because a name still reads. */
        flex-shrink: 0;
        font-size: var(--kp-font-size-xs, 0.75rem);
        color: var(--muted-foreground);
    }

    .kp-sidenav__divider {
        block-size: 1px;
        margin: var(--kp-sidenav-gap, 0.4rem) 0;
        background: var(--border);
        border: none;
    }

    .kp-sidenav__footer {
        padding: var(--kp-sidenav-pad, 0.75rem);
        border-block-start: var(--kp-sidenav-edge, 1px solid var(--border));
    }

    /* A category and its submenu. The open height is a grid track rather
       than a measured pixel value, so the package animates it without
       JavaScript having to know how tall the list is. */
    .kp-sidenav__category-toggle::after {
        content: '';
        margin-inline-start: auto;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        border-inline-end: 1px solid currentcolor;
        border-block-end: 1px solid currentcolor;
        rotate: -45deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-sidenav__category-toggle::after {
            transition: rotate var(--kp-sidenav-duration, var(--fx-duration, 220ms)) var(--kp-sidenav-ease, var(--fx-ease, ease));
        }
    }

    .kp-sidenav__category-toggle[aria-expanded='true']::after {
        rotate: 45deg;
    }

    .kp-sidenav__submenu {
        display: grid;
        grid-template-rows: 0fr;
    }

    .kp-sidenav__submenu > * {
        overflow: hidden;
        min-block-size: 0;
        /* A zero track does not go below its child's own padding, so a
           closed submenu measured 12.8px — the list's padding — and sat
           there as a visible sliver. The inline inset stays; the block
           inset comes from the items. */
        padding-block: 0;
    }

    .kp-sidenav__category[data-kp-sidenav-expanded] > .kp-sidenav__submenu {
        grid-template-rows: 1fr;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-sidenav__submenu {
            transition: grid-template-rows var(--kp-sidenav-duration, var(--fx-duration, 220ms)) var(--kp-sidenav-ease, var(--fx-ease, ease));
        }

        /* A group folding shut is its unfolding played backwards, as the
           rail's collapse is (above). */
        .kp-sidenav__category:not([data-kp-sidenav-expanded]) > .kp-sidenav__submenu,
        .kp-sidenav__category-toggle[aria-expanded='false']::after {
            transition-timing-function: var(--kp-sidenav-ease-back, var(--kp-sidenav-ease, var(--fx-ease, ease)));
        }
    }

    .kp-sidenav__submenu .kp-sidenav__link {
        padding-inline-start: var(--kp-sidenav-submenu-indent, 2.1rem);
    }

    /* A submenu item says so before its name (Kenny, 2026-09-20: "zodat het
       extra duidelijk is wat nu juist een hoofdmenuitem en een submenuitem
       is"). The mark stands in the name's own line, right before its first
       letter, so it is before the word in every theme whatever inline
       padding a register gave the row — pastel's submenu row starts its text
       12.8px in where formal's starts 33.6px, and a mark measured from the
       row's edge fell on top of the word in one and before it in the other.
       In the line rather than over it, because the name clips what overflows
       it for the ellipsis, and an absolutely placed mark was clipped away
       with it. Every submenu name in a theme takes the same mark, so they
       still begin at one point [fix-64].

       Which mark is the register's answer — a glyph through the knob, or a
       shape it draws itself the way nostromo lights the dot its rows already
       carry. Empty by default, so a consumer's own theme shows none. */
    .kp-sidenav__submenu .kp-sidenav__link .kp-sidenav__label::before {
        content: var(--kp-sidenav-submenu-mark, '');
        margin-inline-end: var(--kp-sidenav-submenu-mark-gap, 0.45em);
        color: var(--kp-sidenav-submenu-mark-ink, var(--muted-foreground));
    }

    /* The backdrop is a dimming, not a tint: the same value the dialog
       uses, for the same reason. */
    .kp-sidenav__backdrop {
        position: fixed;
        inset: 0;
        z-index: calc(var(--kp-sidenav-layer, 60) - 1);
        background: rgb(0 0 0 / 0.5);
    }

    /* It arrives with the panel instead of appearing on top of it. A
       backdrop that snaps to full while the panel is still sliding is what
       makes the whole movement read as jerky. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-sidenav__backdrop {
            /* A literal duration, unlike the panel's. The flash check has to
               read this number to know the fade cannot strobe, and a chain of
               fallbacks reads as zero to it — which is the worst case it then
               has to assume. One fade from nothing to half-dark has nothing
               worth tuning anyway. */
            animation: kp-sidenav-backdrop 220ms var(--kp-sidenav-ease, var(--fx-ease, ease)) both;
        }
    }

    @keyframes kp-sidenav-backdrop {
        0% {
            opacity: 0;
        }

        100% {
            opacity: 1;
        }
    }

    /* The control that opens it. It draws nothing of its own: unlike the
       bar's toggle this one is usually placed in a header the consumer
       already has, with their own glyph in it. */
    .kp-sidenav__toggle {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-inline-size: var(--kp-sidenav-toggle-size, 2.25rem);
        min-block-size: var(--kp-sidenav-toggle-size, 2.25rem);
        /* Above the panel and above its backdrop. A control that opens
           something and then disappears underneath it is the fault this
           package already made once, in the bar's own drawer. A toggler
           that does not take this class is the consumer's to place. */
        position: relative;
        z-index: calc(var(--kp-sidenav-layer, 60) + 1);
    }

    /* The content a push panel moves [Kenny, 2026-10-13]. js/sidenav.js
       copies the panel's own time, curve and delay for this change onto the
       content (`--kp-sidenav-shift-duration`, `--kp-sidenav-shift-ease`,
       `--kp-sidenav-shift-delay`), so the content travels with the
       theme's slide and comes back on its reverse; a register that draws the
       move itself (cyberpunk's ticks, nostromo's cut) wins from its layer.
       Without the module, or in a mode that does not push, the time is 0s. */
    @media (prefers-reduced-motion: no-preference) {
        [data-kp-sidenav-shift] {
            transition-property: margin-inline-start, margin-inline-end, padding-inline-start, padding-inline-end;
            transition-duration: var(--kp-sidenav-shift-duration, 0s);
            transition-timing-function: var(--kp-sidenav-shift-ease, linear);
            transition-delay: var(--kp-sidenav-shift-delay, 0s);
        }
    }

    /* The launcher [Kenny, 2026-10-13, translated: "a button (e.g. a hamburger
       icon) at the very top left of the page that is static"]. A box fixed at the window's
       start corner, always in the same place and above the panel, holding
       the panel's toggler, which is the theme's own `.kp-icon-button`: the
       box places it, so no register's `position` on an icon button can move
       it (docs/THEME_LESSONS.md 5 and 43). Its ground is the page's, so
       content scrolled under it never shows through; lit (from the opening's
       first frame to the closing's last, js/sidenav.js) it takes the accent
       plate, as the bar's own toggle does when its panel is open: a state
       change, not three bars folding into a cross, which every register
       would have to keep working.
       Knobs: --kp-sidenav-launcher-inset (the gap to the window's edges,
       default --kp-space-sm), --kp-sidenav-launcher-size (2.25rem, the icon
       button's). The room it takes, inset + size + inset, is what the
       panel's header and a page element marked
       `data-kp-sidenav-launcher-room` keep free. */
    .kp-sidenav__launcher {
        position: fixed;
        inset-block-start: var(--kp-sidenav-launcher-inset, var(--kp-space-sm, 0.5rem));
        inset-inline-start: var(--kp-sidenav-launcher-inset, var(--kp-space-sm, 0.5rem));
        z-index: calc(var(--kp-sidenav-layer, 60) + 1);
        display: flex;
        border-radius: var(--radius, 0.5rem);
        background-color: var(--background);
        color: var(--foreground);
    }

    .kp-sidenav__launcher > :is(button, .kp-icon-button) {
        inline-size: var(--kp-sidenav-launcher-size, 2.25rem);
        block-size: var(--kp-sidenav-launcher-size, 2.25rem);
    }

    .kp-sidenav__launcher[data-kp-sidenav-lit] {
        background-color: var(--accent);
        color: var(--accent-foreground);
    }

    /* The package's glyph: the three bars the bar's toggle draws, put in an
       empty launcher toggler by js/sidenav.js. */
    .kp-sidenav__bars {
        display: block;
        inline-size: 1.05rem;
        block-size: 2px;
        background: currentColor;
        box-shadow:
            0 -0.36rem 0 currentColor,
            0 0.36rem 0 currentColor;
    }

    /* The panel the launcher drives starts its items clear of it: the header
       row begins beside the launcher, or, without a header, the panel's
       first row begins below it. */
    .kp-sidenav[data-kp-sidenav-launched]:not([data-kp-sidenav-side='end']) > .kp-sidenav__header {
        box-sizing: border-box;
        min-block-size: calc(2 * var(--kp-sidenav-launcher-inset, var(--kp-space-sm, 0.5rem)) + var(--kp-sidenav-launcher-size, 2.25rem));
        padding-inline-start: calc(2 * var(--kp-sidenav-launcher-inset, var(--kp-space-sm, 0.5rem)) + var(--kp-sidenav-launcher-size, 2.25rem));
        align-items: center;
    }

    .kp-sidenav[data-kp-sidenav-launched]:not([data-kp-sidenav-side='end']):not(:has(> .kp-sidenav__header)) {
        padding-block-start: calc(2 * var(--kp-sidenav-launcher-inset, var(--kp-space-sm, 0.5rem)) + var(--kp-sidenav-launcher-size, 2.25rem));
    }

    /* The edge tab: a small box on the panel's far edge holding a toggler
       (the theme's `.kp-icon-button`), at the window's edge while the panel
       is away. js/sidenav.js moves it with the panel (`data-kp-sidenav-shift`,
       on the panel's own timing, so a register that draws the content's move
       draws the tab's too) and says which edge (`data-kp-sidenav-tab-edge`).
       The grip it draws in an empty toggler has no state to change. Edge
       tabs belong to panels that slide (over, push). */
    .kp-sidenav__tab {
        position: fixed;
        z-index: calc(var(--kp-sidenav-layer, 60) + 1);
        display: flex;
        inset-block-start: 50%;
        inset-inline-start: 0;
        translate: 0 -50%;
        border: var(--kp-sidenav-edge, 1px solid var(--border));
        border-inline-start: none;
        border-start-end-radius: var(--radius, 0.5rem);
        border-end-end-radius: var(--radius, 0.5rem);
        background-color: var(--kp-sidenav-surface, var(--card));
        color: var(--foreground);
    }

    .kp-sidenav__tab > :is(button, .kp-icon-button) {
        inline-size: var(--kp-sidenav-tab-thickness, 1.25rem);
        block-size: var(--kp-sidenav-tab-length, 3rem);
    }

    .kp-sidenav__tab[data-kp-sidenav-tab-edge='end'] {
        inset-inline: auto 0;
        border-inline: var(--kp-sidenav-edge, 1px solid var(--border)) none;
        border-radius: var(--radius, 0.5rem) 0 0 var(--radius, 0.5rem);
    }

    .kp-sidenav__grip {
        display: block;
        inline-size: 2px;
        block-size: 1rem;
        background: currentColor;
        box-shadow: 0.3rem 0 0 currentColor;
        translate: -0.15rem 0;
    }

    /* --- Side navigation: minor behaviour options ------------------------
       Three opt-in additions [Kenny, 2026-10-13, from the libraries survey]:
       the refusal a static backdrop plays, and the handle that resizes the
       panel. Every rule hangs on an attribute that only js/sidenav.js writes
       when the page asked for the option, so a panel without them is drawn
       exactly as before. The look is the theme's through its own tokens:
       the cue runs on the panel's duration and curve
       (--kp-sidenav-duration, --kp-sidenav-ease), the handle in --ring and
       --border-strong. */

    /* The refused cue: a static backdrop was clicked and nothing closed.
       js/sidenav.js pulls the panel toward the edge it came from and lets it
       go (Web Animations on the panel's margin, run twice, the second time
       backwards: the return is the exact reverse of the pull and as long),
       on the theme's own time and curve, so a stepped theme jolts in steps.
       It is scripted because every register owns the panel's `translate` and
       `animation` for its opening and closing, and a CSS animation here would
       lose to them or replace them. While it plays the panel carries
       `data-kp-sidenav-refused`, and this ring, which stands without motion
       too. Its knobs (travel, duration, ease) are read by the script and
       named at `refuse` in js/sidenav.js. */
    .kp-sidenav[data-kp-sidenav-refused] {
        outline: 2px solid var(--ring);
        outline-offset: -2px;
    }

    /* The resize handle: inside the panel, on the edge that faces the content,
       so it covers none of the page. A strip to grab with a short bar to show
       it is there; the full-height line shows on pointing, focus and while it
       is held. It rests in the border colour and is lit in the ring colour. */
    .kp-sidenav:where([data-kp-sidenav-resizable]):not(
            [data-kp-sidenav-mode='over'],
            [data-kp-sidenav-mode='push'],
            [data-kp-sidenav-position='absolute']
        ) {
        position: relative;
    }

    .kp-sidenav__resizer {
        position: absolute;
        inset-block: 0;
        inset-inline-end: 0;
        z-index: 1;
        display: grid;
        place-items: center;
        inline-size: var(--kp-sidenav-resizer-size, 0.75rem);
        cursor: col-resize;
        touch-action: none;
        user-select: none;
    }

    .kp-sidenav[data-kp-sidenav-side='end'] > .kp-sidenav__resizer {
        inset-inline: 0 auto;
    }

    .kp-sidenav[data-kp-sidenav-slim-collapsed] > .kp-sidenav__resizer {
        display: none;
    }

    .kp-sidenav__resizer::before {
        content: '';
        inline-size: 0.25rem;
        block-size: 2rem;
        border-radius: var(--radius, 0.5rem);
        background: var(--border-strong);
    }

    .kp-sidenav__resizer::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-end: 0;
        inline-size: 2px;
        background: var(--ring);
        opacity: 0;
    }

    .kp-sidenav[data-kp-sidenav-side='end'] > .kp-sidenav__resizer::after {
        inset-inline: 0 auto;
    }

    .kp-sidenav__resizer:is(:hover, :focus-visible)::after,
    .kp-sidenav[data-kp-sidenav-resizing] > .kp-sidenav__resizer::after {
        opacity: 1;
    }

    .kp-sidenav__resizer:is(:hover, :focus-visible)::before,
    .kp-sidenav[data-kp-sidenav-resizing] > .kp-sidenav__resizer::before {
        background: var(--ring);
    }

    /* While it is held the text under the pointer is not selected. */
    .kp-sidenav[data-kp-sidenav-resizing] {
        user-select: none;
    }

    /* An action beside an item [Kenny, 2026-10-14, from the libraries survey:
       shadcn's MenuAction]: a trailing icon button next to a link. The row is
       the list item, `<li class="kp-sidenav__row">`, holding the link and the
       button as siblings, so the button is never inside the link and pressing
       it cannot follow it; both are in the tab order, in that order. Put
       the theme's own `.kp-icon-button` on the button too
       (`class="kp-icon-button kp-sidenav__action"`), and it wears the theme's
       icon button with this component's size and place. The button is as tall
       as its row (so it follows the density preset) and `--kp-sidenav-action-size`
       wide (2rem); its focus ring is drawn inside it, where the panel's
       scroll cannot cut it. In the collapsed rail the actions go with the
       labels. */
    .kp-sidenav__row {
        display: flex;
        align-items: stretch;
        gap: var(--kp-sidenav-action-gap, 0.25rem);
        min-inline-size: 0;
    }

    .kp-sidenav__row > .kp-sidenav__link {
        flex: 1 1 auto;
        inline-size: auto;
    }

    .kp-sidenav__row > .kp-sidenav__action {
        flex: 0 0 auto;
        box-sizing: border-box;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        align-self: stretch;
        inline-size: var(--kp-sidenav-action-size, 2rem);
        block-size: auto;
        min-block-size: 0;
        padding: 0;
        font: inherit;
        font-size: var(--kp-sidenav-link-size, var(--kp-font-size-sm, 0.875rem));
        line-height: 1;
        color: inherit;
        cursor: pointer;
    }

    .kp-sidenav__row > .kp-sidenav__action:hover {
        background: var(--muted);
        color: var(--muted-foreground);
    }

    .kp-sidenav__row > .kp-sidenav__action:focus-visible {
        outline-offset: calc(-2 * var(--kp-focus-ring-inner-width, 2px));
        box-shadow: inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    .kp-sidenav[data-kp-sidenav-slim-collapsed]:not([data-kp-sidenav-peek], [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover)
        .kp-sidenav__action {
        display: none;
    }

    /* Density presets [Kenny, 2026-10-14, from the libraries survey: Fluent's
       `density`, Chakra's `size`]. `data-kp-sidenav-density` on the panel is
       one attribute that only sets tokens this component already reads: a row's
       block padding, its type size, the icon's width and the header and footer
       padding. The default (no attribute) is what the panel always was, at
       37px a row; `compact` is 29px, above the 28px floor the package keeps
       under a control, and `comfortable` 45px. The gap between rows, the list's
       padding and everything a register says about its own rows are the
       theme's, and stay. This is the panel's own knob, apart from the page-wide
       `data-density="compact"` in css/_density.css, which they may share. */
    .kp-sidenav[data-kp-sidenav-density='compact'] {
        --kp-sidenav-link-padding-block: var(--kp-space-xs, 0.25rem);
        --kp-sidenav-icon-size: 1.1rem;
        --kp-sidenav-pad: var(--kp-space-sm, 0.5rem);
    }

    .kp-sidenav[data-kp-sidenav-density='comfortable'] {
        --kp-sidenav-link-padding-block: var(--kp-space-md, 0.75rem);
        --kp-sidenav-link-size: var(--kp-text-md, 1rem);
        --kp-sidenav-icon-size: 1.4rem;
        --kp-sidenav-pad: 1rem;
    }

    /* The peek strip [Kenny, 2026-10-14, from the libraries survey: a sliver of
       the panel stays at the edge, so the panel is known to be there]. Set
       `--kp-sidenav-peek` (0.75rem) on the panel or above it, and
       js/sidenav.js makes this element beside the panel: a thin column at the
       window's edge, in the theme's muted ground (--kp-sidenav-peek-surface) and
       strong edge, under the panel and
       always there, so a theme's own opening and closing (which run where the
       panel stands, not from the edge) stay as they are and the strip stays
       put while they play. A push panel keeps the strip's room in the content
       while it is shut; an `over` panel's strip is the only part of it that
       lies over the page. It takes no pointer and no focus. Without the token
       there is no strip, and nothing here applies. */
    .kp-sidenav__peek {
        position: fixed;
        inset-block: var(--kp-sidenav-inset-block, 0);
        inset-inline-start: 0;
        z-index: calc(var(--kp-sidenav-layer, 60) - 1);
        box-sizing: border-box;
        inline-size: var(--kp-sidenav-peek, 0px);
        background: var(--kp-sidenav-peek-surface, var(--muted));
        border-inline-end: var(--kp-sidenav-edge, 1px solid var(--border-strong));
        pointer-events: none;
    }

    .kp-sidenav__peek[data-kp-sidenav-peek-edge='end'] {
        inset-inline: auto 0;
        border-inline-end: none;
        border-inline-start: var(--kp-sidenav-edge, 1px solid var(--border-strong));
    }

    .kp-sidenav__peek[data-kp-sidenav-peek-hushed] {
        display: none;
    }

    /* --- An entrance played backwards ------------------------------------ */

    /* js/motion.js playEntranceBackwards(): what came in with a CSS
       entrance (a tooltip, the tour's card) goes out as that entrance played
       backwards, in its own time on its curve turned around. `reset` drops
       the entrance for one style read, `play` starts it again reversed and
       held at its first frame, so one that already played out turns around
       too. Important, because the entrance is each register's, in later
       layers. */
    [data-kp-reversing='reset'],
    [data-kp-reversing='reset']::before,
    [data-kp-reversing='reset']::after {
        animation-name: none !important;
    }

    [data-kp-reversing='play'],
    [data-kp-reversing='play']::before,
    [data-kp-reversing='play']::after {
        animation-direction: reverse !important;
        animation-fill-mode: both !important;
    }

    /* --- Growing and shrinking [scope-142] ------------------------------- */

    /* js/motion.js glides a box to its new height and marks it
       `[data-kp-resizing]` meanwhile; a register draws its character on that
       mark (an outline, a glow, a shadow). The boxes carry the transition at
       rest too, so the character fades out as well as in. A register's own
       transition on one of these boxes wins, from its later layer. */
    @media (prefers-reduced-motion: no-preference) {
        :is(
            .kp-dialog,
            .kp-tabs,
            .kp-card,
            .kp-datatable,
            .kp-toasts,
            .kp-upload__list,
            .kp-combobox__list,
            .kp-tree,
            .kp-wizard,
            .kp-field,
            [data-kp-size-motion]
        ) {
            transition:
                outline-color calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                outline-offset calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                filter calc(var(--kp-resize-dur, 300ms) / 2) ease-out;
            outline: 0 solid transparent;
        }
    }

    /* While a column of flex items glides (`[data-kp-gliding='column']`, set
       by js/motion.js), the box clips its items instead of squeezing them:
       a squeezed data table scrolled inside itself and restarted its own
       glide on every frame (Kenny, 2026-10-05). Over the moment the glide
       lasts, an item keeps the size its content gives it. */
    [data-kp-gliding='column'] > * {
        flex: none !important;
    }

    /* --- Dialog ---------------------------------------------------------- */

    /* The browser centres a dialog with `margin: auto` from its own sheet;
       a reset that zeroes every margin (Tailwind's preflight) takes that
       away, and a modal dialog lands in the top-left corner (found live in
       JobTracker, 2026-10-03; fix-92). The dialog says it itself, so a reset in an
       earlier layer cannot undo it. */
    .kp-dialog {
        margin: auto;
        max-width: var(--kp-dialog-max-width, min(32rem, calc(100vw - 2rem)));
        padding: 1.25rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--popover);
        color: var(--popover-foreground);
    }

    /* A dialog stops short of the window and scrolls its body, not itself
 * [gap-11]. With no maximum height of its own, sixty rows scrolled the
 * whole dialog (the browser's cap on a modal one) and took the title and
 * the actions away with the rows. Open, a dialog with a body is a column:
 * the title, the description and the actions keep their size, and the
 * body takes what is left and scrolls inside it. A dialog without a
 * `.kp-dialog__body` keeps its block flow and only gains the cap. */
    .kp-dialog:modal {
        inset: 0;
    }

    .kp-dialog[open] {
        max-block-size: var(--kp-dialog-max-height, calc(100dvh - 2rem));
        box-sizing: border-box;
    }

    .kp-dialog[open]:has(> .kp-dialog__body) {
        display: flex;
        flex-direction: column;
    }

    .kp-dialog[open]:has(> .kp-dialog__body) > :not(.kp-dialog__body) {
        flex: none;
    }

    .kp-dialog__body {
        flex: 1 1 auto;
        min-block-size: 0;
        overflow-y: auto;
        overscroll-behavior: contain;
    }

    .kp-dialog__body > :first-child {
        margin-block-start: 0;
    }

    .kp-dialog__body > :last-child {
        margin-block-end: 0;
    }

    .kp-dialog::backdrop {
        /* Not a token: a backdrop is a dimming of whatever is behind it, and
     * a theme colour here would tint the page rather than dim it. */
        background: rgb(0 0 0 / 0.5);
    }

    .kp-dialog__title {
        margin: 0 0 0.5rem;
        /* Titanium's 1.2rem, taken to 1.25rem so the line is a whole pixel
     * count (22px) at the heading line height [scope-87]. */
        font-size: var(--kp-dialog-title-size, 1.25rem);
        line-height: var(--kp-heading-line-height, 1.1);
    }

    /* The confirmation TH107 opens is a .kp-dialog with one question in
 * it, so it wants the width of a question rather than of a form. Its
 * own class, because a consumer needs something to reach it by. */
    .kp-confirm {
        max-inline-size: var(--kp-confirm-max-width, min(26rem, calc(100vw - 2rem)));
    }

    .kp-dialog__actions {
        display: flex;
        gap: 0.5rem;
        justify-content: flex-end;
        margin-top: 1rem;
    }

    /* The parts a dialog grew in 3.0.0: a description under the title, an
 * optional close button in the corner, and a body class where there was
 * a bare div. */
    .kp-dialog__description {
        margin: 0 0 var(--kp-space-md);
        color: var(--muted-foreground);
        font-size: var(--kp-dialog-description-size, 0.875rem);
    }

    .kp-dialog__close {
        position: absolute;
        inset-inline-end: var(--kp-space-sm);
        inset-block-start: var(--kp-space-sm);
    }

    /* The title stops short of the close button, by at least half a rem
 * [scope-60]. The button is out of flow in the corner, so the title's
 * line ran under it in fifteen themes — formal's words 24px beneath it.
 * The room is the button's size, its inset and the half rem, whatever
 * padding the dialog has; padding rather than margin, because several
 * registers restate the title's margin. */
    .kp-dialog:has(> .kp-dialog__close) > .kp-dialog__title {
        padding-inline-end: calc(var(--kp-dialog-close-size, 2.25rem) + var(--kp-space-sm, 0.5rem) + 0.5rem);
    }

    /* A dialog in sections [kpadopt4; chassis's client dialog, almanac's calendars]: a head that holds the title, a state
 * badge beside it and the description under both; a body of sections, each with a heading and an optional note, the
 * last one the danger section; and a wide variant for a dialog that manages one thing. The wide dialog takes its full
 * width at once, so a section that fills later (a revealed token, a list of requests) moves nothing sideways. Knobs
 * [KT6]: `--kp-dialog-wide` (42rem), `--kp-dialog-section-gap` (the room between sections, 0.75rem). */
    .kp-dialog--wide {
        --kp-dialog-max-width: min(var(--kp-dialog-wide, 42rem), calc(100vw - 2rem));
        inline-size: var(--kp-dialog-max-width);
        box-sizing: border-box;
    }

    .kp-dialog__head {
        display: flex;
        flex-wrap: wrap;
        align-items: baseline;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        margin-block-end: var(--kp-space-sm, 0.5rem);
    }

    .kp-dialog__head > .kp-dialog__title {
        margin: 0;
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    .kp-dialog__head > .kp-dialog__description {
        flex-basis: 100%;
        margin: 0;
    }

    .kp-dialog:has(> .kp-dialog__close) > .kp-dialog__head {
        padding-inline-end: calc(var(--kp-dialog-close-size, 2.25rem) + var(--kp-space-sm, 0.5rem) + 0.5rem);
    }

    .kp-dialog__section {
        padding-block: var(--kp-dialog-section-gap, 0.75rem);
        border-block-start: 1px solid var(--border);
    }

    /* A section is ruled off along its top, and its words keep air from the ends of that rule: the section's box is
     * wider than the text column by `--kp-dialog-section-inset` (0.5rem) on each side and pads it back, so the words stay
     * in line with the title above while the rule runs on past them (text never touches the edge of its plate). The body
     * takes the same room as its own padding, so its scrolling edge does not cut the rule. The danger section has its
     * own edge and padding below and is not pulled out. */
    .kp-dialog__body {
        margin-inline: calc(-1 * var(--kp-dialog-section-inset, 0.5rem));
        padding-inline: var(--kp-dialog-section-inset, 0.5rem);
    }

    .kp-dialog__section:not(.kp-dialog__section--danger) {
        margin-inline: calc(-1 * var(--kp-dialog-section-inset, 0.5rem));
        padding-inline: var(--kp-dialog-section-inset, 0.5rem);
    }

    .kp-dialog__section:first-child {
        padding-block-start: 0;
        border-block-start: 0;
    }

    .kp-dialog__section:last-child {
        padding-block-end: 0;
    }

    .kp-dialog__heading {
        margin: 0 0 var(--kp-space-sm, 0.5rem);
        font-size: var(--kp-text-sm, 0.875rem);
        font-weight: 600;
        line-height: 1.3;
    }

    .kp-dialog__note {
        margin: var(--kp-space-sm, 0.5rem) 0 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    /* The danger section: an entry ruled off along its start edge in the destructive ink, its words in the page's own ink. */
    .kp-dialog__section--danger {
        padding-inline-start: var(--kp-space-md, 0.75rem);
        border-inline-start: 3px solid var(--destructive);
    }

    /* What still uses the thing a confirmation would remove [kpadopt4], and the field a name is typed into. */
    .kp-confirm__dependents {
        margin: 0 0 var(--kp-space-md, 0.75rem);
        padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--muted);
    }

    .kp-confirm__list {
        display: grid;
        gap: var(--kp-space-xs, 0.25rem);
        margin: 0;
        padding-inline-start: 1.25rem;
        overflow-wrap: anywhere;
    }

    .kp-menu__separator {
        margin: var(--kp-space-xs) 0;
        border: 0;
        border-block-start: 1px solid var(--border);
    }

    /* --- Dropdown and tooltip, on the popover layer ----------------------- */

    .kp-popover {
        position: absolute;
        margin: 0;
        padding: 0.25rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        /* Twenty-four themes make the picker's menu taller than most
     * viewports leave under a header: the popover scrolls inside itself
     * rather than running off the bottom [R5]. A knob, like every other
     * measure in this file. */
        max-block-size: var(--kp-popover-max-height, min(80vh, 40rem));
        overflow: auto;
        background: var(--popover);
        color: var(--popover-foreground);
        /* Anchor positioning: the popover sits under its trigger without
     * either of them knowing where the other ended up. */
        position-area: block-end span-inline-end;
        margin-block-start: 0.25rem;
    }

    .kp-menu {
        display: flex;
        flex-direction: column;
        /* nowrap, explicitly: the flat picker's rule above sets wrap, and a
     * wrapping column with a maximum height starts a second column the
     * moment the list is taller than the popover — the dark group moved
     * beside the light one and the light one hung outside the box. Only
     * CI's taller fonts made the list tall enough to see it [R5]. */
        flex-wrap: nowrap;
        min-width: var(--kp-menu-min-width, 10rem);
        margin: 0;
        padding: 0;
        list-style: none;
    }

    /* And the items keep their size rather than shrinking to fit the height;
 * the popover scrolls instead. */
    .kp-menu > * {
        flex-shrink: 0;
    }

    .kp-menu__item {
        padding: 0.375rem 0.625rem;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        border: 0;
        font: inherit;
        color: inherit;
        text-align: start;
        cursor: pointer;
    }

    .kp-menu__item:hover {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    /* A destructive entry keeps its ink, at rest and under the pointer. It sits
 * after `.kp-menu__item` and its hover on purpose: it used to come before
 * them, and their `color: inherit` cancelled it, so in every theme whose
 * register does not restate the ink (synthwave, pastel, ...) "Delete" read
 * like every other entry. */
    .kp-menu__item--destructive,
    .kp-menu__item--destructive:hover {
        color: var(--destructive);
    }

    /* A disabled item looks unavailable and does not answer the pointer
 * [gap-11]. It painted like an enabled one and lit up under the pointer
 * in every theme. `pointer-events: none` rather than a :not() on the
 * hover rule, because nineteen registers write their own item hover in a
 * later layer, and an item the pointer cannot reach matches none of them. */
    .kp-menu__item:is(:disabled, [aria-disabled='true']) {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        pointer-events: none;
    }

    .kp-tooltip {
        max-width: var(--kp-tooltip-max-width, 18rem);
        padding: 0.25rem 0.5rem;
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The page's one hover card (js/hovercard.js): a tooltip that lives in
     * <body>, not in an anchor, and is filled when it opens. In the top layer
     * the script places it in window coordinates, so the popover's UA inset
     * is put back; the margins stay the register's own, which is what keeps
     * the gap a tooltip in its anchor has. It is wider than a one-line
     * tooltip because it may hold rows, and it can be entered by the pointer
     * (WCAG 1.4.13), so a long word wraps rather than widening it. */
    .kp-tooltip[data-kp-hovercard-card] {
        position: fixed;
        inset: auto;
        /* Placed by the script in window coordinates: the popover's anchor area would pin it to the window's end edge. */
        position-area: none;
        max-width: var(--kp-hovercard-max-width, min(24rem, calc(100vw - 1rem)));
        overflow-wrap: anywhere;
        text-align: start;
    }

    /* --- Toast ----------------------------------------------------------- */

    .kp-toasts {
        position: fixed;
        /* Above a bottom tab bar when the page has one (js/tabbar.js). */
        inset-block-end: calc(1rem + var(--kp-tabbar-height, 0px));
        inset-inline-end: 1rem;
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
        /* Above the texture layer (80): a toast under a fixed overlay is a
     * toast nobody can read [KT6]. Every layer reads the z-index scale. */
        z-index: var(--kp-z-toast, 90);
    }

    /* A row: the words, then the buttons at the toast's end. As a block the
 * buttons ran on after the text and stopped wherever it did — 163px short of
 * the end on one toast, flush on the next — so no two toasts lined up
 * (Kenny's second nostromo pass, 2026-09-13). The words go in
 * .kp-toast__body, which both channels write; a toast without one still
 * pushes its first button to the end. */
    .kp-toast {
        display: flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        padding: 0.625rem 0.875rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--popover);
        color: var(--popover-foreground);
    }

    .kp-toast__body {
        flex: 1 1 auto;
        min-inline-size: 0;
    }

    .kp-toast > :is(button, .kp-button, .kp-icon-button) {
        flex: none;
        margin-inline-start: auto;
    }

    .kp-toast > :is(button, .kp-button, .kp-icon-button) ~ :is(button, .kp-button, .kp-icon-button) {
        margin-inline-start: 0;
    }

    /* A button hovered on a toast takes a shade of that toast's own plate
 * instead of the theme's standard hover, which is drawn for the page and not
 * for a coloured plate (Kenny's second nostromo pass, 2026-09-13). The
 * ground is a veil over the plate, so the plate need not be known:
 *   - on a toast of meaning the veil is black under a light ink and white
 *     under a dark one, so the plate deepens away from its ink and the words
 *     read better on hover, never worse — the four plates sit close to 4.5:1
 *     already, and a veil of the ink measured 3.5 to 4.4 on 39 of them;
 *   - on the plain toast, whose plate is often the page's own white or
 *     near-black and cannot deepen further, the veil is the ink itself.
 * Every register restates the hover rule, because each repaints its buttons'
 * hover in the later register layer. The knobs [KT6]: `--kp-toast-button-hover`
 * is the whole veil; `--kp-toast-button-ink` is the colour a toast of
 * meaning judges its veil from (default: the button's own ink). */
    .kp-toast {
        --kp-toast-button-hover: color-mix(in srgb, currentColor 10%, transparent);
    }

    :is(.kp-toast--success, .kp-toast--warning, .kp-toast--info, .kp-toast--destructive, .kp-toast--error) {
        --kp-toast-button-hover: oklch(from var(--kp-toast-button-ink, currentColor) clamp(0, (0.6 - l) * 1000, 1) 0 0 / 0.2);
    }

    .kp-toast :is(.kp-button--ghost, .kp-icon-button):hover:not(:disabled) {
        background: var(--kp-toast-button-hover);
        color: inherit;
    }

    /* A toast with a meaning wears its severity on the alert's four token
 * pairs, as the severity badge does [scope-60]: a plate and the ink drawn
 * for it, so a toast, a badge and an alert that mean one thing are one
 * colour and the contrast gate already holds every pair. It says the
 * meaning in words too: the variant class is never the only carrier
 * [DI4]. `--error` is the name the React channel and 6.0 used for the
 * destructive one, and paints the same. The leading rule stays, in the
 * plate's own colour. Registers repaint the plain toast in a later layer,
 * so every register restates these four [gap-1's shape]. Buttons on the
 * plate take its ink. */
    .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
        border-inline-start: 3px solid var(--success);
    }

    .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
        border-inline-start: 3px solid var(--warning);
    }

    .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
        border-inline-start: 3px solid var(--info);
    }

    .kp-toast--destructive,
    .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
        border-inline-start: 3px solid var(--destructive);
    }

    :is(.kp-toast--success, .kp-toast--warning, .kp-toast--info, .kp-toast--destructive, .kp-toast--error) :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    .kp-toast__close {
        margin-inline-start: auto;
        flex: none;
    }

    /* --- Toast with Undo and a clock [kpadopt5] ---------------------------- */

    /* js/undo-toast.js: the words, the clock and, as the toast's own button, Undo.
     * The clock is a ring that drains (`ring`, with the seconds in it), a rule
     * along the toast's foot that is taken back (`bar`), or the seconds in words
     * (`text`); it stops while the toast is held. Under reduced motion it steps once
     * a second. Knobs: --kp-undo-ms (written by the module), --kp-undo-steps. */
    .kp-toast--undo {
        position: relative;
        overflow: hidden;
        box-sizing: border-box;
        max-inline-size: min(36rem, calc(100vw - 2rem));
    }

    .kp-undo {
        display: flex;
        align-items: center;
        gap: var(--kp-space-md, 0.75rem);
        min-inline-size: 0;
    }

    .kp-undo__text {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    .kp-undo__ringbox {
        position: relative;
        flex: none;
        display: grid;
        place-items: center;
        inline-size: 2rem;
        block-size: 2rem;
    }

    .kp-undo__ring {
        position: absolute;
        inset: 0;
        inline-size: 100%;
        block-size: 100%;
        transform: rotate(-90deg);
        fill: none;
        stroke-width: 2.5;
    }

    .kp-undo__ring-track {
        stroke: color-mix(in srgb, currentColor 25%, transparent);
    }

    .kp-undo__ring-fill {
        stroke: currentColor;
        stroke-dasharray: 1;
        stroke-dashoffset: 0;
        animation: kp-undo-drain var(--kp-undo-ms, 6000ms) linear forwards;
    }

    .kp-undo__secs,
    .kp-undo__clock {
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
        line-height: 1;
    }

    .kp-undo__clock {
        flex: none;
        min-inline-size: 3ch;
        color: color-mix(in srgb, currentColor 70%, transparent);
    }

    .kp-undo__bar {
        position: absolute;
        inset-inline: 0;
        inset-block-end: 0;
        block-size: 3px;
        background: var(--primary);
        transform-origin: inline-start center;
        animation: kp-undo-rule var(--kp-undo-ms, 6000ms) linear forwards;
    }

    .kp-undo__spinner {
        flex: none;
    }

    .kp-toast--undo[data-kp-paused] :is(.kp-undo__ring-fill, .kp-undo__bar) {
        animation-play-state: paused;
    }

    .kp-toast--undo:not([data-kp-undo-state='counting']) :is(.kp-undo__ring-fill, .kp-undo__bar) {
        animation-play-state: paused;
    }

    @media (prefers-reduced-motion: reduce) {
        .kp-undo__ring-fill,
        .kp-undo__bar {
            animation-timing-function: steps(var(--kp-undo-steps, 6), end);
        }
    }

    @keyframes kp-undo-drain {
        to {
            stroke-dashoffset: 1;
        }
    }

    @keyframes kp-undo-rule {
        to {
            transform: scaleX(0);
        }
    }

    /* A phone: the whole width, Undo a normal button in its own column. */
    @media (max-width: 30rem) {
        .kp-toast--undo {
            inline-size: calc(100vw - 2rem);
            max-inline-size: none;
        }

        .kp-toast--undo > .kp-button {
            min-block-size: var(--kp-control-height, 2.25rem);
        }
    }

    /* --- Accordion ------------------------------------------------------- */

    .kp-accordion__item {
        border-bottom: 1px solid var(--border);
    }

    /* A bare item [port spec J3]: the fold's motion and memory without the
 * accordion's chrome, for a group whose title is the page's own (a quiet
 * label above a board's tiles). Give its summary a class of your own, not
 * `.kp-accordion__summary`, which every register paints. */
    .kp-accordion__item--bare {
        border-bottom: 0;
    }

    .kp-accordion__summary {
        padding: 0.625rem 0;
        cursor: pointer;
        font-weight: 600;
    }

    .kp-accordion__body {
        padding-bottom: 0.75rem;
        color: var(--muted-foreground);
    }

    /* --- Tabs ------------------------------------------------------------ */

    .kp-tabs__list {
        display: flex;
        gap: 0.25rem;
        border-bottom: 1px solid var(--border-strong);
    }

    /* A row longer than its box scrolls inside the box [gap-12]. It ran past
     * a 384px pane by 344px and widened the page; wrapping was the other
     * answer, and it was not taken because a wrapped row puts the selected
     * tab's rule in the middle of the list rather than on its edge.
     *
     * Only a row that does not fit becomes a scroller: js/overlays.js (and
     * the React Tabs) write `data-kp-tabs-overflow` while it does, and keep
     * the selected tab in view. A scroller clips whatever paints outside
     * it, and several registers draw their selected tab past the row — a
     * rule above it, a raised tab two pixels up — so a row that fits keeps
     * exactly the look it had. */
    .kp-tabs__list[data-kp-tabs-overflow] {
        overflow-x: auto;
        overflow-y: hidden;
        overscroll-behavior-x: contain;
        scrollbar-width: thin;
        /* Room above the tabs for what a register draws there, given back by
         * a margin so nothing around the row moves. Upward only: a negative
         * margin at the row's ends would widen the pane it sits in. */
        padding-block-start: var(--kp-tabs-overhang, 0.5rem);
        margin-block-start: calc(-1 * var(--kp-tabs-overhang, 0.5rem));
    }

    /* In a scroller the tabs keep their width rather than squeezing their
     * labels onto two lines. */
    .kp-tabs__list[data-kp-tabs-overflow] > .kp-tab {
        flex: none;
    }

    /* The base focus ring paints outside the control, where the scroller
     * clips it, so in a scrolling row the ring is drawn inside the tab: the
     * same two parts, the contrast outline and the inner ring, turned
     * inward [DI2]. */
    .kp-tabs__list[data-kp-tabs-overflow] > .kp-tab:focus-visible {
        outline-offset: calc(-1 * var(--focus-ring-width, 2px));
        box-shadow: inset 0 0 0 calc(var(--focus-ring-width, 2px) + var(--kp-focus-ring-inner-width, 2px)) var(--focus-ring);
    }

    .kp-tab {
        /* The tab's block padding, type size and line height are the
     * package's in every theme [scope-87], titanium's values; a register
     * keeps its inline padding, border, face and case. */
        padding: var(--kp-tab-padding-block, var(--kp-space-sm, 0.5rem)) 0.75rem;
        border: 0;
        border-bottom: 2px solid transparent;
        background: none;
        color: var(--muted-foreground);
        font: inherit;
        font-size: var(--kp-tab-size, var(--kp-text-md, 1rem));
        line-height: var(--kp-line-height, 1.5);
        cursor: pointer;
    }

    /* The selected tab is marked by weight and a rule as well as by colour,
 * and aria-selected is what a screen reader hears [DI4]. */
    .kp-tab[aria-selected='true'] {
        color: var(--foreground);
        border-bottom-color: var(--primary);
        font-weight: 600;
    }

    /* The count on a tab [gap-tab-count; js/tabbar.js, setTabCount]: the exact number on a badge of the package's own plates
 * (neutral, info, success, warning, destructive), after the label. The room of the digits is held (never fewer than two,
 * more for a longer number) and a loading count is a skeleton of that same width, so a number that arrives, grows a digit or
 * changes tone moves no tab beside it. A fixed weight: the selected tab turns bold, and its count must not widen with it. */
    .kp-tab__count {
        box-sizing: border-box;
        justify-content: center;
        min-inline-size: calc(var(--kp-tab-count-digits, 2) * 1ch + 1rem);
        margin-inline-start: var(--kp-tab-count-gap, var(--kp-space-sm, 0.5rem));
        font-size: var(--kp-tab-count-size, var(--kp-text-xs, 0.75rem));
        font-variant-numeric: tabular-nums;
        font-weight: 600;
        letter-spacing: normal;
        text-transform: none;
        vertical-align: middle;
        white-space: nowrap;
    }

    .kp-tab__count[data-kp-state='loading'] {
        padding-inline: 0;
        background: transparent;
    }

    .kp-tab__bone {
        display: block;
        inline-size: calc(var(--kp-tab-count-digits, 2) * 1ch + 1rem);
        block-size: 1em;
        border-radius: var(--kp-radius-pill, 999px);
    }

    .kp-tab__count[data-kp-state='error'] {
        cursor: help;
    }

    .kp-tabs__panel {
        padding-block: 0.75rem;
    }

    /* --- Breadcrumb and pagination --------------------------------------- */

    /* Both trails' type size is the package's [scope-87]: titanium's. */
    .kp-breadcrumb {
        font-size: var(--kp-breadcrumb-size, 0.9rem);
        line-height: var(--kp-line-height, 1.5);
    }

    .kp-pagination {
        font-size: var(--kp-pagination-size, 0.9rem);
        line-height: var(--kp-line-height, 1.5);
    }

    .kp-breadcrumb ol,
    .kp-pagination ul {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-breadcrumb li + li::before {
        content: var(--kp-glyph-breadcrumb, '/');
        margin-inline-end: 0.5rem;
        color: var(--muted-foreground);
    }

    .kp-pagination a[aria-current='page'] {
        font-weight: 700;
        text-decoration-thickness: 2px;
    }

    .kp-pagination__gap {
        padding: 0 var(--kp-space-xs);
        color: var(--muted-foreground);
    }

    /* --- Log [gap-14, gap-15] -------------------------------------------- */

    /* A log line is the shape homelab writes three times by hand and kp-tui
 * carries as `LogPane`; the web had the colours for it and not the
 * component. What it needs is not a new palette but three promises: the
 * columns do not move, the severity is a word before it is a colour, and
 * a name keeps its own hue.
 *
 * Columns first [fix-64]: the list is the grid and every line hands its
 * parts to it with `display: contents`, so the message of every line
 * begins in the same place whatever the source before it is called. Three
 * columns that size to their own content and a fourth that takes the rest
 * — the same shape as .kp-progress-group, for the same reason. */
    .kp-log {
        display: grid;
        grid-template-columns: auto auto auto minmax(0, 1fr);
        gap: var(--kp-log-gap, 0.125rem) var(--kp-space-sm);
        margin: 0;
        padding: var(--kp-log-padding, var(--kp-space-sm));
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
        line-height: var(--kp-log-line-height, 1.6);
        overflow-x: auto;
    }

    .kp-log__line {
        display: contents;
    }

    .kp-log__time {
        color: var(--muted-foreground);
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
    }

    /* The source in its own hue [gap-15]. Which hue is not this
 * stylesheet's to decide: js/log.js hashes the name into the register's
 * own five chart colours, the same FNV-1a kp-tui hashes with, and writes
 * --kp-source-colour here. Without that script the name is simply ink,
 * which is a page that reads rather than a page that breaks. */
    .kp-log__source {
        color: var(--kp-source-colour, var(--foreground));
        font-weight: 600;
        white-space: nowrap;
    }

    /* The severity as a word, in a column of its own, before any colour is
 * asked to carry it: a log read in a screenshot, in a terminal that lost
 * its colours or by someone who does not see the difference between the
 * warning and the danger hue must still say which line failed [fix-1].
 *
 * Where the colour comes from [fix-70]: a status token comes in a pair —
 * a plate and the ink that reads on it — and which half of the pair is
 * the ink is each theme's own answer. high-contrast paints --warning a
 * strong brown and --warning-foreground white; light paints --warning a
 * pale wash and --warning-foreground a dark ochre. Taking one half as ink
 * on the log's own ground is therefore white on white in some themes and
 * read in others: measured 2026-09-20, ten words across four themes sat
 * between 1.00 and 1.27 to one, and the error ink sat between 3.34 and
 * 4.42 in seven more. So a line that needs attention carries the pair
 * itself — the plate behind the word and its own ink on it, which the
 * contrast gate already holds at 4.5 in all 22 themes — and a routine
 * line keeps the quiet word it always had. */
    .kp-log__level {
        color: var(--kp-log-level-ink, var(--muted-foreground));
        text-transform: uppercase;
        letter-spacing: 0.04em;
        white-space: nowrap;
    }

    .kp-log__message {
        color: var(--card-foreground);
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    .kp-log__line[data-kp-severity='debug'] .kp-log__message {
        color: var(--muted-foreground);
    }

    .kp-log__line[data-kp-severity='warning'] .kp-log__level,
    .kp-log__line[data-kp-severity='error'] .kp-log__level,
    .kp-log__line[data-kp-severity='critical'] .kp-log__level {
        padding-inline: 0.4em;
        border-radius: calc(var(--radius, 0.5rem) / 2);
        font-weight: 700;
    }

    .kp-log__line[data-kp-severity='warning'] .kp-log__level {
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-log__line[data-kp-severity='error'] .kp-log__level,
    .kp-log__line[data-kp-severity='critical'] .kp-log__level {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    /* A line the reader is pointed at: the register's own selected plate
 * would be a second decision, so this is the package's muted ground and
 * nothing else. */
    .kp-log__line[data-kp-current] > * {
        background: var(--muted);
    }

    /* --- Progress, spinner, skeleton ------------------------------------- */

    .kp-progress__wrap {
        display: inline-flex;
        align-items: center;
        gap: calc(var(--kp-space-sm) * var(--kp-progressbar-scale, 1));
        /* Never wider than its container: the bar inside gives way, so a
         * phone does not scroll sideways (DI11). */
        max-inline-size: 100%;
    }

    /* A lone bar beside its reading. The bar has no content of its own to
 * size by (its parts are positioned), so inside a shrink-to-fit row it
 * asks for its full width and gives way on a narrow screen, rather than
 * collapsing to nothing. */
    .kp-progress__wrap > .kp-progressbar {
        flex: 0 1 auto;
        inline-size: var(--kp-progressbar-max-width, 32rem);
    }

    /* A group of bars reads as a group [fix-64]. Kenny, 2026-09-20:
 * "Elementen beginnen op vaste punten, niet afhankelijk van de lengte van
 * andere elementen … of beginnen allemaal op hetzelfde punt als ze
 * verschoven worden, dat punt wordt dan bepaald door het langste woord."
 *
 * One label column, one track column, one reading column, and every row
 * gives its three parts to them: a bar behind "Memory" starts where the
 * bar behind "CPU" starts, and the column is as wide as the longest label
 * in the group and no wider. `display: contents` on the row is what puts
 * its parts in the grid — the row itself paints nothing, so it has
 * nothing to lose by not being a box.
 *
 * A single bar keeps `.kp-progress__wrap` on its own, where there is no
 * group to line up with. */
    .kp-progress-group {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-progress-group-gap, calc(var(--kp-space-xs) * var(--kp-progress-group-scale, 1)))
            calc(var(--kp-space-sm) * var(--kp-progress-group-scale, 1));
    }

    .kp-progress-group .kp-progress__wrap {
        display: contents;
    }

    .kp-progress-group .kp-progress__wrap > .kp-progressbar,
    .kp-progress-group > .kp-progressbar {
        /* In a group the track takes the column it was given, rather than
     * the width a lone bar defaults to. */
        inline-size: 100%;
        max-inline-size: none;
    }

    .kp-progress__label {
        font-size: var(--kp-progressbar-text, var(--kp-text-sm, 0.8125rem));
        color: var(--muted-foreground);
    }

    .kp-progress-group .kp-progress__value {
        text-align: end;
        font-variant-numeric: tabular-nums;
    }

    .kp-progress__value {
        font-size: var(--kp-progressbar-text, var(--kp-text-sm, 0.8125rem));
        color: var(--muted-foreground);
    }

    /* A skeleton comes in the shape of what it stands in for, and its gap is
 * a knob rather than an inline style nothing could beat [KT6]. */
    .kp-skeleton--circle {
        inline-size: var(--kp-skeleton-circle, 3rem);
        border-radius: 50%;
        aspect-ratio: 1;
    }

    .kp-skeleton + .kp-skeleton {
        margin-block-start: var(--kp-skeleton-gap, 0.375rem);
    }

    /* The progress bar [scope-140]. It replaced `<progress class="kp-progress">`
 * in 9.0.0, because a native <progress> has two pseudo-elements in one
 * engine, one in the other, and nothing a theme can give a shape: every
 * register drew the same rounded strip. This is one box with three parts
 * every register may draw its own way — the track, the fill and the head on
 * the fill's leading edge — and nothing outside the bar:
 *
 *   <div class="kp-progressbar" role="progressbar" aria-label="…"
 *        aria-valuemin="0" aria-valuemax="100" aria-valuenow="35"
 *        style="--kp-value: 0.35">
 *     <span class="kp-progressbar__track" aria-hidden="true">
 *       <span class="kp-progressbar__fill"></span>
 *       <span class="kp-progressbar__head"></span>
 *     </span>
 *   </div>
 *
 * --kp-value is the share done, 0 to 1; js/progressbar.js keeps it in step
 * with aria-valuenow, so a consumer may set either. `data-kp-indeterminate`
 * (and no aria-valuenow) is "busy, no idea how far". --kp-steps is how many
 * segments a segmented register draws. The box is one line high whatever
 * happens inside it, never wraps, and keeps its width from the first frame;
 * the fill moves inside it.
 *
 * Knobs: --kp-progressbar-height (0.75rem), --kp-progressbar-max-width
 * (32rem; none inside a group), --kp-progressbar-duration (240ms) and
 * --kp-progressbar-ease (ease-out), the values the approved research round
 * used (research/progress-signature/base.css).
 *
 * Three sizes [Kenny, 2026-10-05: "zodat dit de kleine is, een midden en
 * een grotere optie"]: the bar as it was is the small one, and
 * `.kp-progressbar--md` and `.kp-progressbar--lg` are the other two. A size
 * is one number, --kp-progressbar-scale (1, 1.5, 2), that every part of the
 * drawing is multiplied by — the base track here and each register's own
 * bar, its height and its glyphs, cells and pitches alike — so a theme's bar
 * grows as one drawing rather than as a taller box around the same marks.
 * 1.5 and 2 because every register's small height is a whole multiple of
 * 2px (12 to 22px), so both steps land on whole pixels in every theme; the
 * reading beside the bar steps up the type scale with it (13, 16, 18px)
 * through --kp-progressbar-text. The size sits on the bar; the wrap and the
 * group around it read it from there, so the label and the gaps follow. */
    .kp-progressbar {
        --kp-value: 0;
        --kp-steps: 10;
        --kp-progressbar-scale: 1;
        --kp-progressbar-height: calc(0.75rem * var(--kp-progressbar-scale, 1));
        position: relative;
        display: block;
        inline-size: 100%;
        max-inline-size: var(--kp-progressbar-max-width, 32rem);
        block-size: var(--kp-progressbar-height);
        contain: layout paint;
    }

    .kp-progressbar__track {
        container-type: inline-size;
        position: absolute;
        inset: 0;
        display: block;
        overflow: hidden;
        border-radius: calc(var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2)) * var(--kp-progressbar-scale, 1));
        background: var(--muted);
    }

    /* The sizes: one number each, set on the bar (which states its own, so
 * an ancestor's never leaks into a small bar) and read by the row around
 * it, so the reading and the gap grow with the track. A group takes the
 * gaps of the largest size it holds and gives no size to its rows. */
    .kp-progressbar--md,
    .kp-progress__wrap:has(> .kp-progressbar--md) {
        --kp-progressbar-scale: 1.5;
        --kp-progressbar-text: var(--kp-text-md, 1rem);
    }

    .kp-progressbar--lg,
    .kp-progress__wrap:has(> .kp-progressbar--lg) {
        --kp-progressbar-scale: 2;
        --kp-progressbar-text: calc(var(--kp-text-md, 1rem) * 1.125);
    }

    .kp-progress-group:has(.kp-progressbar--md) {
        --kp-progress-group-scale: 1.5;
    }

    .kp-progress-group:has(.kp-progressbar--lg) {
        --kp-progress-group-scale: 2;
    }

    /* The fill spans the track and is clipped to the value, so a pattern in
 * it never stretches and nothing is laid out again as the value moves:
 * only clip-path and transform change [compositor-only motion]. */
    .kp-progressbar__fill {
        position: absolute;
        inset: 0;
        background: var(--primary);
        clip-path: inset(0 calc((1 - var(--kp-value)) * 100%) 0 0);
    }

    /* The head rides on the fill's leading edge; a register gives it a shape
 * or leaves it empty. 100cqi is the track's width, the track being the
 * inline-size container. */
    .kp-progressbar__head {
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        transform: translateX(calc(var(--kp-value) * 100cqi));
    }

    /* Busy, standing still: diagonal stripes in the accent across the whole
 * track, so a reader who asked for less motion sees "working" and never a
 * share that is not there [gap-11 — a still fill at 30% would read as 30%
 * done]. Without that preference the guard below turns it into the sweep. */
    .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        clip-path: none;
        background-color: transparent;
        background-image: linear-gradient(-45deg, var(--primary) 25%, transparent 25% 50%, var(--primary) 50% 75%, transparent 75%);
        background-size: var(--kp-progressbar-height) var(--kp-progressbar-height);
    }

    .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head {
        display: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-progressbar__fill {
            transition: clip-path var(--kp-progressbar-duration, 240ms) var(--kp-progressbar-ease, ease-out);
        }

        .kp-progressbar__head {
            transition: transform var(--kp-progressbar-duration, 240ms) var(--kp-progressbar-ease, ease-out);
        }

        /* A solid band a third of the track wide, sweeping across it: a
     * transform only, so it runs on the compositor. */
        .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            inset-inline-end: auto;
            inline-size: 30%;
            background: var(--primary);
            animation: kp-progressbar-sweep 1400ms ease-in-out infinite;
        }
    }

    @keyframes kp-progressbar-sweep {
        from {
            transform: translateX(-100%);
        }
        to {
            transform: translateX(340%);
        }
    }

    /* A register draws its own motion inside the bar, and a reader who asked
 * for less of it gets none, whichever register drew it: every animation
 * inside the bar ends on its first frame and nothing transitions. The
 * `!important` is what reaches into kp.register from this earlier layer
 * (an important declaration in an earlier layer wins over every later
 * one), and it is the research round's own rule, kept as approved. */
    @media (prefers-reduced-motion: reduce) {
        .kp-progressbar *,
        .kp-progressbar *::before,
        .kp-progressbar *::after {
            animation-duration: 0s !important;
            animation-iteration-count: 1 !important;
            transition: none !important;
        }
    }

    .kp-spinner {
        display: inline-block;
        inline-size: var(--kp-spinner-size, 1.25rem);
        block-size: var(--kp-spinner-size, 1.25rem);
        /* The track is the head at a quarter of its alpha, not --border-strong:
     * in brutalism both were black and nothing visibly turned. Same hue,
     * different weight, in every theme by construction [KT8]. */
        border: 2px solid hsl(from var(--primary) h s l / 0.25);
        border-block-start-color: var(--primary);
        border-radius: 50%;
    }

    .kp-skeleton {
        display: block;
        block-size: var(--kp-skeleton-height, 1rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--muted);
    }

    /* After the base rule, so the shape's own size wins at equal specificity:
 * a block is as tall as it says and a circle is as tall as it is wide. */
    .kp-skeleton--block {
        block-size: var(--kp-skeleton-block, 6rem);
    }

    .kp-skeleton--circle {
        block-size: auto;
    }

    /* Both of these move, so both are guarded: DI7 is not a preference to
 * honour where convenient. A spinner that keeps spinning for someone who
 * asked for stillness is the exact complaint the setting exists for.
 * Neither animation opposes its own direction, so neither approaches the
 * three-flashes threshold of DI5 — check-motion.mjs measures that. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-spinner {
            animation: kp-spin var(--kp-spinner-duration, 900ms) linear infinite;
        }

        .kp-skeleton {
            /* A literal, not a knob: the pulse changes luminance and DI5 pins it
     * above the flash threshold [KT6]. */
            animation: kp-pulse 1600ms ease-in-out infinite;
        }
    }

    @keyframes kp-spin {
        to {
            transform: rotate(360deg);
        }
    }

    @keyframes kp-pulse {
        0%,
        100% {
            opacity: 1;
        }

        50% {
            opacity: 0.6;
        }
    }

    /* --- The theme menu: an icon button with a dropdown [S2] -------------
 *
 * The shape the consuming projects already liked, now in both channels.
 * It was React-only, which meant the two consumers that render HTML from
 * a Rust binary — the ones it was praised in — could not have it.
 *
 * The dropdown is a popover, so Escape and light dismiss are the
 * browser's, and anchor positioning puts it under its button without
 * either measuring the other.
 */

    /* An icon button is the containing block of whatever a register hangs
       off it, as `.kp-button` already is [fix-75]. At zero specificity, so a
       part that places the button itself — the dialog's close in its
       corner — still wins; retro's own rule beat it and put the close button
       back in the title's line. */
    :where(.kp-icon-button) {
        position: relative;
    }

    .kp-icon-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        inline-size: 2.25rem;
        block-size: 2.25rem;
        padding: 0;
        border: 1px solid transparent;
        border-radius: var(--radius, 0.5rem);
        background: none;
        color: inherit;
        cursor: pointer;
    }

    .kp-icon-button:hover {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    .kp-icon-button svg {
        inline-size: 1.25rem;
        block-size: 1.25rem;
    }

    .kp-theme-menu {
        display: inline-block;
    }

    /* Inside a menu the groups stack: the label sits as a small heading
 * above its rows and the separator between the groups runs full width,
 * inset by the row padding so it reads as part of the list [TH63]. */
    .kp-menu .kp-theme-group {
        display: block;
        list-style: none;
        margin: 0;
        padding: 0;
    }

    .kp-menu .kp-theme-group__list {
        display: block;
        list-style: none;
        margin: 0;
        padding: 0;
    }

    .kp-menu .kp-theme-group__label {
        padding: var(--kp-picker-group-pad, 0.375rem 0.625rem 0.125rem);
    }

    .kp-menu .kp-theme-group + .kp-theme-group {
        margin-block-start: var(--kp-picker-gap, 0.25rem);
        padding-block-start: var(--kp-picker-gap, 0.25rem);
        border-block-start: 1px solid var(--border);
    }

    /* The React switcher renders its list itself rather than as a popover
 * element, so it positions under the button here. Both channels share
 * the option and group rules below. */
    .kp-theme-menu {
        position: relative;
    }

    .kp-theme-menu__list {
        position: absolute;
        inset-inline-end: 0;
        inset-block-start: 100%;
        margin-block-start: var(--kp-menu-offset, 0.25rem);
        min-inline-size: var(--kp-menu-min-width, 11rem);
        /* As wide as its longest row: placed against the button, the list
           otherwise takes the button's width as the room it has, and the
           selected row, set bold, broke onto two lines in high-contrast,
           Shade (light) and Shade (dark) (JobTracker, 2026-10-03; fix-93). */
        inline-size: max-content;
        max-inline-size: calc(100vw - 2rem);
        z-index: var(--kp-z-popover, 20);
    }

    /* The theme menu scrolls inside its rounded box, not as it [scope-60].
 * The popover was itself the scroll box, so its scrollbar ran square into
 * the rounded corners. Now the popover clips and the list inside it
 * scrolls, in both shapes: the markup's `.kp-popover > .kp-menu` and the
 * React switcher's `.kp-theme-menu__list > .kp-menu`. */
    .kp-theme-menu :is(.kp-popover, .kp-theme-menu__list):has(> .kp-menu) {
        overflow: hidden;
    }

    .kp-theme-menu :is(.kp-popover, .kp-theme-menu__list) > .kp-menu {
        max-block-size: calc(var(--kp-popover-max-height, min(80vh, 40rem)) - 1rem);
        overflow-y: auto;
        border-radius: 0;
    }

    .kp-theme-menu__status {
        padding: var(--kp-menu-item-pad, 0.375rem 0.625rem);
        color: var(--destructive);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-theme-option__label {
        flex: 1;
    }

    .kp-theme-option__check {
        inline-size: 1rem;
        block-size: 1rem;
        margin-inline-start: auto;
    }

    /* The menu reuses .kp-popover and .kp-menu, so it inherits the overlay
 * looks rather than inventing a second set. */
    .kp-menu [data-kp-theme] {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        inline-size: 100%;
        padding: 0.375rem 0.625rem;
        border: 0;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        color: inherit;
        font: inherit;
        text-align: start;
        /* A theme's name is one line in every theme, the bold selected one
           too. */
        white-space: nowrap;
        cursor: pointer;
        /* Border-box, or `100%` plus the padding overflows the popover by the
     * padding — 20px wider than the menu on CI's scrollbar-bearing
     * Chromium, where every option then lay outside the box [R5]. */
        box-sizing: border-box;
    }

    .kp-menu [data-kp-theme]:hover {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    /* In a menu the mark is a check at the end, not a border: a row does not
 * have a boundary to colour, and the check is the second channel [DI4].
 * The glyph is a knob; the React half renders an SVG child instead and
 * suppresses this one. */
    .kp-menu [data-kp-theme][data-selected='true']:not(:has(.kp-theme-option__check))::after {
        content: var(--kp-glyph-check, '✓');
        margin-inline-start: auto;
    }

    .kp-menu [data-kp-theme][data-selected='true'] {
        font-weight: 600;
    }

    /* ====================================================================
 * Round two: the components rated on 2026-09-04 [TH37-TH59].
 * ==================================================================== */

    /* --- Combobox and tag input [TH39, TH41] ----------------------------- */

    /* Block flow rather than a flex column [gap-11]. The list is positioned
 * absolutely and used to hang from `top: 100%` of the whole box, so with
 * the status line inside the box it opened a line below the input it
 * belongs to. In block flow an absolutely positioned box with no `top`
 * sits at its static position — directly after the input, whatever comes
 * before it (a label, a row of tags) and whatever follows (the status).
 * In a flex container that static position is the container's start, so
 * the flex column had to go; the gap it gave is a margin now. */
    .kp-combobox {
        position: relative;
        display: flow-root;
    }

    .kp-combobox > :where(label, .kp-field__label) {
        display: block;
    }

    .kp-combobox > :not(:first-child, .kp-combobox__list, .kp-combobox__clear) {
        margin-block-start: var(--kp-combobox-gap, 0.375rem);
    }

    /* The same ground, boundary, ink and size as .kp-field__input [gap-11]:
 * the combobox read --card and --border where a field reads --background
 * and --input, so a theme whose card and page differ showed two different
 * boxes side by side in one form. */
    .kp-combobox__input {
        /* Border-box, or `width: 100%` plus padding and a border overflows the
     * wrapper. Found by putting this on the showcase: at 320 px it pushed
     * the page 10 px sideways and DI11 went red on all eleven themes. */
        box-sizing: border-box;
        display: block;
        width: 100%;
        /* The field's box [scope-80]. */
        min-height: var(--kp-control-height, 2.25rem);
        padding: 0 0.625rem;
        line-height: var(--kp-control-line-height, 1.25);
        border: 1px solid var(--input);
        border-radius: var(--radius, 0.5rem);
        background: var(--background);
        color: var(--foreground);
        font: inherit;
        box-shadow: var(--fx-shadow-offset, 0px) var(--fx-shadow-offset, 0px) 0 0 var(--border-strong);
    }

    /* The theme's own timing, and only for someone who did not ask for less
 * motion — the same guard every other transition in this file sits in. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-combobox__input {
            transition:
                border-color var(--fx-duration, 150ms) var(--fx-ease),
                box-shadow var(--fx-duration, 150ms) var(--fx-ease);
        }
    }

    .kp-combobox__input:focus-visible {
        border-color: var(--border-strong);
    }

    /* The list floats over the page, so it needs a surface of its own and a
 * boundary that survives against whatever is behind it. */
    .kp-combobox__list {
        position: absolute;
        inset-inline: 0;
        /* No top: the static position, directly under the input [gap-11]. */
        z-index: var(--kp-z-popover, 20);
        max-height: var(--kp-combobox-list-max-height, 15rem);
        margin: 0.25rem 0 0;
        padding: 0.25rem;
        overflow-y: auto;
        list-style: none;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        box-shadow: 0 8px 24px hsl(from var(--foreground) h s l / 0.12);
    }

    .kp-combobox__option {
        padding: 0.375rem 0.625rem;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        cursor: pointer;
    }

    /* The highlight is the keyboard's position, not the mouse's: it is set by
 * the arrow keys and mirrored on hover, so both agree about what Enter
 * would take. `is-active` and aria-selected are written together. */
    .kp-combobox__option.is-active {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    .kp-combobox__option[hidden] {
        display: none;
    }

    /* An option that cannot be chosen looks it [gap-11]: faded, and the
 * pointer says no. The listbox already skips it for the arrows and the
 * hover; it painted exactly like one that can be taken. */
    .kp-combobox__option:is([aria-disabled='true'], [data-kp-disabled]) {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        cursor: not-allowed;
    }

    /* The "no results" row: in the list, where the eye already is, and not an
 * option — nothing for Enter to take [gap-11]. */
    .kp-combobox__empty {
        padding: 0.375rem 0.625rem;
        color: var(--muted-foreground);
        cursor: default;
    }

    .kp-combobox__status {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The drawn select [scope-54]: `select[data-kp-select]` gets a listbox in
 * the combobox's own classes laid over it, so every register that answers
 * the combobox list answers this one with the same rule. What is its own:
 * js/combobox.js places it under the select (a flex column like .kp-field
 * gives an absolute box no useful static position), and the value the box
 * holds is marked the way the native picker marks it — weight and a check. */
    [data-kp-select-list] {
        box-sizing: border-box;
        inset-inline: auto;
    }

    /* An open list lives in the top layer, where no container's clip-path or
 * overflow reaches it (js/top-layer.js): a combobox's or a drawn select's
 * options were out of reach inside a card in dark, cyberpunk, phantom and
 * titanium. js/combobox.js places it in window coordinates under its field
 * and as wide as the list was; the popover's UA inset, margin and ink are
 * put back to the list's own. With no room below, it opens above the field
 * at the same distance, with `data-kp-overlay-side="above"` written for a
 * register that mirrors something [fix-30]. */
    .kp-combobox__list:popover-open {
        position: fixed;
        inset: auto;
        box-sizing: border-box;
        margin: 0.25rem 0 0;
        color: inherit;
    }

    [data-kp-select-list] > [data-kp-chosen] {
        display: flex;
        gap: var(--kp-space-sm, 0.5rem);
        font-weight: 600;
    }

    [data-kp-select-list] > [data-kp-chosen]::after {
        content: var(--kp-glyph-check, '✓');
        margin-inline-start: auto;
    }

    .kp-tag-list {
        display: flex;
        flex-wrap: wrap;
        gap: 0.375rem;
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-tag {
        display: inline-flex;
        align-items: center;
        gap: 0.25rem;
        padding: 0.125rem 0.25rem 0.125rem 0.5rem;
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-pill, 999px);
        background: var(--muted);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* A list toolbar's active filter is one line. A theme that folds the width of what arrives (formal rules a
       part open from the start edge, js/motion.js animates its width from 0) would otherwise wrap its words to one
       letter per line while it grows: a pill 279 px tall that pushed the page down until the arrival ended (Kenny,
       kpadopt-controls toolbar · formal, 2026-10-16). Only there: a plain tag holding a sentence wraps inside its
       pill, as approved (catalogue/feedback.html#tags). */
    .kp-toolbar__active-list > .kp-tag {
        white-space: nowrap;
    }

    .kp-tag__remove {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        /* 1.25rem is small, so the tap target is widened by padding on the tag
     * rather than by growing the glyph. */
        width: 1.25rem;
        height: 1.25rem;
        padding: 0;
        border: 0;
        border-radius: var(--kp-radius-pill, 999px);
        background: none;
        color: inherit;
        font: inherit;
        line-height: 1;
        cursor: pointer;
    }

    .kp-tag__remove:hover {
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    /* --- Command palette and shortcut sheet [TH40, TH49] ----------------- */

    /* Commands grouped under a small heading; the group hides when every
 * command in it is filtered out [KT6]. */
    .kp-palette__group {
        list-style: none;
    }

    .kp-palette__group > ul {
        list-style: none;
        margin: 0;
        padding: 0;
    }

    .kp-palette__group-label,
    .kp-shortcuts__group-label {
        display: block;
        margin: var(--kp-space-sm) 0 var(--kp-space-xs);
        font-size: var(--kp-shortcuts-label-size, 0.6875rem);
        font-weight: 600;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    .kp-palette__description {
        margin-inline-start: var(--kp-space-sm);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The clear button shares the input's grid cell, so it is centred on the
       input and not on the whole box with its label and status line. */
    .kp-combobox:has(> .kp-combobox__clear) {
        display: grid;
        grid-template-areas: 'label' 'input';
    }

    .kp-combobox:has(> .kp-combobox__clear) > :where(label, .kp-field__label) {
        grid-area: label;
    }

    .kp-combobox:has(> .kp-combobox__clear) > .kp-combobox__input {
        grid-area: input;
    }

    /* Under a label the input carries the gap above it; so does the button,
       or it would centre on the gap and the input together. */
    .kp-combobox > :where(label, .kp-field__label) ~ .kp-combobox__clear {
        margin-block-start: var(--kp-combobox-gap, 0.375rem);
    }

    .kp-combobox__clear {
        grid-area: input;
        font: inherit;
        justify-self: end;
        align-self: center;
        margin-inline-end: var(--kp-space-sm);
        border: 0;
        background: none;
        color: var(--muted-foreground);
        cursor: pointer;
    }

    /* A dialog centred near the top rather than the middle: a palette that
 * grows downwards should not push its own input off-centre while you
 * type. */
    .kp-palette {
        width: var(--kp-palette-width, min(36rem, 92vw));
        margin: 10vh auto auto;
        padding: 0;
        overflow: hidden;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
    }

    .kp-palette__input {
        /* Border-box: content-box made the input 32px wider than its
         * palette (391px in a 359px one), cut off by the overflow. */
        box-sizing: border-box;
        width: 100%;
        padding: 0.875rem 1rem;
        border: 0;
        border-bottom: 1px solid var(--border);
        background: none;
        color: inherit;
        font: inherit;
        font-size: var(--kp-text-md, 1rem);
    }

    .kp-palette__list {
        max-height: var(--kp-palette-list-max-height, 50vh);
        margin: 0;
        padding: 0.25rem;
        overflow-y: auto;
        list-style: none;
    }

    .kp-palette__option {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        padding: 0.5rem 0.75rem;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        cursor: pointer;
    }

    /* A command that is a link [scope-48] looks like every other command:
 * the row is the affordance, not an underline. */
    a.kp-palette__option {
        color: inherit;
        text-decoration: none;
    }

    .kp-palette__option.is-active {
        background: var(--kp-highlight, hsl(from var(--foreground) h s l / 0.08));
        color: inherit;
    }

    .kp-palette__option[hidden] {
        display: none;
    }

    /* The key hint sits at the end and never competes with the label. */
    .kp-palette__keys {
        margin-inline-start: auto;
        font-size: var(--kp-text-xs, 0.75rem);
        /* A chord (Ctrl K, Ctrl Shift P) is one unit: it keeps its width and its line, and the label gives way. */
        flex: none;
        white-space: nowrap;
    }

    .kp-palette__status {
        margin: 0;
        padding: 0.5rem 1rem;
        border-top: 1px solid var(--border);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-shortcuts {
        /* Border-box, and the default width raised by exactly what used to
     * sit outside it — 40px of padding plus 2px of border on a 448px
     * content box, so 30.625rem is the same 490px the sheet has always
     * been on a wide screen. Content-box made it 373px on a 360px
     * viewport and the page scrolled sideways [MR-R6-2, DI11]. The knob
     * therefore means the total width now, which is what a width knob
     * ought to mean. */
        box-sizing: border-box;
        width: var(--kp-shortcuts-width, min(30.625rem, 92vw));
        padding: 1.25rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
    }

    /* A palette or a sheet shown in place (not modal, e.g. an example on
     * a page) stays inside its box: 92vw is wider than a padded column on
     * a phone, and the page scrolled sideways by 30px at 390px. A modal
     * one keeps the browser's own limit against the window. */
    .kp-palette:not(:modal),
    .kp-shortcuts:not(:modal) {
        box-sizing: border-box;
        max-inline-size: 100%;
    }

    .kp-shortcuts__list {
        margin: 0.75rem 0;
    }

    .kp-shortcuts__row {
        display: flex;
        align-items: baseline;
        gap: 0.75rem;
        padding: 0.25rem 0;
    }

    .kp-shortcuts__row dt {
        flex: 0 0 6rem;
    }

    .kp-shortcuts__row dd {
        margin: 0;
        color: var(--muted-foreground);
    }

    /* align-pkg-1019:shortcuts:start
     * The description cell fills the rest of the row, so every dd starts after the key column and ends on the sheet's
     * content edge. It used to shrink to its text and ended wherever the words did (3 to 107 px apart over a sheet). */
    .kp-shortcuts__row dd {
        flex: 1 1 0;
        min-inline-size: 0;
    }
    /* align-pkg-1019:shortcuts:end */

    /* --- DataTable [TH37] ------------------------------------------------ */

    /* The sort control is a button inside the header, so it is reachable
 * from the keyboard [KT6]; it wears the header's own text and nothing of
 * a button's.
 *
 * Inline, and the header keeps its own padding [gap-13]. The first cut
 * made the button a block that took the header's padding, and three
 * things followed: the arrow the header draws after its content dropped
 * to a line of its own (nostromo 65 px against 32 px), the button reset
 * the case and the letter-spacing a register gives its headers, and the
 * padding read a cell-pad knob that nothing else had. The whole
 * cell still sorts: the React header listens for the click itself, and
 * the button's own click reaches it. */
    .kp-datatable__sort {
        display: inline;
        margin: 0;
        padding: 0;
        border: 0;
        background: none;
        color: inherit;
        font: inherit;
        letter-spacing: inherit;
        text-transform: inherit;
        text-align: inherit;
        cursor: pointer;
    }

    .kp-datatable__page-size {
        font: inherit;
    }

    /* A select in a bar — the "In" choice, the density, the page size, the
 * card layout's sort — wears `.kp-field__input` for the theme and this
 * for its width: a field fills its row, a choice in a toolbar does not. */
    .kp-datatable__select {
        flex: 0 0 auto;
        inline-size: auto;
    }

    .kp-datatable__label {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The filter panel, the pills, the action bar, the loading slot and the
 * card layout's sort control sit between the bars and the table, and take
 * the bars' inset, so nothing touches the frame a register draws
 * [gap-11]. */
    .kp-datatable__filters,
    .kp-datatable__pills,
    .kp-datatable__actions,
    .kp-datatable__loading,
    .kp-datatable__card-sort {
        padding-block: var(--kp-datatable-bar-padding-block, var(--kp-space-sm, 0.5rem));
        padding-inline: var(--kp-datatable-bar-padding-inline, var(--kp-space-md, 0.75rem));
    }

    .kp-datatable__filters {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--kp-datatable-filter-min, 12rem)), 1fr));
        gap: var(--kp-space-md, 0.75rem);
    }

    .kp-datatable__filter {
        display: flex;
        flex-direction: column;
        gap: var(--kp-space-xs, 0.25rem);
    }

    .kp-datatable__range {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-datatable__range > input {
        flex: 1 1 7rem;
        min-inline-size: 0;
    }

    /* A date bound is the package's date picker (scope-58): each takes a
 * whole row of the range, so its calendar button stays beside its field. */
    .kp-datatable__range > .kp-datepicker {
        --kp-datepicker-input-min: 5rem;
        flex: 1 1 100%;
        min-inline-size: 0;
    }

    /* A date filter takes two columns where the panel has them [Kenny's note
 * of 2026-09-13]. One column holds a number range or a list of choices,
 * but a date field beside its calendar button did not hold the date: in a
 * 238px column the date was cut in eighteen of the twenty-two themes with
 * the old ghost button, and still 2px short in brutalism with the glyph
 * (97px of room for 99px). From 40rem the panel always has two columns at its 12rem
 * floor, so the span never makes a column the grid does not have. */
    @container kp-table (min-width: 40rem) {
        .kp-datatable__filter:has(.kp-datepicker) {
            grid-column: span 2;
        }
    }

    .kp-datatable__pills {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* The add-filter mode [Kenny, 2026-09-14, "Allebei, per tabel"], as the
 * approved mock of research/datatable/demo.html#filter-add draws it: a menu
 * of columns under "+ Add filter", an editor between the bar and the
 * pills, and one pill per filter whose words reopen its editor. */

    /* Under its button, and above it where the window has no room below.
 * Fixed, not the popover's absolute: in the top layer an absolute box is
 * placed in the initial containing block, which a page scrolled down has
 * left, so the fallback never found room and the menu opened below the
 * window — where its focused first item then pulled the whole page up
 * (measured 2026-09-14 at 720px, all 22 themes, both channels). A fixed
 * box is tried against the window and still follows its anchor. */
    .kp-datatable__add-menu {
        position: fixed;
        position-try-fallbacks: flip-block;
    }

    /* Block, not flex: a register may put a ::before on a menu item
 * (cyberpunk's dash), and in a flex row it becomes an item. */
    .kp-datatable__add-item {
        display: block;
        inline-size: 100%;
        white-space: nowrap;
        text-align: start;
    }

    .kp-datatable__add-item > .kp-badge {
        margin-inline-start: var(--kp-datatable-add-mark-gap, 0.5rem);
    }

    /* Its own frame, not a .kp-card or a .kp-popover: both carry a clip-path
 * in some registers, which cut off the calendar a date bound opens. The
 * calendar goes to the top layer; the editor stays in the flow. */
    .kp-datatable__filter-editor {
        display: grid;
        gap: var(--kp-datatable-filter-editor-gap, var(--kp-space-md, 0.75rem));
        margin-block: var(--kp-datatable-bar-padding-block, var(--kp-space-sm, 0.5rem)) 0;
        margin-inline: var(--kp-datatable-bar-padding-inline, var(--kp-space-md, 0.75rem));
        padding: var(--kp-datatable-filter-editor-padding, var(--kp-space-md, 0.75rem));
        max-inline-size: var(--kp-datatable-filter-editor-max-width, 34rem);
        border: var(--kp-datatable-filter-editor-border-width, 1px) solid var(--kp-datatable-filter-editor-border, var(--border-strong));
        border-radius: var(--kp-datatable-filter-editor-radius, var(--radius, 0.5rem));
        background: var(--kp-datatable-filter-editor-ground, var(--card));
        color: var(--kp-datatable-filter-editor-ink, var(--card-foreground));
    }

    .kp-datatable__filter-editor-title {
        margin: 0;
        font-weight: var(--kp-datatable-filter-editor-title-weight, 600);
    }

    .kp-datatable__filter-editor-choices {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kp-datatable-filter-choice-min, 9rem)), 1fr));
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
    }

    .kp-datatable__filter-editor-pair {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--kp-datatable-filter-bound-min, 12rem)), 1fr));
        gap: var(--kp-space-md, 0.75rem);
    }

    .kp-datatable__filter-editor-pair > .kp-datepicker {
        --kp-datepicker-input-min: 6rem;
        min-inline-size: 0;
    }

    .kp-datatable__filter-editor-actions {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* A pill's words are a button that reopens its editor; it reads as the
 * pill's text, with a dotted underline to say it can be pressed. */
    .kp-datatable__pill-edit {
        padding: 0;
        border: 0;
        background: none;
        color: inherit;
        font: inherit;
        letter-spacing: inherit;
        text-transform: inherit;
        text-align: start;
        cursor: pointer;
        text-decoration: underline dotted;
        text-underline-offset: 0.2em;
    }

    .kp-datatable__actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        background: var(--muted);
        color: var(--foreground);
    }

    /* --- Rows ticked with the keyboard, and the selection bar [kpadopt5] ---- */

    /* The cursor row of js/row-select.js is a ring on the row, not a fill, so a
     * ticked row (the selected tint) and the cursor read apart. The ring shows
     * once a key has been used, never for the mouse. A ticked row takes the
     * theme's selected tint (`--kp-selected`). */
    [data-kp-cursor-visible] .is-cursor,
    [data-kp-roving]:focus-visible {
        outline: 2px solid var(--ring, var(--primary));
        outline-offset: -2px;
    }

    [data-kp-roving]:has([data-kp-select-row]:checked),
    tr[data-kp-roving]:has([data-kp-select-row]:checked) > :is(td, th) {
        background: var(--kp-selected, color-mix(in oklab, var(--primary) 9%, transparent));
    }

    /* A bar that is there as soon as rows are ticked: how many, which, the page's
     * actions, and a way to untick all. It keeps its height whether or not
     * anything is ticked, so the list under it never jumps; the panel is ruled
     * open along its start edge, at the theme's rule time (`--kp-rule-time`,
     * `--kp-rule-ease`), and closed the same way backwards. Knobs:
     * --kp-selection-height (3.5rem), --kp-selection-top (0, where the bar
     * sticks), --kp-selection-digits (written by the module). */
    .kp-selection {
        container: kp-selection / inline-size;
        position: relative;
        display: block;
        box-sizing: border-box;
        min-block-size: var(--kp-selection-height, 3.5rem);
        min-inline-size: 0;
        margin-block: var(--kp-space-sm, 0.5rem);
    }

    .kp-selection[data-kp-placement='sticky-top'] {
        position: sticky;
        inset-block-start: var(--kp-selection-top, 0);
        z-index: var(--kp-z-sticky, 20);
    }

    .kp-selection[data-kp-placement='floating-bottom'] {
        position: fixed;
        inset-inline: var(--kp-space-md, 0.75rem);
        inset-block-end: calc(var(--kp-space-md, 1rem) + var(--kp-tabbar-height, 0px));
        z-index: var(--kp-z-toast, 90);
        display: flex;
        justify-content: center;
        min-block-size: 0;
        margin: 0;
        pointer-events: none;
    }

    .kp-selection[data-kp-placement='floating-bottom'] > .kp-selection__panel {
        inline-size: min(100%, var(--kp-selection-max, 64rem));
        pointer-events: auto;
    }

    .kp-selection__panel {
        box-sizing: border-box;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr) auto auto;
        grid-template-areas:
            'count names actions clear'
            'offer offer offer offer'
            'result result result result';
        align-items: center;
        column-gap: var(--kp-space-md, 0.75rem);
        min-block-size: var(--kp-selection-height, 3.5rem);
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem) var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        border: 1px solid var(--border-strong);
        border-inline-start: 3px solid var(--primary);
        border-radius: var(--radius, 0.5rem);
        background: var(--popover, var(--card));
        color: var(--popover-foreground, var(--card-foreground));
        clip-path: inset(0 0 0 0);
        visibility: visible;
        transition:
            clip-path var(--kp-rule-time, 400ms) var(--kp-rule-ease, linear),
            visibility 0s;
    }

    .kp-selection[data-kp-selection-state='empty'] > .kp-selection__panel {
        clip-path: inset(0 100% 0 0);
        visibility: hidden;
        transition:
            clip-path var(--kp-rule-time, 400ms) var(--kp-rule-ease, linear),
            visibility 0s linear var(--kp-rule-time, 400ms);
    }

    [dir='rtl'] .kp-selection[data-kp-selection-state='empty'] > .kp-selection__panel {
        clip-path: inset(0 0 0 100%);
    }

    @media (prefers-reduced-motion: reduce) {
        .kp-selection__panel,
        .kp-selection[data-kp-selection-state='empty'] > .kp-selection__panel {
            transition: none;
        }
    }

    .kp-selection__count {
        grid-area: count;
        display: flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        margin: 0;
        /* The room of the next digit: "99 selected" and "100 selected" take the same place. */
        min-inline-size: calc(var(--kp-selection-digits, 2) * 1ch + 9ch);
        font-weight: 600;
        font-variant-numeric: tabular-nums;
    }

    .kp-selection__busy {
        font-weight: 400;
    }

    .kp-selection__names {
        grid-area: names;
        display: flex;
        flex-wrap: wrap;
        align-items: baseline;
        gap: 0 0.4em;
        min-inline-size: 0;
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: anywhere;
    }

    .kp-selection__names[hidden] {
        display: none;
    }

    .kp-selection__more {
        padding: 0;
        border: 0;
        background: none;
        color: var(--foreground);
        font: inherit;
        font-weight: 600;
        text-decoration: underline;
        text-underline-offset: 0.2em;
        cursor: pointer;
    }

    .kp-selection__offer,
    .kp-selection__result {
        margin: 0;
        padding-block-start: var(--kp-space-xs, 0.25rem);
    }

    .kp-selection__offer {
        grid-area: offer;
    }

    .kp-selection__result {
        grid-area: result;
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-selection__offer[hidden],
    .kp-selection__result[hidden] {
        display: none;
    }

    .kp-selection__result[data-kp-selection-result='refused'] {
        color: var(--destructive);
    }

    .kp-selection__actions {
        grid-area: actions;
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem);
    }

    .kp-selection__clear {
        grid-area: clear;
        white-space: nowrap;
    }

    .kp-selection__toggle {
        display: none;
        grid-area: actions;
    }

    .kp-selection [data-kp-selection-off] {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        cursor: not-allowed;
    }

    /* A row that refused an action: a rule on its start edge and the reason in words. */
    [data-kp-refused] > :first-child,
    tr[data-kp-refused] > :first-child {
        box-shadow: inset 3px 0 0 var(--destructive);
    }

    .kp-selection__refusal {
        display: block;
        color: var(--destructive);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    /* A narrow bar: the count, "Actions" and untick; the names fold to the count. */
    @container kp-selection (max-width: 40rem) {
        .kp-selection__panel {
            grid-template-columns: minmax(0, 1fr) auto auto;
            grid-template-areas:
                'count toggle clear'
                'actions actions actions'
                'offer offer offer'
                'result result result';
        }

        .kp-selection__names {
            display: none;
        }

        .kp-selection__toggle {
            display: inline-flex;
            grid-area: toggle;
        }

        .kp-selection__actions {
            display: none;
            padding-block-start: var(--kp-space-xs, 0.25rem);
        }

        .kp-selection[data-kp-selection-open] .kp-selection__actions {
            display: flex;
        }
    }

    .kp-datatable__loading {
        display: grid;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* The card layout's sort control is for the card layout only: in the
 * table shape the headers sort, and a second control would be a second
 * way to say the same thing [gap-13]. */
    .kp-datatable__card-sort {
        display: none;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* A refresh keeps the old rows, dimmed, so the page does not jump; a
 * first load has no rows and shows the loading slot instead. */
    .kp-datatable[aria-busy='true'] .kp-table tbody {
        opacity: var(--kp-datatable-busy-opacity, 0.55);
    }

    /* A header that stays whenever the table has a max height [Kenny,
 * 2026-09-13]: `data-kp-max-height` on the data table, which the script
 * carries into the knob. The ground is opaque so rows do not show through
 * the header; a register whose data table stands on another surface
 * names it in `--kp-datatable-head-ground`, and a register that paints its
 * headers keeps its own paint, because it is a later layer. */
    .kp-datatable[data-kp-max-height] > .kp-table-wrap {
        max-block-size: var(--kp-datatable-max-height, 24rem);
        overflow: auto;
    }

    .kp-datatable[data-kp-max-height] .kp-table thead th {
        position: sticky;
        inset-block-start: 0;
        z-index: 1;
        background-color: var(--kp-datatable-head-ground, var(--background));
    }

    /* The header's ground reaches 2px above the header [fix-32]: Kenny saw
 * slivers of row text just above it while wheel-scrolling in FireDragon,
 * the box starting on a half pixel. An unblurred shadow in the header's
 * own ground, clipped by the scroll box. The shadow is a knob: a register
 * that paints its header in another colour names that colour in
 * `--kp-datatable-head-ground` on the cell, and one that draws its own
 * shadow on the cell adds `var(--kp-datatable-head-reach)` to its list,
 * under `[data-kp-scrolled]` only.
 *
 * The reach is drawn only while the box is scrolled away from the top
 * [scope-90]: at rest it painted the bottom 2px of a caption standing
 * directly above the header. js/datatable.js (both channels) sets
 * `data-kp-scrolled` on the data table while its scroll box is scrolled;
 * without script the attribute never comes, and there is no reach at all,
 * which is accepted: the slivers it covers only appear while scrolling. */
    .kp-datatable[data-kp-max-height] .kp-table thead th {
        --kp-datatable-head-reach: 0 -2px 0 0 var(--kp-datatable-head-ground, var(--background));
    }

    .kp-datatable[data-kp-max-height][data-kp-scrolled] .kp-table thead th {
        box-shadow: var(--kp-datatable-head-reach);
    }

    /* The box clips its own top edge while scrolled [fix-32, 2026-09-15
 * follow-up]. Kenny still saw row letters above the header in FireDragon,
 * zoomed. Recorded from the compositor (FireDragon 155 on a virtual
 * display, real wheel clicks): when the box's top edge falls in the lower
 * half of a device pixel, the box's ground and the sticky header start on
 * the next pixel row, but row text still paints one device pixel above
 * them, outside the box, at every zoom 1 to 1.75 and in every theme. The
 * reach cannot cover it — the box clips the reach too — and a larger reach,
 * a backing pseudo-element or a layer on the header left it; a clip-path
 * with its top at 0 took it away. Only the top edge is clipped, and only
 * while scrolled and not keyboard-focused, so a caption above is untouched
 * at rest and the focus ring keeps its top side. */
    .kp-datatable[data-kp-max-height][data-kp-scrolled] > .kp-table-wrap:not(:focus-visible) {
        clip-path: inset(0 -100vmax -100vmax);
    }

    /* A status label in a table keeps its word whole [gap-13]: the badge's
 * default `anywhere` broke "WATCHING" into WATCHI / NG in nostromo, in a
 * column squeezed by a long note. The knob is the badge's own. */
    .kp-datatable,
    .kp-table {
        --kp-badge-wrap: normal;
    }

    .kp-table tr[data-kp-clickable] {
        cursor: pointer;
    }

    /* The seven of Kenny's form of 2026-09-13 ("Alle zeven, nu"), each as
 * its approved mock in research/datatable/demo.html drew it. */

    /* Sorting on more than one column: each sorted header carries its place
 * in a small ring beside its label, on the header's line [#multi-sort]. */
    .kp-datatable[data-kp-sort-multi] .kp-table thead th {
        white-space: nowrap;
    }

    .kp-datatable__sort-order {
        display: inline-block;
        margin-inline-start: 0.3rem;
        min-inline-size: 1.2em;
        padding: 0 0.25em;
        border: 1px solid currentColor;
        border-radius: var(--kp-datatable-sort-order-radius, 999px);
        font-size: var(--kp-datatable-sort-order-size, 0.7em);
        line-height: 1.35;
        text-align: center;
    }

    .kp-datatable__sort-summary {
        flex: 1 1 auto;
    }

    /* The multi-sort summary's own line [fix-83]: one line high whatever it
       says, so sorting moves nothing, and the way back to the opening sort
       keeps its room when there is nothing to go back to. */
    .kp-datatable__sort-line {
        flex-wrap: nowrap;
    }

    .kp-datatable__sort-line > .kp-datatable__sort-summary {
        min-inline-size: 0;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    [data-kp-datatable-sort-reset][data-kp-datatable-at-opening] {
        visibility: hidden;
    }

    /* Refreshing: a spinner beside the status words [#states]. */
    .kp-datatable__status:has(> .kp-spinner) {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-datatable__status > .kp-spinner {
        --kp-spinner-size: 1em;
    }

    /* Loading, in sight [busy overlay]: a table long or slow enough that its
 * status line sits below the fold asks for a large spinner over its rows,
 * with the status words and the count under it. The layer is placed in the
 * box that holds the table, under the header, so nothing moves when it
 * comes or goes; the rows show dimmed through it. */
    .kp-datatable:has(> .kp-datatable__busy-overlay) {
        position: relative;
    }

    .kp-datatable__busy-overlay {
        position: absolute;
        inset: var(--kp-busy-overlay-top, 0px) var(--kp-busy-overlay-right, 0px) var(--kp-busy-overlay-bottom, 0px) var(--kp-busy-overlay-left, 0px);
        z-index: 1;
        display: grid;
        place-items: center;
        background: color-mix(in oklab, var(--background) var(--kp-busy-overlay-veil, 70%), transparent);
        pointer-events: none;
    }

    .kp-datatable__busy-panel {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        padding: var(--kp-space-md, 1rem) var(--kp-space-lg, 1rem);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        box-shadow: 0 0 0 1px var(--border);
        text-align: center;
    }

    .kp-datatable__busy-panel > .kp-spinner {
        --kp-spinner-size: var(--kp-busy-overlay-spinner, 2.5rem);
    }

    .kp-datatable__busy-panel > .kp-datatable__busy-clock {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* Loading, on a phone [scope-143]: the layer clips rather than spilling
 * over the status line, and in a narrow table the panel lies flat: the
 * spinner beside the words, the words kept to three lines (the status line
 * says all of it), so it fits over the three skeleton rows of a first
 * load. */
    .kp-datatable__busy-overlay {
        overflow: hidden;
    }

    @container kp-table (max-width: 30rem) {
        .kp-datatable__busy-panel {
            display: grid;
            grid-template-columns: auto minmax(0, 1fr);
            align-items: center;
            gap: 0 var(--kp-space-md, 1rem);
            max-inline-size: calc(100% - 2 * var(--kp-space-sm, 0.5rem));
            padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 1rem);
            text-align: start;
        }

        .kp-datatable__busy-panel > .kp-spinner {
            --kp-spinner-size: var(--kp-busy-overlay-spinner-narrow, 1.75rem);
            grid-row: span 2;
        }

        .kp-datatable__busy-panel > .kp-datatable__busy-words {
            display: -webkit-box;
            overflow: hidden;
            -webkit-box-orient: vertical;
            -webkit-line-clamp: 3;
            line-clamp: 3;
        }
    }

    /* Choosing which columns show [#columns]. The menu hangs under its
 * button, and above it where the window has no room below, placed as the
 * "+ Add filter" menu is (fixed, see there): opened at the bottom of a
 * 720px window it ran 212 to 288px past the edge in all 22 themes. */
    .kp-datatable__columns {
        position: fixed;
        position-try-fallbacks: flip-block;
    }

    /* A checkbox and its column on one line in the menu. */
    .kp-datatable__column-option {
        display: flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* Rows that open: the detail row wraps its prose rather than widening
 * the table, and the toggle keeps its width when its glyph turns
 * [#expansion]. */
    /* The whole row opens it, so the whole row says so [Kenny, 2026-10-02]. */
    .kp-datatable tbody > tr:has(> td [data-kp-row-toggle]) {
        cursor: pointer;
    }

    .kp-datatable__expand {
        min-inline-size: var(--kp-datatable-expand-size, 2em);
    }

    .kp-table tr.kp-datatable__detail > td {
        padding-block: var(--kp-datatable-detail-padding-block, 0.75rem 1rem);
        white-space: normal;
    }

    /* A group row that folds a run of rows [J2, scope-143]: the whole row
 * folds, so the whole row says so; it reads as a heading over its rows,
 * on the ground a row takes under the pointer, and its toggle sits before
 * its name. */
    .kp-datatable tbody > tr[data-kp-row-group] {
        cursor: pointer;
    }

    .kp-table tbody > tr[data-kp-row-group] > :is(th, td) {
        background-color: var(--kp-datatable-group-ground, var(--muted));
        font-weight: var(--kp-datatable-group-weight, 600);
        text-align: start;
        white-space: normal;
    }

    .kp-datatable__group-toggle {
        margin-inline-end: var(--kp-space-xs, 0.25rem);
    }

    /* In the card layout a group row is the heading over its cards, not a
 * card of its own: the whole width, no frame [J2]. */
    @container kp-table (max-width: 40rem) {
        .kp-datatable[data-kp-cards] .kp-table tr[data-kp-row-group] {
            padding: 0;
            border: 0;
            background: none;
        }

        .kp-datatable[data-kp-cards] .kp-table tr[data-kp-row-group] > :is(th, td) {
            display: block;
            border-radius: var(--radius, 0.5rem);
        }
    }

    /* A first column that stays [#sticky]. The script marks the cells of the
 * fixed columns and writes the offset each sticks at; the ground is opaque
 * so the scrolled cells do not show through, and the last fixed column
 * draws a hairline. The header's cells stay above the body's, and the
 * corner above both. */
    .kp-datatable[data-kp-fixed-columns] .kp-table :is(th, td)[data-kp-fixed] {
        position: sticky;
        inset-inline-start: var(--kp-datatable-fixed-start, 0);
        z-index: 1;
        background-color: var(--kp-datatable-fixed-ground, var(--kp-datatable-head-ground, var(--background)));
    }

    .kp-datatable[data-kp-fixed-columns] .kp-table :is(th, td)[data-kp-fixed='last'] {
        box-shadow: inset calc(-1 * var(--kp-datatable-fixed-rule-width, 1px)) 0 var(--kp-datatable-fixed-rule, var(--border-strong));
    }

    .kp-datatable[data-kp-fixed-columns][data-kp-max-height] .kp-table thead th {
        z-index: 2;
    }

    /* The last fixed header cell keeps its hairline and, while the box is
 * scrolled, the reach above the sticky header [fix-32, scope-90]. At rest
 * the hairline rule above draws it alone. */
    .kp-datatable[data-kp-fixed-columns][data-kp-max-height][data-kp-scrolled] .kp-table thead th[data-kp-fixed='last'] {
        box-shadow:
            inset calc(-1 * var(--kp-datatable-fixed-rule-width, 1px)) 0 var(--kp-datatable-fixed-rule, var(--border-strong)),
            var(--kp-datatable-head-reach);
    }

    .kp-datatable[data-kp-fixed-columns] .kp-table thead th[data-kp-fixed] {
        z-index: 3;
    }

    /* Editing a value in its cell [#inline-edit]: an editable value is a
 * button with a dashed underline and a pencil, so it can be told apart
 * before a pointer finds it; the editor is the package's own field, in
 * the compact density so the row does not jump. */
    .kp-datatable__edit {
        display: inline-flex;
        align-items: center;
        gap: 0.35rem;
        margin: 0;
        padding: 0;
        border: 0;
        border-block-end: 1px dashed var(--kp-datatable-edit-rule, var(--border-strong));
        border-radius: 0;
        background: none;
        color: inherit;
        font: inherit;
        letter-spacing: inherit;
        text-transform: inherit;
        text-align: inherit;
        cursor: pointer;
    }

    /* The pencil is paint, not text: it stays out of the value a search, a
 * sort or an export reads, and out of what a screen reader says (the
 * second declaration, for a browser that reads alternative text). */
    .kp-datatable__edit::after {
        content: var(--kp-datatable-edit-glyph, '✎');
        content: var(--kp-datatable-edit-glyph, '✎') / '';
    }

    .kp-datatable__editor {
        display: grid;
        gap: var(--kp-space-xs, 0.25rem);
        min-inline-size: var(--kp-datatable-editor-min, 8rem);
    }

    .kp-datatable__editor > .kp-field__input {
        inline-size: 100%;
    }

    /* Moving through cells with the arrow keys [#keyboard]: the two-part
 * ring drawn inside the cell, so the next cell's ground and the scroll box
 * cannot cut it away. */
    .kp-table[role='grid'] :is(th, td):focus-visible {
        outline-offset: calc(-1 * var(--focus-ring-width, 2px));
        box-shadow: inset 0 0 0 calc(var(--focus-ring-width, 2px) + var(--kp-focus-ring-inner-width, 2px)) var(--focus-ring);
    }

    .kp-datatable {
        display: flex;
        flex-direction: column;
        gap: 0.75rem;

        /* The fallback container for a data table whose markup has no
     * `.kp-table-wrap` [TH96, AR24]: without it, converting the card
     * layout from a media query to a container query would have taken
     * the cards away from every consumer who left the wrapper out, which
     * is a repair that breaks the thing it repairs. Where both exist the
     * wrapper is nearer and wins, and the two measure the same width in
     * the shape this package draws. */
        container: kp-table / inline-size;
        /* The same floor as .kp-table-wrap; see there for why [R3-CQ]. */
        min-inline-size: var(--kp-table-wrap-min, auto);
    }

    .kp-datatable__bar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.5rem;
        /* An inset of its own [gap-11, Kenny 2026-09-13, seen in nostromo].
     * Twenty registers frame the data table and draw its bars as strips,
     * and with no padding the row count sat on the frame's left edge and
     * the pager on its bottom edge. The bar carries the inset rather than
     * the table, so the rows still run to the frame.
     * Two knobs rather than one shorthand [Kenny's note of 2026-09-13, "Bars
     * inset" chosen in research/datatable/demo.html]: the inset is the
     * default, and a theme or a consumer moves the inline and the block half
     * on their own. */
        padding-block: var(--kp-datatable-bar-padding-block, var(--kp-space-sm, 0.5rem));
        padding-inline: var(--kp-datatable-bar-padding-inline, var(--kp-space-md, 0.75rem));
    }

    .kp-datatable__search {
        box-sizing: border-box;
        flex: 1 1 12rem;
        /* The spacing steps rather than their comfortable values [gap-13]:
     * the same 0.5rem and 0.75rem in the default density, and the density
     * switch reaches the search box as it reaches the rows. */
        padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        font: inherit;
        inline-size: 100%;
        min-inline-size: 0;
        box-sizing: border-box;
    }

    /* A sortable header is a control, so it says so on hover and carries its
 * state in an arrow that is not the only carrier — aria-sort is. */
    .kp-table th[data-kp-sort] {
        cursor: pointer;
        user-select: none;
    }

    .kp-table th[data-kp-sort]::after {
        content: var(--kp-glyph-sortable, '↕');
        margin-inline-start: 0.375rem;
        opacity: 0.35;
    }

    .kp-table th[aria-sort='ascending']::after {
        content: var(--kp-glyph-ascending, '↑');
        opacity: 1;
    }

    .kp-table th[aria-sort='descending']::after {
        content: var(--kp-glyph-descending, '↓');
        opacity: 1;
    }

    /* A column that cannot be sorted now [kpadopt4] (`aria-disabled="true"`): no pointer, no sortable mark; a sort it
 * already carries keeps its arrow. */
    .kp-table th[data-kp-sort][aria-disabled='true'] {
        cursor: default;
    }

    .kp-table th[data-kp-sort][aria-disabled='true']:not([aria-sort='ascending'], [aria-sort='descending'])::after {
        content: none;
    }

    .kp-datatable__status {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-datatable__pager {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.5rem;
    }

    .kp-datatable__page {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* Narrow: a row becomes a card [TH37, TH96, DI11].
 *
 * The alternative every table reaches for is a horizontal scrollbar, and
 * SC 1.4.10 is about not making a reader drag a page sideways to finish a
 * sentence. The header text is carried into each cell through a data
 * attribute the consumer writes, because a cell without its column name
 * is a value with no question attached.
 *
 * Two things changed in 3.2.0 [TH96]. The width that decides is the
 * width of the TABLE'S OWN CONTAINER rather than the window's: a table
 * in a 400 px column on a 1280 px page was told it had 1280 px and kept
 * a shape that did not fit. And the plain `.kp-table` can do it too, by
 * asking for it — `data-kp-cards` on the table, `data-label` on the
 * cells, which is what components/table.jsx writes for the React
 * channel. Opt-in rather than automatic, because every plain table that
 * already ships would otherwise change shape in a minor release [S20].
 *
 * The container is `.kp-table-wrap`, and `.kp-datatable` as well for the
 * markup that has no wrapper — the nearest one wins, and in the shape
 * this package draws the two are the same width [AR24]. */
    @container kp-table (max-width: 40rem) {
        /* 40rem is a contract value [TH26]: a container query can no more
     * read a custom property than a media query can, so this number is
     * repeated in docs/USER_GUIDE.md rather than exposed as a knob. It is
     * the same number as the one this block used as a media query up to
     * 3.1.1, so no table changes shape at a width it did not before. */
        /* The headers are the sort control and they are hidden, so the
     * control that stands in for them shows [gap-13]. */
        .kp-datatable[data-kp-cards] > .kp-datatable__card-sort {
            display: flex;
        }

        /* A card has no columns to keep in place. */
        .kp-datatable[data-kp-cards] .kp-table :is(th, td)[data-kp-fixed] {
            position: static;
            box-shadow: none;
        }

        .kp-datatable[data-kp-cards] .kp-table thead,
        .kp-table[data-kp-cards] thead {
            position: absolute;
            width: 1px;
            height: 1px;
            overflow: hidden;
            clip-path: inset(50%);
        }

        .kp-datatable[data-kp-cards] .kp-table,
        .kp-datatable[data-kp-cards] .kp-table tbody,
        .kp-datatable[data-kp-cards] .kp-table tr,
        .kp-datatable[data-kp-cards] .kp-table td,
        .kp-table[data-kp-cards],
        .kp-table[data-kp-cards] tbody,
        .kp-table[data-kp-cards] tr,
        .kp-table[data-kp-cards] td {
            display: block;
            width: auto;
        }

        /* The caption is a table part; with the table laid out as blocks
     * it has no table to sit above, so it becomes one too. */
        .kp-datatable[data-kp-cards] .kp-table caption,
        .kp-table[data-kp-cards] caption {
            display: block;
        }

        .kp-datatable[data-kp-cards] .kp-table tr,
        .kp-table[data-kp-cards] tr {
            margin-block-end: 0.75rem;
            padding: 0.5rem;
            border: 1px solid var(--border);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
        }

        .kp-datatable[data-kp-cards] .kp-table td,
        .kp-table[data-kp-cards] td {
            display: flex;
            /* A card's line is a block, where a block size is a height and
         * not a floor: it sizes to its value, with the padding it had
         * before the row height was fixed [scope-80]. */
            block-size: auto;
            padding-block: var(--kp-table-cell-block, var(--kp-space-sm, 0.5rem));
            gap: 0.75rem;
            justify-content: space-between;
            border: 0;
        }

        .kp-datatable[data-kp-cards] .kp-table td::before,
        .kp-table[data-kp-cards] td::before {
            content: attr(data-label);
            color: var(--muted-foreground);
            font-weight: 500;
        }

        /* The low-priority column, at the same width as the cards [TH96].
     * Header and cells together: hiding the header alone leaves a column
     * of values with nothing saying what they are, which is worse than
     * either keeping it or dropping it. A separate threshold would be a
     * second layout to reason about, so there is only one. */
        .kp-table .kp-col-low {
            display: none;
        }
    }

    /* --- Forms [TH38] ---------------------------------------------------- */

    /* A radio group laid out in a row rather than a column. The fieldset is
 * made a flex container here: the rule used to set only the direction, on
 * an element that was never flex, so it did nothing at all [gap-11]. The
 * rendered legend stays above the row, outside the flex flow, as a
 * fieldset's legend does. */
    .kp-fieldset[data-kp-layout='inline'] {
        display: flex;
        flex-direction: row;
        flex-wrap: wrap;
        /* Not baseline: an option's baseline is its control's, and a register
     * that draws its own radio has none until the dot exists, so ticking
     * one moved the whole row by 4 to 5px (cyberpunk, dark) [scope-92]. */
        align-items: center;
        column-gap: var(--kp-space-md);
    }

    .kp-fieldset[data-kp-layout='inline'] > legend {
        flex-basis: 100%;
    }

    /* Choices as tiles [kpadopt4-rows; JobTracker's `jt-check-tile`]. The
 * same fieldset, legend and `.kp-field__option` labels as any group, with
 * `data-kp-layout="tiles"`: each option becomes a tile the whole of which
 * is the target, its box at the start, a title and a hint under it. A
 * checkbox group picks several, a radio group one; the control is the
 * native input, so the form, the keyboard (Space, the arrows of a radio
 * group) and a screen reader work as for any option. The tiles share one
 * height per row and wrap to one column on a phone; the group's invalid
 * mark is the fieldset's own outline. Knobs [KT6]: `--kp-field-tiles-min`
 * (the narrowest column, 14rem), `--kp-field-tiles-gap`,
 * `--kp-field-tile-pad`, `--kp-field-tile-radius`,
 * `--kp-field-tile-ground`, `--kp-field-tile-ground-checked` (the primary
 * at 6 % on the card) and `--kp-field-tile-edge-checked`. */
    .kp-fieldset[data-kp-layout='tiles'] {
        align-self: stretch;
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kp-field-tiles-min, 14rem)), 1fr));
        align-items: stretch;
        gap: var(--kp-field-tiles-gap, var(--kp-space-sm, 0.5rem));
    }

    .kp-fieldset[data-kp-layout='tiles'] > legend {
        margin-block-end: var(--kp-space-sm, 0.5rem);
    }

    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        box-sizing: border-box;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-content: start;
        align-items: start;
        gap: calc(var(--kp-space-xs, 0.25rem) / 2) var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        padding: var(--kp-field-tile-pad, 0.75rem 0.875rem);
        border: 1px solid var(--border);
        border-radius: var(--kp-field-tile-radius, var(--radius, 0.5rem));
        background: var(--kp-field-tile-ground, var(--card));
        color: var(--card-foreground, var(--foreground));
        cursor: pointer;
    }

    /* The box on the title's first line, centred on it. */
    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option > .kp-field__check {
        grid-row: 1;
        margin-block-start: calc((1lh - 1.15rem) / 2);
    }

    .kp-field__option-title,
    .kp-field__option-hint {
        grid-column: 2;
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    .kp-field__option-title {
        font-weight: 600;
    }

    .kp-field__option-hint {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--ring);
    }

    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        border-color: var(--kp-field-tile-edge-checked, var(--primary));
        background: var(--kp-field-tile-ground-checked, color-mix(in oklab, var(--primary) 6%, var(--card)));
        box-shadow: inset 0 0 0 1px var(--kp-field-tile-edge-checked, var(--primary));
    }

    /* The tile wears the focus ring, as the upload zone does: the box alone
     * is too small a thing to find the focus on. */
    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
    }

    /* Disabled: quieter by ground and ink, not by opacity [DI8]; the hint
     * keeps saying why. */
    .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        border-style: dashed;
        background: var(--muted);
        color: var(--muted-foreground);
        cursor: not-allowed;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
            transition:
                background-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                border-color var(--fx-duration, 150ms) var(--fx-ease, ease),
                box-shadow var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    .kp-form {
        display: flex;
        flex-direction: column;
        /* On the scale rather than a literal, so the density mode reaches
     * it [TH94, TH105]. --kp-space-lg is 1rem, which is what this was. */
        gap: var(--kp-form-gap, var(--kp-space-lg));
    }

    /* The summary is a landmark, not a banner: it takes focus when a submit
 * fails, so it needs a boundary that reads at 3:1 and a colour that says
 * something is wrong without being the only carrier — the heading says it
 * in words. */
    .kp-form__summary {
        padding: 0.75rem 1rem;
        border: 1px solid var(--destructive);
        border-radius: var(--radius, 0.5rem);
        background: hsl(from var(--destructive) h s l / 0.08);
    }

    .kp-form__summary:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring);
        outline-offset: 2px;
    }

    .kp-form__summary-title {
        margin: 0 0 0.375rem;
        font-weight: 600;
    }

    .kp-form__summary ul {
        margin: 0;
        padding-inline-start: 1.25rem;
    }

    /* A required marking that is not only an asterisk: the word is there for
 * anyone who never learned what the star means, and for a screen reader
 * that reads it as "star". */
    .kp-field__required {
        margin-inline-start: 0.25rem;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 400;
    }

    .kp-field__required::before {
        content: var(--kp-glyph-required, '\002A\00a0');
        color: var(--destructive);
    }

    /* --- The small patterns [TH50, TH51, TH52, TH53, TH54] --------------- */

    /* An empty state that knows which emptiness it is. "Nog geen items" and
 * "niets gevonden" are different messages, and offering "maak er een" to
 * someone who just typed a filter is noise. */
    .kp-empty__title {
        margin: 0 0 0.25rem;
        color: var(--foreground);
        font-weight: 600;
    }

    .kp-empty__body {
        margin: 0 0 0.75rem;
    }

    /* A drawing at the top of an empty state [kpadopt4] (`data-kp-art`, js/art.js): a picture only, the words carry the
 * meaning. Every theme draws its own set and its register shows it; a theme without one shows none, so the drawing is
 * hidden here. Knobs [KT6]: `--kp-art-size` (7.5rem wide; `data-kp-art-size` sm 5rem, lg 10rem), `--kp-art-stroke`
 * (1.5px), `--kp-art-rule` (the acting colour), `--kp-art-line` (the faint ruled lines), `--kp-art-ink`, `--kp-art-red`. */
    .kp-art {
        display: none;
        box-sizing: content-box;
        inline-size: var(--kp-art-size, 7.5rem);
        block-size: auto;
        aspect-ratio: 120 / 72;
        margin: 0 auto var(--kp-space-sm, 0.5rem);
        overflow: visible;
    }

    .kp-art > g {
        display: none;
    }

    .kp-art path {
        fill: none;
        stroke-width: var(--kp-art-stroke, 1.5px);
        stroke-linecap: square;
        stroke-linejoin: miter;
        vector-effect: non-scaling-stroke;
    }

    .kp-art__rule {
        stroke: var(--kp-art-rule, var(--primary));
    }

    .kp-art path.kp-art__rule {
        stroke-width: calc(var(--kp-art-stroke, 1.5px) + 0.5px);
    }

    .kp-art__line {
        stroke: var(--kp-art-line, var(--border-strong));
    }

    .kp-art path.kp-art__line {
        stroke-width: 1px;
    }

    .kp-art__ink {
        stroke: var(--kp-art-ink, var(--muted-foreground));
    }

    .kp-art__red {
        stroke: var(--kp-art-red, var(--destructive));
    }

    [data-kp-art-size='sm'] > .kp-art {
        --kp-art-size: 5rem;
    }

    [data-kp-art-size='lg'] > .kp-art {
        --kp-art-size: 10rem;
    }

    /* Copyable value [TH53] */
    .kp-copyable {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        /* The 3.2.0 copy of the overflow floor -- `max-inline-size: 100%`
     * here and `overflow-wrap: anywhere` on the value -- moved to the
     * shared rule above the button [AR32]. It was found the same way the
     * other four were: a 44-character key measured 344px inside a 360px
     * viewport and put the copy button at 421, hidden until the
     * documentation site stopped wrapping its examples in a scroll box. */
    }

    .kp-copyable__value {
        font-family: var(--font-mono, ui-monospace, monospace);
        min-inline-size: 0;
    }

    /* The Copy button keeps its word in one piece [r6r8-1019; almanac gap 15]: the shared overflow floor (`overflow-wrap: anywhere`)
     * lowers a flex item's minimum width to one letter, so a narrow cell squeezed "Copy" into "Co / py" while the long value
     * kept its room. The button is a short fixed word, so it neither wraps nor shrinks; the value takes what is left. */
    .kp-copyable__button {
        flex: 0 0 auto;
        white-space: nowrap;
        overflow-wrap: normal;
    }

    .kp-copyable__value {
        flex: 1 1 auto;
    }

    /* In a fact list the copyable takes its value cell and the Copy button stands at the cell's end, so the buttons of every
     * row line up in one column and the value wraps in the room beside them. */
    .kp-kv__row > dd > .kp-copyable {
        display: flex;
        flex: 1 1 100%;
        justify-content: space-between;
    }

    /* Confirmed in words on the button, not by colour: a green flash is
 * invisible to a screen reader and to anyone who looked away.
 *
 * Both states are restated in every register [gap-12]: a register paints
 * its buttons in kp.register, which beats this layer, and 19 of 22 themes
 * painted their own ghost ground over the success plate. */
    .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    /* A copy the clipboard refused says so on the button as well as in the
     * toast [gap-12]: the destructive ink and a dashed frame, so the two
     * carriers are a colour and a shape. The word stays "Copy", because
     * pressing it again is the way out [KT6]. */
    .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* Secret field [kpadopt4] -----------------------------------------------
 * `.kp-secret[data-kp-secret]` (js/patterns.js): a masked value, Reveal and
 * Copy, and one line under them for the countdown, the reason a field is off
 * or why it could not be read. The value box has the control height and the
 * row's width whatever it holds, and the line under it always keeps its
 * room, so showing, hiding, loading or failing moves nothing. A long value
 * stays on one line and scrolls inside its box (a fade at the end says there
 * is more) unless `data-kp-secret-wrap="wrap"`, which keeps
 * `data-kp-secret-lines` lines of room. Knobs [KT6]: `--kp-secret-min`
 * (16rem, the value box's least width before the buttons go under it),
 * `--kp-secret-lines` (2), `--kp-secret-drain` (the rule that runs out with
 * the countdown, `--primary`), `--kp-secret-drain-size` (2px). */
    .kp-secret {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        max-inline-size: 100%;
    }

    .kp-secret__value {
        box-sizing: border-box;
        display: block;
        flex: 1 1 var(--kp-secret-min, 16rem);
        min-inline-size: 0;
        block-size: var(--kp-control-height, 2.25rem);
        margin: 0;
        padding: 0 var(--kp-space-sm, 0.5rem);
        overflow-x: auto;
        overflow-y: hidden;
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--muted);
        color: var(--foreground);
        font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
        line-height: calc(var(--kp-control-height, 2.25rem) - 2px);
        white-space: nowrap;
        scrollbar-width: none;
    }

    .kp-secret__value.kp-masked {
        color: var(--muted-foreground);
        user-select: none;
    }

    .kp-secret[data-kp-secret-overflow] .kp-secret__value {
        mask-image: linear-gradient(to left, transparent, var(--foreground) 1.5rem);
    }

    .kp-secret[data-kp-secret-overflow] .kp-secret__value:dir(rtl) {
        mask-image: linear-gradient(to right, transparent, var(--foreground) 1.5rem);
    }

    .kp-secret[data-kp-secret-wrap='wrap'] .kp-secret__value {
        block-size: auto;
        min-block-size: calc(var(--kp-secret-lines, 2) * 1.5em + 2 * var(--kp-space-xs, 0.25rem) + 2px);
        padding-block: var(--kp-space-xs, 0.25rem);
        overflow: visible;
        line-height: 1.5;
        white-space: normal;
        overflow-wrap: anywhere;
    }

    .kp-secret__actions {
        display: flex;
        flex: none;
        gap: var(--kp-space-sm, 0.5rem);
    }

    /* The reveal button keeps the width of its longest word, so Reveal, Hide and Try again move nothing. */
    .kp-secret__reveal {
        min-inline-size: 6.5em;
    }

    .kp-secret__line {
        display: grid;
        grid-template-rows: var(--kp-secret-drain-size, 2px) auto;
        flex: 1 0 100%;
        gap: var(--kp-space-xs, 0.25rem);
        margin: 0;
        min-block-size: calc(var(--kp-secret-drain-size, 2px) + var(--kp-space-xs, 0.25rem) + 1.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        line-height: 1.25rem;
    }

    .kp-secret__words {
        grid-row: 2;
        display: flex;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        min-inline-size: 0;
        overflow-wrap: anywhere;
        font-variant-numeric: tabular-nums;
    }

    .kp-secret__spinner {
        --kp-spinner-size: 0.875rem;
        flex: none;
    }

    .kp-secret__drain {
        grid-row: 1;
        display: block;
        block-size: var(--kp-secret-drain-size, 2px);
        background: var(--kp-secret-drain, var(--primary));
        transform-origin: 0 50%;
        visibility: hidden;
    }

    .kp-secret__drain:dir(rtl) {
        transform-origin: 100% 50%;
    }

    /* Why it could not be read: an entry ruled off along its start edge, in the page's ink [fix-70]. */
    .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        padding-inline-start: var(--kp-space-sm, 0.5rem);
        border-inline-start: 3px solid var(--destructive);
        color: var(--foreground);
    }

    .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        border-style: dashed;
        background: transparent;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-secret:not([data-kp-secret-ttl='0'], [data-kp-secret-reveal-on='hold'])[data-kp-secret-state='shown'] .kp-secret__drain {
            visibility: visible;
            animation: kp-secret-drain var(--kp-secret-ttl, 30s) linear forwards;
        }

        .kp-secret[data-kp-secret-paused] .kp-secret__drain {
            animation-play-state: paused;
        }
    }

    @keyframes kp-secret-drain {
        from {
            scale: 1 1;
        }

        to {
            scale: 0 1;
        }
    }

    /* Status parts [TH52] */
    .kp-health {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        font-weight: 500;
    }

    /* The dot is the second carrier, never the only one: the word beside it
 * is what makes this readable to someone who cannot tell the colours
 * apart [DI4]. */
    .kp-health__dot {
        width: 0.625rem;
        height: 0.625rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--kp-radius-pill, 999px);
        background: var(--muted);
    }

    .kp-health[data-state='ok'] .kp-health__dot {
        background: var(--success);
    }

    .kp-health[data-state='warn'] .kp-health__dot {
        background: var(--warning);
    }

    .kp-health[data-state='down'] .kp-health__dot {
        background: var(--destructive);
    }

    .kp-timeline {
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-timeline__item {
        display: grid;
        grid-template-columns: 0.75rem 1fr;
        gap: 0.75rem;
        padding-block: 0.5rem;
    }

    /* The rule down the left is drawn on the marker, so a one-item timeline
 * does not get a line hanging under it. */
    .kp-timeline__item:not(:last-child) .kp-timeline__marker {
        background-image: linear-gradient(var(--border), var(--border));
        background-repeat: no-repeat;
        background-position: 50% 0.75rem;
        background-size: 1px 100%;
    }

    .kp-timeline__marker {
        width: 0.75rem;
        height: 0.75rem;
        margin-block-start: 0.25rem;
        border: 2px solid var(--primary);
        border-radius: var(--kp-radius-pill, 999px);
    }

    .kp-timeline__when {
        display: block;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* --- Step list: the steps of one run, live ----------------------------
 * The list of a process in flight (an update, an import, a deploy): each
 * step is waiting, running, done, failed or skipped, and the page changes it
 * as the run goes. Not a timeline (that is what happened, in the past, with
 * a time, and never changes) and not a wizard (that is where a person is in
 * a form, and they move it). js/steplist.js keeps the marks, the words for a
 * screen reader and the live announcement in step with `data-state`.
 *
 * Every state is a shape and a word as well as a colour [DI4]: a hollow ring
 * (waiting), the theme's spinner (running), a filled disc with a tick (done),
 * a filled disc with a cross (failed), a dashed ring with a dash (skipped).
 * The mark has one fixed box, so a step changing state moves nothing, and the
 * time column has a floor, so a time arriving does not rewrap the title.
 * Knobs [KT6]: `--kp-steplist-mark` (the mark's box, 1.375rem),
 * `--kp-steplist-time` (the time column's floor, 3.5rem),
 * `--kp-steplist-mark-radius`, `--kp-steplist-gap`, and the glyphs
 * `--kp-glyph-done` (falls back to `--kp-glyph-check`), `--kp-glyph-failed`,
 * `--kp-glyph-skipped`. */
    .kp-steplist {
        display: grid;
        gap: var(--kp-steplist-gap, var(--kp-space-sm, 0.5rem));
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-steplist__item {
        display: grid;
        grid-template-columns: var(--kp-steplist-mark, 1.375rem) minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
        padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    .kp-steplist__mark {
        box-sizing: border-box;
        display: grid;
        place-items: center;
        inline-size: var(--kp-steplist-mark, 1.375rem);
        block-size: var(--kp-steplist-mark, 1.375rem);
        border: 2px solid var(--border-strong);
        border-radius: var(--kp-steplist-mark-radius, var(--kp-radius-pill, 999px));
        font-size: 0.6875rem;
        font-weight: 700;
        line-height: 1;
    }

    .kp-steplist__mark > .kp-spinner {
        --kp-spinner-size: var(--kp-steplist-mark, 1.375rem);
    }

    .kp-steplist__body {
        display: grid;
        min-inline-size: 0;
        gap: 0.125rem;
    }

    .kp-steplist__title {
        overflow-wrap: anywhere;
    }

    .kp-steplist__note {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: anywhere;
    }

    .kp-steplist__time {
        min-inline-size: var(--kp-steplist-time, 3.5rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
        text-align: end;
    }

    /* The state's word, for a screen reader: the mark is a picture. */
    .kp-steplist__state {
        position: absolute;
        inline-size: 1px;
        block-size: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        white-space: nowrap;
        border: 0;
        clip-path: inset(50%);
    }

    .kp-steplist__item[data-state='running'] {
        border-color: var(--primary);
    }

    .kp-steplist__item[data-state='running'] .kp-steplist__title {
        font-weight: 600;
    }

    .kp-steplist__item[data-state='running'] .kp-steplist__mark {
        border-color: transparent;
    }

    .kp-steplist__item[data-state='done'] .kp-steplist__mark {
        border-color: var(--success);
        background: var(--success);
        color: var(--success-foreground);
    }

    .kp-steplist__item[data-state='done'] .kp-steplist__mark::after {
        content: var(--kp-glyph-done, var(--kp-glyph-check, '✓'));
    }

    .kp-steplist__item[data-state='failed'] {
        border-color: var(--destructive);
    }

    .kp-steplist__item[data-state='failed'] .kp-steplist__mark {
        border-color: var(--destructive);
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    .kp-steplist__item[data-state='failed'] .kp-steplist__mark::after {
        content: var(--kp-glyph-failed, '✕');
    }

    /* Skipped is quieter, by ink and by a dashed ring, not by opacity: the
 * words keep their contrast. */
    .kp-steplist__item[data-state='skipped'] {
        color: var(--muted-foreground);
    }

    .kp-steplist__item[data-state='skipped'] .kp-steplist__mark {
        border-style: dashed;
        color: var(--muted-foreground);
    }

    .kp-steplist__item[data-state='skipped'] .kp-steplist__mark::after {
        content: var(--kp-glyph-skipped, '–');
    }

    /* The step a process stands at now, neither running nor done [kpadopt4]: a ring with a dot, the title in weight. */
    .kp-steplist__item[data-state='current'] {
        border-color: var(--kp-step-tone, var(--primary));
    }

    .kp-steplist__item[data-state='current'] .kp-steplist__title {
        font-weight: 600;
    }

    .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        border-color: var(--kp-step-tone, var(--primary));
        background: radial-gradient(circle, var(--kp-step-tone, var(--primary)) 0 34%, transparent 38%);
    }

    .kp-steplist__item[data-kp-tone='1'] {
        --kp-step-tone: var(--chart-1);
    }

    .kp-steplist__item[data-kp-tone='2'] {
        --kp-step-tone: var(--chart-2);
    }

    .kp-steplist__item[data-kp-tone='3'] {
        --kp-step-tone: var(--chart-3);
    }

    .kp-steplist__item[data-kp-tone='4'] {
        --kp-step-tone: var(--chart-4);
    }

    .kp-steplist__item[data-kp-tone='5'] {
        --kp-step-tone: var(--chart-5);
    }

    /* A step with its own colour (`data-kp-tone` 1 to 5, or any value with `--kp-step-tone` set by the page) wears it when
 * reached; the tick is drawn in the card's ground on it. */
    .kp-steplist__item[data-kp-tone][data-state='done'] .kp-steplist__mark {
        border-color: var(--kp-step-tone);
        background: var(--kp-step-tone);
        color: var(--card);
    }

    /* A journey [kpadopt4] (`.kp-steplist--journey`): the steps side by side on one path, a mark over each name, the date it
 * was reached under it, joined by a rule that is drawn in the step's colour once the step is reached. Under 30rem of its
 * own width the path turns to a column, the rule down the marks. Every step has the same width, so a long name wraps
 * under its own mark and never reaches the next. Knob: `--kp-journey-rule` (2px). */
    .kp-steplist--journey {
        container: kp-journey / inline-size;
        display: flex;
        flex-wrap: wrap;
        gap: 0;
    }

    .kp-steplist--journey > .kp-steplist__item {
        position: relative;
        flex: 1 1 0;
        min-inline-size: 0;
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: auto auto auto;
        justify-items: center;
        align-content: start;
        gap: var(--kp-space-xs, 0.25rem);
        padding: 0 var(--kp-space-xs, 0.25rem);
        border: 0;
        border-radius: 0;
        background: transparent;
        text-align: center;
    }

    .kp-steplist--journey .kp-steplist__mark {
        position: relative;
        z-index: 1;
        background-color: var(--card);
    }

    .kp-steplist--journey .kp-steplist__body {
        justify-items: center;
    }

    .kp-steplist--journey .kp-steplist__title {
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: break-word;
        hyphens: auto;
    }

    .kp-steplist--journey .kp-steplist__time {
        min-inline-size: 0;
        text-align: center;
    }

    .kp-steplist--journey .kp-steplist__time:empty {
        display: none;
    }

    /* The rule into a step, from the previous mark to this one. */
    .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
        content: '';
        position: absolute;
        inset-block-start: calc(var(--kp-steplist-mark, 1.375rem) / 2 - var(--kp-journey-rule, 2px) / 2);
        inset-inline: calc(-50% + var(--kp-steplist-mark, 1.375rem) / 2) calc(50% + var(--kp-steplist-mark, 1.375rem) / 2);
        block-size: var(--kp-journey-rule, 2px);
        background: var(--border-strong);
    }

    .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: var(--kp-step-tone, var(--success));
    }

    .kp-steplist--journey > .kp-steplist__item[data-state='failed']::before {
        background: repeating-linear-gradient(90deg, var(--destructive) 0 0.375rem, transparent 0.375rem 0.625rem);
    }

    .kp-steplist--journey > .kp-steplist__item:not([data-state='current']) .kp-steplist__title {
        font-weight: 400;
    }

    .kp-steplist--journey > .kp-steplist__item[data-state='current'] .kp-steplist__title {
        font-weight: 600;
    }

    @container kp-journey (max-width: 30rem) {
        .kp-steplist--journey > .kp-steplist__item {
            flex-basis: 100%;
            grid-template-columns: var(--kp-steplist-mark, 1.375rem) minmax(0, 1fr) auto;
            grid-template-rows: auto;
            justify-items: stretch;
            align-items: start;
            gap: var(--kp-space-md, 0.75rem);
            padding: 0 0 var(--kp-space-md, 0.75rem);
            text-align: start;
        }

        .kp-steplist--journey .kp-steplist__body {
            justify-items: start;
        }

        .kp-steplist--journey .kp-steplist__time {
            text-align: end;
        }

        /* Down the column the rule leaves each mark for the next one, in this step's colour once the next is reached. */
        .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
            content: none;
        }

        .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            content: '';
            position: absolute;
            inset-block: var(--kp-steplist-mark, 1.375rem) 0;
            inset-inline-start: calc(var(--kp-steplist-mark, 1.375rem) / 2 - var(--kp-journey-rule, 2px) / 2);
            inline-size: var(--kp-journey-rule, 2px);
            background: var(--border-strong);
        }

        .kp-steplist--journey > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: var(--kp-step-tone, var(--success));
        }

        .kp-steplist--journey > .kp-steplist__item:has(+ .kp-steplist__item[data-state='failed'])::after {
            background: repeating-linear-gradient(180deg, var(--destructive) 0 0.25rem, transparent 0.25rem 0.4375rem);
        }
    }

    /* --- Week agenda: seven days, the items of the week placed in time -----
 * `section.kp-week[data-kp-week]` (js/week.js). A grid of an hour axis and
 * one column per day; every item is a pill at its time of day. The column's
 * height is fixed (--kp-week-height), so nothing moves when items arrive,
 * when a day is crowded or when the week is loading: what does not fit is
 * folded into a `+N` menu button at the end of the stack. Below the agenda's
 * own width of 40rem (a container query, so it follows the pane and not the
 * window) the columns become rows: the day on the left, its items in time
 * order on the right, every item shown.
 *
 * Every state is a shape or a word as well as a colour [DI4]: the day that
 * is today wears the word and a filled number; the next run a ring; an item
 * that is off or skipped is struck through and quieter by ink, not by
 * opacity; the host's own round is dashed and is not a button.
 * Knobs [KT6]: `--kp-week-height` (15rem, the day column), `--kp-week-pill`
 * (1.5rem, one pill's height), `--kp-week-axis` (3.25rem, the hour labels'
 * column), `--kp-week-day-label` (5.5rem, the day's column in the list),
 * `--kp-week-pill-radius`, `--kp-week-now` (the line for now, --destructive),
 * `--kp-week-today` (the today plate, --primary), `--kp-week-gap`. */
    .kp-week {
        container: kp-week / inline-size;
        display: grid;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
    }

    /* The range's title on the start side, the steps on the end side, on one line; the title in the theme's display
     * face, as a page's section title. The steps are the package's segmented track (`.kp-segmented.kp-week__steps`,
     * dressed by every register) used as a group of actions: nothing in it is chosen, so no plate; a chevron back,
     * Today, a chevron on. Today is `aria-disabled` while the range already starts today.
     * Knobs: --kp-week-title-size (1.25rem), --kp-week-step-pad (the chevrons' inline padding, --kp-space-sm). */
    .kp-week__nav {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 1rem);
        margin-block-end: var(--kp-space-sm, 0.5rem);
    }

    .kp-week__title {
        flex: 1 1 auto;
        min-inline-size: 0;
        margin: 0;
        font-family: var(--theme-font-display, inherit);
        font-size: var(--kp-week-title-size, 1.25rem);
        line-height: 1.25;
        font-variant-numeric: tabular-nums;
        text-align: start;
    }

    /* Two classes: the segmented track is written later in this layer and gives its items equal columns. */
    .kp-segmented.kp-week__steps {
        flex: none;
        grid-auto-columns: auto;
    }

    .kp-segmented__item.kp-week__step--icon {
        padding-inline: var(--kp-week-step-pad, var(--kp-space-sm, 0.5rem));
    }

    .kp-week__chevron {
        inline-size: 1rem;
        block-size: 1rem;
        fill: none;
        stroke: currentColor;
        stroke-width: 2;
        stroke-linecap: round;
        stroke-linejoin: round;
    }

    .kp-week__steps:dir(rtl) .kp-week__chevron {
        scale: -1 1;
    }

    .kp-week__frame {
        position: relative;
    }

    .kp-week__grid {
        --kp-week-mode: grid;
        display: grid;
        grid-template-columns: var(--kp-week-axis, 3.25rem) repeat(var(--kp-week-days, 7), minmax(0, 1fr));
        grid-template-rows: auto var(--kp-week-height, 15rem);
        padding-block-end: 0.5rem;
        min-inline-size: 0;
    }

    .kp-week__day {
        display: contents;
    }

    .kp-week__head {
        grid-row: 1;
        grid-column: calc(var(--kp-week-i, 0) + 2);
        display: grid;
        grid-template-columns: auto auto;
        justify-content: start;
        align-content: end;
        align-items: baseline;
        column-gap: 0.375rem;
        padding: 0 var(--kp-space-sm, 0.5rem) 0.75rem;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    .kp-week__num {
        font-variant-numeric: tabular-nums;
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 600;
    }

    .kp-week__date {
        display: none;
    }

    /* The mark's room is always there, so today moving from one day to the
 * next changes no height. */
    .kp-week__today {
        grid-column: 1 / -1;
        visibility: hidden;
        font-size: 0.625rem;
        line-height: 1;
    }

    .kp-week__day[data-kp-today] .kp-week__head {
        color: var(--foreground);
        font-weight: 600;
    }

    .kp-week__day[data-kp-today] .kp-week__today {
        visibility: visible;
        color: var(--kp-week-today, var(--primary));
    }

    .kp-week__day[data-kp-today] .kp-week__num {
        color: var(--kp-week-today, var(--primary));
    }

    .kp-week__axis {
        grid-row: 2;
        grid-column: 1;
        position: relative;
    }

    .kp-week__axis > span {
        position: absolute;
        inset-inline-end: var(--kp-space-sm, 0.5rem);
        inset-block-start: calc(var(--kp-week-at, 0) * 100%);
        translate: 0 -50%;
        color: var(--muted-foreground);
        font-size: 0.6875rem;
        font-variant-numeric: tabular-nums;
        line-height: 1;
    }

    .kp-week__col {
        grid-row: 2;
        grid-column: calc(var(--kp-week-i, 0) + 2);
        position: relative;
        min-inline-size: 0;
        border-inline-start: 1px solid var(--border);
        border-block-end: 1px solid var(--border);
        background-image: linear-gradient(to bottom, var(--border) 1px, transparent 1px);
        background-size: 100% 25%;
        background-repeat: no-repeat repeat;
    }

    .kp-week__day[data-kp-today] .kp-week__col {
        background-color: color-mix(in oklab, var(--kp-week-today, var(--primary)) 6%, transparent);
    }

    .kp-week__pill {
        --kp-week-ink: var(--chart-1);
        box-sizing: border-box;
        position: absolute;
        inset-inline: 0.25rem;
        inset-block-start: var(--kp-week-top, 0);
        display: flex;
        align-items: center;
        gap: 0.25rem;
        block-size: var(--kp-week-pill, 1.5rem);
        margin: 0;
        padding: 0 0.375rem;
        overflow: hidden;
        border: 1px solid color-mix(in oklab, var(--kp-week-ink) 45%, var(--border));
        border-radius: var(--kp-week-pill-radius, var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2)));
        background: color-mix(in oklab, var(--kp-week-ink) 14%, var(--card));
        color: var(--foreground);
        font: inherit;
        font-size: var(--kp-text-xs, 0.75rem);
        line-height: 1;
        text-align: start;
        white-space: nowrap;
        cursor: pointer;
    }

    .kp-week__pill[data-kp-series='2'],
    .kp-week__swatch[data-kp-series='2'] {
        --kp-week-ink: var(--chart-2);
    }

    .kp-week__pill[data-kp-series='3'],
    .kp-week__swatch[data-kp-series='3'] {
        --kp-week-ink: var(--chart-3);
    }

    .kp-week__pill[data-kp-series='4'],
    .kp-week__swatch[data-kp-series='4'] {
        --kp-week-ink: var(--chart-4);
    }

    .kp-week__pill[data-kp-series='5'],
    .kp-week__swatch[data-kp-series='5'] {
        --kp-week-ink: var(--chart-5);
    }

    .kp-week__time {
        flex: none;
        font-variant-numeric: tabular-nums;
        font-weight: 600;
    }

    .kp-week__label {
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    /* align-pkg-1019:week:start
     * The label cell fills the pill after the time, so the cells of one role end on one edge (the pill's inner edge)
     * instead of wherever each label's words end (15 px apart at 390 px in state-plates week-states). */
    .kp-week__pill > .kp-week__label {
        flex: 1 1 0;
    }
    /* align-pkg-1019:week:end */

    .kp-week__pill:is(button):hover {
        box-shadow: 0 0 0 1px var(--foreground);
    }

    .kp-week__pill[data-kp-state='next'] {
        box-shadow: 0 0 0 2px var(--ring);
    }

    .kp-week__pill[data-kp-state='next']:hover {
        box-shadow:
            0 0 0 2px var(--ring),
            0 0 0 3px var(--foreground);
    }

    /* Off and skipped: quieter by ink and a strike, so the words keep their contrast. */
    .kp-week__pill:is([data-kp-state='off'], [data-kp-state='skipped']) {
        background: transparent;
        color: var(--muted-foreground);
        text-decoration: line-through;
    }

    .kp-week__pill[data-kp-state='reference'] {
        background: transparent;
        border-style: dashed;
        border-color: var(--border-strong);
        color: var(--muted-foreground);
        cursor: default;
    }

    .kp-week__pill[data-kp-past]:not([data-kp-state='next']) .kp-week__label {
        color: var(--muted-foreground);
    }

    .kp-week .kp-week__pill--more {
        position: static;
        inset: auto;
        justify-content: center;
        inline-size: 100%;
        border-style: solid;
        border-color: var(--border-strong);
        background: var(--card);
        font-weight: 600;
        font-variant-numeric: tabular-nums;
    }

    .kp-week .kp-week__more {
        position: absolute;
        display: block;
        inset-inline: 0.25rem;
        inset-block-start: var(--kp-week-top, 0);
        block-size: var(--kp-week-pill, 1.5rem);
    }

    .kp-week__more[hidden] {
        display: none;
    }

    .kp-week__now {
        position: absolute;
        inset-inline: 0;
        inset-block-start: calc(var(--kp-week-at, 0) * 100%);
        z-index: 2;
        border-block-start: 2px solid var(--kp-week-now, var(--destructive));
        pointer-events: none;
    }

    .kp-week__now[hidden] {
        display: none;
    }

    .kp-week__now::before {
        content: '';
        position: absolute;
        inset-inline-start: -4px;
        inset-block-start: -5px;
        inline-size: 8px;
        block-size: 8px;
        border-radius: 50%;
        background: var(--kp-week-now, var(--destructive));
    }

    /* Loading is the data table's own loading picture [Kenny, 2026-10-16: "zoals bij table waarbij de hele table het
 * laadicoon centraal krijgt"]: js/week.js puts the busy table's layer and panel (`.kp-datatable__busy-overlay` >
 * `.kp-datatable__busy-panel`, the theme's spinner and the words) centred over the days' columns, which stay empty
 * and steady under it. The days hold nothing to dim, so the layer draws no veil: the grid's rules read the same
 * while it loads and once it has loaded. */
    .kp-week__busy {
        --kp-busy-overlay-veil: 0%;
        /* In rows the layer is only the items' column wide: the panel keeps a margin from its edges there. */
        padding-inline: var(--kp-space-sm, 0.5rem);
    }

    .kp-week[data-kp-state='loading'] .kp-week__now {
        display: none;
    }

    /* The sentence of an empty, loading or failed week sits over the grid:
 * it takes no room, so nothing moves when it comes and goes. */
    .kp-week__state {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        margin: 0;
        padding: var(--kp-space-md, 0.75rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        text-align: center;
        pointer-events: none;
    }

    .kp-week__state-words {
        max-inline-size: 36rem;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-week-state-ground, var(--card));
    }

    .kp-week__state:empty {
        display: none;
    }

    /* While the week loads, the busy panel says so; the sentence is still read out (role="status") but drawn nowhere, so
     * no second plate stands beside the panel (Kenny, 2026-10-16: the words alone in the middle were not enough). */
    .kp-week__state[data-kp-state='loading'] {
        inset: auto;
        inline-size: 1px;
        block-size: 1px;
        padding: 0;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
    }

    .kp-week__state[data-kp-state='error'] {
        color: var(--destructive);
    }

    .kp-week__legend {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        margin: 0;
        padding: 0;
        list-style: none;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-week__legend[hidden] {
        display: none;
    }

    .kp-week__legend li {
        display: inline-flex;
        align-items: center;
        gap: 0.375rem;
    }

    .kp-week__swatch {
        --kp-week-ink: var(--chart-1);
        inline-size: 0.875rem;
        block-size: 0.625rem;
        border: 1px solid color-mix(in oklab, var(--kp-week-ink) 45%, var(--border));
        border-radius: var(--kp-week-pill-radius, var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2)));
        background: color-mix(in oklab, var(--kp-week-ink) 14%, var(--card));
    }

    /* The items that did not fit are listed in the `+N` menu; the narrow
 * layout shows every item and needs none of it. */
    @container kp-week (min-width: 40rem) {
        .kp-week__pill[data-kp-overflow] {
            display: none;
        }
    }

    @container kp-week (max-width: 39.99rem) {
        .kp-week__grid {
            --kp-week-mode: list;
            grid-template-columns: minmax(0, 1fr);
            grid-template-rows: none;
            padding-block-end: 0;
        }

        .kp-week__title {
            flex-basis: 100%;
            font-size: var(--kp-week-title-size-narrow, 1.0625rem);
        }

        .kp-week__axis,
        .kp-week__now,
        .kp-week__more {
            display: none;
        }

        .kp-week__day {
            display: grid;
            grid-template-columns: var(--kp-week-day-label, 5.5rem) minmax(0, 1fr);
            column-gap: var(--kp-space-sm, 0.5rem);
            align-items: start;
            padding-block: var(--kp-space-sm, 0.5rem);
            border-block-end: 1px solid var(--border);
        }

        .kp-week__head {
            grid-row: auto;
            grid-column: 1;
            grid-template-columns: auto auto;
            align-content: start;
            padding: 0.125rem 0 0;
        }

        .kp-week__date {
            display: inline;
            grid-column: 1 / -1;
            letter-spacing: 0;
            text-transform: none;
            font-variant-numeric: tabular-nums;
        }

        .kp-week__today {
            grid-column: 1 / -1;
        }

        .kp-week__col {
            grid-row: auto;
            grid-column: 2;
            display: flex;
            flex-direction: column;
            gap: var(--kp-week-gap, 0.25rem);
            /* --kp-week-hold: the height a day keeps while the week loads again (js/week.js holdRows()). */
            min-block-size: max(var(--kp-week-pill, 1.5rem), var(--kp-week-hold, 0px));
            border: 0;
            background: none;
        }

        /* In rows the sentence stays in the items' column, clear of the day names it would otherwise run over. */
        .kp-week__state {
            inset-inline-start: calc(var(--kp-week-day-label, 5.5rem) + var(--kp-space-sm, 0.5rem));
        }

        .kp-week__day[data-kp-today] .kp-week__col {
            background: none;
        }

        .kp-week__pill {
            position: static;
            inset: auto;
            flex: none;
        }
    }

    /* The upcoming list [kpadopt3] (`data-kp-week-upcoming="8"`, js/week.js): below 40rem the agenda lists its next items
     * in place of the day rows, in the rows' own columns and rules: the day on the start side, named on the first row of
     * each day, the item's own pill beside it. Wider it is not drawn. It keeps its height while the week loads again
     * (--kp-week-hold, as a day row does). */
    .kp-week__upcoming {
        display: none;
    }

    @container kp-week (max-width: 39.99rem) {
        .kp-week:has(> .kp-week__frame > .kp-week__upcoming) .kp-week__grid {
            display: none;
        }

        .kp-week__upcoming {
            display: grid;
            min-block-size: var(--kp-week-hold, 0px);
            margin: 0;
            padding: 0;
            list-style: none;
            align-content: start;
        }

        .kp-week__next {
            display: grid;
            grid-template-columns: var(--kp-week-day-label, 5.5rem) minmax(0, 1fr);
            column-gap: var(--kp-space-sm, 0.5rem);
            align-items: center;
            padding-block: var(--kp-week-next-pad, 0.375rem);
            border-block-end: 1px solid var(--border);
        }

        /* A run of the same day reads as one block: the rule falls only where the next day starts. */
        .kp-week__next:has(+ .kp-week__next:not([data-kp-day-start])) {
            border-block-end-color: transparent;
        }

        .kp-week__next[data-kp-day-start] {
            padding-block-start: var(--kp-space-sm, 0.5rem);
        }

        .kp-week__next > .kp-week__pill {
            grid-column: 2;
            min-inline-size: 0;
        }

        /* The day on one line, as tall as a pill, so every row is a pill's height: the weekday and the date; today's
         * says Today in the today colour in place of its weekday. */
        .kp-week__next > .kp-week__head {
            display: flex;
            align-items: center;
            gap: 0.375rem;
            min-block-size: var(--kp-week-pill, 1.5rem);
            padding: 0;
            white-space: nowrap;
        }

        .kp-week__next > .kp-week__head > .kp-week__today {
            display: none;
            font-size: inherit;
            line-height: inherit;
        }

        .kp-week__next[data-kp-today] > .kp-week__head {
            color: var(--foreground);
            font-weight: 600;
        }

        .kp-week__next[data-kp-today] > .kp-week__head > .kp-week__dow {
            display: none;
        }

        .kp-week__next[data-kp-today] > .kp-week__head > .kp-week__today {
            display: inline;
            visibility: visible;
            color: var(--kp-week-today, var(--primary));
        }

        .kp-week__none {
            grid-column: 2;
            display: flex;
            align-items: center;
            min-block-size: var(--kp-week-pill, 1.5rem);
            color: var(--muted-foreground);
            font-size: var(--kp-text-sm, 0.8125rem);
        }
    }

    /* --- Run timeline: one bar per run on a time axis ----------------------
 * `section.kp-gantt[data-kp-gantt]` (js/gantt.js). A bar of range buttons, a
 * Live button and the selected range; under it a frame with the axis on top
 * (it stays while the lanes scroll), one lane per job with its label on the
 * left, and the runs as bars. Every bar is placed by the stylesheet from
 * three numbers the script keeps current (`--kp-g-from`, `--kp-g-span`,
 * `--kp-g-now`, seconds from a base moment) and its own two (`--kp-g-s`,
 * `--kp-g-e`), so a growing bar and a moving window repaint nothing else.
 * A lane's height is its rows times --kp-gantt-row and never shrinks while
 * the window stays: a run that finishes moves nothing. The viewport keeps
 * the height it first had with data (js/gantt.js), so a start that needs a
 * new row scrolls inside the frame and the page does not jump.
 *
 * The state is a shape as well as a colour [DI4]: ok is solid; failed is
 * solid, taller, with a cap at its end and a cross where the bar is wide
 * enough; running is striped with a bright leading edge; queued is hollow
 * and dashed. Knobs [KT6]: `--kp-gantt-label` (9rem, the lanes' labels),
 * `--kp-gantt-row` (1.75rem), `--kp-gantt-bar` (1.125rem),
 * `--kp-gantt-bar-failed` (1.5rem), `--kp-gantt-bar-min` (0.5rem),
 * `--kp-gantt-height` (22rem, past which the lanes scroll),
 * `--kp-gantt-bar-radius`, `--kp-gantt-now` (the line for now),
 * `--kp-gantt-axis` (1.75rem, the axis row). */
    .kp-gantt {
        container: kp-gantt / inline-size;
        display: grid;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
    }

    .kp-gantt__bar {
        position: relative;
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
    }

    /* The selected-range chip takes the toolbar row over (inset 0): while a range is selected it stands where the range
 * buttons and Live are, so it lies on no lane and adds no height at any width; Clear gives the buttons back. */
    .kp-gantt__selection {
        position: absolute;
        inset: 0;
        z-index: 5;
        box-sizing: border-box;
        display: flex;
        flex-wrap: nowrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        padding-inline: var(--kp-space-sm, 0.5rem);
        border: 1px solid var(--border-strong, var(--border));
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    .kp-gantt__selection > .kp-button {
        flex: none;
    }

    .kp-gantt__selection > .kp-gantt__selected {
        flex: 1 1 0;
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-gantt__selection[hidden] {
        display: none;
    }

    .kp-gantt__selected {
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    .kp-gantt__live[aria-pressed='true']::before {
        content: '';
        display: inline-block;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        margin-inline-end: 0.375rem;
        border-radius: 50%;
        background: var(--success);
    }

    .kp-gantt__frame {
        position: relative;
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    /* The viewport holds whole lanes (js/gantt.js sets its height to the last lane that fits under --kp-gantt-height) and a
     * scroll comes to rest on a lane's top, so a lane is never cut at the frame's edge [r3r5-1019 gantt-frame]. */
    .kp-gantt__scroll {
        max-block-size: var(--kp-gantt-height, 22rem);
        scroll-padding-block-start: var(--kp-gantt-axis, 1.75rem);
        scroll-snap-type: y proximity;
        overflow-x: hidden;
        overflow-y: auto;
        touch-action: pan-y;
        user-select: none;
    }

    .kp-gantt__body {
        --kp-gantt-pad: 0.25rem;
        position: relative;
        display: grid;
        /* The lanes' name column is as wide as its longest name (never under --kp-gantt-label, never over
         * --kp-gantt-label-max, then the names wrap) [r3r5-1019 gantt-names]. */
        grid-template-columns: fit-content(var(--kp-gantt-label-max, min(40%, 14rem))) minmax(0, 1fr);
        isolation: isolate;
    }

    .kp-gantt__corner,
    .kp-gantt__axis {
        grid-row: 1;
        position: sticky;
        inset-block-start: 0;
        z-index: 3;
        box-sizing: border-box;
        block-size: var(--kp-gantt-axis, 1.75rem);
        border-block-end: 1px solid var(--border-strong);
        background: var(--card);
    }

    .kp-gantt__corner {
        grid-column: 1;
        min-inline-size: var(--kp-gantt-label, 9rem);
    }

    .kp-gantt__axis {
        grid-column: 2;
        overflow: hidden;
    }

    .kp-gantt__tick {
        position: absolute;
        inset-inline-start: calc((var(--kp-g-t, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inset-block-start: 0;
        padding-inline-start: 0.3125rem;
        color: var(--muted-foreground);
        font-size: 0.6875rem;
        font-variant-numeric: tabular-nums;
        line-height: var(--kp-gantt-axis, 1.75rem);
        white-space: nowrap;
    }

    /* Near the end edge js/gantt.js marks a label `data-kp-gantt-edge`: it stands before its rule, ending at it, so the
     * edge never cuts it (--kp-gantt-tick-flip, 1 by default; 0 keeps the label after its rule). */
    .kp-gantt__tick[data-kp-gantt-edge]:not(button) {
        translate: calc(-100% * var(--kp-gantt-tick-flip, 1)) 0;
        padding-inline: calc(0.3125rem * (1 - var(--kp-gantt-tick-flip, 1))) calc(0.3125rem * var(--kp-gantt-tick-flip, 1));
    }

    .kp-gantt__tick[data-kp-gantt-edge]:not(button):dir(rtl) {
        translate: calc(100% * var(--kp-gantt-tick-flip, 1)) 0;
    }

    /* An end-edge label that would run into the label before it is not drawn [kpadopt4]. */
    .kp-gantt__tick[data-kp-gantt-crowded]:not(button) {
        visibility: hidden;
    }

    .kp-gantt__tick[data-kp-day] {
        color: var(--foreground);
        font-weight: 600;
    }

    /* A day on the axis that can be pressed [kpadopt3] (`data-kp-gantt-days`, js/gantt.js): the same label, as a button as
     * tall as the axis. Pointing underlines it; pressed (its day is the selection) it stands on the selection's tint with
     * the selection's edge under it, so the label and the band in the plot read as one choice. Its focus ring is drawn
     * inside, where the axis does not clip it. */
    .kp-gantt__tick:is(button) {
        box-sizing: border-box;
        block-size: var(--kp-gantt-axis, 1.75rem);
        margin: 0;
        padding-block: 0;
        padding-inline-end: 0.3125rem;
        border: 0;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        font-family: inherit;
        font-size: 0.6875rem;
        letter-spacing: inherit;
        cursor: pointer;
        text-decoration: underline 1px transparent;
        text-underline-offset: 0.25em;
    }

    .kp-gantt__tick:is(button):hover {
        color: var(--primary);
        text-decoration-color: currentColor;
    }

    .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: color-mix(in oklab, var(--primary) 14%, transparent);
        box-shadow: inset 0 -2px 0 var(--primary);
        color: var(--foreground);
    }

    .kp-gantt__tick:is(button)[data-kp-gantt-edge] {
        inset-inline-start: auto;
        inset-inline-end: 0;
    }

    .kp-gantt__tick:is(button)[data-kp-gantt-crowded] {
        visibility: hidden;
    }

    .kp-gantt__tick:is(button):focus-visible {
        outline: 2px solid var(--ring);
        outline-offset: -2px;
    }

    /* The layers that run down every lane (the rules, the line for now, the selection) are no taller than what the frame shows:
     * they stand under the axis as the viewport scrolls (`--kp-g-view`, set by js/gantt.js) instead of running on, unseen, past
     * the frame and the legend under it [r3r5-1019 gantt-frame]. */
    .kp-gantt__lines {
        grid-column: 2;
        grid-row: 2 / span var(--kp-g-lanes, 1);
        position: sticky;
        inset-block-start: var(--kp-gantt-axis, 1.75rem);
        align-self: start;
        block-size: min(100%, var(--kp-g-view, 100%));
        overflow: hidden;
        pointer-events: none;
    }

    .kp-gantt__rule {
        position: absolute;
        inset-block: 0;
        inset-inline-start: calc((var(--kp-g-t, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inline-size: 0;
        border-inline-start: 1px solid var(--border);
    }

    /* A lane's name is never cut with an ellipsis: it wraps and its row grows to hold it. Its first line stands on the
     * middle of the lane's first row, where the bars and marks of that row stand [r3r5-1019 gantt-names]. */
    .kp-gantt__lane {
        grid-column: 1;
        display: flex;
        align-items: flex-start;
        min-inline-size: 0;
        box-sizing: border-box;
        padding: var(--kp-gantt-pad) var(--kp-space-sm, 0.5rem) calc(var(--kp-gantt-pad) - 1px);
        border-block-end: 1px solid var(--border);
        font-size: var(--kp-text-sm, 0.8125rem);
        scroll-snap-align: start;
    }

    .kp-gantt__lane:not(.kp-gantt__ghost) > :is(span, a) {
        display: grid;
        align-content: center;
        min-inline-size: 0;
        min-block-size: var(--kp-gantt-row, 1.75rem);
        overflow-wrap: break-word;
    }

    .kp-gantt__track {
        grid-column: 2;
        position: relative;
        overflow: hidden;
        box-sizing: border-box;
        min-block-size: calc(var(--kp-g-rows, 1) * var(--kp-gantt-row, 1.75rem) + 2 * var(--kp-gantt-pad));
        border-block-end: 1px solid var(--border);
    }

    .kp-gantt__plot {
        grid-column: 2;
        grid-row: 2 / span var(--kp-g-lanes, 1);
        position: sticky;
        inset-block-start: var(--kp-gantt-axis, 1.75rem);
        align-self: start;
        block-size: min(100%, var(--kp-g-view, 100%));
        overflow: hidden;
        pointer-events: none;
    }

    .kp-gantt__now {
        position: absolute;
        inset-block: 0;
        inset-inline-start: calc((var(--kp-g-now, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inline-size: 0;
        border-inline-start: 2px solid var(--kp-gantt-now, var(--destructive));
    }

    .kp-gantt__now[data-kp-out] {
        display: none;
    }

    .kp-gantt__select,
    .kp-gantt__brush {
        position: absolute;
        inset-block: 0;
        background: color-mix(in oklab, var(--primary) 14%, transparent);
        border-inline: 1px solid var(--primary);
    }

    .kp-gantt__select {
        inset-inline-start: calc((var(--kp-g-s, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inline-size: calc((var(--kp-g-e, 0) - var(--kp-g-s, 0)) / var(--kp-g-span, 21600) * 100%);
    }

    .kp-gantt__brush {
        inset-inline-start: var(--kp-g-x, 0);
        inline-size: var(--kp-g-w, 0);
        border-style: dashed;
    }

    .kp-gantt__select[hidden],
    .kp-gantt__brush[hidden] {
        display: none;
    }

    .kp-gantt__run {
        --kp-gantt-fill: var(--success);
        --kp-gantt-ink: var(--success-foreground);
        container: kp-gantt-run / inline-size;
        box-sizing: border-box;
        position: absolute;
        inset-block-start: calc(
            var(--kp-gantt-pad) + var(--kp-g-row, 0) * var(--kp-gantt-row, 1.75rem) + (var(--kp-gantt-row, 1.75rem) - var(--kp-gantt-bar, 1.125rem)) /
                2
        );
        inset-inline-start: calc((var(--kp-g-s, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inline-size: max(var(--kp-gantt-bar-min, 0.5rem), calc((var(--kp-g-e, 0) - var(--kp-g-s, 0)) / var(--kp-g-span, 21600) * 100%));
        block-size: var(--kp-gantt-bar, 1.125rem);
        margin: 0;
        padding: 0;
        overflow: hidden;
        border: 1px solid var(--kp-gantt-fill);
        border-radius: var(--kp-gantt-bar-radius, var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2)));
        background: var(--kp-gantt-fill);
        color: var(--kp-gantt-ink);
        font: inherit;
        font-size: 0.6875rem;
        text-align: start;
        cursor: pointer;
    }

    .kp-gantt__run[hidden] {
        display: none;
    }

    .kp-gantt__run:is(button):hover {
        z-index: 1;
        box-shadow: 0 0 0 2px var(--foreground);
    }

    .kp-gantt__label {
        display: block;
        padding-inline: 0.375rem;
        overflow: hidden;
        line-height: calc(var(--kp-gantt-bar, 1.125rem) - 2px);
        text-overflow: ellipsis;
        white-space: nowrap;
        pointer-events: none;
    }

    .kp-gantt__run[data-kp-state='failed'] {
        --kp-gantt-fill: var(--destructive);
        --kp-gantt-ink: var(--destructive-foreground);
        inset-block-start: calc(
            var(--kp-gantt-pad) + var(--kp-g-row, 0) * var(--kp-gantt-row, 1.75rem) +
                (var(--kp-gantt-row, 1.75rem) - var(--kp-gantt-bar-failed, 1.5rem)) / 2
        );
        block-size: var(--kp-gantt-bar-failed, 1.5rem);
        box-shadow: inset -3px 0 0 var(--kp-gantt-ink);
    }

    .kp-gantt__run[data-kp-state='failed'] .kp-gantt__label {
        line-height: calc(var(--kp-gantt-bar-failed, 1.5rem) - 2px);
    }

    .kp-gantt__run[data-kp-state='failed']:hover {
        box-shadow:
            inset -3px 0 0 var(--kp-gantt-ink),
            0 0 0 2px var(--foreground);
    }

    .kp-gantt__run[data-kp-state='running'],
    .kp-gantt__swatch[data-kp-state='running'] {
        --kp-gantt-fill: var(--warning);
        --kp-gantt-ink: var(--warning-foreground);
        background-image: repeating-linear-gradient(
            135deg,
            transparent 0 0.375rem,
            hsl(from var(--warning-foreground) h s l / 0.22) 0.375rem 0.75rem
        );
        background-size: 1.0607rem 1.0607rem;
        box-shadow: inset -3px 0 0 var(--kp-gantt-ink);
    }

    .kp-gantt__run[data-kp-state='running']:hover {
        box-shadow:
            inset -3px 0 0 var(--kp-gantt-ink),
            0 0 0 2px var(--foreground);
    }

    .kp-gantt__run[data-kp-state='queued'],
    .kp-gantt__swatch[data-kp-state='queued'] {
        --kp-gantt-fill: var(--muted-foreground);
        --kp-gantt-ink: var(--foreground);
        /* Hollow, but on the card's own ground: the rules and bands under it do not cross its words [r3r5-1019 gantt-rules]. */
        background: var(--card);
        border-style: dashed;
    }

    /* A finished run of a series [kpadopt3] (`series` 1 to 5, js/gantt.js) is a category, not a state: a plate of its chart
     * colour, tinted into the card with its edge in the full colour, the words in the page's ink so every series reads
     * the same. Failed, running and queued keep their own look; the legend names the series after the states. */
    :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='ok'][data-kp-series] {
        --kp-gantt-series: var(--chart-1);
        --kp-gantt-fill: color-mix(in oklab, var(--kp-gantt-series) 34%, var(--card));
        --kp-gantt-ink: var(--foreground);
        border-color: var(--kp-gantt-series);
    }

    :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='ok'][data-kp-series='2'] {
        --kp-gantt-series: var(--chart-2);
    }

    :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='ok'][data-kp-series='3'] {
        --kp-gantt-series: var(--chart-3);
    }

    :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='ok'][data-kp-series='4'] {
        --kp-gantt-series: var(--chart-4);
    }

    :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='ok'][data-kp-series='5'] {
        --kp-gantt-series: var(--chart-5);
    }

    .kp-gantt__run[data-kp-state='failed'] .kp-gantt__label::before {
        content: var(--kp-glyph-failed, '✕');
        margin-inline-end: 0.25rem;
        font-weight: 700;
    }

    @container kp-gantt-run (max-width: 2rem) {
        .kp-gantt__label {
            display: none;
        }
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-gantt__run[data-kp-state='running'] {
            animation: kp-gantt-march 1600ms linear infinite;
        }
    }

    @keyframes kp-gantt-march {
        to {
            background-position: 1.0607rem 0;
        }
    }

    .kp-gantt__ghost.kp-gantt__lane {
        border-block-end-color: var(--border);
    }

    .kp-gantt__ghost.kp-gantt__lane > .kp-skeleton {
        inline-size: 70%;
        block-size: 0.75rem;
    }

    .kp-gantt__ghost .kp-gantt__run {
        inset-inline-start: calc(var(--kp-g-at, 0) * 100%);
        inline-size: calc(var(--kp-g-width, 0.1) * 100%);
        border: 0;
        cursor: default;
        background: var(--muted);
    }

    .kp-gantt__state {
        position: absolute;
        inset: var(--kp-gantt-axis, 1.75rem) 0 0;
        z-index: 4;
        display: grid;
        place-items: center;
        margin: 0;
        padding: var(--kp-space-md, 0.75rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        text-align: center;
        pointer-events: none;
    }

    .kp-gantt__state:empty {
        display: none;
    }

    /* Loading is the data table's own loading card [Kenny, 2026-10-16: "zoals bij een table waar het icoon in het
 * midden van de matrix staat en lijkt te laden"]: js/gantt.js lays js/busy-card.js's layer and panel centred over
 * the lanes, so the sentence is read out but no longer drawn. */
    .kp-gantt[data-kp-state='loading'] .kp-gantt__state {
        inset: auto;
        inline-size: 1px;
        block-size: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        white-space: nowrap;
        clip-path: inset(50%);
    }

    .kp-gantt__state[data-kp-state='error'] {
        color: var(--destructive);
    }

    /* A timeline with no lane, empty or failed, keeps a lane-sized room under its axis for the sentence, taller when its
     * words need more lines (`--kp-gantt-words`, measured by js/gantt.js), so the sentence never runs out of the frame
     * onto the legend under it. */
    .kp-gantt:is([data-kp-state='ready'], [data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: max(5.25rem, calc(var(--kp-gantt-axis, 1.75rem) + var(--kp-gantt-words, 0px)));
    }

    /* An empty or failed timeline is the state plate over its plot, which needs the plate's own room [state-plates-1019]. */
    .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body,
    .kp-gantt[data-kp-state='ready']:has(> .kp-gantt__frame > .kp-gantt__plate:not([hidden])) .kp-gantt__body {
        min-block-size: var(--kp-stateplate-floor, 12rem);
    }

    .kp-gantt__legend {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        margin: 0;
        padding: 0;
        list-style: none;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-gantt__legend li {
        display: inline-flex;
        align-items: center;
        gap: 0.375rem;
    }

    .kp-gantt__swatch {
        --kp-gantt-fill: var(--success);
        box-sizing: border-box;
        inline-size: 1.25rem;
        block-size: 0.625rem;
        border: 1px solid var(--kp-gantt-fill);
        border-radius: var(--kp-gantt-bar-radius, var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2)));
        background: var(--kp-gantt-fill);
    }

    .kp-gantt__swatch[data-kp-state='failed'] {
        --kp-gantt-fill: var(--destructive);
        block-size: 0.8125rem;
        box-shadow: inset -3px 0 0 var(--destructive-foreground);
    }

    .kp-gantt__hint {
        margin: 0;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-gantt__announce {
        position: absolute;
        inline-size: 1px;
        block-size: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        white-space: nowrap;
        border: 0;
        clip-path: inset(50%);
    }

    @container kp-gantt (max-width: 32rem) {
        .kp-gantt__body {
            --kp-gantt-label: 5.5rem;
        }

        .kp-gantt__lane {
            font-size: var(--kp-text-xs, 0.75rem);
        }
    }

    /* Point events on the run timeline [kpadopt4] (setGanttPoints, setGanttKinds, setGanttZones in js/gantt.js): a moment is a
 * small mark in its lane, in the colour and shape of its kind (the shape is the second carrier [DI4]); a planned one is
 * hollow; marks too close to tell apart are one mark with a count on a small plate beside it. A stretch is a thin band in
 * its lane, or a band behind every lane. The mark's button is larger than the mark, so it is easy to hit. Knobs [KT6]:
 * `--kp-gantt-mark-size` (0.75rem), `--kp-gantt-hit` (1.375rem, the button), `--kp-gantt-zone` (0.25rem, a lane's band),
 * `--kp-gantt-row-sub` (2.5rem, a lane's row when lanes carry a second line). */
    .kp-gantt__point {
        --kp-gantt-mark: var(--primary);
        position: absolute;
        z-index: 1;
        box-sizing: border-box;
        display: grid;
        place-items: center;
        inset-block-start: calc(var(--kp-gantt-pad) + (var(--kp-gantt-row, 1.75rem) - var(--kp-gantt-hit, 1.375rem)) / 2);
        inset-inline-start: calc((var(--kp-g-s, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100% - var(--kp-gantt-hit, 1.375rem) / 2);
        inline-size: var(--kp-gantt-hit, 1.375rem);
        block-size: var(--kp-gantt-hit, 1.375rem);
        margin: 0;
        padding: 0;
        border: 0;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: transparent;
        color: var(--foreground);
        font: inherit;
        cursor: pointer;
    }

    .kp-gantt__point[hidden],
    .kp-gantt__point[data-kp-clustered] {
        display: none;
    }

    :is(.kp-gantt__point, .kp-gantt__mark)::before {
        content: '';
        grid-area: 1 / 1;
        box-sizing: border-box;
        inline-size: var(--kp-gantt-mark-size, 0.75rem);
        block-size: var(--kp-gantt-mark-size, 0.75rem);
        border: 2px solid var(--kp-gantt-mark);
        border-radius: 50%;
        background: var(--kp-gantt-mark);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='square']::before {
        border-radius: 1px;
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='diamond']::before {
        border-radius: 1px;
        rotate: 45deg;
        scale: 0.85;
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='triangle']::before {
        border: 0;
        border-radius: 0;
        clip-path: polygon(50% 4%, 100% 96%, 0 96%);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='ring']::before,
    .kp-gantt__point[data-kp-planned]::before {
        background: var(--card);
    }

    /* A planned triangle has no border to keep: its hollow is the card's ground inside an edge of its own colour. */
    .kp-gantt__point[data-kp-planned][data-kp-shape='triangle']::before {
        padding: 0.25rem 0.1875rem 0.125rem;
        background:
            linear-gradient(var(--card), var(--card)) content-box,
            var(--kp-gantt-mark) border-box;
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-series] {
        --kp-gantt-mark: var(--chart-1);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-series='2'] {
        --kp-gantt-mark: var(--chart-2);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-series='3'] {
        --kp-gantt-mark: var(--chart-3);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-series='4'] {
        --kp-gantt-mark: var(--chart-4);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-series='5'] {
        --kp-gantt-mark: var(--chart-5);
    }

    :is(.kp-gantt__point, .kp-gantt__mark, .kp-gantt__zone, .kp-gantt__band)[data-kp-tone='success'] {
        --kp-gantt-mark: var(--success);
    }

    :is(.kp-gantt__point, .kp-gantt__mark, .kp-gantt__zone, .kp-gantt__band)[data-kp-tone='warning'] {
        --kp-gantt-mark: var(--warning);
    }

    :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-tone='destructive'] {
        --kp-gantt-mark: var(--destructive);
    }

    :is(.kp-gantt__point, .kp-gantt__mark, .kp-gantt__zone, .kp-gantt__band)[data-kp-tone='info'] {
        --kp-gantt-mark: var(--info);
    }

    :is(.kp-gantt__point, .kp-gantt__mark, .kp-gantt__zone, .kp-gantt__band)[data-kp-tone='muted'] {
        --kp-gantt-mark: var(--muted-foreground);
    }

    .kp-gantt__point:hover::before {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--foreground);
    }

    .kp-gantt__count {
        position: absolute;
        inset-block-start: 50%;
        inset-inline-start: calc(50% + var(--kp-gantt-mark-size, 0.75rem) / 2 + 0.125rem);
        translate: 0 -50%;
        padding: 0.0625rem 0.1875rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--card);
        color: var(--foreground);
        font-size: 0.625rem;
        font-variant-numeric: tabular-nums;
        font-weight: 600;
        line-height: 1;
        white-space: nowrap;
        pointer-events: none;
    }

    .kp-gantt__count:empty {
        display: none;
    }

    .kp-gantt__zone {
        --kp-gantt-mark: var(--warning);
        position: absolute;
        inset-block: 0;
        inset-inline-start: calc((var(--kp-g-s, 0) - var(--kp-g-from, 0)) / var(--kp-g-span, 21600) * 100%);
        inline-size: calc((var(--kp-g-e, 0) - var(--kp-g-s, 0)) / var(--kp-g-span, 21600) * 100%);
        border-inline: 1px dashed var(--kp-gantt-mark);
        background: hsl(from var(--kp-gantt-mark) h s l / 0.14);
        pointer-events: none;
    }

    /* A lane's own stretch stands on the foot of the lane's first row, under the marks and their count plates, not through
     * their middle where it ran behind a "+2" [r3r5-1019 gantt-zone]. */
    .kp-gantt__zone[data-kp-lane-zone] {
        inset-block: auto;
        inset-block-start: calc(var(--kp-gantt-pad) + var(--kp-gantt-row, 1.75rem) - var(--kp-gantt-zone, 0.25rem));
        block-size: var(--kp-gantt-zone, 0.25rem);
        border: 0;
        border-radius: var(--kp-radius-pill, 999px);
        background: hsl(from var(--kp-gantt-mark) h s l / 0.55);
    }

    .kp-gantt__mark {
        --kp-gantt-mark: var(--primary);
        display: inline-grid;
        place-items: center;
        inline-size: 1rem;
        block-size: 1rem;
    }

    .kp-gantt__band {
        --kp-gantt-mark: var(--warning);
        box-sizing: border-box;
        inline-size: 1.25rem;
        block-size: 0.625rem;
        border-inline: 1px dashed var(--kp-gantt-mark);
        background: hsl(from var(--kp-gantt-mark) h s l / 0.14);
    }

    .kp-gantt__legend > li[hidden] {
        display: none;
    }

    /* A lane's name as a link, and a second line under it. */
    .kp-gantt__lane > a {
        min-inline-size: 0;
    }

    .kp-gantt__lane-link {
        color: inherit;
        text-decoration: underline;
        text-decoration-thickness: 1px;
        text-underline-offset: 0.2em;
    }

    .kp-gantt__words,
    .kp-gantt__words > .kp-gantt__lane-link {
        display: grid;
        min-inline-size: 0;
        line-height: 1.25;
    }

    :is(.kp-gantt__name, .kp-gantt__sub) {
        display: block;
        min-inline-size: 0;
        overflow-wrap: break-word;
    }

    .kp-gantt__sub {
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-gantt__body[data-kp-gantt-subs] {
        --kp-gantt-row: var(--kp-gantt-row-sub, 2.5rem);
    }

    /* The dated line [kpadopt4] (`.kp-gantt--line`): one lane, no toolbar, no lane names, no hint, the axis under the line. */
    .kp-gantt--line :is(.kp-gantt__bar, .kp-gantt__hint) {
        display: none;
    }

    .kp-gantt--line .kp-gantt__body {
        --kp-gantt-row: 2.25rem;
        grid-template-columns: 0 minmax(0, 1fr);
    }

    .kp-gantt--line .kp-gantt__lane {
        visibility: hidden;
        padding: 0;
        overflow: hidden;
    }

    .kp-gantt--line .kp-gantt__corner {
        min-inline-size: 0;
    }

    .kp-gantt--line :is(.kp-gantt__corner, .kp-gantt__axis) {
        grid-row: 3;
        position: relative;
        border-block-end: 0;
        border-block-start: 1px solid var(--border-strong);
    }

    .kp-gantt--line .kp-gantt__track {
        border-block-end: 0;
    }

    .kp-gantt--line .kp-gantt__state {
        inset: 0 0 var(--kp-gantt-axis, 1.75rem);
    }

    /* A timeline of moments [kpadopt4] gives its sentence the card's ground, so no rule of the axis runs through it. */
    .kp-gantt[data-kp-gantt-points]:not([data-kp-state='loading']) .kp-gantt__state:not(:empty) {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--card);
    }

    /* --- Pipeline: where each item stands, a lane per stage [kpadopt4] ------
 * `section.kp-pipeline[data-kp-pipeline]` (js/pipeline.js). A read-only board: lanes side by side at one width, each as
 * tall as the tallest, a plate with the stage's name and its exact count in the stage's colour (a tint of the chart
 * colour, the words in the page's ink [fix-70]), the share of all under it, and the cards. A closed lane stands under the
 * board across its width. Under 40rem of the board's own width the lanes turn to rows. The sentence of an empty or a
 * failed board stands on its own plate above the lanes, which keep their place and are covered by nothing. Knobs [KT6]: `--kp-pipeline-gap`
 * (0.75rem), `--kp-pipeline-min` (12rem, the board's least height), `--kp-pipeline-card-min` (12rem, a card's least
 * width where cards flow in a row), `--kp-pipeline-mark` (1.75rem), `--kp-pipeline-tone` (the stage's colour). */
    .kp-pipeline {
        container: kp-pipeline / inline-size;
        display: grid;
        gap: var(--kp-pipeline-gap, 0.75rem);
        min-inline-size: 0;
    }

    .kp-pipeline__frame {
        position: relative;
        min-inline-size: 0;
    }

    .kp-pipeline__board {
        display: grid;
        grid-template-columns: repeat(var(--kp-pipeline-lanes, 4), minmax(0, 1fr));
        column-gap: var(--kp-pipeline-gap, 0.75rem);
        row-gap: 0;
        align-items: stretch;
        min-block-size: var(--kp-pipeline-min, 12rem);
    }

    .kp-pipeline__lane {
        --kp-pipeline-tone: var(--muted-foreground);
        display: grid;
        grid-template-rows: auto auto 1fr;
        align-content: start;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        padding: var(--kp-space-sm, 0.5rem);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--muted);
        color: var(--foreground);
    }

    :is(.kp-pipeline__lane, .kp-pipeline__card)[data-kp-tone='1'] {
        --kp-pipeline-tone: var(--chart-1);
    }

    :is(.kp-pipeline__lane, .kp-pipeline__card)[data-kp-tone='2'] {
        --kp-pipeline-tone: var(--chart-2);
    }

    :is(.kp-pipeline__lane, .kp-pipeline__card)[data-kp-tone='3'] {
        --kp-pipeline-tone: var(--chart-3);
    }

    :is(.kp-pipeline__lane, .kp-pipeline__card)[data-kp-tone='4'] {
        --kp-pipeline-tone: var(--chart-4);
    }

    :is(.kp-pipeline__lane, .kp-pipeline__card)[data-kp-tone='5'] {
        --kp-pipeline-tone: var(--chart-5);
    }

    .kp-pipeline__head {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border: 1px solid var(--kp-pipeline-tone);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: color-mix(in oklab, var(--kp-pipeline-tone) 22%, var(--card));
        color: var(--foreground);
    }

    .kp-pipeline__name {
        grid-row: 1;
        grid-column: 1;
        min-inline-size: 0;
        margin: 0;
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 600;
        line-height: 1.4;
        overflow-wrap: break-word;
    }

    .kp-pipeline__count {
        grid-row: 1;
        grid-column: 2;
        min-inline-size: 1.5rem;
        font-size: 1.125rem;
        font-variant-numeric: tabular-nums;
        font-weight: 700;
        line-height: 1.4;
        text-align: end;
    }

    .kp-pipeline__ghost-count {
        display: inline-block;
        inline-size: 1.25rem;
        block-size: 1rem;
        vertical-align: middle;
    }

    .kp-pipeline__share {
        min-block-size: 1.25rem;
        margin: 0;
        padding-inline: var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
        line-height: 1.25rem;
    }

    .kp-pipeline__cards {
        display: grid;
        align-content: start;
        gap: var(--kp-space-xs, 0.25rem);
        min-inline-size: 0;
    }

    .kp-pipeline__card {
        box-sizing: border-box;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        grid-template-areas:
            'mark title'
            'mark sub'
            'mark meta';
        align-items: center;
        column-gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
        margin: 0;
        padding: var(--kp-space-sm, 0.5rem);
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
        font: inherit;
        text-align: start;
        text-decoration: none;
        cursor: pointer;
    }

    .kp-pipeline__card:hover {
        border-color: var(--border-strong);
    }

    .kp-pipeline__card[aria-current='true'] {
        border-color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
    }

    /* Filtered out, kept in its place: quieter by ink and a dashed edge, not by opacity, so its words keep their contrast. */
    .kp-pipeline__card[data-kp-dimmed] {
        border-style: dashed;
        background: transparent;
        color: var(--muted-foreground);
    }

    .kp-pipeline__mark {
        grid-area: mark;
        display: grid;
        place-items: center;
        inline-size: var(--kp-pipeline-mark, 1.75rem);
        block-size: var(--kp-pipeline-mark, 1.75rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: color-mix(in oklab, var(--kp-pipeline-tone, var(--muted-foreground)) 30%, var(--card));
        color: var(--foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 700;
        letter-spacing: 0.02em;
        text-transform: uppercase;
    }

    .kp-pipeline__mark[hidden],
    .kp-pipeline__sub[hidden],
    .kp-pipeline__meta[hidden] {
        display: none;
    }

    :is(.kp-pipeline__title, .kp-pipeline__sub, .kp-pipeline__meta) {
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .kp-pipeline__title {
        grid-area: title;
        font-size: var(--kp-text-sm, 0.8125rem);
        font-weight: 600;
    }

    .kp-pipeline__sub {
        grid-area: sub;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-pipeline__meta {
        grid-area: meta;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-variant-numeric: tabular-nums;
    }

    .kp-pipeline__card[data-kp-dimmed] :is(.kp-pipeline__sub, .kp-pipeline__meta) {
        color: inherit;
    }

    .kp-pipeline__ghost {
        grid-template-areas: none;
        grid-template-columns: minmax(0, 1fr);
        row-gap: var(--kp-space-xs, 0.25rem);
        block-size: 3.5rem;
        align-content: center;
        cursor: default;
    }

    .kp-pipeline__ghost > .kp-skeleton {
        block-size: 0.75rem;
        inline-size: 75%;
    }

    .kp-pipeline__ghost > .kp-skeleton + .kp-skeleton {
        inline-size: 45%;
    }

    .kp-pipeline__none {
        margin: 0;
        padding: var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-pipeline__more {
        justify-self: start;
    }

    .kp-pipeline__closed {
        display: grid;
        gap: var(--kp-pipeline-gap, 0.75rem);
    }

    .kp-pipeline__closed[hidden] {
        display: none;
    }

    .kp-pipeline__lane--closed .kp-pipeline__cards {
        grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kp-pipeline-card-min, 12rem)), 1fr));
    }

    /* [r1r2-1019] The lanes of a board share their rows: every name plate is as high as the highest (names wrap, never an ellipsis),
 * the share lines and the first cards start on one line across the lanes. A board without a share line has two rows. */
    .kp-pipeline__board {
        grid-template-rows: auto auto 1fr;
    }

    .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board {
        grid-template-rows: auto 1fr;
    }

    .kp-pipeline__board > .kp-pipeline__lane {
        grid-row: span 3;
        grid-template-rows: subgrid;
    }

    .kp-pipeline__board > .kp-pipeline__lane > .kp-pipeline__cards {
        grid-row: 3;
    }

    .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board > .kp-pipeline__lane {
        grid-row: span 2;
    }

    .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board > .kp-pipeline__lane > .kp-pipeline__cards {
        grid-row: 2;
    }

    /* [r1r2-1019] A failing stage: the lane takes the destructive colour in the theme's own way (its tone), and its name plate carries a
 * flag, the destructive status plate with the words, so the colour is never the only carrier. The flag stands under the name,
 * across the plate, so a narrow lane keeps its name in whole words. */
    .kp-pipeline__lane[data-kp-status='danger'] {
        --kp-pipeline-tone: var(--destructive);
    }

    .kp-pipeline__flag {
        grid-row: 2;
        grid-column: 1 / -1;
        justify-self: start;
        padding: 0 var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
        font-weight: 600;
        line-height: 1.5;
    }

    /* [r1r2-1019] An empty or failed board is the package's state plate over the whole board, closed lane included, at the height the
 * board had (js/footprint.js holds it on the host). The lanes stay in the document, covered and inert, none of their counts drawn. */
    .kp-pipeline:has(> .kp-pipeline__plate:not([hidden])) {
        position: relative;
        min-block-size: var(--kp-stateplate-floor, 12rem);
    }

    .kp-pipeline__plate {
        position: absolute;
        inset: 0;
        z-index: 5;
        display: grid;
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    .kp-pipeline__plate[hidden] {
        display: none;
    }

    .kp-pipeline__plate > .kp-stateplate {
        block-size: 100%;
    }

    .kp-pipeline:has(> .kp-pipeline__plate:not([hidden])) > :is(.kp-pipeline__frame, .kp-pipeline__closed) {
        visibility: hidden;
    }

    @container kp-pipeline (max-width: 40rem) {
        .kp-pipeline__board,
        .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board {
            grid-template-columns: minmax(0, 1fr);
            grid-template-rows: none;
            row-gap: var(--kp-pipeline-gap, 0.75rem);
            min-block-size: 0;
        }

        .kp-pipeline__board > .kp-pipeline__lane,
        .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board > .kp-pipeline__lane {
            grid-row: auto;
            grid-template-rows: auto auto 1fr;
        }

        .kp-pipeline__board > .kp-pipeline__lane > .kp-pipeline__cards,
        .kp-pipeline[data-kp-pipeline-share='false'] .kp-pipeline__board > .kp-pipeline__lane > .kp-pipeline__cards {
            grid-row: auto;
        }

        .kp-pipeline__cards {
            grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--kp-pipeline-card-min, 12rem)), 1fr));
        }

        .kp-pipeline__more,
        .kp-pipeline__none {
            grid-column: 1 / -1;
        }
    }

    /* Diff view [TH54] */
    .kp-diff {
        margin: 0;
        overflow-x: auto;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-diff__line {
        display: grid;
        grid-template-columns: 3rem 1ch 1fr;
        gap: 0.5rem;
        padding-inline: 0.5rem;
        white-space: pre-wrap;
    }

    /* The sign in its own column is the carrier that survives when the colour
 * does not — printed, in high contrast, or for a reader who cannot tell
 * green from red [DI4]. */
    .kp-diff__sign {
        color: var(--muted-foreground);
    }

    .kp-diff__number {
        color: var(--muted-foreground);
        text-align: end;
        font-variant-numeric: tabular-nums;
    }

    .kp-diff__line[data-kind='added'] {
        background: hsl(from var(--success) h s l / 0.14);
    }

    .kp-diff__line[data-kind='removed'] {
        background: hsl(from var(--destructive) h s l / 0.12);
    }

    /* The hunk header: the `@@ -12,6 +12,8 @@ function name` row that opens
 * each block of changes, between the lines it introduces and the lines of
 * the hunk before. A band of its own (the muted ground, a rule under it, a
 * rule over it from the second hunk on) so the eye finds where a hunk
 * begins without colour; the `@@` marks are the text carrier [DI4]. It
 * wraps like a line, so a long function name never scrolls the diff.
 * `font: inherit` keeps the container's mono face; a register that sets the
 * face on the lines sets it on this row too. */
    .kp-diff__hunk {
        display: block;
        padding: 0.125rem 0.5rem;
        border-block-end: 1px solid var(--border);
        background: var(--muted);
        color: var(--muted-foreground);
        font: inherit;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
    }

    .kp-diff__hunk:not(:first-child) {
        border-block-start: 1px solid var(--border);
    }

    /* The context after the second `@@` (the function the hunk sits in) in
 * the foreground, so the range reads as the quiet part and the place as the
 * one that matters. Optional: a header may be one text node. */
    .kp-diff__hunk-context {
        color: var(--foreground);
    }

    /* --- A diff of several files [gap-diff-view; homelab's editui.js diffBlocks] -------------------------------------
 *
 * js/diff.js writes the lines `.kp-diff` already dresses and adds what a diff of several files needs: a header per file
 * (a chevron, a status word on a badge, the path, exact +N and -M counts with five blocks for their share, Copy path),
 * the unchanged lines folded into one row that is a button, and the changed words marked inside a changed line. The
 * header's columns are as wide as the longest of the page (--kp-diffview-added-ch and -removed-ch are written by the
 * script) so the headers of several files line up. Every state (reading, nothing changed, failed) stands in the box the
 * diff had (js/footprint.js). Knobs [KT6]: --kp-diffview-min (least height of a state, 18rem), --kp-diffview-status
 * (the status column, 5.5rem), --kp-diffview-gap (between files). */
    .kp-diffview {
        --kp-diffview-min: 18rem;
        --kp-diffview-status: 5.5rem;
        --kp-diffview-gap: var(--kp-space-sm, 0.5rem);
        container: kp-diffview / inline-size;
        position: relative;
        display: grid;
        gap: var(--kp-diffview-gap);
        min-inline-size: 0;
    }

    .kp-diffview:not([data-kp-state='ready']) {
        min-block-size: var(--kp-diffview-min);
    }

    .kp-diffview__stage {
        position: relative;
        display: grid;
        min-block-size: 0;
    }

    .kp-diffview__stage > .kp-stateplate {
        border-radius: var(--radius, 0.5rem);
    }

    .kp-diffview__bar {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        min-block-size: var(--kp-button-height, 2.25rem);
    }

    .kp-diffview__summary {
        display: flex;
        flex-wrap: wrap;
        align-items: baseline;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        margin: 0;
    }

    .kp-diffview__tools {
        display: flex;
        gap: var(--kp-space-xs, 0.25rem);
    }

    .kp-diffview__list {
        display: grid;
        gap: var(--kp-diffview-gap);
        min-inline-size: 0;
    }

    .kp-diffview__file {
        min-inline-size: 0;
        overflow: clip;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card, var(--background));
    }

    .kp-diffview__head {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        padding-inline-end: var(--kp-space-sm, 0.5rem);
        background: var(--muted);
    }

    .kp-diffview__title {
        min-inline-size: 0;
        margin: 0;
        font: inherit;
    }

    .kp-diffview__toggle {
        display: grid;
        grid-template-columns: 1rem var(--kp-diffview-status) minmax(0, 1fr) auto auto;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        box-sizing: border-box;
        inline-size: 100%;
        min-block-size: 2.75rem;
        margin: 0;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem) var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        border: 0;
        border-radius: 0;
        background: transparent;
        color: var(--foreground);
        font: inherit;
        text-align: start;
        cursor: pointer;
    }

    .kp-diffview__toggle:hover {
        background: hsl(from var(--foreground) h s l / 0.06);
    }

    .kp-diffview__toggle:focus-visible,
    .kp-diff__row-button:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast, var(--primary));
        outline-offset: -2px;
    }

    /* The chevron is drawn, not typed: a corner turned a quarter, a half further when the file is open. */
    .kp-diffview__chevron {
        justify-self: center;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-inline-end: 2px solid currentColor;
        border-block-end: 2px solid currentColor;
        transform: rotate(-45deg);
    }

    .kp-diffview__file[data-kp-diff-file-open='true'] .kp-diffview__chevron {
        transform: translateY(-0.125rem) rotate(45deg);
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-diffview__chevron {
            transition: transform var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    .kp-diffview__status {
        justify-content: center;
        box-sizing: border-box;
        inline-size: 100%;
    }

    .kp-diffview__path {
        min-inline-size: 0;
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: anywhere;
    }

    .kp-diffview__dir,
    .kp-diffview__arrow {
        color: var(--muted-foreground);
    }

    .kp-diffview__arrow {
        padding-inline: 0.5ch;
    }

    .kp-diffview__name {
        color: var(--foreground);
        font-weight: 600;
    }

    /* A long token wraps in the text column instead of running out of the plate (the column may shrink below its content). */
    .kp-diffview .kp-diff__line {
        grid-template-columns: 3rem 1ch minmax(0, 1fr);
    }

    .kp-diffview .kp-diff__text {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    /* Exact counts on their own quiet plates, a column as wide as the longest of the page. The sign is the carrier;
     * the tint is the second one [DI4]. */
    .kp-diffview__counts {
        display: inline-flex;
        gap: var(--kp-space-xs, 0.25rem);
    }

    .kp-diffview__added,
    .kp-diffview__removed {
        box-sizing: border-box;
        padding-inline: 0.375rem;
        border-radius: var(--kp-radius-sm, 0.25rem);
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
        text-align: end;
        white-space: nowrap;
    }

    .kp-diffview__added {
        min-inline-size: calc(var(--kp-diffview-added-ch, 2) * 1ch + 0.75rem);
        background: hsl(from var(--success) h s l / 0.14);
    }

    .kp-diffview__removed {
        min-inline-size: calc(var(--kp-diffview-removed-ch, 2) * 1ch + 0.75rem);
        background: hsl(from var(--destructive) h s l / 0.12);
    }

    .kp-diffview__summary > .kp-diffview__added,
    .kp-diffview__summary > .kp-diffview__removed {
        min-inline-size: 0;
    }

    .kp-diffview__proportion {
        display: inline-flex;
        gap: 2px;
    }

    .kp-diffview__block {
        display: block;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        background: var(--border);
    }

    .kp-diffview__block[data-kind='added'] {
        background: var(--success);
    }

    .kp-diffview__block[data-kind='removed'] {
        background: var(--destructive);
    }

    .kp-diffview__body {
        border-block-start: 1px solid var(--border);
        min-inline-size: 0;
    }

    .kp-diffview__body:focus {
        outline: none;
    }

    /* The diff inside a file has no frame of its own: the file's frame is the frame. */
    .kp-diffview .kp-diffview__body .kp-diff {
        border: 0;
        border-radius: 0;
    }

    .kp-diffview .kp-diff__number,
    .kp-diffview .kp-diff__sign {
        user-select: none;
    }

    .kp-diffview__note {
        margin: 0;
        padding: var(--kp-space-md, 0.75rem) var(--kp-space-md, 0.75rem);
        color: var(--muted-foreground);
    }

    .kp-diffview__plate {
        min-block-size: 8rem;
        border-radius: 0;
    }

    /* The changed words: weight and a line are the carriers, the deeper tint the second. Added words are underlined,
     * removed words struck through, so the two sides differ without colour. */
    .kp-diff__word {
        padding: 0;
        border-radius: 2px;
        background: hsl(from var(--success) h s l / 0.34);
        color: inherit;
        font-weight: 700;
        text-decoration: underline;
        text-decoration-thickness: 2px;
        text-underline-offset: 0.2em;
    }

    .kp-diff__line[data-kind='removed'] .kp-diff__word {
        background: hsl(from var(--destructive) h s l / 0.3);
        text-decoration-line: line-through;
        text-decoration-thickness: 2px;
    }

    /* The folded run and the "show the rest" row: a button across the diff's own three columns, so its words stand where
     * the code stands and a pointer finds it anywhere along the row. */
    .kp-diff__row-button {
        display: grid;
        grid-template-columns: 3rem 1ch minmax(0, 1fr);
        align-items: center;
        gap: 0.5rem;
        box-sizing: border-box;
        inline-size: 100%;
        min-block-size: 2rem;
        margin: 0;
        padding: 0.125rem 0.5rem;
        border: 0;
        border-block: 1px dashed var(--border);
        border-radius: 0;
        background: hsl(from var(--muted) h s l / 0.6);
        color: var(--muted-foreground);
        font: inherit;
        text-align: start;
        cursor: pointer;
    }

    .kp-diff__row-button:hover {
        background: var(--muted);
        color: var(--foreground);
    }

    .kp-diff__row-button + .kp-diff__row-button,
    .kp-diff__line + .kp-diff__row-button[aria-expanded='true'] {
        border-block-start-width: 0;
    }

    /* Three dots for a fold that is closed, one rule for a fold that is open. */
    .kp-diff__row-glyph {
        justify-self: end;
        inline-size: 1.25rem;
        block-size: 0.5rem;
        background: radial-gradient(circle, currentColor 1.5px, transparent 2px) 0 50% / 0.4rem 0.5rem repeat-x;
    }

    .kp-diff__row-button[aria-expanded='true'] > .kp-diff__row-glyph {
        background: linear-gradient(currentColor, currentColor) center / 100% 2px no-repeat;
    }

    .kp-diff__row-label {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    /* Reading: the file headers at their final size, the first with its lines, the busy card over them. */
    .kp-diffview__wait {
        display: grid;
        gap: var(--kp-diffview-gap);
        align-content: start;
        min-inline-size: 0;
    }

    .kp-diffview__head--wait {
        grid-template-columns: var(--kp-diffview-status) minmax(0, 1fr) 5rem;
        min-block-size: 2.75rem;
        padding-inline: var(--kp-space-md, 0.75rem);
    }

    .kp-diffview__wait-badge,
    .kp-diffview__wait-counts {
        block-size: 1.25rem;
    }

    .kp-diffview__wait-path {
        block-size: 1rem;
        max-inline-size: 60%;
    }

    .kp-diffview__body--wait {
        display: grid;
        gap: 0.5rem;
        padding: var(--kp-space-md, 0.75rem);
    }

    .kp-diffview__wait-line {
        block-size: 1rem;
    }

    .kp-diffview__wait-line:nth-child(3n + 2) {
        max-inline-size: 80%;
    }

    .kp-diffview__wait-line:nth-child(3n) {
        max-inline-size: 55%;
    }

    @container kp-diffview (max-width: 40rem) {
        /* The path takes a line of its own under the status and the counts; the blocks go (the numbers say it). */
        .kp-diffview__toggle {
            grid-template-columns: 1rem var(--kp-diffview-status) minmax(0, 1fr);
            grid-template-areas:
                'chevron status counts'
                'path path path';
            row-gap: var(--kp-space-xs, 0.25rem);
        }

        .kp-diffview__chevron {
            grid-area: chevron;
        }

        .kp-diffview__status {
            grid-area: status;
        }

        .kp-diffview__counts {
            grid-area: counts;
            justify-self: end;
        }

        .kp-diffview__path {
            grid-area: path;
        }

        .kp-diffview__proportion {
            display: none;
        }

        .kp-diffview__copy {
            min-block-size: 2.75rem;
        }

        .kp-diffview__bar {
            grid-template-columns: minmax(0, 1fr);
        }

        .kp-diffview__tools .kp-button {
            min-block-size: 2.75rem;
        }
    }

    @media (pointer: coarse) {
        .kp-diff__row-button {
            min-block-size: 2.75rem;
        }
    }

    /* Visually hidden, still announced. Used where a change is obvious on
 * screen and silent otherwise — a button whose own label changed, for
 * instance, which a screen reader does not report on its own. */
    .kp-sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        margin: -1px;
        padding: 0;
        overflow: hidden;
        white-space: nowrap;
        border: 0;
        clip-path: inset(50%);
    }

    /* --- Tree, reorder and split pane [TH45, TH46, TH55] ----------------- */

    .kp-tree,
    .kp-tree [role='group'] {
        margin: 0;
        padding-inline-start: 1rem;
        list-style: none;
    }

    .kp-tree {
        padding-inline-start: 0;
    }

    .kp-tree [role='treeitem'] {
        padding: 0.25rem 0.375rem;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        cursor: pointer;
        /* The indent per level is a knob; the React tree sets the depth and
     * the framework-free markup may set aria-level [KT6]. */
        padding-inline-start: calc(var(--kp-tree-inset, 0.375rem) + var(--kp-tree-depth, 0) * var(--kp-tree-indent, 1rem));
        /* The start inset is the row's own 0.375rem padding, which this
         * longhand used to overwrite with the depth alone: a root row's text
         * touched the edge of its selected wash and its hover plate (forest
         * and cyberpunk, Kenny 2026-10-12). A register with its own inset
         * (forest: 0.5rem) sets it, or overrides this longhand. */
        /* A file name with nowhere to break wraps inside its pane rather than
         * pushing it wider: 64 characters made a 320px pane 632px wide
         * [gap-12, DI11]. Inherited, so every level below has it too. */
        overflow-wrap: anywhere;
    }

    .kp-tree [role='treeitem']:hover {
        background: var(--muted);
    }

    /* The selected item is marked, and marked twice [gap-12, DI4]: a bar at
     * its start edge and a wash of the primary colour, plus the weight. It
     * painted exactly like its unselected sibling in all 22 themes.
     *
     * A branch holds its children inside its own element, so a background
     * would paint the whole subtree as selected. Both marks are gradients
     * sized to the item's own row instead — one line plus the row's block
     * padding — and the weight is handed back to the group below. */
    .kp-tree [role='treeitem'][aria-selected='true'] {
        background:
            linear-gradient(var(--kp-tree-selected-bar, var(--primary)) 0 0) no-repeat 0 0 / 3px calc(1lh + 0.5rem),
            linear-gradient(var(--kp-tree-selected, hsl(from var(--primary) h s l / 0.14)) 0 0) no-repeat 0 0 / 100% calc(1lh + 0.5rem);
        font-weight: 600;
    }

    .kp-tree [role='treeitem'][aria-selected='true'] [role='group'] {
        font-weight: 400;
    }

    /* The twisty is a second carrier beside aria-expanded, and it points the
 * way the branch will go rather than the way it is. */
    .kp-tree [role='treeitem'][aria-expanded]::before {
        content: var(--kp-glyph-closed, '▸');
        display: inline-block;
        width: 1em;
        color: var(--muted-foreground);
    }

    .kp-tree [role='treeitem'][aria-expanded='true']::before {
        content: var(--kp-glyph-open, '▾');
    }

    .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'],
    .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'] {
        display: none;
    }

    .kp-reorder {
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-reorder [data-kp-item] {
        display: flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.375rem 0.5rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        margin-block-end: 0.375rem;
        background: var(--card);
    }

    /* A real button, not a decorative grip: it has to be reachable by Tab or
 * the arrow keys have nothing to act on. */
    .kp-reorder [data-kp-handle] {
        padding: 0.125rem 0.375rem;
        border: 1px solid var(--border);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        color: var(--muted-foreground);
        font: inherit;
        cursor: grab;
    }

    /* The row under a held handle [gap-12]. js/structure.js writes
     * data-kp-dragging for as long as the pointer holds it, and nothing
     * answered it: in all 22 themes the row you held looked like the rows
     * you did not. The frame turns primary and dashed (a colour and a shape)
     * and the row lifts off the list; releasing takes all of it away. */
    .kp-reorder [data-kp-item][data-kp-dragging] {
        border-color: var(--primary);
        border-style: dashed;
        box-shadow: 0 6px 16px -8px hsl(from var(--foreground) h s l / 0.45);
    }

    .kp-reorder [data-kp-item][data-kp-dragging] [data-kp-handle] {
        cursor: grabbing;
    }

    .kp-split {
        display: grid;
        /* One custom property drives the whole layout, so the keyboard and
     * the pointer move the same thing. */
        grid-template-columns: var(--kp-split, 50%) auto 1fr;
        align-items: stretch;
        min-height: 8rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        overflow: hidden;
    }

    .kp-split__pane {
        padding: 0.75rem;
        overflow: auto;
    }

    .kp-split__separator {
        width: 0.5rem;
        border: 0;
        border-inline: 1px solid var(--border);
        background: var(--muted);
        cursor: col-resize;
    }

    .kp-split__separator:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring);
        outline-offset: -2px;
    }

    /* Top and bottom [gap-12]. js/structure.js has moved a horizontal split
     * with Up and Down since 3.0.0, but this stylesheet only ever set
     * columns, so data-kp-orientation="horizontal" drew a second left and
     * right split. The same custom property drives the rows. A register that
     * sets the separator's thickness as an inline size restates it here as
     * a block size, in its own value. */
    .kp-split[data-kp-orientation='horizontal'] {
        grid-template-columns: none;
        grid-template-rows: var(--kp-split, 50%) auto 1fr;
    }

    .kp-split[data-kp-orientation='horizontal'] > .kp-split__separator {
        width: auto;
        block-size: 0.5rem;
        border-inline: 0;
        border-block: 1px solid var(--border);
        cursor: row-resize;
    }

    /* --- Date picker [TH43] ---------------------------------------------- */

    .kp-datepicker {
        position: relative;
        display: flex;
        flex-wrap: wrap;
        align-items: end;
        gap: 0.5rem;
    }

    /* The calendar button on the line with its input [gap-11]. The input's
 * `inline-size: 100%` filled the wrapping row on its own, so the button
 * always fell to the next line. The label takes the row above, the input
 * the room that is left, and the button stays beside it; the React
 * channel wraps label and input in a .kp-field, which grows the same way. */
    .kp-datepicker > .kp-field__label {
        flex-basis: 100%;
    }

    .kp-datepicker > .kp-field__input,
    .kp-datepicker > .kp-field {
        flex: 1 1 var(--kp-datepicker-input-min, 8rem);
        inline-size: auto;
    }

    .kp-datepicker__panel {
        position: absolute;
        top: 100%;
        inset-inline-start: 0;
        z-index: var(--kp-z-popover, 20);
        margin-block-start: 0.25rem;
        padding: 0.75rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        box-shadow: 0 8px 24px hsl(from var(--foreground) h s l / 0.12);
    }

    /* Opened toward the inline start, hanging from the picker's inline end,
 * when the window has no room past it [Kenny's note of 2026-09-13]; the
 * module measures and sets the attribute (placeDatePanel). */
    .kp-datepicker__panel[data-kp-align='end'] {
        inset-inline-start: auto;
        inset-inline-end: 0;
    }

    /* An open calendar lives in the top layer, where no container's clip-path
 * or overflow reaches it (js/top-layer.js). js/datepicker.js places it in
 * window coordinates; what the popover's UA sheet gives every popover —
 * an inset of 0, auto margins, its own overflow and ink — is put back to
 * what the panel had. With no room below, it opens above the picker, with
 * `data-kp-overlay-side="above"` [fix-30]. */
    .kp-datepicker__panel:popover-open {
        position: fixed;
        inset: auto;
        margin: 0;
        margin-block-start: 0.25rem;
        overflow: visible;
    }

    .kp-datepicker__head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.5rem;
        margin-block-end: 0.5rem;
    }

    .kp-datepicker__title {
        font-weight: 600;
    }

    /* The title that opens the month or the year grid [scope-89]: still the
 * title to look at, so no button chrome of its own — only the day cell's
 * hover, which says it can be pressed. A register's title rule reaches it
 * through the same class. */
    button.kp-datepicker__title {
        padding: 0.125rem 0.375rem;
        /* The padding and border give the hover ground room without taking
         * room from the head: a span's width, so the day view keeps the size
         * it had (without this, nine themes' panels grew 12 to 14px). */
        margin-inline: calc(-0.375rem - 1px);
        border: 1px solid transparent;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        color: inherit;
        font: inherit;
        font-weight: 600;
        cursor: pointer;
    }

    button.kp-datepicker__title:hover {
        background: var(--muted);
    }

    .kp-datepicker__grid {
        display: grid;
        grid-template-columns: repeat(7, 2rem);
        gap: 0.125rem;
        text-align: center;
    }

    /* Twelve months or twelve years, three a row, filling the size the day
 * grid had: the module holds that size while they show, so the panel does
 * not jump under the pointer [scope-89]. */
    .kp-datepicker__grid:is([data-kp-view='months'], [data-kp-view='years']) {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        grid-template-rows: repeat(4, minmax(0, 1fr));
    }

    .kp-datepicker__weekday {
        padding-block: 0.25rem;
        color: var(--muted-foreground);
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-datepicker__day {
        padding: 0.25rem 0;
        border: 1px solid transparent;
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: none;
        color: inherit;
        font: inherit;
        font-variant-numeric: tabular-nums;
        cursor: pointer;
    }

    .kp-datepicker__day:hover {
        background: var(--muted);
    }

    /* The chosen day carries a border as well as a fill, so it is still the
 * chosen day when the fill is the same colour as the hover [DI4]. */
    .kp-datepicker__day[aria-selected='true'] {
        border-color: var(--border-strong);
        background: var(--primary);
        color: var(--primary-foreground);
    }

    /* A disabled day stays in the grid and says it is not a choice [gap-11]:
 * struck through in the muted ink, so it reads as unavailable without
 * relying on the colour, and it does not light up under the pointer. It
 * painted exactly like a day that could be chosen, and the only sign was
 * a click that did nothing. */
    .kp-datepicker__day[aria-disabled='true'] {
        color: var(--muted-foreground);
        text-decoration-line: line-through;
        cursor: not-allowed;
    }

    .kp-datepicker__day[aria-disabled='true']:hover {
        background: none;
    }

    /* --- Upload and wizard [TH44, TH48] ---------------------------------- */

    .kp-upload__zone {
        display: block;
        padding: 1.5rem;
        border: 2px dashed var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--muted);
        color: var(--muted-foreground);
        text-align: center;
        cursor: pointer;
    }

    /* The zone is the label of a visually hidden file input, so Tab lands on
 * the input and the base focus ring draws round an element nobody can see
 * [gap-11]. The zone wears the ring instead, the same two parts the base
 * layer draws: the contrast outline and the inner ring. */
    :focus-visible + .kp-upload__zone,
    [data-kp-upload]:has([data-kp-upload-input]:focus-visible) .kp-upload__zone {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
        box-shadow: 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }

    .kp-upload__zone[data-kp-dragging] {
        border-color: var(--primary);
        color: var(--foreground);
    }

    .kp-upload__list {
        margin: 0.75rem 0 0;
        padding: 0;
        list-style: none;
    }

    .kp-upload__file {
        display: grid;
        /* minmax(0, …): a name with nowhere to break gives way first, and the
     * size and the remove button stay whole [DI11]. */
        grid-template-columns: minmax(0, 1fr) auto auto;
        align-items: center;
        gap: 0.5rem;
        padding: 0.375rem 0.5rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        margin-block-end: 0.375rem;
    }

    .kp-upload__name {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    /* The remove button on the line with the name and the size [gap-11]. The
 * row has three columns and five children (name, size, bar, message,
 * button) in that order, so the button was auto-placed onto a row of its
 * own under the message. Placed, not moved in the markup: a screen reader
 * still meets it after the message, where the module writes it. */
    .kp-upload__file > [data-kp-upload-remove] {
        grid-row: 1;
        grid-column: -2;
    }

    .kp-upload__size {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* One element, filled by a gradient stop: a second element for the fill
 * would need its own width kept in step with aria-valuenow. */
    .kp-upload__bar {
        grid-column: 1 / -1;
        height: 0.25rem;
        border-radius: var(--kp-radius-pill, 999px);
        background: linear-gradient(to right, var(--primary) var(--kp-progress, 0%), var(--muted) var(--kp-progress, 0%));
    }

    .kp-upload__message {
        grid-column: 1 / -1;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-upload__file[data-state='error'] {
        border-color: var(--destructive);
    }

    .kp-upload__file[data-state='error'] .kp-upload__message {
        color: var(--destructive);
    }

    /* The frame a register draws around the wizard needs room inside it:
 * without padding the step list, the step and the buttons touched the
 * border in every theme [scope-60, held-60]. A knob, 1rem by default. */
    .kp-wizard {
        padding: var(--kp-wizard-padding, 1rem);
    }

    .kp-wizard__steps {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin: 0 0 1rem;
        padding: 0;
        list-style: none;
        counter-reset: kp-step;
    }

    .kp-wizard__steps li {
        display: flex;
        align-items: center;
        gap: 0.375rem;
        color: var(--muted-foreground);
        counter-increment: kp-step;
    }

    .kp-wizard__steps li::before {
        content: counter(kp-step);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 1.5rem;
        height: 1.5rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--kp-radius-pill, 999px);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    /* The current step is marked by weight AND by the filled circle, and
 * aria-current="step" carries it for everyone else [DI4]. */
    .kp-wizard__steps li[data-state='current'] {
        color: var(--foreground);
        font-weight: 600;
    }

    .kp-wizard__steps li[data-state='current']::before {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
    }

    .kp-wizard__steps li[data-state='done']::before {
        content: var(--kp-glyph-check, '✓');
        border-color: var(--success);
        color: var(--success);
    }

    .kp-wizard__actions {
        display: flex;
        gap: 0.5rem;
        margin-block-start: 1rem;
    }

    .kp-wizard [data-kp-step]:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring);
        outline-offset: 4px;
    }

    /* --- Colour picker [TH57] -------------------------------------------- */

    /* A channel is a label and a slider that lay out as siblings of the
 * others: the wrapper contributes nothing to the box tree. */
    .kp-colorpicker__channel {
        display: inline-flex;
    }

    .kp-colorpicker {
        display: grid;
        grid-template-columns: auto 1fr;
        align-items: center;
        gap: 0.5rem 0.75rem;
        max-width: var(--kp-colorpicker-max-width, 22rem);
    }

    /* The sliders wear the ink and no ground of their own: a range has no
 * text, but the browser gives it a colour and, in a dark colour scheme, a
 * grey background — both of which the foreign-colour test reads [KT8]. */
    .kp-colorpicker input {
        color: inherit;
        background: transparent;
    }

    .kp-colorpicker__swatch {
        grid-column: 1;
        width: 2.5rem;
        height: 2.5rem;
        /* A boundary, because a pale swatch on a pale card is otherwise an
     * invisible square [DI4]. */
        border: 1px solid var(--border-strong);
        border-radius: var(--radius, 0.5rem);
    }

    .kp-colorpicker__value {
        grid-column: 2;
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-colorpicker__contrast {
        grid-column: 1 / -1;
        margin: 0;
        color: var(--destructive);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The verdict is in the text; the colour is the second carrier, never the
 * only one [DI4]. */
    .kp-colorpicker[data-kp-contrast-ok] .kp-colorpicker__contrast {
        color: var(--muted-foreground);
    }

    /* --- Movable grid layout [TH56] -------------------------------------- */

    /* The box the grid measures itself against [TH104, AR24].
 *
 * A container query styles a container's CONTENTS, never the container
 * itself, and the rule that has to change is `grid-template-columns` on
 * the grid — so the query needs an element one level up.
 * components/canvas.jsx renders this itself (`wrap`, default true);
 * markup written by hand adds it, which is what MIGRATION.md's 4.0.0
 * section is for. */
    .kp-grid-wrap {
        container: kp-grid / inline-size;
        /* The same floor as .kp-table-wrap, for the same reason [R3-CQ, KT6]. */
        min-inline-size: var(--kp-grid-wrap-min, auto);
    }

    .kp-grid {
        display: grid;
        grid-template-columns: repeat(var(--kp-grid-columns, 6), 1fr);
        grid-auto-rows: 4rem;
        gap: 0.5rem;
    }

    .kp-grid__tile {
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 0.5rem;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground);
        overflow: hidden;

        /* The tile's place on the grid, derived here from four numbers the
     * module writes [AR31]. Up to 4.0.0 js/gridlayout.js and
     * components/canvas.jsx wrote `grid-column` and `grid-row`
     * themselves, as inline styles — which beat any rule in any layer,
     * so the narrow rule below could never win once the grid was
     * attached, and attaching is the only way the grid is used.
     * Measured at 320px on 3.2.0: before attach the tile read
     * `1 / -1` at 302px wide, after attach `1 / span 2` at 241px.
     *
     * A custom property is a VALUE, not a declaration: the module still
     * says where the tile is, and the stylesheet still decides what
     * that means. The defaults are the initial placement, so a tile
     * nothing has attached to sits exactly where it did before. */
        grid-column: var(--kp-tile-x, auto) / span var(--kp-tile-w, 1);
        grid-row: var(--kp-tile-y, auto) / span var(--kp-tile-h, 1);
    }

    /* The tile is a tab stop, because moving it is a keyboard gesture first
 * and a drag second. */
    .kp-grid__tile:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring);
        outline-offset: 2px;
    }

    /* In a narrow BOX the arrangement stops being an arrangement: one
 * column, source order. A six-column dashboard at 320px is six columns of
 * nothing [DI11], and so is one in a 320px panel on a wide page — which
 * is why the width that decides is the wrapper's rather than the
 * window's since 4.0.0 [TH104]. The media query this replaced is gone
 * rather than kept beside it: two mechanisms that can disagree are worse
 * than either. */
    @container kp-grid (max-width: 40rem) {
        /* 40rem is a contract value [TH26], the same number the table's card
     * query and the nav bar use. It is the number this block used as a
     * media query up to 3.2.0, so no grid changes shape at a width it did
     * not before. */
        .kp-grid {
            grid-template-columns: 1fr;
        }

        .kp-grid__tile {
            grid-column: 1 / -1;
            /* Source order, so two tiles that shared a row do not land on
         * top of each other in the single column. The height stays the
         * tile's own. */
            grid-row: auto / span var(--kp-tile-h, 1);
        }
    }

    /* A surface keeps its content off its own edges [Kenny, 2026-09-15]. A
     * surface paints a ground (css/_rules.css), and in every theme the
     * heading, the prose and the first button stood on the ground's very
     * edge: 0px between the text and the colour change, on the left where
     * the eye starts a line. The room is the package's, in every theme, on
     * the inline axis only — the block axis is the section rhythm's. The
     * room gives way before the content does: a surface of 20rem or less (a
     * 320px phone, where the concept page's 16rem grid already fills the
     * surface to the pixel) keeps none, and from 22rem it keeps the whole lg
     * step. Knob: --kp-surface-padding-inline (the lg step, from 22rem
     * wide). Its companion,
     * data-kp-surface-align="center", sits beside the ground in
     * css/_rules.css, because it reaches the layout layer's row. */
    [data-kp-surface] {
        padding-inline: var(--kp-surface-padding-inline, max(0px, min(var(--kp-space-lg, 1rem), (100% - 20rem) / 2)));
    }

    /* --- Alarm [scope-94] -------------------------------------------------
 * A full-screen dramatic alert: a code line, one huge word, the reason
 * under it and one way out, over a plate that takes the whole window. The
 * prototype Kenny approved on 2026-09-15 (research/alarm/demo.html), with
 * the full drama in every theme: nothing here names a theme, every paint is
 * a token or a relative colour of one, so each theme's own --destructive,
 * --primary and faces make it that theme's alarm, and each register adds its
 * own voice on the knobs below. js/alarm.js builds it and opens it with
 * showModal(), which puts it in the top layer and makes the page inert.
 *
 * The default arrives whole [scope-98]: the plate fades in, the panel
 * settles, the headline arrives in one piece and the reason follows. The
 * glitch is not the default any more — Kenny, judging formal's and pastel's
 * portraits: "het alarm geeft nog altijd het glitch effect, dat enkel bij
 * cyberpunk thuishoort". Its parts stay in the markup and its keyframes stay
 * here, for a register that opts in (cyberpunk's does, and only cyberpunk's):
 * the split copies (.kp-alarm__glyphs::before/::after, content: none until a
 * register gives them attr(data-text)), the letter cells' noise glyphs
 * (.kp-alarm__char::before/::after, content: none until attr(data-n1) and
 * attr(data-n2)), the caret (.kp-alarm__detail::after, display: none), the
 * scanlines and the sweeping band (.kp-alarm__scan, a vignette alone by
 * default; its ::after has no content), and the hazard stripes (a
 * transparent --kp-alarm-stripe by default); and the keyframes
 * kp-alarm-jitter, kp-alarm-slice-in, kp-alarm-slice, kp-alarm-decode-letter,
 * kp-alarm-decode-noise, kp-alarm-caret, kp-alarm-march and kp-alarm-sweep.
 * The panel's flicker is cyberpunk's own keyframe since scope-100
 * (kp-alarm-cyberpunk-flicker, in its register). tests/alarm.spec.mjs holds
 * that they run in cyberpunk alone.
 *
 * The knobs [KT6], the colours defaulting to the prototype's dark plate:
 * --kp-alarm-ground (the plate), --kp-alarm-ink (the headline, the frame,
 * the bars), --kp-alarm-soft (the detail line), --kp-alarm-split (the second
 * colour of the glitch split), --kp-alarm-on-ink (words on the ink: the
 * button), --kp-alarm-glow (the frame's breathing inner glow),
 * --kp-alarm-halo (the glow around the headline), --kp-alarm-scan (the
 * scanlines), --kp-alarm-vignette (the darkened edges), --kp-alarm-stripe
 * (the hazard bars), --kp-alarm-bar (their height), --kp-alarm-frame (the
 * frame's border), the
 * headline's --kp-alarm-title-font, --kp-alarm-title-size,
 * --kp-alarm-title-case and --kp-alarm-title-tracking, and the panel's
 * --kp-alarm-panel-ground, --kp-alarm-panel-border, --kp-alarm-panel-shadow,
 * --kp-alarm-panel-padding and --kp-alarm-panel-radius, for a theme whose
 * alarm is a box (a 1995 error window, a slammed stamp). --kp-alarm-left and
 * --kp-alarm-left-step are written by the script: the share of the time
 * left, continuous and in whole seconds. */
    .kp-alarm {
        container-type: inline-size;
        position: fixed;
        inset: 0;
        box-sizing: border-box;
        inline-size: 100%;
        block-size: 100%;
        max-inline-size: none;
        max-block-size: none;
        margin: 0;
        padding: calc(var(--kp-alarm-bar, 0.9rem) + 2.5rem) 1.5rem;
        border: 0;
        border-radius: 0;
        overflow: hidden auto;
        background: var(--kp-alarm-ground, hsl(from var(--destructive) h calc(s * 0.6) 5% / 0.95));
        color: var(--kp-alarm-ink, hsl(from var(--destructive) h s max(l, 60)));
        font-family: var(--theme-font-body);
        text-align: center;
        box-shadow: none;
        outline: none;
    }

    .kp-alarm::backdrop {
        background: transparent;
    }

    .kp-alarm:is([open], [data-kp-alarm-inline]) {
        display: grid;
        place-items: center;
    }

    /* A held-open frame for a page that shows the alarm without raising it
     * (the catalogue, a style guide): the same markup in the flow of the
     * page, not in the top layer, as tall as its words need and at least a
     * small screen's worth. Mark it inert: its button is a picture. */
    .kp-alarm[data-kp-alarm-inline] {
        position: relative;
        inset: auto;
        block-size: auto;
        min-block-size: 22rem;
        padding: calc(var(--kp-alarm-bar, 0.9rem) + 1.75rem) 1.75rem;
    }

    /* The frame: a hairline box inside the bars. */
    .kp-alarm::before {
        content: '';
        position: absolute;
        inset: calc(var(--kp-alarm-bar, 0.9rem) + 0.75rem) 0.75rem;
        border: var(--kp-alarm-frame, 2px solid);
        pointer-events: none;
    }

    /* The glow the frame breathes with. */
    .kp-alarm::after {
        content: '';
        position: absolute;
        inset: 0;
        box-shadow: inset 0 0 7rem var(--kp-alarm-glow, hsl(from var(--destructive) h s max(l, 45) / 0.5));
        pointer-events: none;
    }

    .kp-alarm__scan,
    .kp-alarm__bars {
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The darkened edges. The scanlines are a part a register opts into: it
     * restates this background with a repeating gradient of --kp-alarm-scan
     * over the vignette [scope-98]. */
    .kp-alarm__scan {
        background: radial-gradient(ellipse at center, transparent 50%, var(--kp-alarm-vignette, hsl(from var(--destructive) h s 2% / 0.7)));
    }

    /* A faint band that sweeps down the plate: the geometry, for a register
     * that opts in with content: '' and kp-alarm-sweep [scope-98]. */
    .kp-alarm__scan::after {
        content: none;
        position: absolute;
        inset-inline: 0;
        block-size: 18%;
        inset-block-start: -18%;
        background: linear-gradient(to bottom, transparent, var(--kp-alarm-scan, hsl(from var(--destructive) h s max(l, 50) / 0.09)), transparent);
    }

    /* The hazard bars, top and bottom: transparent unless a register names
     * --kp-alarm-stripe, still unless it opts into kp-alarm-march [scope-98]. */
    .kp-alarm__bars::before,
    .kp-alarm__bars::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        block-size: var(--kp-alarm-bar, 0.9rem);
        background: repeating-linear-gradient(-45deg, var(--kp-alarm-stripe, transparent) 0 1rem, transparent 1rem 2rem);
        background-size: 2.8284rem 100%;
    }

    .kp-alarm__bars::before {
        inset-block-start: 0;
    }

    .kp-alarm__bars::after {
        inset-block-end: 0;
    }

    .kp-alarm__panel {
        position: relative;
        z-index: 1;
        display: grid;
        justify-items: center;
        gap: clamp(0.5rem, 1.6cqi, 1.25rem);
        box-sizing: border-box;
        inline-size: min(100%, 72rem);
        padding: var(--kp-alarm-panel-padding, 0);
        border: var(--kp-alarm-panel-border, 0);
        border-radius: var(--kp-alarm-panel-radius, 0);
        background: var(--kp-alarm-panel-ground, transparent);
        box-shadow: var(--kp-alarm-panel-shadow, none);
    }

    .kp-alarm__code {
        margin: 0;
        font-family: var(--theme-font-mono, monospace);
        font-size: clamp(0.7rem, 1.3cqi, 0.95rem);
        letter-spacing: 0.3em;
        text-transform: uppercase;
    }

    .kp-alarm__title {
        margin: 0;
        font-family: var(--kp-alarm-title-font, var(--theme-font-display, var(--theme-font-body)));
        font-size: var(--kp-alarm-title-size, clamp(2.5rem, 12cqi, 10rem));
        font-weight: 700;
        line-height: 0.95;
        letter-spacing: var(--kp-alarm-title-tracking, 0.04em);
        text-transform: var(--kp-alarm-title-case, uppercase);
        overflow-wrap: anywhere;
        text-wrap: balance;
        text-shadow: 0 0 0.3em var(--kp-alarm-halo, hsl(from var(--destructive) h s max(l, 50) / 0.55));
    }

    .kp-alarm__glyphs {
        position: relative;
        display: inline-block;
    }

    /* The chromatic split: two copies of the words, clipped to nothing at
     * rest and to thin bands during a burst. A part a register opts into
     * with content: attr(data-text) [scope-98]; the default draws neither. */
    .kp-alarm__glyphs::before,
    .kp-alarm__glyphs::after {
        content: none;
        position: absolute;
        inset: 0;
        clip-path: inset(50% 0 50% 0);
        text-shadow: none;
        pointer-events: none;
    }

    .kp-alarm__glyphs::before {
        color: var(--kp-alarm-split, hsl(from var(--primary) h s max(l, 60)));
        translate: -0.04em 0;
    }

    .kp-alarm__glyphs::after {
        color: var(--kp-alarm-soft, hsl(from var(--destructive) h calc(s * 0.4) 86));
        translate: 0.04em 0;
    }

    .kp-alarm__word {
        white-space: nowrap;
    }

    .kp-alarm__char {
        position: relative;
    }

    /* The two noise glyphs of a letter cell, drawn over the letter, so the
     * layout never changes while it decodes. A part a register opts into with
     * content: attr(data-n1) and attr(data-n2) [scope-98]. */
    .kp-alarm__char::before,
    .kp-alarm__char::after {
        position: absolute;
        inset-block-start: 0;
        inset-inline-start: 0;
        opacity: 0;
        pointer-events: none;
    }

    .kp-alarm__char::before,
    .kp-alarm__char::after {
        content: none;
    }

    .kp-alarm__detail {
        max-inline-size: 60ch;
        margin: 0;
        color: var(--kp-alarm-soft, hsl(from var(--destructive) h calc(s * 0.4) 86));
        font-family: var(--theme-font-mono, monospace);
        font-size: clamp(0.85rem, 1.9cqi, 1.35rem);
        line-height: 1.45;
        text-wrap: pretty;
    }

    /* A caret at the end of the line: one character cell. A part a register
     * opts into with display: inline-block [scope-98]. */
    .kp-alarm__detail::after {
        content: '';
        display: none;
        inline-size: 0.6em;
        block-size: 1.05em;
        margin-inline-start: 0.2em;
        vertical-align: text-bottom;
        background: currentColor;
    }

    .kp-alarm__actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        align-items: center;
        gap: 0.75rem 1rem;
        margin-block-start: clamp(0.5rem, 2cqi, 1.5rem);
        font-size: 0.8rem;
    }

    .kp-alarm__hint {
        font-family: var(--theme-font-mono, monospace);
        letter-spacing: 0.08em;
    }

    /* The one way out: a .kp-button, so the register keeps its button's
     * shape (a notch, a radius, a bevel); the paint is the alarm's, and every
     * register restates it, because each repaints its buttons in the later
     * layer. */
    .kp-alarm__ack {
        min-inline-size: 14rem;
        border: 2px solid var(--kp-alarm-ink, hsl(from var(--destructive) h s max(l, 60)));
        background: var(--kp-alarm-ink, hsl(from var(--destructive) h s max(l, 60)));
        color: var(--kp-alarm-on-ink, hsl(from var(--destructive) h s 6%));
        font-family: var(--theme-font-mono, monospace);
        letter-spacing: 0.2em;
        text-transform: uppercase;
    }

    .kp-alarm__ack:is(:hover, :focus-visible) {
        background: var(--kp-alarm-on-ink, hsl(from var(--destructive) h s 6%));
        color: var(--kp-alarm-ink, hsl(from var(--destructive) h s max(l, 60)));
    }

    .kp-alarm :is(.kp-alarm__ack, .kp-alarm__keep):focus-visible {
        outline: 3px solid var(--kp-alarm-soft, hsl(from var(--destructive) h calc(s * 0.4) 86));
        outline-offset: 4px;
    }

    .kp-alarm__countdown {
        display: grid;
        gap: 0.5rem;
        justify-items: center;
        inline-size: min(100%, 36rem);
        margin-block-start: clamp(0.5rem, 2cqi, 1.5rem);
        font-family: var(--theme-font-mono, monospace);
        font-size: 0.8rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }

    .kp-alarm__track {
        display: block;
        inline-size: 100%;
        block-size: 0.375rem;
        background: color-mix(in srgb, currentColor 22%, transparent);
    }

    /* The bar reads as time running out: it shrinks towards the start. Under
     * reduced motion it steps a whole second at a time. */
    .kp-alarm__fill {
        display: block;
        block-size: 100%;
        background: currentColor;
        transform: scaleX(var(--kp-alarm-left-step, 1));
        transform-origin: left center;
    }

    .kp-alarm__keep {
        border-color: currentColor;
        background: transparent;
        color: inherit;
    }

    .kp-alarm:not([data-kp-alarm-mode='auto']) .kp-alarm__countdown,
    .kp-alarm[data-kp-alarm-mode='auto'] .kp-alarm__actions {
        display: none;
    }

    /* Motion, only when the reader has not asked for less, and never on a
     * held-open frame marked still. The default arrives whole [scope-98]; the
     * budget per one-second window (WCAG 2.3.1 allows three flashes; each
     * keyframe has its row in TIMINGS in js/effects.js):
     *   kp-alarm-ground-in    the plate, 0 -> 1, once
     *   kp-alarm-settle       the panel, 0 -> 1 with a rise and a scale, once
     *   kp-alarm-arrive       the headline, whole, 0 -> 1 from a larger size, once
     *   kp-alarm-detail-in    the reason, 0 -> 1, once
     *   kp-alarm-pulse        one half-cycle of the glow per 1.4 s
     * The glitch keyframes below (jitter, slice-in, slice,
     * decode-letter, decode-noise, caret, march, sweep) run only where a
     * register names them. Under reduced motion nothing runs: the words are
     * there at once, and the drama is the plate, the glow at full strength,
     * the frame and the size. The rendered frames are measured in
     * tests/alarm.spec.mjs. */
    @media (prefers-reduced-motion: no-preference) {
        .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-alarm-ground-in 240ms ease-out both;
        }

        .kp-alarm:not([data-kp-alarm-motion='still'])::after {
            animation: kp-alarm-pulse 1400ms ease-in-out infinite alternate;
        }

        .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__panel {
            animation: kp-alarm-settle 520ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
        }

        .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__title {
            animation: kp-alarm-arrive 480ms 120ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
        }

        .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__detail {
            animation: kp-alarm-detail-in 300ms 360ms ease-out both;
        }

        .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__fill {
            transform: scaleX(var(--kp-alarm-left, 1));
            transition: transform 100ms linear;
        }
    }

    @keyframes kp-alarm-settle {
        0% {
            opacity: 0;
            translate: 0 1.25rem;
            scale: 0.98;
        }
        100% {
            opacity: 1;
            translate: 0 0;
            scale: 1;
        }
    }

    @keyframes kp-alarm-arrive {
        0% {
            opacity: 0;
            scale: 1.06;
        }
        100% {
            opacity: 1;
            scale: 1;
        }
    }

    @keyframes kp-alarm-ground-in {
        0% {
            opacity: 0;
        }
        100% {
            opacity: 1;
        }
    }

    @keyframes kp-alarm-pulse {
        0% {
            opacity: 0.4;
        }
        100% {
            opacity: 1;
        }
    }

    @keyframes kp-alarm-jitter {
        0%,
        94% {
            opacity: 1;
            translate: 0 0;
        }
        95% {
            opacity: 0.6;
            translate: -0.03em 0;
        }
        97% {
            opacity: 1;
            translate: 0.02em 0;
        }
        99% {
            translate: 0 0;
        }
    }

    @keyframes kp-alarm-slice-in {
        0% {
            clip-path: inset(10% 0 72% 0);
        }
        20% {
            clip-path: inset(62% 0 22% 0);
        }
        40% {
            clip-path: inset(34% 0 52% 0);
        }
        60% {
            clip-path: inset(80% 0 6% 0);
        }
        80%,
        100% {
            clip-path: inset(50% 0 50% 0);
        }
    }

    @keyframes kp-alarm-slice {
        0%,
        94% {
            clip-path: inset(50% 0 50% 0);
        }
        95% {
            clip-path: inset(20% 0 66% 0);
        }
        97% {
            clip-path: inset(58% 0 28% 0);
        }
        99% {
            clip-path: inset(50% 0 50% 0);
        }
    }

    @keyframes kp-alarm-decode-letter {
        0% {
            color: transparent;
            text-shadow: none;
        }
    }

    @keyframes kp-alarm-decode-noise {
        0% {
            opacity: 1;
        }
        100% {
            opacity: 0;
        }
    }

    @keyframes kp-alarm-detail-in {
        0% {
            opacity: 0;
        }
        100% {
            opacity: 1;
        }
    }

    @keyframes kp-alarm-caret {
        0%,
        49.9% {
            opacity: 1;
        }
        50%,
        100% {
            opacity: 0;
        }
    }

    @keyframes kp-alarm-march {
        100% {
            background-position-x: 2.8284rem;
        }
    }

    @keyframes kp-alarm-sweep {
        100% {
            translate: 0 680%;
        }
