        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height) var(--kp-entity-action-row);
    }

    /* No actions in the data: no row for them, and no gap left behind. */
    .kp-card--entity[data-kp-entity-actions='none'] {
        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height);
    }

    .kp-entity-grid[data-kp-density='compact'] > .kp-card--entity[data-kp-entity-actions='none'],
    .kp-card--entity[data-kp-density='compact'][data-kp-entity-actions='none'] {
        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height);
    }

    .kp-card--entity > .kp-entity__actions[hidden] {
        display: none !important;
    }

    .kp-entity-grid[data-kp-density='compact'] > .kp-card--entity > .kp-entity__figures,
    .kp-card--entity[data-kp-density='compact'] > .kp-entity__figures {
        display: none;
    }

    .kp-card--entity.is-ticked {
        border-color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
    }

    .kp-card--entity.is-cursor {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast, var(--focus-ring));
        outline-offset: 2px;
    }

    .kp-entity__id .kp-idmark {
        flex: none;
    }

    .kp-entity__name {
        flex: 1 1 auto;
        min-inline-size: 0;
        color: inherit;
        font-weight: 600;
        overflow-wrap: anywhere;
        text-decoration: none;
    }

    a.kp-entity__name::after {
        content: '';
        position: absolute;
        inset: 0;
    }

    a.kp-entity__name:hover {
        text-decoration: underline;
    }

    .kp-entity__vmid {
        color: var(--muted-foreground);
        font-family: var(--font-mono, ui-monospace, monospace);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-entity__vmid:empty {
        display: none;
    }

    .kp-entity__state {
        flex: none;
    }

    .kp-entity__figures {
        flex-wrap: nowrap;
        gap: var(--kp-space-md, 0.75rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-entity__value {
        color: var(--foreground);
        font-variant-numeric: tabular-nums;
    }

    .kp-entity__none {
        color: var(--muted-foreground);
    }

    .kp-entity__flags {
        flex-wrap: nowrap;
    }

    .kp-entity__flag {
        flex: none;
    }

    /* The "+N" opener never shrinks below its text: squeezed in the nowrap flag row it broke "+2" over two lines. */
    .kp-entity__more-flags {
        flex: none;
    }

    .kp-entity__plus {
        white-space: nowrap;
    }

    .kp-entity__meters {
        display: grid !important;
        grid-template-columns: auto minmax(0, 1fr) auto;
        grid-auto-rows: var(--kp-entity-row, 1.5rem);
        column-gap: var(--kp-space-sm, 0.5rem);
        align-items: center;
    }

    .kp-entity__meter {
        grid-column: 1 / -1;
        display: grid;
        grid-template-columns: subgrid;
        align-items: center;
        font-size: var(--kp-text-xs, 0.75rem);
        color: var(--muted-foreground);
    }

    .kp-entity__meter-value {
        font-variant-numeric: tabular-nums;
        text-align: end;
        white-space: nowrap;
    }

    .kp-entity__actions {
        display: grid !important;
        grid-template-columns: repeat(var(--kp-entity-cols, 4), minmax(min-content, 1fr));
        gap: var(--kp-space-sm, 0.5rem);
        align-items: center;
        padding-block-start: var(--kp-entity-actions-gap, var(--kp-space-md, 0.75rem));
    }

    .kp-entity__actions > :is(.kp-button, .kp-menu-button, .kp-reason),
    .kp-entity__tick,
    .kp-entity__star,
    .kp-entity__description > .kp-entity__retry,
    .kp-entity__more-flags {
        position: relative;
        z-index: 1;
    }

    .kp-entity__actions .kp-button,
    .kp-entity__actions .kp-menu-button {
        inline-size: 100%;
    }

    .kp-entity__actions .kp-button {
        overflow-wrap: normal;
    }

    .kp-entity__actions > .kp-entity__retry {
        grid-column: 1 / -1;
    }

    .kp-entity__bone {
        display: block;
        inline-size: 70%;
        block-size: 1rem;
    }

    .kp-card--ghost {
        pointer-events: none;
    }

    /* --- The trend row: a line over the meters' columns --- */
    .kp-entity__trend-line {
        display: flex;
        align-items: center;
        min-inline-size: 0;
    }

    .kp-entity__trend-line > .kp-entity__none {
        font-size: var(--kp-text-xs, 0.75rem);
    }

    .kp-entity__spark {
        display: block;
        inline-size: 100%;
        block-size: calc(var(--kp-entity-row, 1.5rem) - 0.25rem);
        overflow: visible;
        color: var(--kp-entity-spark, var(--chart-1));
    }

    .kp-entity__spark-line {
        fill: none;
        stroke: currentColor;
        stroke-width: 1.6;
        stroke-linejoin: round;
        vector-effect: non-scaling-stroke;
    }

    .kp-entity__spark-area {
        fill: currentColor;
        opacity: 0.12;
    }

    /* --- The favourite star: a small square toggle at the end of the identity row, above the card's link --- */
    .kp-card--entity .kp-button.kp-entity__star[data-kp-toggle] {
        flex: none;
        inline-size: 1.75rem;
        block-size: 1.75rem;
        min-block-size: 0;
        padding: 0 !important;
        color: var(--muted-foreground);
    }

    .kp-card--entity .kp-button.kp-entity__star[data-kp-toggle][aria-pressed='true'] {
        color: var(--kp-toggle-on-ink, var(--background)) !important;
    }

    .kp-entity__star-glyph {
        inline-size: 1.0625rem;
        block-size: 1.0625rem;
        fill: none;
        stroke: currentColor;
        stroke-width: 1.75;
        stroke-linejoin: round;
    }

    .kp-entity__star[aria-pressed='true'] .kp-entity__star-glyph {
        fill: currentColor;
    }

    /* --- The tile: four rows, one link over all of them --- */
    .kp-entity-grid[data-kp-entity-kind='tile'] {
        --kp-entity-min: 16rem;
    }

    .kp-card--entity[data-kp-entity-tile][data-kp-entity-tile] {
        grid-template-rows: minmax(1.75rem, auto) auto minmax(var(--kp-entity-tile-body, 2.75rem), 1fr);
        grid-auto-rows: auto;
        align-content: stretch;
    }

    .kp-card--entity[data-kp-entity-tile]:has(a.kp-entity__name):hover {
        border-color: var(--ring);
    }

    .kp-card--entity[data-kp-entity-tile]:has(a.kp-entity__name:focus-visible) {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast, var(--focus-ring));
        outline-offset: 2px;
    }

    .kp-card--entity[data-kp-entity-tile] a.kp-entity__name:focus-visible {
        outline: none;
    }

    .kp-entity__external {
        flex: none;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-entity__tile-state {
        font-size: var(--kp-text-sm, 0.8125rem);
        color: var(--muted-foreground);
    }

    .kp-card--entity > .kp-entity__description,
    .kp-card--entity > .kp-entity__lines {
        align-items: flex-start;
    }

    .kp-entity__description {
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-entity__description > .kp-entity__retry {
        flex: none;
    }

    .kp-entity__description:has(> .kp-entity__retry) {
        flex-direction: column;
        justify-content: center;
        align-items: flex-start;
    }

    .kp-entity__tile-failed {
        font-weight: 600;
        overflow-wrap: anywhere;
    }

    .kp-card--entity > .kp-entity__lines {
        flex-direction: column;
        gap: var(--kp-space-xs, 0.25rem);
        min-block-size: 1lh;
        font-size: var(--kp-text-xs, 0.75rem);
        color: var(--muted-foreground);
        font-variant-numeric: tabular-nums;
    }

    .kp-card--entity > .kp-entity__lines[hidden] {
        display: none !important;
    }

    .kp-entity__line {
        overflow-wrap: anywhere;
    }
}

/* --- State plates in the last layer [t56-statefix-1018] ---------------------------------------------------------------
 * Kenny's rule (2026-10-17 15:37, docs/RULES.md): an empty or failed area is prominent, centred in the component, at heading
 * size, with a normal-size action, and fills the footprint. A register sets the title of a card's note by its own selector
 * (solstice 20 px, titanium 18 px, nostromo 16 px, brutalism and deco their capitals) and a register beats kp.components, so
 * the plate is stated here, in the last layer, as the tour's dim and the side navigation's variants are; a utility still wins.
 * Every rule hangs on the plate's own class, so nothing here touches a card that does not fail.
 *
 * A card's failure: the destructive alert turned into the state plate. Its words are centred in the stage, its title at
 * `--kp-stateplate-text` (heading size, the same knob the empty plate and the picker's plates read), its sentence at body size,
 * and its Try again is a normal button (2.25rem) under them. The card grows to hold it: a heading, a sentence and a button need
 * more room than one alert row did. */
@layer kp.layout {
    .kp-card__state:has(> .kp-card__failure) {
        align-content: stretch;
    }

    .kp-card__state > .kp-card__failure {
        display: grid;
        place-content: center;
        justify-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        box-sizing: border-box;
        inline-size: 100%;
        block-size: 100%;
        padding: var(--kp-space-lg, 1.5rem);
        font-size: var(--kp-stateplate-text, clamp(1.125rem, 1rem + 0.6vw, 1.5rem));
        line-height: 1.35;
        text-align: center;
        text-wrap: balance;
    }

    .kp-card__failure > .kp-alert__body {
        justify-items: center;
        flex: none;
    }

    .kp-card__state > .kp-card__failure .kp-card__state-title {
        font-size: var(--kp-stateplate-text, clamp(1.125rem, 1rem + 0.6vw, 1.5rem));
        font-weight: 600;
        line-height: 1.35;
    }

    .kp-card__failure .kp-card__state-text {
        font-size: var(--kp-text-md, 1rem);
    }

    .kp-card__failure > .kp-card__retry {
        min-block-size: 2.25rem;
    }
}

/* A failed operations page [t56-statefix-1018, S12]. `data-kp-ops-failed` on `.kp-ops`, switchable at runtime (an attribute change
 * is all it takes, there is no script): `plate` (the default) shows the failure whole, the alert taking the page's body, centred at
 * heading size and holding the height the page had (js/footprint.js), the cards of the last read hidden; `keep` is what the page did
 * before, its cards staying under one attention band on top (the page says "what is shown is from earlier"). It needs the page to
 * write `data-kp-state="error"` on `.kp-ops`. In the last layer, because a register styles `.kp-attention__item` and beats
 * kp.components. */
@layer kp.layout {
    .kp-ops[data-kp-state='error']:not([data-kp-ops-failed='keep']) > :is(.kp-ops__kpis, .kp-ops__toolbar, .kp-ops__body) {
        display: none;
    }

    .kp-ops[data-kp-state='error']:not([data-kp-ops-failed='keep']) > .kp-ops__attention {
        display: grid;
        flex: 1 1 auto;
        min-block-size: 24rem;
    }

    .kp-ops[data-kp-state='error']:not([data-kp-ops-failed='keep']) .kp-attention__item {
        grid-template-columns: minmax(0, 1fr);
        place-content: center;
        justify-items: center;
        text-align: center;
        padding: var(--kp-space-xl, 2rem);
    }

    .kp-ops[data-kp-state='error']:not([data-kp-ops-failed='keep']) .kp-attention__text > strong {
        font-size: var(--kp-stateplate-text, clamp(1.125rem, 1rem + 0.6vw, 1.5rem));
    }

    .kp-ops[data-kp-state='error']:not([data-kp-ops-failed='keep']) .kp-attention__actions {
        justify-content: center;
    }
}

/* A waiting gallery tile keeps the final tile's square footprint [t56-statefix-1018]. `block-size: auto` on `.kp-gallery__tile.kp-skeleton`
 * (kp.components) lets the tile's aspect ratio make it as tall as it is wide, but a register sets `.kp-skeleton` to a line of 1 to 1.5 rem
 * and a register beats kp.components, so the tiles collapsed to 16 to 24 px (formal drew 24 px of a 146 px tile): restated in the last layer. */
@layer kp.layout {
    .kp-gallery__tile.kp-skeleton {
        block-size: auto;
        min-block-size: 0;
    }
}

/* A failed rating's plate is laid over the rating's whole box [t56-statefix-1018]. A register gives `.kp-alert` its own `position`
 * (pastel's is relative, for its printed pass) and beats the absolute placement in kp.components, which put the plate back in the
 * flow, narrow and taller than the stars it was to cover; restated in the last layer. */
@layer kp.layout {
    .kp-rating[data-kp-state='error'] .kp-rating__failure:not([hidden]) {
        position: absolute;
        inset: 0;
    }
}

/* One state plate for every area that can be empty or fail [state-plates-1019]: js/state-plate.js `hostStatePlate()` puts the
 * package's plate into the component's own box (the heat grid and matrix, the run timeline, the week, the network graph, the data
 * table), over the whole footprint the component has with its data, with a normal-size Retry on a failure. The rules live in the last
 * layer because a register dresses `.kp-alert` and `.kp-empty` and beats kp.components. Knobs [KT6]: --kp-stateplate-floor (the least
 * height of a plate with no loaded height to hold, 12rem), --kp-datatable-held (written by js/datatable.js). */
@layer kp.layout {
    .kp-stateplate__art {
        display: block;
        color: var(--muted-foreground);
        font-size: 2.5rem;
        line-height: 1;
    }

    .kp-stateplate--error .kp-stateplate__art {
        color: inherit;
    }

    .kp-stateplate__art > svg {
        display: block;
        inline-size: 2.5rem;
        block-size: 2.5rem;
        margin-inline: auto;
    }

    /* The heat grid and the matrix: the plate is the whole box (js/footprint.js holds the loaded height on the host). */
    .kp-heat:is([data-kp-state='empty'], [data-kp-state='error']),
    .kp-matrix:is([data-kp-state='empty'], [data-kp-state='error']) {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: minmax(0, 1fr);
        align-content: stretch;
        align-items: stretch;
    }

    .kp-heat__state,
    .kp-matrix__state {
        display: grid;
        grid-column: 1 / -1;
        min-block-size: var(--kp-stateplate-floor, 12rem);
        color: inherit;
        font-size: inherit;
    }

    .kp-heat__state > .kp-stateplate,
    .kp-matrix__state > .kp-stateplate {
        block-size: 100%;
    }

    /* The network graph: the plate over the whole picture; loading is the busy card, the words are read out only. */
    .kp-graph__state {
        position: absolute;
        inset: 0;
        z-index: 2;
        display: grid;
        border-radius: inherit;
        background: var(--background);
    }

    .kp-graph__state[hidden] {
        display: none;
    }

    .kp-graph__state > .kp-stateplate {
        block-size: 100%;
    }

    .kp-graph[data-kp-state='loading'] .kp-graph__note {
        position: absolute;
        inset: auto;
        inline-size: 1px;
        block-size: 1px;
        margin: -1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
    }

    /* The run timeline and the week: the plate over the plot (below the axis) or the whole agenda. */
    .kp-gantt__plate {
        position: absolute;
        inset: var(--kp-gantt-axis, 1.75rem) 0 0;
        z-index: 5;
        display: grid;
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    .kp-gantt--line .kp-gantt__plate {
        inset: 0 0 var(--kp-gantt-axis, 1.75rem);
    }

    .kp-gantt__plate[hidden],
    .kp-week__plate[hidden] {
        display: none;
    }

    .kp-week__plate {
        position: absolute;
        inset: 0;
        z-index: 5;
        display: grid;
        background: var(--kp-week-state-ground, var(--card));
        color: var(--card-foreground, var(--foreground));
    }

    .kp-week__frame:has(> .kp-week__plate:not([hidden])) {
        min-block-size: var(--kp-stateplate-floor, 12rem);
    }

    .kp-gantt__plate > .kp-stateplate,
    .kp-week__plate > .kp-stateplate {
        block-size: 100%;
    }

    /* What the plate covers is not drawn behind it: the hour rules and the lanes of the timeline, the days of the week, the empty picture of the graph. */
    .kp-gantt__frame:has(> .kp-gantt__plate:not([hidden])) :is(.kp-gantt__lines, .kp-gantt__plot, .kp-gantt__lane, .kp-gantt__track),
    .kp-week__frame:has(> .kp-week__plate:not([hidden])) > :is(.kp-week__grid, .kp-week__upcoming),
    .kp-graph:is([data-kp-state='empty'], [data-kp-state='error']) .kp-graph__svg {
        visibility: hidden;
    }

    /* The data table: a failed table, or one with nothing to show, covers its rows and the plate fills the height the table had. */
    /* A card's empty note has the failed note's air (24 px), not the plate's 32, so both fit the stage a short list leaves them. */
    .kp-card__state > .kp-card__empty.kp-stateplate {
        padding: var(--kp-space-lg, 1.5rem);
    }

    .kp-datatable > [data-kp-state-covered] {
        display: none;
    }

    .kp-datatable > :is([data-kp-datatable-empty], [data-kp-datatable-failed]).kp-stateplate {
        min-block-size: max(var(--kp-stateplate-floor, 12rem), min(var(--kp-datatable-held, 0px), var(--kp-footprint-max, 48rem)));
    }

    /* The sentence a page wrote in the empty slot is body text; its title (`.kp-empty__title`) is the plate's heading. */
    .kp-datatable > [data-kp-datatable-empty].kp-stateplate {
        font-size: var(--kp-text-md, 1rem);
    }

    .kp-datatable > [data-kp-datatable-empty].kp-stateplate .kp-empty__title {
        font-size: var(--kp-stateplate-text, clamp(1.125rem, 1rem + 0.6vw, 1.5rem));
        font-weight: 600;
    }

    .kp-datatable > [data-kp-datatable-failed] > [data-kp-datatable-failed-reason] {
        margin: 0;
    }

    /* A group of uptime strips that load together has ONE busy card over the group (js/uptime.js groupHost). */
    [data-kp-uptime-group] {
        position: relative;
    }
}

@layer kp.components {
    /* --- A live log viewer [gap-log-viewer] ------------------------------
 *
 * The existing `.kp-log` (the four-column grid, the severity word, the source's own hue) inside a frame with a bar over it and
 * a foot under it. The log keeps one height (`--kp-logviewer-height`, never below `--kp-logviewer-min`), so loading, empty,
 * failed, filtered and full all stand in one box and the bar and the foot do not move. The states are laid over the whole
 * stage. Knobs: --kp-logviewer-height, --kp-logviewer-min.
 *
 * Columns [fix-64]: the grid is the log's own; when the time column or the source column is off it leaves the grid
 * (`display: none` on a cell would shift the cells after it), so the track list is restated for the four combinations.
 * No wrap keeps each message on one line and scrolls the log sideways; the time cell is sticky then, so the clock stays
 * beside the line it belongs to. */
    .kp-logviewer {
        --kp-logviewer-min: 16rem;
        container: kp-logviewer / inline-size;
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        inline-size: 100%;
        min-inline-size: 0;
        overflow: clip;
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        background: var(--card);
        color: var(--card-foreground, var(--foreground));
    }

    .kp-logviewer__bar {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        gap: var(--kp-space-sm, 0.5rem);
        padding: var(--kp-space-sm, 0.5rem);
        border-block-end: 1px solid var(--border);
    }

    .kp-logviewer__bar[hidden],
    .kp-logviewer__search[hidden],
    .kp-logviewer__tools[hidden] {
        display: none;
    }

    .kp-logviewer__search {
        display: grid;
        grid-template-columns: minmax(8rem, 1fr) auto auto auto auto;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-logviewer__find {
        min-inline-size: 0;
    }

    .kp-logviewer__matches {
        min-inline-size: 7.5em;
        padding-inline: var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
        text-align: end;
    }

    .kp-logviewer__tools {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
    }

    .kp-logviewer__tools > [hidden],
    .kp-logviewer__search > [hidden] {
        display: none;
    }

    /* The follow button holds the room of its longer word, so Pause and Resume do not move the tools after it. */
    .kp-logviewer__follow {
        min-inline-size: 6.5em;
    }

    .kp-logviewer__level-wrap {
        display: inline-flex;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem);
        margin-inline-start: auto;
    }

    .kp-logviewer__level-label {
        padding-inline-start: var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-logviewer__level {
        inline-size: auto;
    }

    .kp-logviewer__stage {
        position: relative;
        min-inline-size: 0;
    }

    .kp-logviewer__log {
        position: relative;
        box-sizing: border-box;
        min-block-size: var(--kp-logviewer-min);
        block-size: var(--kp-logviewer-height, 26rem);
        align-content: start;
        gap: 0;
        padding: 0;
        overflow: auto;
        overscroll-behavior: contain;
        border: 0;
        border-radius: 0;
        scroll-padding-block: var(--kp-space-lg, 1.5rem);
    }

    .kp-logviewer__log:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast, var(--focus-ring));
        outline-offset: -2px;
    }

    .kp-logviewer__log .kp-log__line[hidden] {
        display: none;
    }

    .kp-logviewer__log .kp-log__line > * {
        padding-block: 0.0625rem;
        padding-inline: var(--kp-space-sm, 0.5rem);
    }

    .kp-logviewer__log .kp-log__line > :first-child {
        padding-inline-start: var(--kp-space-md, 0.75rem);
    }

    /* The columns. */
    .kp-logviewer[data-kp-log-time='off'] .kp-log__time,
    .kp-logviewer[data-kp-log-nosource] .kp-log__source {
        display: none;
    }

    .kp-logviewer[data-kp-log-time='off'] .kp-logviewer__log,
    .kp-logviewer[data-kp-log-nosource] .kp-logviewer__log {
        grid-template-columns: auto auto minmax(0, 1fr);
    }

    .kp-logviewer[data-kp-log-time='off'][data-kp-log-nosource] .kp-logviewer__log {
        grid-template-columns: auto minmax(0, 1fr);
    }

    /* The level is the colour: a plate on the word (the log's own, now on the word inside the level cell) and the same tone,
     * faint, behind the whole line, so a warning or an error is found by the eye while scrolling; the word stays the carrier
     * [DI4]. The cell keeps the row's tint, so the line is one band with no stripe where the level column is. */
    .kp-logviewer__log .kp-log__line[data-kp-severity='warning'] > * {
        background: hsl(from var(--warning) h s l / 0.12);
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity='error'] > *,
    .kp-logviewer__log .kp-log__line[data-kp-severity='critical'] > * {
        background: hsl(from var(--destructive) h s l / 0.14);
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity] > .kp-log__level {
        border-radius: 0;
        color: var(--kp-log-level-ink, var(--muted-foreground));
        font-weight: inherit;
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity='info'] > .kp-log__level,
    .kp-logviewer__log .kp-log__line[data-kp-severity='notice'] > .kp-log__level {
        color: var(--foreground);
    }

    .kp-log__word {
        padding-inline: 0.4em;
        border-radius: calc(var(--radius, 0.5rem) / 2);
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity='warning'] .kp-log__word {
        background: var(--warning);
        color: var(--warning-foreground);
        font-weight: 700;
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity='error'] .kp-log__word,
    .kp-logviewer__log .kp-log__line[data-kp-severity='critical'] .kp-log__word {
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-weight: 700;
    }

    .kp-logviewer__log .kp-log__line[data-kp-severity='critical'] .kp-log__message {
        font-weight: 700;
    }

    .kp-logviewer__log .kp-log__line:hover > * {
        background: var(--muted);
    }

    /* No wrap: one line per message, the log scrolls sideways, the clock stays. */
    .kp-logviewer[data-kp-log-wrap='off'] .kp-logviewer__log {
        grid-template-columns: auto auto auto minmax(max-content, 1fr);
    }

    .kp-logviewer[data-kp-log-wrap='off'][data-kp-log-time='off'] .kp-logviewer__log,
    .kp-logviewer[data-kp-log-wrap='off'][data-kp-log-nosource] .kp-logviewer__log {
        grid-template-columns: auto auto minmax(max-content, 1fr);
    }

    .kp-logviewer[data-kp-log-wrap='off'][data-kp-log-time='off'][data-kp-log-nosource] .kp-logviewer__log {
        grid-template-columns: auto minmax(max-content, 1fr);
    }

    .kp-logviewer[data-kp-log-wrap='off'] .kp-log__message {
        overflow-wrap: normal;
        white-space: pre;
    }

    .kp-logviewer[data-kp-log-wrap='off'] .kp-log__time {
        position: sticky;
        inset-inline-start: 0;
        z-index: 1;
        background: var(--card);
    }

    .kp-logviewer[data-kp-log-wrap='off'] .kp-log__line:hover > .kp-log__time {
        background: var(--muted);
    }

    /* The divider for the lines that came while the tab was away takes the whole row. */
    .kp-logviewer__log > .kp-newpill__since {
        grid-column: 1 / -1;
    }

    /* The find: a match is a mark with a weight as well as a ground, the current one is the filled plate with a rule round it. */
    .kp-log__match {
        padding-inline: 0.125em;
        border-radius: calc(var(--radius, 0.5rem) / 4);
        background: hsl(from var(--primary) h s l / 0.3);
        color: inherit;
        font-weight: 700;
        text-decoration: underline;
        text-decoration-thickness: 1px;
        text-underline-offset: 0.15em;
    }

    .kp-log__match[data-kp-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        outline: 2px solid var(--primary);
        outline-offset: 1px;
        text-decoration: none;
    }

    /* The foot: the count on the left, what the cap pushed out beside it. */
    .kp-logviewer__foot {
        display: flex;
        flex-wrap: wrap;
        align-items: baseline;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        min-block-size: 2.25rem;
        box-sizing: border-box;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        border-block-start: 1px solid var(--border);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
    }

    .kp-logviewer__foot [hidden] {
        display: none;
    }

    /* The states fill the whole stage; the lines already read stay in the buffer and are out of sight until the log answers. */
    .kp-logviewer__plate {
        position: absolute;
        inset: 0;
        box-sizing: border-box;
        z-index: 3;
    }

    .kp-logviewer[data-kp-log-plate='loading'] .kp-logviewer__log,
    .kp-logviewer[data-kp-log-plate='error'] .kp-logviewer__log,
    .kp-logviewer[data-kp-log-plate='empty'] .kp-logviewer__log,
    .kp-logviewer[data-kp-log-plate='nomatch'] .kp-logviewer__log {
        overflow: hidden;
        visibility: hidden;
    }

    .kp-logviewer[data-kp-log-plate='loading'] .kp-newpill,
    .kp-logviewer[data-kp-log-plate='error'] .kp-newpill {
        display: none;
    }

    .kp-logviewer__step {
        min-inline-size: 2.5rem;
    }

    /* A narrow viewer: the search box takes its own row, then the count with the two arrows; the tools stand in two columns, so
     * the buttons share one width and the rows line up. */
    @container kp-logviewer (max-width: 40rem) {
        .kp-logviewer__find {
            grid-column: 1 / -1;
        }

        .kp-logviewer__search {
            grid-template-columns: minmax(0, 1fr) auto auto;
        }

        .kp-logviewer__matches {
            text-align: start;
        }

        .kp-logviewer__search > [data-kp-logviewer-only] {
            grid-column: 1 / -1;
        }

        .kp-logviewer__tools {
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .kp-logviewer__tools > *,
        .kp-logviewer__tools .kp-button {
            inline-size: 100%;
        }

        .kp-logviewer__time {
            grid-column: 1 / -1;
        }

        .kp-logviewer__level-wrap {
            grid-column: 1 / -1;
            display: grid;
            grid-template-columns: auto minmax(0, 1fr);
            margin-inline-start: 0;
        }
    }
}

/* The find's mark and the stage's plate keep their place in the last layer: a register gives `.kp-alert` and `.kp-empty` a
 * position of its own (pastel's printed pass) and beats the absolute placement in kp.components, which would put the plate
 * back in the flow under the lines [gap-log-viewer]. */
@layer kp.layout {
    .kp-logviewer__stage > .kp-logviewer__plate {
        position: absolute;
        inset: 0;
    }
    /* gap-activity-feed:feed:start */
    /* --- The activity feed [gap-activity-feed-1019] ------------------------------
     * js/feed.js. Who did what, and when, day by day: a row is a state mark (the status
     * row's shapes and glyph tokens, so a theme's step and status marks are one family),
     * a title with its muted detail line, the identity chip of whoever started it and the
     * time, which is the ticking `kp-ago` for the first 24 hours (js/freshness.js). The
     * timeline's rule joins the marks of a day; a day heading (the thread's divider, with
     * the day's count) separates the days. The list is ONE grid: the mark, the text, the
     * actor and the time are columns every row of every day gives its parts to (subgrids),
     * so the chips and the times stand under each other whichever row is longer, and the
     * column is as wide as its longest chip and no wider [fix-64]. Loading, empty and
     * failed fill the body's footprint (the busy card, the state plate), and the foot
     * keeps the room of "Load earlier" in all four of its states, so nothing moves when
     * one changes.
     * Knobs [KT6]: --kp-feed-min (the body's least height, 20rem), --kp-feed-max (set by
     * data-kp-feed-max: the list scrolls and the day headings stay), --kp-feed-pad (a
     * row's air above and below, 0.625rem), --kp-feed-gap (between the columns),
     * --kp-feed-actor-max (the chip column's ceiling, 12rem), --kp-feed-ground (what the
     * sticky day headings are drawn on, the card), --kp-feed-foot-min, --kp-feed-head-min,
     * and the status-row marks' --kp-statusrow-mark, --kp-statusrow-mark-radius and
     * --kp-glyph-done, --kp-glyph-failed, --kp-glyph-warn. */
    .kp-feed {
        container: kp-feed / inline-size;
        --kp-feed-mark-size: var(--kp-statusrow-mark, 1.25rem);
        --kp-feed-row-pad: var(--kp-feed-pad, 0.625rem);
        display: flex;
        flex-direction: column;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
    }

    .kp-feed__head {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        min-block-size: var(--kp-feed-head-min, 2.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-feed__head[hidden],
    .kp-feed__stale[hidden],
    .kp-feed__fresh[hidden],
    .kp-feed__state[hidden],
    .kp-feed__skeleton[hidden],
    .kp-feed__list[hidden] {
        display: none;
    }

    .kp-feed__count {
        color: var(--foreground);
        font-weight: 600;
        font-variant-numeric: tabular-nums;
    }

    .kp-feed__fresh {
        margin-inline-start: auto;
    }

    /* A refresh that failed while the rows are still good: the warning pair on its own plate, the reason in plain words, and the one button. */
    .kp-feed__stale {
        display: flex;
        flex: 1 1 auto;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: calc(var(--radius, 0.5rem) * 0.75);
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-feed__stale-text {
        min-inline-size: 0;
        overflow-wrap: anywhere;
    }

    /* --- The body: the list, the skeleton and the state plate share one cell --- */
    .kp-feed__body {
        position: relative;
        display: grid;
        flex: 1 1 auto;
        min-block-size: var(--kp-feed-min, 20rem);
    }

    .kp-feed__body > * {
        grid-area: 1 / 1;
        min-inline-size: 0;
    }

    /* A list that scrolls keeps the wash of a failed row and the scrollbar clear of the text: the box has air of its own. */
    .kp-feed[data-kp-feed-scroll] > .kp-feed__body {
        max-block-size: var(--kp-feed-max);
        padding-inline: var(--kp-space-sm, 0.5rem);
        overflow: auto;
        scrollbar-gutter: stable;
    }

    .kp-feed__state {
        display: grid;
    }

    /* One grid for every day: mark, text, actor, time. The group, its rows and each row are subgrids of it. */
    .kp-feed__list,
    .kp-feed__rows {
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .kp-feed__list {
        display: grid;
        grid-template-columns: var(--kp-feed-mark-size) minmax(0, 1fr) max-content max-content;
        column-gap: var(--kp-feed-gap, var(--kp-space-md, 0.75rem));
        align-content: start;
    }

    .kp-feed[data-kp-feed-actor-mode='off'] .kp-feed__list {
        grid-template-columns: var(--kp-feed-mark-size) minmax(0, 1fr) max-content;
    }

    .kp-feed__group,
    .kp-feed__rows,
    .kp-feed__row {
        display: grid;
        grid-template-columns: subgrid;
        grid-column: 1 / -1;
        min-inline-size: 0;
    }

    .kp-feed__group:not(:first-child) > .kp-feed__day {
        margin-block-start: var(--kp-space-md, 0.75rem);
    }

    /* A day heading: the thread's divider, with the word first and the day's count at the end. */
    .kp-feed__day {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        grid-column: 1 / -1;
        gap: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        padding-block: var(--kp-space-xs, 0.25rem);
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-feed__day-word {
        color: var(--foreground);
        font-weight: 600;
    }

    .kp-feed__day-date,
    .kp-feed__day-summary {
        font-variant-numeric: tabular-nums;
    }

    .kp-feed__day-rule {
        flex: 1 1 var(--kp-space-lg, 1.5rem);
        border-block-start: 1px solid var(--border-strong, var(--border));
    }

    .kp-feed[data-kp-feed-scroll] .kp-feed__day {
        position: sticky;
        inset-block-start: 0;
        z-index: 2;
        margin-inline: calc(var(--kp-space-sm, 0.5rem) * -1);
        padding-inline: var(--kp-space-sm, 0.5rem);
        background: var(--kp-feed-ground, var(--card));
    }

    /* --- A row --- */
    .kp-feed__row {
        position: relative;
        isolation: isolate;
        align-items: start;
        padding-block: var(--kp-feed-row-pad);
    }

    /* The mark sits on the title's first line: the cell is one line high and centres it. */
    .kp-feed__mark-cell {
        display: flex;
        align-items: center;
        justify-content: center;
        block-size: 1lh;
    }

    .kp-feed__mark {
        box-sizing: border-box;
        display: grid;
        place-items: center;
        inline-size: var(--kp-feed-mark-size);
        block-size: var(--kp-feed-mark-size);
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-statusrow-mark-radius, var(--kp-steplist-mark-radius, var(--kp-radius-pill, 999px)));
        font-size: 0.75rem;
        font-weight: 700;
        line-height: 1;
    }

    .kp-feed__mark > .kp-spinner {
        --kp-spinner-size: var(--kp-feed-mark-size);
    }

    .kp-feed__row[data-state] .kp-feed__mark {
        border-style: solid;
    }

    .kp-feed__row[data-state='ok'] .kp-feed__mark {
        border-color: var(--success-foreground);
        background: var(--success);
        color: var(--success-foreground);
    }

    .kp-feed__row[data-state='ok'] .kp-feed__mark::after {
        content: var(--kp-glyph-done, var(--kp-glyph-check, '✓'));
    }

    .kp-feed__row[data-state='failed'] .kp-feed__mark {
        border-color: var(--destructive);
        background: var(--destructive);
        color: var(--destructive-foreground);
    }

    .kp-feed__row[data-state='failed'] .kp-feed__mark::after {
        content: var(--kp-glyph-failed, '✕');
    }

    .kp-feed__row[data-state='warn'] .kp-feed__mark {
        border-color: var(--warning-foreground);
        background: var(--warning);
        color: var(--warning-foreground);
    }

    .kp-feed__row[data-state='warn'] .kp-feed__mark::after {
        content: var(--kp-glyph-warn, '!');
    }

    .kp-feed__row[data-state='info'] .kp-feed__mark {
        border-color: var(--info-foreground);
        background: var(--info);
        color: var(--info-foreground);
    }

    .kp-feed__row[data-state='info'] .kp-feed__mark::after {
        content: var(--kp-glyph-info, 'i');
    }

    .kp-feed__row[data-state='running'] .kp-feed__mark {
        border-color: transparent;
    }

    /* A row that failed or needs attention is found at a glance: a faint wash of its own colour behind the whole row (the words keep the page's ink). */
    .kp-feed__row:is([data-state='failed'], [data-state='warn'])::after {
        content: '';
        position: absolute;
        z-index: -1;
        inset-block: 0;
        inset-inline: calc(var(--kp-space-sm, 0.5rem) * -1);
        border-radius: calc(var(--radius, 0.5rem) * 0.75);
        background: color-mix(in oklab, var(--destructive) 8%, transparent);
        pointer-events: none;
    }

    .kp-feed__row[data-state='warn']::after {
        background: color-mix(in oklab, var(--warning) 40%, transparent);
    }

    /* The timeline's rule: from under this mark to above the next one, only inside a day. */
    .kp-feed__row:not(:last-child)::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset-inline-start: calc(var(--kp-feed-mark-size) / 2 - 0.5px);
        inset-block-start: calc(var(--kp-feed-row-pad) + (1lh + var(--kp-feed-mark-size)) / 2 + 3px);
        inset-block-end: calc((var(--kp-feed-row-pad) + (1lh - var(--kp-feed-mark-size)) / 2 - 3px) * -1);
        inline-size: 1px;
        background: var(--border-strong, var(--border));
    }

    .kp-feed[data-kp-feed-no-rail] .kp-feed__row::before {
        content: none;
    }

    .kp-feed__text {
        display: grid;
        gap: 0.125rem;
        min-inline-size: 0;
    }

    .kp-feed__title {
        font-weight: 600;
        overflow-wrap: anywhere;
    }

    .kp-feed__detail {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        overflow-wrap: anywhere;
    }

    .kp-feed__toggle,
    .kp-feed__link {
        display: inline-flex;
        align-items: baseline;
        gap: var(--kp-space-xs, 0.25rem);
        max-inline-size: 100%;
        margin: 0;
        padding: 0;
        border: 0;
        background: none;
        color: inherit;
        font: inherit;
        font-weight: inherit;
        text-align: start;
        text-decoration: none;
        cursor: pointer;
    }

    .kp-feed__toggle:hover > .kp-feed__title-text,
    .kp-feed__link:hover > .kp-feed__title-text {
        text-decoration: underline;
        text-underline-offset: 0.2em;
    }

    .kp-feed__toggle:focus-visible,
    .kp-feed__link:focus-visible,
    .kp-feed__open:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring);
        outline-offset: 2px;
    }

    .kp-feed__chevron {
        display: inline-grid;
        flex: none;
        place-items: center;
        inline-size: 1em;
        color: var(--muted-foreground);
    }

    .kp-feed__chevron::before {
        content: var(--kp-glyph-open, '›');
        display: inline-block;
    }

    .kp-feed__toggle[aria-expanded='true'] > .kp-feed__chevron::before {
        rotate: 90deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        .kp-feed__chevron::before {
            transition: rotate var(--fx-duration, 150ms) var(--fx-ease, ease);
        }
    }

    /* The lines that open under a row: a log excerpt in the mono face, on the muted plate. */
    .kp-feed__more {
        display: grid;
        gap: 0.125rem;
        margin-block-start: var(--kp-space-xs, 0.25rem);
        padding: var(--kp-space-sm, 0.5rem) var(--kp-space-md, 0.75rem);
        border: 1px solid var(--border);
        border-radius: calc(var(--radius, 0.5rem) * 0.75);
        background: var(--muted);
        color: var(--foreground);
        font-family: var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace);
        font-size: var(--kp-text-xs, 0.75rem);
        line-height: 1.5;
    }

    .kp-feed__more[hidden] {
        display: none;
    }

    .kp-feed__line {
        white-space: pre-wrap;
        overflow-wrap: anywhere;
    }

    .kp-feed__open {
        justify-self: start;
        margin-block-start: var(--kp-space-xs, 0.25rem);
        font-family: var(--font-sans, inherit);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    /* The meta cell gives its two parts to the list's columns on a wide feed. */
    .kp-feed__meta {
        display: contents;
    }

    .kp-feed__actor,
    .kp-feed__when {
        display: flex;
        align-items: center;
        min-block-size: 1lh;
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-feed__actor {
        min-inline-size: 0;
        max-inline-size: var(--kp-feed-actor-max, 12rem);
    }

    /* align-pkg-1019:feed:start
     * The actor chip and the time stand on the title's baseline. Their boxes were one line of their OWN (smaller) text high
     * and centred their content, so beside a title set in the body size they sat 2 px above its line (measure-align,
     * gap-round-1 feed-*). The row now puts the title, the chip and the time on one first baseline, as a caption stands
     * beside its heading. */
    .kp-feed__row :is(.kp-feed__text, .kp-feed__actor, .kp-feed__when):is(.kp-feed__row > *, .kp-feed__meta > *) {
        align-self: first baseline;
    }

    /* The chip's baseline is its name's, not the bottom of its mark; the mark centres on the line beside it. */
    .kp-feed__actor .kp-idmark-name {
        align-items: baseline;
    }

    .kp-feed__actor .kp-idmark-name > .kp-idmark {
        align-self: center;
    }

    /* A chip that is only its mark has no text to share a baseline with: it stands in a cell one title line high. */
    .kp-feed__actor:not(:has(.kp-feed__actor-name)) {
        align-self: start;
        font-size: inherit;
    }
    /* align-pkg-1019:feed:end */

    .kp-feed__actor-name {
        overflow-wrap: anywhere;
    }

    .kp-feed__when {
        justify-content: flex-end;
        color: var(--muted-foreground);
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
        text-align: end;
    }

    /* --- Loading: the final geometry in skeletons, the busy card laid over it by the script --- */
    .kp-feed__skeleton {
        display: grid;
        align-content: start;
        gap: var(--kp-space-lg, 1.5rem);
    }

    .kp-feed__skel-group {
        display: grid;
        gap: var(--kp-feed-row-pad);
    }

    .kp-feed__skel-day {
        inline-size: 9rem;
        block-size: 1rem;
    }

    .kp-feed__skel-row {
        display: grid;
        grid-template-columns: var(--kp-feed-mark-size) minmax(0, 1fr) minmax(0, 7rem) minmax(0, 5rem);
        align-items: center;
        column-gap: var(--kp-feed-gap, var(--kp-space-md, 0.75rem));
        padding-block: calc(var(--kp-feed-row-pad) / 2);
    }

    .kp-feed__skel-mark {
        --kp-skeleton-circle: var(--kp-feed-mark-size);
    }

    .kp-feed__skel-text,
    .kp-feed__skel-chip,
    .kp-feed__skel-when {
        block-size: 1rem;
        margin: 0 !important;
    }

    .kp-feed__skel-text {
        inline-size: 70%;
    }

    /* --- The foot: "Load earlier", the same room in all four states --- */
    .kp-feed__foot {
        display: grid;
        justify-items: center;
        align-content: center;
        gap: var(--kp-space-xs, 0.25rem);
        padding-block: var(--kp-space-sm, 0.5rem);
        text-align: center;
    }

    .kp-feed__foot:not([data-kp-earlier='none']) {
        min-block-size: var(--kp-feed-foot-min, 5.5rem);
    }

    .kp-feed__foot:empty {
        display: none;
    }

    .kp-feed__foot-note {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
        font-variant-numeric: tabular-nums;
        overflow-wrap: anywhere;
    }

    .kp-feed__foot-note--error {
        color: var(--foreground);
        font-weight: 600;
    }

    .kp-feed__earlier {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 11rem;
    }

    .kp-feed__earlier > .kp-spinner {
        --kp-spinner-size: 1.125rem;
    }

    /* A feed narrower than this puts the actor and the time on a line of their own under the text. */
    @container kp-feed (max-width: 34rem) {
        .kp-feed__list,
        .kp-feed[data-kp-feed-actor-mode='off'] .kp-feed__list {
            grid-template-columns: var(--kp-feed-mark-size) minmax(0, 1fr);
        }

        .kp-feed__meta {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            grid-column: 2;
            gap: var(--kp-space-xs, 0.25rem) var(--kp-space-md, 0.75rem);
            justify-content: space-between;
        }

        .kp-feed__actor {
            max-inline-size: 100%;
        }

        .kp-feed__skel-row {
            grid-template-columns: var(--kp-feed-mark-size) minmax(0, 1fr) minmax(0, 4rem);
        }

        .kp-feed__skel-chip {
            display: none;
        }
    }

    /* gap-activity-feed:feed:end */
}

/* ---- css/layout.css ---- */
@layer kp.layout {
    /* @kp-soft/themes — css/layout.css
       The layout layer [TH90, TH91, S22].

       Twenty-three classes, and the reason they exist is measured rather than
       assumed: the chassis kit wrote 71 lines of its own layout glue plus
       28 inline style attributes, and its stylesheet header said in so many
       words that this is "layout glue and the few utilities @kp-soft/themes
       deliberately does not ship". These are those.

       Import it beside the tokens and the components, in that order:
       css/themes.css, css/components.css, css/layout.css.

       Every class reads a knob with the scale as its default, so a page or
       a theme retunes it without rewriting the rule (KT6). Nothing here
       paints a colour that is not a token (DI9).

       The layer matters: kp.layout sits after kp.components, so adding
       .kp-stack to a component that sets its own gap wins — which is what
       someone reaching for a layout class means (AR17).

       The comment directly above each rule is what site/layout.html prints
       beside it [AR21, scope-77], so it names the rule's knobs and their
       defaults; a comment there may not contain an asterisk, because the
       generator reads up to the first one. The name is a promise: every
       class here falls under the same semver promise as the component
       classes, and renaming one is a major version. */

    /* ── Containers ─────────────────────────────────────────────────── */

    /* The page itself: centred, eighty percent of the window wide and never
       narrower than 64rem, so a wide desktop screen is used and a laptop
       keeps the old measure; on a phone it is the whole width, with margins
       that shrink instead of stepping at a breakpoint. Text inside keeps
       its own measure through kp-prose. Knobs: --kp-page-max (the larger of
       80vw and 64rem), --kp-page-pad (between the md and xl steps of the
       scale, 3vw in between), --kp-page-pad-block (the xl step). */
    .kp-page {
        max-inline-size: var(--kp-page-max, max(80vw, 64rem));
        margin-inline: auto;
        padding-inline: var(--kp-page-pad, clamp(var(--kp-space-md), 3vw, var(--kp-space-xl)));
        padding-block: var(--kp-page-pad-block, var(--kp-space-xl));
    }

    /* Vertical rhythm. This is the fault the round started from: two fields
       and a button touched because a field has no vertical margin and
       nothing above it supplied one. Knob: --kp-stack-gap (the md step). */
    .kp-stack {
        display: flex;
        flex-direction: column;
        gap: var(--kp-stack-gap, var(--kp-space-md));
    }

    /* A row of controls that wraps rather than overflowing, aligned on the
       centre by default because that is what a row of controls wants. Four
       modifiers change one thing each. Knobs: --kp-row-gap (the sm step),
       --kp-row-align (center). */
    .kp-row {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-row-gap, var(--kp-space-sm));
        align-items: var(--kp-row-align, center);
    }

    /* Aligns the row on the bottom edge, which is what a field beside a
       button wants. */
    .kp-row--end {
        --kp-row-align: flex-end;
    }

    /* Aligns the row on the top edge. */
    .kp-row--start {
        --kp-row-align: flex-start;
    }

    /* Pushes the ends of the row apart. */
    .kp-row--between {
        justify-content: space-between;
    }

    /* Refuses to wrap. */
    .kp-row--nowrap {
        flex-wrap: nowrap;
    }

    /* A grid that adds a column when there is room for one, with no
       breakpoint anywhere. The minimum track is the knob: a card wants
       16rem, a tile less. It keeps a little air on all four sides so the
       first column's text never sits against the edge of whatever it lands
       in (Kenny, 2026-09-08). Knobs: --kp-autogrid-min (16rem),
       --kp-autogrid-gap (the lg step), --kp-autogrid-pad (the sm step; set
       it to 0 for a grid that should reach its container's edge). */
    .kp-autogrid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(var(--kp-autogrid-min, 16rem), 1fr));
        gap: var(--kp-autogrid-gap, var(--kp-space-lg));
        /* A little air on all four sides, so the first column's text never
           sits against whatever edge the grid happens to land on (Kenny,
           2026-09-08). The gap keeps the columns apart; this keeps the
           grid off its own container's edge, and it is a knob like every
           other length here [KT6]. */
        padding: var(--kp-autogrid-pad, var(--kp-space-sm));
    }
    /* A tighter minimum, for a grid that must keep its columns on a phone
       (three footer columns at 320px; the concept demo, round six). */
    .kp-autogrid--tight {
        --kp-autogrid-min: 10rem;
    }
    /* A page that uses the whole viewport: two frames side by side need
       the width more than the measure (the compare page, round six). */
    .kp-page--full {
        max-inline-size: none;
    }

    /* Content with a side column that drops below when there is no room for
       both — no media query, so it behaves the same inside a narrow
       container as it does in a narrow window. The aside drops once the
       main column would be narrower than half the track. Knob:
       --kp-sidebar-gap (the lg step). */
    .kp-sidebar {
        display: flex;
        flex-wrap: wrap;
        gap: var(--kp-sidebar-gap, var(--kp-space-lg));
    }

    /* The side column. Knob: --kp-sidebar-width (16rem). */
    .kp-sidebar > .kp-sidebar__aside {
        flex-basis: var(--kp-sidebar-width, 16rem);
        flex-grow: 1;
    }

    /* The main column, which takes every spare pixel. Knob:
       --kp-sidebar-break (50%), the narrowest it may be before the aside
       drops below it. */
    .kp-sidebar > .kp-sidebar__main {
        flex-basis: 0;
        flex-grow: 999;
        min-inline-size: var(--kp-sidebar-break, 50%);
    }

    /* An application shell: the bar on top and a body under it that fills
       the rest of the window, so a rail beside the content runs to the
       bottom of the window rather than stopping where the content does
       (scope-80). The body is a row that wraps, the rail and the content
       its items. Knob: --kp-shell-min (100dvh), the least height of the
       whole shell. */
    .kp-shell {
        display: flex;
        flex-direction: column;
        min-block-size: var(--kp-shell-min, 100dvh);
    }

    /* A shell is the whole window, so the page around it gives up the
       browser's default body margin: with it the bar stood 8px off the
       edges and a shell as tall as the window scrolled by 16px, the rail
       ending 8px under the window's bottom (measured at 1400 by 900). */
    body:has(.kp-shell) {
        margin: 0;
    }

    /* The shell's body, which takes every spare pixel of that height. */
    .kp-shell > .kp-shell__body {
        display: flex;
        flex-wrap: wrap;
        flex-grow: 1;
    }

    /* A section of a page: space above it, and nothing else. The heading
       inside keeps whatever the theme gives it. Knob: --kp-section-gap
       (the 2xl step). */
    .kp-section {
        margin-block-start: var(--kp-section-gap, var(--kp-space-2xl));
    }

    /* As the first child a section puts no space above itself, where the
       space would push the page down for no reason. */
    .kp-section:first-child {
        margin-block-start: 0;
    }

    /* A box with a ceiling, centred — the login card, the empty state, the
       one-column form. Knob: --kp-center-max (28rem). */
    .kp-center {
        margin-inline: auto;
        max-inline-size: var(--kp-center-max, 28rem);
    }

    /* ── Text and content ───────────────────────────────────────────── */

    /* Running text stops at a readable measure. ch rather than rem, because
       the measure is about characters per line and the themes ship faces of
       very different widths. Knob: --kp-prose-max (65ch). */
    .kp-prose {
        max-inline-size: var(--kp-prose-max, 65ch);
    }

    /* Exactly the theme's --muted-foreground, never a lightened copy of the
       body colour. */
    .kp-text-muted {
        color: var(--muted-foreground);
    }

    /* Aligns text to the end. This and .kp-text-center are the reason the
       layer exists at all: a table cell sets its own alignment at higher
       specificity, so before the cascade layers these two did nothing
       inside a table. */
    .kp-text-end {
        text-align: end;
    }

    /* Centres text; see .kp-text-end for why it is in this layer. */
    .kp-text-center {
        text-align: center;
    }

    /* The package's own monospace face. Knobs: --kp-mono-face (the theme's
       --font-mono), --kp-mono-size (0.9em). */
    .kp-mono {
        font-family: var(--kp-mono-face, var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace));
        font-size: var(--kp-mono-size, 0.9em);
    }

    /* A block of code that breaks rather than widening the page. A key or a
       token has no spaces to break at, which is why anywhere and not
       break-word. It sits on a card and reads --kp-mono-face like .kp-mono. */
    .kp-code-block {
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        padding: var(--kp-space-md) var(--kp-space-lg);
        font-family: var(--kp-mono-face, var(--font-mono, ui-monospace, SFMono-Regular, Menlo, monospace));
        overflow-wrap: anywhere;
        white-space: pre-wrap;
    }

    /* ── Staying put, and where an anchor lands [scope-10, stage 1.1] ─ */

    /* Measured on 2026-09-11 across css/, js/ and components/: this package
       contained zero occurrences of `sticky`, and zero of `scroll-behavior`,
       `scroll-padding` or `scroll-margin`. Nothing stayed put while a page
       scrolled, and nothing knew where an anchor should land.

       Both defaults here change nothing for a page that does not ask: the
       offset is 0 and the behaviour is `auto`, so an existing consumer sees
       exactly what it saw before. What they buy is that the two belong
       together — the moment anything is stuck over the content, every
       in-page link has to clear it, and the link that matters most is the
       skip link every page in this package carries. Someone using that link
       cannot see that its target went under the bar. */
    html {
        /* A sticky nav bar (`.kp-nav-wrap--sticky`) writes its own height to
           --kp-nav-sticky-height here; a page's --kp-scroll-offset still wins. */
        scroll-padding-block-start: var(--kp-scroll-offset, var(--kp-nav-sticky-height, 0px));
    }

    /* DI7: a page that asks for smooth scrolling still does not get it when
       the reader asked for less motion. The knob is read inside the guard
       rather than outside it, so `smooth` cannot survive the preference. */
    @media (prefers-reduced-motion: no-preference) {
        html {
            scroll-behavior: var(--kp-scroll-behavior, auto);
        }
    }

    /* Opt-in, by an attribute rather than a class, because staying put is a
       behaviour of that element on that page and not a kind of element.
       Knobs: --kp-sticky-top (0), --kp-sticky-layer (30). It has a partner
       on the html element: --kp-scroll-offset (0px) is how far an in-page
       link stops short of the top, and a page that sticks its nav sets it
       to the height it stuck. Without it the skip link every page carries
       lands underneath the bar, and the person using that link is exactly
       the person who cannot see that it did. --kp-scroll-behavior (auto)
       turns on smooth scrolling, read inside the reduced-motion guard so
       smooth cannot survive a reader who asked for less motion. All three
       defaults change nothing: a page that does not ask gets what it got
       before. */
    [data-kp-sticky] {
        position: sticky;
        inset-block-start: var(--kp-sticky-top, 0);
        z-index: var(--kp-sticky-layer, 30);
    }

    /* ── State ──────────────────────────────────────────────────────── */

    /* Standing rule 31 says a button that starts something slow shows it.
       The behaviour was already in the package and the styling was not, so
       the chassis kit wrote this rule itself. It belongs here. The busy
       state made visible: the element dims and the cursor becomes a
       progress cursor. An attribute rather than a class, because the
       attribute is what a screen reader already reads, and a busy control
       that looks identical to an idle one is the fault correction KT6
       exists about. Knob: --kp-busy-opacity (0.7). */
    [aria-busy='true'] {
        opacity: var(--kp-busy-opacity, 0.7);
        cursor: progress;
    }
}

