    .kp-tt-lower {
        text-transform: lowercase;
    }

    .kp-tt-capitalize {
        text-transform: capitalize;
    }

    .kp-text-nowrap {
        white-space: nowrap;
    }

    .kp-text-balance {
        text-wrap: balance;
    }

    .kp-text-pretty {
        text-wrap: pretty;
    }

    .kp-lh-tight {
        line-height: var(--kp-lh-tight, 1.25);
    }

    .kp-lh-normal {
        line-height: var(--kp-lh-normal, 1.5);
    }

    .kp-lh-loose {
        line-height: var(--kp-lh-loose, 1.75);
    }

    /* Width and height — The three measures read the same knobs the layout containers do, so retuning `--kp-prose-max` moves both. */
    .kp-w-full {
        inline-size: 100%;
    }

    .kp-w-auto {
        inline-size: auto;
    }

    .kp-w-min {
        inline-size: min-content;
    }

    .kp-w-max {
        inline-size: max-content;
    }

    .kp-w-fit {
        inline-size: fit-content;
    }

    .kp-max-w-prose {
        max-inline-size: var(--kp-prose-max, 65ch);
    }

    .kp-max-w-center {
        max-inline-size: var(--kp-center-max, 28rem);
    }

    .kp-max-w-page {
        max-inline-size: var(--kp-page-max, 64rem);
    }

    .kp-h-full {
        block-size: 100%;
    }

    .kp-h-auto {
        block-size: auto;
    }
}

/* ---- catalogue/catalogue.css ---- */
/* The catalogue's own chrome: the bar, the stage a component sits on, and
   the "Look at" note beside it. Nothing here styles a kp- class — the page
   must show what the package paints, not what this file paints, which is
   the same trap KT3 caught in showcase.css. Every selector is prefixed
   `cat-`, and the whole file sits in its own layer above the package's so
   a stage can never win a declaration from a register by accident. */
@layer catalogue {
    /* The shell catalogue.js builds around every page: the package's own
       side navigation beside a column holding the bar and the page. */
    body.cat-shell {
        display: flex;
        align-items: flex-start;
        min-block-size: 100vh;
    }

    /* Sticky only while it sits beside the page: this layer is above the
       package's, so an unconditional position here would also pin the
       panel in its "over" mode and stop it covering the page. */
    .cat-nav:not([data-kp-sidenav-mode='over']) {
        position: sticky;
        inset-block-start: 0;
        block-size: 100vh;
        flex: 0 0 auto;
    }

    .cat-column {
        flex: 1 1 auto;
        min-inline-size: 0;
    }

    /* The toggle only matters where the navigation lies over the page. */
    .cat-nav-toggle {
        display: none;
    }

    @media (max-width: 56rem) {
        .cat-nav-toggle {
            display: inline-flex;
        }
    }

    .cat-bar {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.75rem;
        padding: 0.6rem 1rem;
        border-block-end: 1px solid var(--border);
        background: var(--card);
        color: var(--card-foreground);
        position: sticky;
        inset-block-start: 0;
        z-index: 40;
    }

    .cat-bar__home {
        font-weight: 600;
        text-decoration: none;
        color: inherit;
    }

    .cat-bar__spacer {
        flex: 1 1 auto;
    }

    .cat-main {
        max-inline-size: 70rem;
        margin: 0 auto;
        padding: 1.5rem 1rem 6rem;
    }

    .cat-intro {
        max-inline-size: 46rem;
        color: var(--muted-foreground);
    }

    .cat-toc {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem 1rem;
        padding: 0.75rem 0 0;
        margin: 0 0 2rem;
        list-style: none;
        border-block-start: 1px solid var(--border);
        font-size: 0.9rem;
    }

    .cat-block {
        margin-block: 2.5rem;
        scroll-margin-block-start: 4rem;
    }

    .cat-block > h2 {
        margin-block-end: 0.35rem;
    }

    /* The reviewer's instruction. It is the point of the page: a block
       without one is a screenshot, and a screenshot answers nothing. */
    .cat-look {
        border-inline-start: 3px solid var(--accent);
        background: var(--muted);
        color: var(--muted-foreground);
        padding: 0.6rem 0.9rem;
        margin-block: 0.75rem;
        font-size: 0.88rem;
        line-height: 1.55;
    }

    .cat-look b {
        color: var(--foreground);
    }

    .cat-look code {
        font-family: var(--theme-font-mono, monospace);
        font-size: 0.85em;
    }

    /* The stage is deliberately plain: a hairline and breathing room, so
       what is inside it is the theme's doing and not this file's. */
    .cat-stage {
        border: 1px dashed var(--border);
        padding: 1.25rem;
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
        align-items: flex-start;
    }

    .cat-stage--block {
        display: block;
    }

    /* A block judged in a theme of its own (`data-cat-theme`, judging.js puts
       it on the stage as `data-theme`) inherits nothing from the page theme:
       what the body would pass down, it takes from its own [scope-86]. */
    .cat-stage[data-theme] {
        color: var(--foreground);
        font-family: var(--theme-font-body, ui-sans-serif, system-ui, sans-serif);
    }

    .cat-stage--tight {
        gap: 0.5rem;
    }

    .cat-stage--dense {
        padding: 0;
    }

    /* A surface needs room before its texture reads as one: the stage lays
       its one child out as a grid row of at least this height, so the
       surface grows without this file touching the surface itself. */
    .cat-stage--surface {
        display: grid;
        grid-auto-rows: minmax(22rem, auto);
    }

    /* The live copy of a reveal (catalogue/page-effects.html): outside the
       stage on purpose, since a verdict records the copy at rest, and marked
       off by a dotted rule so the two are never taken for one. */
    .cat-live {
        border: 1px dotted var(--border);
        padding: 0.75rem 1.25rem 1.25rem;
        margin-block-end: 0.75rem;
    }

    .cat-live__bar {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        margin-block-end: 0.75rem;
    }

    .cat-live__bar .cat-note {
        margin: 0;
    }

    /* Options to compare (`[data-cat-option]`, wired in demos.js): they wrap
 * whole on a phone, and the picked one carries a ring in the primary
 * colour. */
    .cat-options {
        flex-wrap: wrap;
        gap: 0.5rem 0.75rem;
    }

    .cat-options > .kp-button {
        white-space: nowrap;
    }

    .cat-options > [aria-pressed='true'] {
        border-color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
    }

    /* A choice this window cannot show: greyed, still focusable, and its
     * title says why (the key figures' strip widths). */
    .cat-options > [aria-disabled='true'] {
        opacity: var(--kp-field-disabled-opacity, 0.55);
        cursor: not-allowed;
    }

    /* Two copies side by side, and under each other where they do not fit. */
    .cat-pair {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr));
        gap: 1rem;
        align-items: start;
    }

    /* data.html#calendar: the page's own detail of the picked night, beside
       the month heatmap (a copy of the approved demo's detail). */
    .cat-calendar-detail {
        display: grid;
        gap: var(--kp-space-xs, 0.25rem);
        padding: var(--kp-space-md, 1rem);
        border: 1px solid var(--border);
        border-radius: var(--radius, 0.5rem);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .cat-calendar-detail h3,
    .cat-calendar-detail p {
        margin: 0;
    }

    .cat-calendar-detail ul {
        display: grid;
        gap: var(--kp-space-xs, 0.25rem);
        margin: 0;
        padding: 0;
        list-style: none;
    }

    .cat-calendar-detail li > span {
        display: block;
        color: var(--muted-foreground);
    }

    .cat-calendar-detail [data-cat-missing] > b {
        color: var(--destructive);
    }

    /* data.html#calendar: the phone pane, 360 px with its edge drawn, as the
       approved demo's frame; border-box, so on a 390 px screen it never
       reaches past the page. */
    .cat-calendar-frame {
        box-sizing: border-box;
        max-inline-size: 22.5rem;
        padding: var(--kp-space-md, 1rem);
        border: 1px dashed var(--border-strong);
        border-radius: var(--radius, 0.5rem);
        background: var(--background);
    }
    .cat-width-400 {
        inline-size: 400px;
        max-inline-size: 100%;
    }

    /* A window of a given size (catalogue/frame/): its edge is drawn, so what
       fits inside it can be judged. */
    .cat-viewport {
        border: 1px dashed var(--border-strong);
        background: var(--background);
    }

    body.cat-viewport-page {
        margin: 0;
        padding-block: 0.5rem;
    }

    /* The intro inspector (catalogue/intros.html): a window tall enough for
       a boot screen, and the words beside it as the dictionary gives them. */
    .cat-intro-controls {
        flex-wrap: wrap;
    }

    .cat-intro-controls .kp-field__label {
        margin: 0;
    }

    /* The speed slider is the catalogue's own control, not one the package
       draws, so the `font-family: inherit` list in css/components.css never
       reaches it and the browser's own stylesheet hands it the desktop font
       [fix-28]. tests/control-font.spec.mjs found it on 2026-09-17, the only
       control on any review page still taking the forced default. */
    .cat-intro-controls input[type='range'] {
        font-family: inherit;
    }

    .cat-intro-frame {
        display: block;
        inline-size: 100%;
        block-size: 22rem;
    }

    .cat-intro-words > h3 {
        font-size: 0.82rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
        margin: 0 0 0.35rem;
        font-weight: 600;
    }

    .cat-intro-words > pre {
        white-space: pre-wrap;
        font-family: var(--theme-font-mono, monospace);
        font-size: 0.85rem;
        margin: 0 0 1rem;
    }

    .cat-note {
        font-size: 0.8rem;
        color: var(--muted-foreground);
        margin-block-start: 0.4rem;
    }

    .cat-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(16rem, 1fr));
        gap: 1rem;
        align-items: start;
    }

    .cat-cell {
        min-inline-size: 0;
    }

    .cat-cell > h3 {
        font-size: 0.82rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
        margin: 0 0 0.5rem;
        font-weight: 600;
    }

    /* A pane the reviewer can widen and narrow to find the breaking point,
       because an extreme that only shows at one width is half measured. */
    /* Feedback under each block, and the prompt that gathers it. */
    .cat-feedback-field {
        margin-block-start: 0.75rem;
        max-inline-size: 46rem;
    }

    .cat-feedback-input {
        inline-size: 100%;
        resize: vertical;
    }

    .cat-feedback {
        margin-block-start: 4rem;
        padding-block-start: 1.5rem;
        border-block-start: 2px solid var(--border);
    }

    .cat-feedback-prompt {
        white-space: pre-wrap;
        overflow-wrap: anywhere;
        background: var(--muted);
        color: var(--foreground);
        padding: 0.9rem 1rem;
        font-size: 0.85rem;
        max-block-size: 24rem;
        overflow: auto;
    }

    .cat-feedback-actions {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.75rem;
    }

    /* The review page: a filter bar, a component heading per gathered page,
       and the approval state under every block. */
    .cat-review-bar {
        display: flex;
        flex-wrap: wrap;
        align-items: end;
        gap: 0.75rem 1.5rem;
        padding: 0.75rem 0;
        margin-block: 1rem;
        border-block: 1px solid var(--border);
    }

    .cat-component {
        margin-block-start: 3.5rem;
        scroll-margin-block-start: 4rem;
    }

    .cat-component__title {
        margin-block-end: 0.2rem;
    }

    /* The judging panel under every judged block (judging.js): one unit, set
       apart from the component on show by a surface and a rule. The state on
       the left, the two verdicts as a pair on the right, the note below at
       the panel's full width. Theme tokens only, so it reads in every theme. */
    .cat-judge {
        margin-block-start: 1rem;
        padding: 0.85rem 1rem 1rem;
        background: var(--card);
        color: var(--card-foreground);
        border: 1px solid var(--border);
        border-block-start: 3px solid var(--border);
        border-radius: var(--radius, 0);
        display: grid;
        gap: 0.75rem;
        container-type: inline-size;
    }

    .cat-judge[data-cat-state='approved'] {
        border-block-start-color: var(--success-foreground, var(--border));
    }

    .cat-judge[data-cat-state='rejected'] {
        border-block-start-color: var(--destructive);
    }

    .cat-judge[data-cat-state='changed'] {
        border-block-start-color: var(--warning-foreground, var(--border));
    }

    .cat-judge__head {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 0.6rem 1rem;
    }

    .cat-judge__status {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.3rem 0.6rem;
        margin: 0;
        min-inline-size: 0;
    }

    /* Where the verdict is kept: in the register, or only in this browser so far. */
    .cat-judge__source:empty {
        display: none;
    }

    .cat-judge__glyph {
        font-weight: 700;
        line-height: 1;
    }

    .cat-judge__actions {
        display: flex;
        align-items: stretch;
        gap: 0.5rem;
    }

    /* A narrow column: the pair goes under the state, full width, halves. */
    @container (max-width: 26rem) {
        .cat-judge__actions {
            flex: 1 1 100%;
        }

        .cat-judge__actions > * {
            flex: 1 1 0;
        }
    }

    /* Too narrow for two labels side by side (a compare column on a small
       window broke "Not approved" mid-word): one above the other. */
    @container (max-width: 20rem) {
        .cat-judge__actions {
            flex-direction: column;
        }
    }

    .cat-judge__note {
        margin: 0;
        max-inline-size: none;
    }

    .cat-judge__note-head {
        display: flex;
        align-items: baseline;
        justify-content: space-between;
        gap: 1rem;
    }

    /* Quiet by size and weight, not by a lighter ink: --muted-foreground on
       the card measured 4.13:1 in Shade (light). */
    .cat-judge__label {
        color: var(--card-foreground);
        font-size: 0.8rem;
        font-weight: 600;
        letter-spacing: 0.02em;
    }

    .cat-judge__saved {
        font-size: 0.78rem;
        color: var(--card-foreground);
    }

    .cat-judge__input {
        inline-size: 100%;
        min-block-size: 4.5rem;
        resize: vertical;
        box-sizing: border-box;
    }

    /* A rejected block's temporary note (catalogue/review-notes.json): the
       package's own warning alert, so its ink and ground are the theme's
       measured pair; the panel only spaces it. Its text stays in the alert's
       own foreground, no lighter ink for the date. */
    .cat-judge__review-note {
        margin-block-end: 0.85rem;
    }

    .cat-judge__review-note p {
        margin: 0;
        max-inline-size: 72ch;
    }

    .cat-judge__review-note p + p {
        margin-block-start: 0.35rem;
    }

    .cat-judge__review-note-meta {
        font-size: 0.8rem;
    }

    /* The review dialog (review-dialog.js) [scope-89, scope-90]: one fixed
       size, 92% of the window wide and 90% high, whatever block it holds.
       The header on top; the block's stage on the left, the note and the
       verdicts on the right. The class sits on the package's own dialog, so
       its surface, border and backdrop are the theme's.

       Its size is set on its own properties, never through the package's
       `--kp-dialog-max-width` / `--kp-dialog-max-height` [fix-36]: a custom
       property inherits, and `none` set here reached every dialog of the
       block under review. The sixty-row dialog then opened 2574px tall with
       no cap, centred on a 900px window (top at -837px, "02:19" the first
       row in sight) and its body never scrolled. This layer comes after the
       package's, so the properties below win over `.kp-dialog[open]`. */
    .cat-review-dialog {
        /* The review chrome opens without the theme's dialog entrance
         * [scope-140]: it swaps blocks in place, and its size is measured
         * from the first frame (scope-90). */
        animation: none;
        box-sizing: border-box;
        inline-size: 92vw;
        block-size: 90vh;
        max-inline-size: none;
        max-block-size: none;
        padding: 0;
        overflow: hidden;
    }

    .cat-review-dialog[open] {
        display: grid;
        grid-template-rows: auto auto minmax(0, 1fr) auto;
    }

    /* A theme's in-flow dialog ornament (deco and Lapis drew one as
       ::before since 9.0.0) gets a row of its own, so it never takes the
       head's row (review-ornament-M1). An empty row is zero tall. */
    .cat-review-dialog::before {
        grid-row: 1;
    }

    .cat-review-dialog__head {
        grid-row: 2;
    }

    .cat-review-dialog__grid {
        grid-row: 3;
    }

    .cat-review-dialog::after {
        grid-row: 4;
    }

    .cat-review-dialog__head {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.5rem 0.75rem;
        padding: 0.75rem 1rem;
        padding-inline-end: 3.5rem;
        border-block-end: 1px solid var(--border);
    }

    .cat-review-dialog__head > h2 {
        margin: 0;
        flex: 1 1 18rem;
        min-inline-size: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .cat-review-dialog__position {
        margin: 0;
        font-family: var(--theme-font-mono, monospace);
        font-size: 0.85rem;
        color: var(--muted-foreground);
    }

    .cat-review-dialog__grid {
        display: grid;
        grid-template-columns: minmax(0, 1fr) 24rem;
        min-block-size: 0;
    }

    /* The stage scrolls in both directions and never gives its size back to
       the dialog: `contain: strict` keeps the block's own size out of the
       dialog's layout. */
    .cat-review-dialog__stage {
        contain: strict;
        overflow: auto;
        overscroll-behavior: contain;
        padding: 1rem 1.25rem;
    }

    .cat-review-dialog__stage > .cat-block {
        margin: 0;
    }

    /* The title is in the header, the look and the note at the side. */
    .cat-review-dialog__stage > .cat-block > h2,
    .cat-review-dialog__stage > .cat-block > h3,
    .cat-review-dialog__stage > .cat-block > .cat-look,
    .cat-review-dialog__stage > .cat-block > .cat-judge {
        display: none;
    }

    /* The side is a body over a footer [scope-92]. The body trades room
       inside itself — the frame shrinks when a refusal or a message shows —
       and never gives any back to the footer, so the four buttons keep one
       place for every block (measured before: a long review note pushed them
       ~900 px down, out of the dialog; a verdict's message lifted them 19 px). */
    .cat-review-dialog__side {
        display: grid;
        grid-template-rows: minmax(0, 1fr) auto;
        gap: 0.75rem;
        min-block-size: 0;
        padding: 1rem;
        border-inline-start: 1px solid var(--border);
    }

    .cat-review-dialog__body {
        display: grid;
        grid-template-rows: minmax(0, 1fr) auto auto;
        gap: 0.75rem;
        min-block-size: 0;
        overflow: hidden;
    }

    /* One frame for the review note and the look, the note first; the frame
       scrolls and opens at its top. */
    .cat-review-dialog__frame {
        margin: 0;
        overflow: auto;
        overscroll-behavior: contain;
    }

    /* The note in the look's own font and size, in the theme's warning pair —
       the ink and ground the package measures together — so it reads apart
       from the look's muted text in every theme. */
    .cat-review-dialog__review-note {
        background: var(--warning);
        color: var(--warning-foreground);
        padding: 0.45rem 0.6rem;
        margin-block-end: 0.6rem;
    }

    .cat-review-dialog__review-note b {
        color: inherit;
    }

    .cat-review-dialog__review-note p {
        margin: 0;
    }

    .cat-review-dialog__review-note p + p {
        margin-block-start: 0.35rem;
    }

    .cat-review-dialog__live:empty {
        display: none;
    }

    .cat-review-dialog__footer {
        display: grid;
        gap: 0.5rem;
    }

    .cat-review-dialog__field {
        margin: 0;
    }

    .cat-review-dialog__field textarea {
        resize: none;
    }

    .cat-review-dialog__actions {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.5rem;
    }

    .cat-review-dialog__meta {
        margin: 0;
        font-size: 0.8rem;
        color: var(--muted-foreground);
    }

    .cat-review-dialog__away {
        padding: 1rem;
        font-style: italic;
    }

    /* While the review dialog is open on the review page, the blocks left on
       the page behind it are not drawn: the dialog covers them, and a theme
       chosen in it (the walk to the next theme, scope-113) then restyles and
       lays out the one block in the dialog rather than all 196 behind it.
       Measured 2026-10-05 in Firefox, judging.js reading nothing again:
       the next theme judgeable 0.7 to 1.4 s after the last verdict with the
       page drawn, 0.22 to 0.30 s without. The
       `hidden` attribute stays as judging.js sets it, so Left and Right
       still walk the blocks the page shows, and closing the dialog brings
       them back. */
    body:has(> .cat-review-dialog[open]) [data-cat-compose='all'] .cat-component > .cat-block {
        display: none;
    }

    /* The prompt bar every page carries under its header. */
    .cat-prompt-bar {
        padding: 0.45rem 1rem;
        background: var(--muted);
        color: var(--foreground);
        border-block-end: 1px solid var(--border);
    }

    .cat-prompt-bar__row {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.5rem 0.75rem;
    }

    .cat-prompt-bar__count {
        font-size: 0.85rem;
    }

    .cat-prompt-bar__status {
        margin: 0;
    }

    .cat-prompt-bar .cat-feedback-prompt {
        margin: 0.5rem 0 0.25rem;
        background: var(--background);
    }

    .cat-main--wide {
        max-inline-size: 110rem;
    }

    /* The compare page: two documents side by side, rows lined up by message. */
    .cat-compare {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
        gap: 1rem;
        align-items: start;
    }

    .cat-compare__frame {
        inline-size: 100%;
        block-size: 60vh;
        border: 1px solid var(--border);
    }

    /* Inside a column. */
    .cat-frame__main {
        padding: 1rem;
    }

    .cat-frame__row {
        display: flow-root;
        box-sizing: border-box;
        padding-block-end: 0.75rem;
    }

    .cat-frame__row > h2,
    .cat-frame__row > h3 {
        margin: 0.5rem 0 0;
    }

    /* A pane that narrows to a few characters, for the short buttons only. */
    .cat-to-top {
        position: fixed;
        inset-block-end: 1.25rem;
        inset-inline-end: 1.25rem;
        z-index: 45;
    }

    .cat-review-bar {
        position: sticky;
        inset-block-start: 3.5rem;
        z-index: 35;
        background: var(--background);
    }

    .cat-resize.cat-resize--narrow {
        min-inline-size: 2.5rem;
        inline-size: 16rem;
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
        align-items: flex-start;
    }

    .cat-resize {
        resize: horizontal;
        overflow: auto;
        min-inline-size: 12rem;
        max-inline-size: 100%;
        inline-size: 32rem;
        border: 1px dashed var(--border);
        padding: 1rem;
    }
}

/* A `.kp-shell` in a stage (navigation.html#app-shell) matches the
   package's `body:has(.kp-shell) { margin: 0 }` (css/layout.css), which is
   right for an app and wrong for the page reviewing it. Undone in that rule's
   own layer, with `revert-layer`: the body gets back exactly what the layers
   under kp.layout give it, the browser's margin in most themes and retro's
   centred window in retro. A `margin: revert` in the catalogue layer threw
   the theme's margin away as well, and moved every block in retro. */
@layer kp.layout {
    body.cat-shell:has(.kp-shell) {
        margin: revert-layer;
    }
}

/* ------------------------------------------------------------------------
   Review aids (Kenny, 2026-10-05: "zoek een manier om het mij makkelijker te
   maken om demo's te testen"): Play (play.js), the look as a checklist
   (checklist.js), the keys (shortcuts.js) and the page of what changed
   (changed.js). Chrome around the blocks only; theme tokens, so it reads in
   every theme. */
@layer catalogue {
    /* The button a running Play pressed last, and the block it plays. */
    .cat-play-step {
        outline: 3px solid var(--ring, var(--primary));
        outline-offset: 3px;
    }

    .cat-block[data-cat-playing] > .cat-stage,
    .cat-block[data-cat-playing] > .cat-live__bar {
        box-shadow: 0 0 0 2px var(--accent);
    }

    .cat-play-caption {
        margin-block: 0.5rem 0;
        padding: 0.35rem 0.6rem;
        border-inline-start: 3px solid var(--primary);
        background: var(--muted);
    }

    .cat-play-caption:empty {
        display: none;
    }

    /* The dialog's own Play, above its four buttons. The caption keeps two
       lines whatever it says, so the buttons below never move. */
    .cat-play-dialog {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: center;
        gap: 0.6rem;
    }

    .cat-play-dialog__caption {
        margin: 0;
        font-size: 0.8rem;
        line-height: 1.35;
        block-size: 2.7em;
        overflow: hidden;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        color: var(--muted-foreground);
    }

    /* The look as a checklist, right under the prose it is read from. */
    .cat-checklist {
        margin-block: -0.4rem 0.75rem;
        padding: 0.5rem 0.9rem 0.6rem;
        border-inline-start: 3px solid var(--accent);
        background: var(--muted);
        font-size: 0.85rem;
    }

    .cat-checklist__head {
        margin: 0 0 0.35rem;
        display: flex;
        gap: 0.6rem;
        align-items: baseline;
    }

    .cat-checklist__count {
        color: var(--muted-foreground);
    }

    .cat-checklist__lines {
        list-style: none;
        margin: 0;
        padding: 0;
        display: grid;
        gap: 0.3rem;
    }

    /* The box, then the sentence at the list's full width; the buttons it
       names sit under the sentence, so a long line never squeezes it. */
    .cat-checklist .cat-checklist__line {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: start;
        gap: 0.2rem 0.5rem;
        margin: 0;
        inline-size: auto;
        max-inline-size: none;
    }

    .cat-checklist__text {
        font-weight: normal;
        cursor: pointer;
        line-height: 1.45;
        color: var(--foreground);
    }

    .cat-checklist__line:has(:checked) .cat-checklist__text {
        color: var(--muted-foreground);
        text-decoration: line-through;
        text-decoration-color: var(--border-strong, currentColor);
    }

    .cat-checklist__presses {
        grid-column: 2;
        display: flex;
        flex-wrap: wrap;
        gap: 0.3rem;
    }

    .cat-checklist__press {
        white-space: nowrap;
    }

    /* In the dialog the side holds the list (under its copy of the look);
       the one inside the block stays out of the stage. */
    .cat-review-dialog__stage > .cat-block > .cat-checklist {
        display: none;
    }

    [data-cat-dialog-look] > .cat-checklist {
        margin: 0.6rem 0 0;
        padding: 0;
        border: 0;
        background: none;
    }

    /* The block the keys act on, after N or A. */
    .cat-key-current > .cat-judge {
        outline: 2px solid var(--ring, var(--primary));
        outline-offset: 2px;
    }

    .cat-key-flash {
        position: fixed;
        inset-block-end: 1rem;
        inset-inline-start: 50%;
        translate: -50% 0;
        z-index: 2147483000;
        margin: 0;
        padding: 0.5rem 0.9rem;
        background: var(--popover, var(--card));
        color: var(--popover-foreground, var(--card-foreground));
        border: 1px solid var(--border-strong, var(--border));
        box-shadow: 0 4px 16px rgb(0 0 0 / 0.2);
        max-inline-size: min(40rem, calc(100vw - 2rem));
    }

    .cat-key-flash[hidden] {
        display: none;
    }

    .cat-keys-help {
        position: fixed;
        inset: 0;
        margin: auto;
        inline-size: min(34rem, calc(100vw - 2rem));
        block-size: fit-content;
        padding: 1rem 1.25rem;
    }

    .cat-keys-help__title {
        margin: 0 0 0.5rem;
    }

    .cat-keys-help__list {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        gap: 0.35rem 0.9rem;
        margin: 0 0 0.75rem;
    }

    .cat-keys-help__list dd {
        margin: 0;
    }

    .cat-keys-help kbd,
    .cat-keys-legend kbd {
        font-family: var(--theme-font-mono, monospace);
        font-size: 0.85em;
        padding: 0 0.3em;
        border: 1px solid var(--border-strong, var(--border));
        border-block-end-width: 2px;
    }

    /* How many blocks each theme in the menu has left (open-pairs.js). */
    .cat-bar__theme [data-kp-theme][data-cat-left]::after {
        content: attr(data-cat-left);
        margin-inline-start: auto;
        padding-inline-start: 0.75rem;
        font-size: 0.8em;
        color: var(--muted-foreground);
    }

    .cat-changed-done {
        padding: 1rem 1.25rem;
        border-inline-start: 3px solid var(--success-foreground, var(--primary));
        background: var(--muted);
    }

    /* "To judge" (changed.html): the one page Kenny starts from. A head with
       the lead on the left and Start on the right; the demos as rows whose
       title, state and button share three columns from row to row (subgrid),
       stacked on a phone. */
    .cat-hub__head {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(12rem, max-content);
        gap: var(--kp-space-md) var(--kp-space-xl);
        align-items: end;
    }

    .cat-hub__go {
        display: grid;
        gap: var(--kp-space-xs);
        justify-items: stretch;
    }

    .cat-hub__next {
        margin: 0;
        max-inline-size: 22rem;
    }

    .cat-hub__totals {
        margin-block: var(--kp-space-lg) 0;
        padding-block: var(--kp-space-sm);
        border-block: 1px solid var(--border);
        font-variant-numeric: tabular-nums;
    }

    .cat-hub__part {
        margin-block-start: var(--kp-space-2xl);
    }

    .cat-hub__list {
        display: grid;
        grid-template-columns: minmax(0, 1fr) max-content max-content;
        gap: 0 var(--kp-space-lg);
        margin: var(--kp-space-md) 0 0;
        padding: 0;
        list-style: none;
    }

    .cat-hub__row,
    .cat-hub__list > .cat-changed-done {
        grid-column: 1 / -1;
    }

    .cat-hub__row {
        display: grid;
        grid-template-columns: subgrid;
        align-items: center;
        padding-block: var(--kp-space-md);
        border-block-end: 1px solid var(--border);
    }

    .cat-hub__title {
        margin: 0;
        font-size: 1.05rem;
    }

    .cat-hub__ask {
        margin: var(--kp-space-xs) 0 0;
        color: var(--muted-foreground);
        font-size: 0.9rem;
    }

    .cat-hub__state {
        margin: 0;
        font-variant-numeric: tabular-nums;
    }

    .cat-hub__open {
        justify-self: stretch;
        text-align: center;
        text-decoration: none;
    }

    .cat-hub__decided {
        margin-block-start: var(--kp-space-lg);
    }

    .cat-hub__decided > summary {
        cursor: pointer;
        font-weight: 600;
    }

    @media (max-width: 40rem) {
        .cat-hub__head {
            grid-template-columns: minmax(0, 1fr);
        }

        .cat-hub__next {
            max-inline-size: none;
        }

        /* A row stacks: what it is on top, its state and its button under it. */
        .cat-hub__list {
            grid-template-columns: minmax(0, 1fr) max-content;
        }

        .cat-hub__row {
            row-gap: var(--kp-space-sm);
        }

        .cat-hub__what {
            grid-column: 1 / -1;
        }
    }
}

/* ---- catalogue/agenda.css ---- */
/* The Agenda (agenda.html): the page Kenny starts from. A head with the lead on the left and the one primary action
   on the right; a status slot; the attention band for answers not yet copied; then the items as numbered rows whose
   number, description, count and button share four columns from row to row (subgrid), so every count and every
   button lines up whatever the text. On a phone a row stacks: the number and description, then the count and the
   button side by side. Tokens only; the theme on screen paints it. */
@layer catalogue {
    .agenda {
        --agenda-number: 2.25rem;
        --agenda-count: 11rem;
        --agenda-action: 8.5rem;
    }

    .agenda__head {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(14rem, max-content);
        gap: var(--kp-space-md) var(--kp-space-xl);
        align-items: end;
    }

    .agenda__lead h1 {
        margin-block-end: var(--kp-space-xs);
    }

    .agenda__intro {
        margin: 0;
    }

    .agenda__actions {
        display: grid;
        gap: var(--kp-space-xs);
        justify-items: stretch;
        max-inline-size: 22rem;
    }

    .agenda__next,
    .agenda__other {
        margin: 0;
        font-size: var(--kp-text-sm);
    }

    .agenda__other {
        display: flex;
        flex-wrap: wrap;
        gap: 0 var(--kp-space-sm);
        color: var(--muted-foreground);
    }

    /* The status slot: one line today, room for more below it. */
    .agenda__status {
        display: grid;
        gap: var(--kp-space-xs);
        margin-block-start: var(--kp-space-lg);
        padding-block: var(--kp-space-sm);
        border-block: 1px solid var(--border);
    }

    .agenda__status-line {
        margin: 0;
        font-variant-numeric: tabular-nums;
    }

    .agenda__answers {
        margin-block-start: var(--kp-space-md);
        align-items: center;
    }

    .agenda__answers-copy {
        margin-inline-start: auto;
        flex: 0 0 auto;
    }

    /* Saved verdicts: per demo a fold with its round picker, its one copy button and its entries, newest first. */
    .agenda__saved {
        margin-block-start: var(--kp-space-2xl);
    }

    .agenda__saved-list {
        display: grid;
        gap: var(--kp-space-md);
    }

    .agenda-saved {
        border: 1px solid var(--border);
        border-radius: var(--radius);
        padding: var(--kp-space-sm) var(--kp-space-md);
    }

    .agenda-saved__summary {
        font-weight: 600;
        cursor: pointer;
    }

    .agenda-saved__copy {
        display: flex;
        flex-wrap: wrap;
        align-items: end;
        gap: var(--kp-space-sm);
        margin-block: var(--kp-space-sm);
    }

    .agenda-saved__said {
        margin: 0;
        font-size: var(--kp-text-sm);
    }

    .agenda-saved__text {
        margin: 0 0 var(--kp-space-sm);
        padding: var(--kp-space-sm);
        max-block-size: 16rem;
        overflow: auto;
        white-space: pre-wrap;
        font-size: var(--kp-text-sm);
        background: var(--muted);
    }

    .agenda-saved__entries {
        display: grid;
        gap: var(--kp-space-xs);
        margin: 0;
        padding: 0;
        list-style: none;
        font-size: var(--kp-text-sm);
    }

    .agenda-saved__entry {
        display: grid;
        grid-template-columns: 9.5rem minmax(0, 1fr);
        gap: var(--kp-space-sm);
        padding-block: var(--kp-space-xs);
        border-block-end: 1px solid var(--border);
    }

    .agenda-saved__what {
        white-space: pre-wrap;
        overflow-wrap: anywhere;
    }

    .agenda-saved__when {
        color: var(--muted-foreground);
        font-variant-numeric: tabular-nums;
    }

    .agenda__part {
        margin-block-start: var(--kp-space-2xl);
    }

    .agenda__part > h2 {
        margin-block-end: var(--kp-space-xs);
    }

    .agenda__part > .cat-intro {
        margin-block-start: 0;
    }

    /* The list's area: a minimum height of a few rows, so reading to read jumps little, and the host the busy card is laid over. */
    .agenda__area {
        position: relative;
        min-block-size: 22rem;
    }

    /* The rows: four shared columns. */
    .agenda__list {
        display: grid;
        grid-template-columns: var(--agenda-number) minmax(0, 1fr) var(--agenda-count) var(--agenda-action);
        gap: 0 var(--kp-space-lg);
        margin: var(--kp-space-md) 0 0;
        padding: 0;
        list-style: none;
        border-block-start: 1px solid var(--border);
    }

    .agenda-row,
    .agenda__list > .agenda__none {
        grid-column: 1 / -1;
    }

    .agenda__none {
        margin-block: var(--kp-space-md);
    }

    .agenda-row {
        display: grid;
        grid-template-columns: subgrid;
        align-items: start;
        padding-block: var(--kp-space-lg);
        border-block-end: 1px solid var(--border);
        scroll-margin-block-start: 5rem;
    }

    .agenda-row:target {
        outline: 2px solid var(--ring);
        outline-offset: 2px;
    }

    .agenda-row__number {
        display: grid;
        place-items: center;
        inline-size: var(--agenda-number);
        block-size: var(--agenda-number);
        border: 1px solid var(--border-strong, var(--border));
        border-radius: 50%;
        font-family: var(--theme-font-mono, monospace);
        font-variant-numeric: tabular-nums;
        font-weight: 600;
    }

    .agenda-row[data-agenda-state='done'] .agenda-row__number {
        color: var(--muted-foreground);
    }

    .agenda-row__what {
        display: grid;
        gap: var(--kp-space-xs);
        min-inline-size: 0;
    }

    .agenda-row__kind {
        margin: 0;
        font-size: var(--kp-text-xs);
        font-weight: 600;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    .agenda-row__title {
        margin: 0;
        font-size: 1.05rem;
        overflow-wrap: anywhere;
    }

    .agenda-row__about {
        margin: 0;
        max-inline-size: 46rem;
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm);
    }

    /* The order in words: what comes first, and what a rejection reaches. A rule at the start tells the two apart
       without colouring text. */
    .agenda-row__links {
        display: grid;
        gap: var(--kp-space-xs);
        margin: var(--kp-space-xs) 0 0;
        padding: 0;
        list-style: none;
        font-size: var(--kp-text-sm);
    }

    .agenda-dep {
        padding-inline-start: var(--kp-space-sm);
        border-inline-start: 3px solid var(--border-strong, var(--border));
    }

    .agenda-dep--affects {
        border-inline-start-color: var(--warning);
    }

    .agenda-dep__label {
        font-weight: 600;
    }

    .agenda-row__count {
        display: grid;
        gap: var(--kp-space-xs);
        justify-items: start;
        margin: 0;
        font-variant-numeric: tabular-nums;
    }

    .agenda-row__badge {
        white-space: nowrap;
    }

    .agenda-row__spread {
        font-size: var(--kp-text-sm);
        color: var(--muted-foreground);
    }

    .agenda-row__go {
        display: grid;
    }

    .agenda-row__button {
        justify-content: center;
        text-align: center;
        text-decoration: none;
    }

    /* The laid-out blocks and Done: folded away below the list. */
    .agenda__blocks,
    .agenda__done {
        margin-block-start: var(--kp-space-2xl);
    }

    .agenda__blocks + .agenda__done {
        margin-block-start: var(--kp-space-lg);
    }

    .agenda__fold-summary {
        cursor: pointer;
        font-size: 1.25rem;
        font-weight: 600;
    }

    .agenda__fold-count {
        color: var(--muted-foreground);
        font-variant-numeric: tabular-nums;
    }

    .agenda__blocks[open] > .cat-intro,
    .agenda__done[open] > .cat-intro {
        margin-block: var(--kp-space-sm) 0;
    }

    @media (max-width: 40rem) {
        .agenda-saved__entry {
            grid-template-columns: minmax(0, 1fr);
            gap: 0;
        }

        .agenda__head {
            grid-template-columns: minmax(0, 1fr);
        }

        .agenda__actions {
            max-inline-size: none;
        }

        .agenda__answers {
            flex-wrap: wrap;
        }

        /* A row stacks: number and description on top, count and button below, in the same two columns. */
        .agenda__list {
            grid-template-columns: var(--agenda-number) minmax(0, 1fr) max-content;
            column-gap: var(--kp-space-md);
        }

        .agenda-row {
            row-gap: var(--kp-space-md);
        }

        .agenda-row__what {
            grid-column: 2 / -1;
        }

        .agenda-row__count {
            grid-column: 2;
            align-self: center;
        }

        .agenda-row__go {
            grid-column: 3;
            align-self: center;
        }
    }
}

/* ---- research/_review/rv-progress.css ---- */
/* The progress options of the review kit (rv-progress.js): the remaining line in the dialog's head, the remaining
   line on an Agenda row, the Continue button and the Review options fold. Tokens only; the theme on screen paints it. */

/* The counts in the dialog's header row (review.js hands the slot): plain text, no pills, the parts separated by a thin dot. */
.rv-remaining {
    display: inline-flex;
    align-items: baseline;
    gap: 0 0.5rem;
    margin: 0;
    font-size: 0.8125rem;
    line-height: 1.4;
    white-space: nowrap;
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
}

.rv-remaining > span + span::before {
    content: '·';
    margin-inline-end: 0.5rem;
}

.rv-remaining__part {
    color: var(--foreground);
    font-weight: 600;
}

.rv-remaining[hidden],
.agenda-row__remaining[hidden],
.agenda__continue[hidden],
.agenda__continue-note[hidden] {
    display: none;
}

.agenda-row__remaining {
    margin: var(--kp-space-xs, 0.25rem) 0 0;
    font-size: var(--kp-text-sm, 0.875rem);
    color: var(--muted-foreground);
    font-variant-numeric: tabular-nums;
    overflow-wrap: anywhere;
}

/* Continue sits at the top of the head's actions, the same width as the start button. */
.agenda__continue {
    display: flex;
    justify-content: center;
    text-align: center;
    white-space: normal;
}

.agenda__continue-note {
    margin: 0;
    font-size: var(--kp-text-sm, 0.875rem);
}

.agenda__options {
    margin-block-start: var(--kp-space-md, 1rem);
}

.agenda__options-list {
    display: grid;
    grid-template-columns: minmax(14rem, max-content) minmax(0, 1fr);
    gap: var(--kp-space-sm, 0.5rem) var(--kp-space-lg, 1.5rem);
    align-items: center;
}

.agenda__option {
    display: grid;
    grid-template-columns: subgrid;
    grid-column: 1 / -1;
    align-items: center;
}

.agenda__option > p {
    margin: 0;
}

@media (max-width: 48rem) {
    .agenda__options-list,
    .agenda__option {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* ---- research/_review/flow.css ---- */
/* The flow's parts (flow.js, reasons.js, the Agenda's flow panel). Tokens only. */

.kf-leave {
    position: fixed;
    inset-block-end: var(--kp-space-lg, 1.5rem);
    inset-inline: var(--kp-space-md, 1rem);
    margin-inline: auto;
    max-inline-size: 40rem;
    z-index: 2147483000;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--kp-space-sm, 0.75rem);
    padding: var(--kp-space-md, 1rem);
    overflow: hidden;
    background: var(--popover, var(--card, Canvas));
    color: var(--popover-foreground, var(--foreground, CanvasText));
    border: 1px solid var(--border);
    border-radius: var(--kp-radius-md, 0.5rem);
    box-shadow: 0 0.5rem 1.5rem color-mix(in srgb, var(--foreground, black) 25%, transparent);
}

.kf-leave__text {
    margin: 0;
}

.kf-leave__esc {
    color: var(--muted-foreground);
    white-space: nowrap;
}

.kf-leave__bar {
    position: absolute;
    inset-inline: 0;
    inset-block-end: 0;
    block-size: 0.25rem;
    background: var(--primary, currentColor);
    transform-origin: left center;
    animation: kf-count 2s linear forwards;
}

@keyframes kf-count {
    from {
        transform: scaleX(1);
    }
    to {
        transform: scaleX(0);
    }
}

@media (max-width: 40rem) {
    .kf-leave {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* Reason chips on a reject (reasons.js): beside the note, one row that wraps. */
.kf-chips {
    display: flex;
    flex-wrap: wrap;
    gap: var(--kp-space-xs, 0.25rem);
    margin-block-start: 0.4rem;
}

.kf-chips[hidden] {
    display: none;
}

.kf-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.2rem 0.6rem;
    font: inherit;
    font-size: 0.8125rem;
    color: var(--foreground);
    background: var(--muted, transparent);
    border: 1px solid var(--border);
    border-radius: 999px;
    cursor: pointer;
}

.kf-chip kbd {
    font: inherit;
    font-size: 0.75rem;
    color: var(--muted-foreground);
}

.kf-chip[aria-pressed='true'] {
    background: var(--primary);
    color: var(--primary-foreground);
    border-color: var(--primary);
}

.kf-chip[aria-pressed='true'] kbd {
    color: inherit;
}

.kf-chip:focus-visible {
    outline: 2px solid var(--ring, currentColor);
    outline-offset: 2px;
}

/* The Agenda's flow panel (flow-agenda.js). */
.kf-panel {
    display: grid;
    gap: var(--kp-space-sm, 0.75rem);
    margin-block-start: var(--kp-space-md, 1rem);
}

.kf-panel__grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
    gap: var(--kp-space-md, 1rem);
    align-items: start;
}

.kf-panel__tonight {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--kp-space-md, 1rem);
}

.kf-panel__tonight[hidden] {
    display: none;
}

.kf-panel__tonight p {
    margin: 0;
}

@media (max-width: 40rem) {
    .kf-panel__tonight {
        grid-template-columns: minmax(0, 1fr);
    }
}

@media (prefers-reduced-motion: reduce) {
    .kf-leave__bar {
        animation: none;
    }
}

.kf-panel__tonight {
    margin-block: var(--kp-space-sm, 0.75rem) var(--kp-space-md, 1rem);
}
